By case analysis on the argument:
  \begin{align*}
    q(\ensuremath{\textsf{id}})(0) &= 0 = \ensuremath{\textsf{id}}(0) \\
    q(\ensuremath{\textsf{id}})(x+1) &= \ensuremath{\textsf{id}}(x) + 1 = x + 1 = \ensuremath{\textsf{id}}(x+1)
  \end{align*}

By induction on $t$.
  We show a few representative cases.
  \begin{itemize}[label=Case]
  \@idxitem $t = x$ (variable).
    \begin{align*}
      x[\ensuremath{\textsf{id}}] = \ensuremath{\textsf{id}}(x) = x
    \end{align*}
  \@idxitem $t = \lambda x.\, t'$.
    \begin{align*}
      (\lambda x.\, t')[\ensuremath{\textsf{id}}]
      &= \lambda x.\, (t'[q(\ensuremath{\textsf{id}})]) \\
      &= \lambda x.\, (t'[\ensuremath{\textsf{id}}])
        \tag{by \Cref{lem:wk-q-id}} \\
      &= \lambda x.\, t'
        \tag{by IH}
    \end{align*}
  \@idxitem $t = \Pi(x : S).\, T$.
    \begin{align*}
      (\Pi(x : S).\, T)[\ensuremath{\textsf{id}}]
      &= \Pi(x : S[\ensuremath{\textsf{id}}]).\, (T[q(\ensuremath{\textsf{id}})]) \\
      &= \Pi(x : S).\, (T[\ensuremath{\textsf{id}}])
        \tag{by IH and \Cref{lem:wk-q-id}} \\
      &= \Pi(x : S).\, T
        \tag{by IH}
    \end{align*}
  \end{itemize}
  All other cases follow the same pattern.

\label{lem:wk-q-comp}
  For all weakenings $\phi, \psi$:
  $q(\phi) \circ q(\psi) = q(\phi \circ \psi)$.

\label{lem:wk-qn-comp}
  For all weakenings $\phi, \psi$:
  $q^n(\phi) \circ q^n(\psi) = q^n(\phi \circ \psi)$.

\label{lem:wk-comp}
  For all $t \in \textsf{Exp}$ and weakenings $\phi, \psi$:
  $t[\phi][\psi] = t[\phi \circ \psi]$.

\label{lem:wk-cat}
  Weakenings satisfy:
  \begin{enumerate}
  \@idxitem (Left identity) $\ensuremath{\textsf{id}} \circ \phi = \phi$.
  \@idxitem (Right identity) $\phi \circ \ensuremath{\textsf{id}} = \phi$.
  \@idxitem (Associativity) $(\phi \circ \psi) \circ \chi = \phi \circ (\psi \circ \chi)$.
  \end{enumerate}

All three are immediate from the definition of composition as function composition on $\mathbb{N}$:
  \begin{align*}
    (\ensuremath{\textsf{id}} \circ \phi)(x) &= \phi(\ensuremath{\textsf{id}}(x)) = \phi(x) \\
    (\phi \circ \ensuremath{\textsf{id}})(x) &= \ensuremath{\textsf{id}}(\phi(x)) = \phi(x) \\
    ((\phi \circ \psi) \circ \chi)(x) &= \chi(\psi(\phi(x))) = (\phi \circ (\psi \circ \chi))(x)
  \end{align*}

\label{lem:wk-embed-correct}
  For all $t \in \textsf{Exp}$ and weakenings $\phi$:
  $t[\phi] = t[\iota(\phi)]$.

\label{lem:iota-struct}
  The embedding $\iota$ preserves all weakening structure:
  \begin{enumerate}
  \@idxitem $\iota(\ensuremath{\textsf{id}}) = \ensuremath{\textsf{id}}$.
  \@idxitem $\iota(\Uparrow) = \Uparrow$ (as substitutions, i.e.\ $\iota(\Uparrow)(x) = x + 1$).
  \@idxitem $\iota(q(\phi)) = q(\iota(\phi))$.
  \@idxitem $\iota(\phi \circ \psi) = \iota(\phi) \circ \iota(\psi)$.
  \end{enumerate}

By case analysis:
  \begin{align*}
    q(\ensuremath{\textsf{id}})(0) &= 0 = \ensuremath{\textsf{id}}(0) \\
    q(\ensuremath{\textsf{id}})(x+1) &= \ensuremath{\textsf{id}}(x)[\Uparrow] = x[\Uparrow] = x + 1 = \ensuremath{\textsf{id}}(x+1)
  \end{align*}

\label{lem:qn-index}
  For all $n$ and weakenings $\phi$:
  \begin{enumerate}
  \@idxitem If $x < n$, then $q^n(\phi)(x) = x$.
  \@idxitem $q^n(\phi)(x) = \phi(0) + x$.
  \@idxitem If $x > n$, then $q^n(\phi)(x) = \phi(x - n) + n$.
  \end{enumerate}
  In particular, for $\phi = \Uparrow$:
  \begin{enumerate}
  \@idxitem[(a)] If $x < n$, then $q^n(\Uparrow)(x) = x$.
  \@idxitem[(b)] $q^n(\Uparrow)(x) = x + 1$.
  \@idxitem[(c)] If $x > n$, then $q^n(\Uparrow)(x) = x + 1$.
  \end{enumerate}

\label{lem:qn-subst-index}
  For all $n$ and substitutions $\sigma$:
  \begin{enumerate}
  \@idxitem If $x < n$, then $q^n(\sigma)(x) = x$.
  \@idxitem $q^n(\sigma)(n) = \sigma(0)[\Uparrow^n]$ (where $\Uparrow^n$ denotes $n$-fold shift).
  \@idxitem If $x > n$, then $q^n(\sigma)(x) = \sigma(x - n)[\Uparrow^n]$.
  \end{enumerate}

By induction on $t$, generalizing over $n$.
  \begin{itemize}[label=Case]
  \@idxitem $t = x$ (variable).
    We must show $(q^n(\Uparrow)(x))[q^{1+n}(\sigma)] = (q^n(\sigma)(x))[q^n(\Uparrow)]$.
    We case-split on the position of $x$ relative to $n$.
    \begin{itemize}
    \@idxitem If $x < n$:
      \begin{align*}
        \text{LHS}
        &= (q^n(\Uparrow)(x))[q^{1+n}(\sigma)] \\
        &= x[q^{1+n}(\sigma)]
          \tag{by \Cref{lem:qn-index}(a): $q^n(\Uparrow)(x) = x$ since $x < n$} \\
        &= x
          \tag{by \Cref{lem:qn-subst-index}(1): $q^{1+n}(\sigma)(x) = x$ since $x < n < 1+n$}
      \end{align*}
      \begin{align*}
        \text{RHS}
        &= (q^n(\sigma)(x))[q^n(\Uparrow)] \\
        &= x[q^n(\Uparrow)]
          \tag{by \Cref{lem:qn-subst-index}(1): $q^n(\sigma)(x) = x$ since $x < n$} \\
        &= x
          \tag{by \Cref{lem:qn-index}(a)}
      \end{align*}

    \@idxitem If $x = n$:
      \begin{align*}
        \text{LHS}
        &= (q^n(\Uparrow)(n))[q^{1+n}(\sigma)] \\
        &= (n + 1)[q^{1+n}(\sigma)]
          \tag{by \Cref{lem:qn-index}(b)} \\
        &= q^{1+n}(\sigma)(1+n) \\
        &= \sigma(0)[\Uparrow^{1+n}]
          \tag{by \Cref{lem:qn-subst-index}(2) at iteration $1+n$}
      \end{align*}
      \begin{align*}
        \text{RHS}
        &= (q^n(\sigma)(n))[q^n(\Uparrow)] \\
        &= (\sigma(0)[\Uparrow^n])[q^n(\Uparrow)]
          \tag{by \Cref{lem:qn-subst-index}(2)} \\
        &= \sigma(0)[\Uparrow^n \circ q^n(\Uparrow)]
          \tag{by \Cref{lem:wk-comp}} \\
        &= \sigma(0)[\Uparrow^{1+n}]
          \tag{since $(\Uparrow^n \circ q^n(\Uparrow))(x) = q^n(\Uparrow)(x + n) = x + 1 + n = \Uparrow^{1+n}(x)$}
      \end{align*}

    \@idxitem If $x > n$: Let $x = 1 + n + k$.
      \begin{align*}
        \text{LHS}
        &= (q^n(\Uparrow)(1 + n + k))[q^{1+n}(\sigma)] \\
        &= (2 + n + k)[q^{1+n}(\sigma)]
          \tag{by \Cref{lem:qn-index}(c)} \\
        &= q^{1+n}(\sigma)(2 + n + k) \\
        &= \sigma(1+k)[\Uparrow^{1+n}]
          \tag{by \Cref{lem:qn-subst-index}(3): $(2+n+k) - (1+n) = 1+k$}
      \end{align*}
      \begin{align*}
        \text{RHS}
        &= (q^n(\sigma)(1 + n + k))[q^n(\Uparrow)] \\
        &= (\sigma(1+k)[\Uparrow^n])[q^n(\Uparrow)]
          \tag{by \Cref{lem:qn-subst-index}(3): $(1+n+k) - n = 1+k$} \\
        &= \sigma(1+k)[\Uparrow^n \circ q^n(\Uparrow)]
          \tag{by \Cref{lem:wk-comp}} \\
        &= \sigma(1+k)[\Uparrow^{1+n}]
          \tag{as above}
      \end{align*}
    \end{itemize}

  \@idxitem $t = \lambda y.\, t'$.
    \begin{align*}
      (\lambda y.\, t')[q^n(\Uparrow)][q^{1+n}(\sigma)]
      &= (\lambda y.\, t'[q^{1+n}(\Uparrow)])[q^{1+n}(\sigma)] \\
      &= \lambda y.\, (t'[q^{1+n}(\Uparrow)][q^{2+n}(\sigma)]) \\
      &= \lambda y.\, (t'[q^{1+n}(\sigma)][q^{1+n}(\Uparrow)])
        \tag{by IH at $1+n$} \\
      &= (\lambda y.\, t'[q^{1+n}(\sigma)])[q^n(\Uparrow)] \\
      &= (\lambda y.\, t')[q^n(\sigma)][q^n(\Uparrow)]
    \end{align*}

  \@idxitem $t = \Pi(y : S).\, T$.
    \begin{align*}
      (\Pi(y:S).\,T)[q^n(\Uparrow)][q^{1+n}(\sigma)]
      &= (\Pi(y : S[q^n(\Uparrow)]).\, (T[q^{1+n}(\Uparrow)]))[q^{1+n}(\sigma)] \\
      &= \Pi(y : S[q^n(\Uparrow)][q^{1+n}(\sigma)]).\, (T[q^{1+n}(\Uparrow)][q^{2+n}(\sigma)]) \\
      &= \Pi(y : S[q^n(\sigma)][q^n(\Uparrow)]).\, (T[q^{1+n}(\sigma)][q^{1+n}(\Uparrow)])
        \tag{by IH at $n$ and $1+n$} \\
      &= (\Pi(y : S[q^n(\sigma)]).\, (T[q^{1+n}(\sigma)]))[q^n(\Uparrow)] \\
      &= (\Pi(y:S).\,T)[q^n(\sigma)][q^n(\Uparrow)]
    \end{align*}
  \end{itemize}
  The remaining cases follow the same pattern, applying the IH at increased $n$ for
  each binder.

\label{lem:subst-q-comp}
  For all substitutions $\sigma, \tau$:
  $q(\sigma) \circ q(\tau) = q(\sigma \circ \tau)$.

\label{lem:subst-assoc}
  For all $t \in \textsf{Exp}$ and substitutions $\sigma, \tau$:
  $t[\sigma][\tau] = t[\sigma \circ \tau]$.

\label{lem:q-wk-comm}
  For all substitutions $\sigma$ and weakenings $\phi$:
  $q(\sigma[\phi]) = q(\sigma)[q(\phi)]$.

\label{lem:wk-subst-interact}
  The following two properties hold:
  \begin{enumerate}
  \@idxitem For all $t \in \textsf{Exp}$, weakening $\phi$, and substitution $\sigma$:
    $(t[\phi])[\sigma] = t[\phi \circ \sigma]$.
  \@idxitem For all $t \in \textsf{Exp}$, substitution $\sigma$, and weakening $\phi$:
    $(t[\sigma])[\phi] = t[\sigma[\phi]]$.
  \end{enumerate}

Statement (1) is a corollary of \Cref{lem:wk-embed-correct,lem:subst-assoc}.
  Since we elide the embedding, treating $\phi$ as a substitution:
  \begin{align*}
    (t[\phi])[\sigma]
    &= t[\phi \circ \sigma]
      \tag{by \Cref{lem:subst-assoc}}
  \end{align*}

  Statement (2) also follows from \Cref{lem:subst-assoc}:
  \begin{align*}
    (t[\sigma])[\phi]
    &= t[\sigma \circ \phi]
      \tag{by \Cref{lem:subst-assoc}}
  \end{align*}
  We verify: $(\sigma \circ \phi)(x) = \sigma(x)[\phi] = (\sigma[\phi])(x)$,
  which is exactly the definition of $\sigma[\phi]$.
  Hence $\sigma \circ \phi = \sigma[\phi]$ and the claim holds.

\label{lem:shift-ext}
  For all substitutions $\sigma$ and terms $s$:
  $\Uparrow \circ (\sigma, s/x) = \sigma$.

\label{lem:ext-comp}
  For all substitutions $\sigma, \tau$ and terms $s$:
  $(\sigma, s/x) \circ \tau = (\sigma \circ \tau,\; s[\tau]/x)$.

\label{lem:subst-cat}
  Substitutions satisfy:
  \begin{enumerate}
  \@idxitem (Left identity) $\ensuremath{\textsf{id}} \circ \sigma = \sigma$ for all $\sigma$.
  \@idxitem (Right identity) $\sigma \circ \ensuremath{\textsf{id}} = \sigma$ for all $\sigma$.
  \@idxitem (Associativity) $(\sigma \circ \tau) \circ \delta = \sigma \circ (\tau \circ \delta)$.
  \end{enumerate}

We show both sides equal $t[\sigma, s[\sigma]/x]$.
  \begin{align*}
    t[q(\sigma)][s[\sigma]/x]
    &= t[q(\sigma)][\ensuremath{\textsf{id}}, s[\sigma]/x]
      \tag{by notation} \\
    &= t[\sigma, s[\sigma]/x]
      \tag{by \Cref{lem:q-ext}}
  \end{align*}
  \begin{align*}
    t[s/x][\sigma]
    &= t[\ensuremath{\textsf{id}}, s/x][\sigma]
      \tag{by notation} \\
    &= t[(\ensuremath{\textsf{id}}, s/x) \circ \sigma]
      \tag{by \Cref{lem:subst-assoc}} \\
    &= t[\ensuremath{\textsf{id}} \circ \sigma, s[\sigma]/x]
      \tag{by \Cref{lem:ext-comp}} \\
    &= t[\sigma, s[\sigma]/x]
      \tag{by \Cref{lem:subst-cat} (left identity)}
  \end{align*}

\label{def:judgments}
  The judgments of our type theory are:
  \[
    \begin{array}{lll}
      \vdash \Gamma & & \text{$\Gamma$ is a well-formed context} \\[4pt]
      \typing[\Gamma]{t}{T} & & \text{$t$ has type $T$ in $\Gamma$} \\[4pt]
      \tyequiv[\Gamma]{t}{t'}{T} & & \text{$t$ and $t'$ are equal terms of type $T$ in $\Gamma$} \\[4pt]

  \IfNoValueTF {S}
  {\Gamma \vdash T \subseteq &}
  {S \vdash T \subseteq &}
 & \text{$S$ is a subtype of $T$ in $\Gamma$}
    \end{array}
  \]
  Additionally, we have a derived judgment for substitution typing:
  \[
    \judge[\Gamma]{\sigma : \Delta} \qquad\qquad \text{$\sigma$ is a well-typed substitution from $\Delta$ to $\Gamma$}
  \]

\label{lem:wk-id-wt}
  If $\vdash \Gamma$, then $
  \wkjudge[\ensuremath{\textsf{id}}]{\Gamma : $}
.

\label{lem:wk-shift-wt}
  If $\vdash \Gamma$ and $\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}}$, then
  $\weakening[\Gamma, x_0 : S] \Uparrow \Gamma$.

\label{lem:wk-q-wt}
  If $
  \wkjudge[\phi]{\Delta : $}
 and $\typing[\Delta]{S}{\ensuremath{\texttt{Ty}_{i}}}$, then
  $\weakening[\Gamma, x_0 : S[\phi]] {q(\phi)} {\Delta, x_0 : S}$.

\label{lem:wk-comp-wt}
  If $
  \wkjudge[\psi]{\Delta : $}
 and $\weakening[\Delta] \phi \Theta$, then
  $
  \wkjudge[\phi \circ \psi]{\Theta : $}
.

\label{lem:wk-typing}
  The following are proved by mutual induction on the syntactic judgments:
  \begin{enumerate}
  \@idxitem If $\typing[\Gamma]{t}{T}$ and $\weakening[\Delta] \phi \Gamma$, then
    $\typing[\Delta]{t[\phi]}{T[\phi]}$.
  \@idxitem If $\tyequiv[\Gamma]{t}{t'}{T}$ and $\weakening[\Delta] \phi \Gamma$, then
    $\tyequiv[\Delta]{t[\phi]}{t'[\phi]}{T[\phi]}$.
  \@idxitem If $\subty[\Gamma]{S}{T}$ and $\weakening[\Delta] \phi \Gamma$, then
    $\subty[\Delta]{S[\phi]}{T[\phi]}$.
  \end{enumerate}

By mutual induction on the derivation of the syntactic judgment.
  We show representative cases for statement (1).

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{Var}]
    {\vdash \Gamma \\ y : T \in \Gamma}
    {\typing[\Gamma]{y}{T}}
  \end{mathpar}
  Then $y[\phi] = \phi(y)$.
  By the definition of $\weakening[\Delta] \phi \Gamma$, $\phi(y) : T[\phi] \in \Delta$.
  By \textsc{Var}, $\typing[\Delta]{\phi(y)}{T[\phi]}$.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{$\lambda$-I}]
    {\typing[\Gamma]{S'}{\ensuremath{\texttt{Ty}_{i}}} \\ \typing[\Gamma, y : S']{t}{T}}
    {\typing[\Gamma]{\lambda y.\,t}{\Pi(y:S').\,T}}
  \end{mathpar}
  We must show $\typing[\Delta]{(\lambda y.\,t)[\phi]}{(\Pi(y:S').\,T)[\phi]}$,
  i.e.\ $\typing[\Delta]{\lambda y.\,(t[q(\phi)])}{\Pi(y:S'[\phi]).\,(T[q(\phi)])}$.
  \begin{align*}
    &\typing[\Delta]{S'[\phi]}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by IH on first premise)} \\
    &\weakening[\Delta, y:S'[\phi]] {q(\phi)} {\Gamma, y:S'}
      && \text{(by \Cref{lem:wk-q-wt})} \\
    &\typing[\Delta, y:S'[\phi]]{t[q(\phi)]}{T[q(\phi)]}
      && \text{(by IH on second premise)} \\
    &\typing[\Delta]{\lambda y.\,(t[q(\phi)])}{\Pi(y:S'[\phi]).\,(T[q(\phi)])}
      && \text{(by \textsc{$\lambda$-I})}
  \end{align*}

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{$\lambda$-E}]
    {\typing[\Gamma]{S'}{\ensuremath{\texttt{Ty}_{i}}} \\ \typing[\Gamma, y:S']{T}{\ensuremath{\texttt{Ty}_{i}}} \\
     \typing[\Gamma]{r}{\Pi(y:S').\,T} \\ \typing[\Gamma]{s}{S'}}
    {\typing[\Gamma]{r\;s}{T[s/y]}}
  \end{mathpar}
  \begin{align*}
    &\typing[\Delta]{S'[\phi]}{\ensuremath{\texttt{Ty}_{i}}} && \text{(by IH)} \\
    &\typing[\Delta, y:S'[\phi]]{T[q(\phi)]}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by IH, using \Cref{lem:wk-q-wt})} \\
    &\typing[\Delta]{r[\phi]}{\Pi(y:S'[\phi]).\,(T[q(\phi)])} && \text{(by IH)} \\
    &\typing[\Delta]{s[\phi]}{S'[\phi]} && \text{(by IH)} \\
    &\typing[\Delta]{r[\phi]\;s[\phi]}{T[q(\phi)][s[\phi]/y]} && \text{(by \textsc{$\lambda$-E})}
  \end{align*}
  It remains to show $T[q(\phi)][s[\phi]/y] = T[s/y][\phi]$,
  which is \Cref{lem:subst-ext-comm}.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{Subsump}]
    {\typing[\Gamma]{T}{\ensuremath{\texttt{Ty}_{i}}} \\ \typing[\Gamma]{t}{S} \\ \subty[\Gamma]{S}{T}}
    {\typing[\Gamma]{t}{T}}
  \end{mathpar}
  \begin{align*}
    &\typing[\Delta]{T[\phi]}{\ensuremath{\texttt{Ty}_{i}}} && \text{(by IH)} \\
    &\typing[\Delta]{t[\phi]}{S[\phi]} && \text{(by IH)} \\
    &\subty[\Delta]{S[\phi]}{T[\phi]} && \text{(by IH, statement (3))} \\
    &\typing[\Delta]{t[\phi]}{T[\phi]} && \text{(by \textsc{Subsump})}
  \end{align*}

  \medskip
  We now show representative cases for statement (2).

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{$\Pi$-$\beta$}]
    {\typing[\Gamma]{S'}{\ensuremath{\texttt{Ty}_{i}}} \\ \typing[\Gamma, x:S']{T'}{\ensuremath{\texttt{Ty}_{i}}} \\
     \typing[\Gamma, x:S']{t}{T'} \\ \typing[\Gamma]{s}{S'}}
    {\tyequiv[\Gamma]{(\lambda x.\,t)\;s}{t[s/x]}{T'[s/x]}}
  \end{mathpar}
  We must show $\tyequiv[\Delta]{((\lambda x.\,t)\;s)[\phi]}{t[s/x][\phi]}{T'[s/x][\phi]}$.
  \begin{align*}
    &((\lambda x.\,t)\;s)[\phi] = (\lambda x.\,(t[q(\phi)]))\;(s[\phi])
  \end{align*}
  Now:
  \begin{align*}
    &\typing[\Delta]{S'[\phi]}{\ensuremath{\texttt{Ty}_{i}}} && \text{(by IH)} \\
    &\typing[\Delta, x:S'[\phi]]{T'[q(\phi)]}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by IH, using \Cref{lem:wk-q-wt})} \\
    &\typing[\Delta, x:S'[\phi]]{t[q(\phi)]}{T'[q(\phi)]}
      && \text{(by IH, using \Cref{lem:wk-q-wt})} \\
    &\typing[\Delta]{s[\phi]}{S'[\phi]} && \text{(by IH)} \\
    &\tyequiv[\Delta]{(\lambda x.\,(t[q(\phi)]))\;(s[\phi])}{t[q(\phi)][s[\phi]/x]}{T'[q(\phi)][s[\phi]/x]}
      && \text{(by \textsc{$\Pi$-$\beta$})}
  \end{align*}
  By \Cref{lem:subst-ext-comm}:
  $t[q(\phi)][s[\phi]/x] = t[s/x][\phi]$ and $T'[q(\phi)][s[\phi]/x] = T'[s/x][\phi]$.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{$\Pi$-$\eta$}]
    {\typing[\Gamma]{S'}{\ensuremath{\texttt{Ty}_{i}}} \\ \typing[\Gamma, x:S']{T'}{\ensuremath{\texttt{Ty}_{i}}} \\
     \typing[\Gamma]{t}{\Pi(x:S').\,T'}}
    {\tyequiv[\Gamma]{t}{\lambda x.\,(t[\Uparrow]\;x)}{\Pi(x:S').\,T'}}
  \end{mathpar}
  We must show $\tyequiv[\Delta]{t[\phi]}{(\lambda x.\,(t[\Uparrow]\;x))[\phi]}{(\Pi(x:S').\,T')[\phi]}$.
  Unfolding the right-hand side:
  \begin{align*}
    (\lambda x.\,(t[\Uparrow]\;x))[\phi]
    &= \lambda x.\,((t[\Uparrow]\;x)[q(\phi)]) \\
    &= \lambda x.\,(t[\Uparrow][q(\phi)]\;x) \\
    &= \lambda x.\,(t[\phi][\Uparrow]\;x)
      \tag{by \Cref{lem:wk-subst-comm}}
  \end{align*}
  \begin{align*}
    &\typing[\Delta]{S'[\phi]}{\ensuremath{\texttt{Ty}_{i}}} && \text{(by IH)} \\
    &\typing[\Delta, x:S'[\phi]]{T'[q(\phi)]}{\ensuremath{\texttt{Ty}_{i}}} && \text{(by IH, using \Cref{lem:wk-q-wt})} \\
    &\typing[\Delta]{t[\phi]}{\Pi(x:S'[\phi]).\,(T'[q(\phi)])} && \text{(by IH)} \\
    &\weakening[\Delta, x:S'[\phi]] \Uparrow \Delta
      && \text{(by \Cref{lem:wk-shift-wt})} \\
    &\tyequiv[\Delta]{t[\phi]}{\lambda x.\,(t[\phi][\Uparrow]\;x)}{\Pi(x:S'[\phi]).\,(T'[q(\phi)])}
      && \text{(by \textsc{$\Pi$-$\eta$})}
  \end{align*}

  \medskip
  We show a case for statement (3).

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{Sub-Pi}]
    {\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}} \\
     \typing[\Gamma]{S'}{\ensuremath{\texttt{Ty}_{i}}} \\
     \tyequiv[\Gamma]{S}{S'}{\ensuremath{\texttt{Ty}_{i}}} \\
     \typing[\Gamma, x:S]{T}{\ensuremath{\texttt{Ty}_{i}}} \\
     \typing[\Gamma, x:S']{T'}{\ensuremath{\texttt{Ty}_{i}}} \\
     \subty[\Gamma, x:S]{T}{T'}}
    {\subty[\Gamma]{\Pi(x:S).\,T}{\Pi(x:S').\,T'}}
  \end{mathpar}
  \begin{align*}
    &\typing[\Delta]{S[\phi]}{\ensuremath{\texttt{Ty}_{i}}} && \text{(by IH)} \\
    &\typing[\Delta]{S'[\phi]}{\ensuremath{\texttt{Ty}_{i}}} && \text{(by IH)} \\
    &\tyequiv[\Delta]{S[\phi]}{S'[\phi]}{\ensuremath{\texttt{Ty}_{i}}} && \text{(by IH, statement (2))} \\
    &\typing[\Delta, x:S[\phi]]{T[q(\phi)]}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by IH, using \Cref{lem:wk-q-wt})} \\
    &\typing[\Delta, x:S'[\phi]]{T'[q(\phi)]}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by IH, using \Cref{lem:wk-q-wt})} \\
    &\subty[\Delta, x:S[\phi]]{T[q(\phi)]}{T'[q(\phi)]}
      && \text{(by IH, statement (3), using \Cref{lem:wk-q-wt})} \\
    &\subty[\Delta]{\Pi(x:S[\phi]).\,(T[q(\phi)])}{\Pi(x:S'[\phi]).\,(T'[q(\phi)])}
      && \text{(by \textsc{Sub-Pi})}
  \end{align*}
  This is $\subty[\Delta]{(\Pi(x:S).\,T)[\phi]}{(\Pi(x:S').\,T')[\phi]}$.

  \medskip\noindent
  The remaining cases (\textsc{U-Wf}, \textsc{N-Wf}, \textsc{$\Pi$-Wf},
  \textsc{Ze-I}, \textsc{Su-I}, \textsc{N-E}, congruence rules,
  \textsc{Sub-Univ}, \textsc{Sub-Trans}, \textsc{Sub-Eq}) are analogous:
  apply the IH to each premise, using \Cref{lem:wk-q-wt} to construct
  the weakening for extended contexts, and re-apply the rule.

\label{lem:single-subst-wt}
  If $\vdash \Gamma$, $\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}}$, and $\typing[\Gamma]{s}{S}$, then
  $\judge[\Gamma]{(\ensuremath{\textsf{id}}, s/x) : (\Gamma, x : S)}$.

\label{lem:wk-subst-wt}
  If $\judge[\Gamma]{\sigma : \Delta}$ and $\weakening[\Gamma'] \phi \Gamma$, then
  $\judge[\Gamma']{\sigma[\phi] : \Delta}$.

We must show that $q(\sigma)$ maps each variable in $(\Delta, x_0 : S)$ to a well-typed
  term in $(\Gamma, x_0 : S[\sigma])$.
  We case-split on the lookup in $(\Delta, x_0 : S)$:
  \begin{itemize}
  \@idxitem $x_0 : S[\Uparrow] \in \Delta, x_0 : S$:
    \begin{align*}
      &q(\sigma)(x_0) = x_0 \\
      &S[\Uparrow][q(\sigma)] = S[\sigma][\Uparrow]
        && \text{(by \Cref{lem:wk-subst-comm})} \\
      &x_0 : S[\sigma][\Uparrow] \in \Gamma, x_0 : S[\sigma]
        && \text{(by lookup)}
    \end{align*}
    Hence $\typing[\Gamma, x_0 : S[\sigma]]{x_0}{S[\Uparrow][q(\sigma)]}$ by \textsc{Var}.
  \@idxitem $1{+}y : T[\Uparrow] \in \Delta, x_0 : S$ where $y : T \in \Delta$:
    \begin{align*}
      &q(\sigma)(1{+}y) = \sigma(y)[\Uparrow] \\
      &\typing[\Gamma]{\sigma(y)}{T[\sigma]}
        && \text{(from $\judge[\Gamma]{\sigma : \Delta}$)} \\
      &\typing[\Gamma, x_0 : S[\sigma]]{\sigma(y)[\Uparrow]}{T[\sigma][\Uparrow]}
        && \text{(by \Cref{lem:wk-typing} using \Cref{lem:wk-shift-wt})} \\
      &T[\Uparrow][q(\sigma)] = T[\sigma][\Uparrow]
        && \text{(by \Cref{lem:wk-subst-comm})}
    \end{align*}
    Hence $\typing[\Gamma, x_0 : S[\sigma]]{\sigma(y)[\Uparrow]}{T[\Uparrow][q(\sigma)]}$.
  \end{itemize}

\label{lem:subst-preserves}
  The following are proved by mutual induction on the syntactic judgments:
  \begin{enumerate}
  \@idxitem If $\typing[\Delta]{t}{T}$ and $\judge[\Gamma]{\sigma : \Delta}$, then
    $\typing[\Gamma]{t[\sigma]}{T[\sigma]}$.
  \@idxitem If $\tyequiv[\Delta]{t}{t'}{T}$ and $\judge[\Gamma]{\sigma : \Delta}$, then
    $\tyequiv[\Gamma]{t[\sigma]}{t'[\sigma]}{T[\sigma]}$.
  \@idxitem If $\subty[\Delta]{S}{T}$ and $\judge[\Gamma]{\sigma : \Delta}$, then
    $
  \IfNoValueTF {S[\sigma]}
  {\Gamma \vdash T[\sigma] \subseteq $}
  {S[\sigma] \vdash T[\sigma] \subseteq $}
.
  \end{enumerate}

By mutual induction on the derivation of the syntactic judgment.
  We show representative cases for statement (1).

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule
    {\vdash \Delta \\ x : T \in \Delta}
    {\typing[\Delta]{x}{T}}
  \end{mathpar}
  Then $t[\sigma] = x[\sigma] = \sigma(x)$.
  By the definition of $\judge[\Gamma]{\sigma : \Delta}$, we have
  $\typing[\Gamma]{\sigma(x)}{T[\sigma]}$, which is the goal.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule
    {\typing[\Delta]{S}{\ensuremath{\texttt{Ty}_{i}}} \\ \typing[\Delta, x : S]{t'}{T}}
    {\typing[\Delta]{\lambda x.\,t'}{\Pi(x:S).\,T}}
  \end{mathpar}
  We must show $\typing[\Gamma]{(\lambda x.\,t')[\sigma]}{(\Pi(x:S).\,T)[\sigma]}$.
  Unfolding:
  \begin{align*}
    (\lambda x.\,t')[\sigma] &= \lambda x.\,(t'[q(\sigma)]) \\
    (\Pi(x:S).\,T)[\sigma] &= \Pi(x:S[\sigma]).\,(T[q(\sigma)])
  \end{align*}
  Now:
  \begin{align*}
    &\typing[\Gamma]{S[\sigma]}{\ensuremath{\texttt{Ty}_{i}}} && \text{(by IH on first premise)} \\
    &\judge[\Gamma, x:S[\sigma]]{q(\sigma) : (\Delta, x:S)} && \text{(by \Cref{lem:q-subst-typing})} \\
    &\typing[\Gamma, x:S[\sigma]]{t'[q(\sigma)]}{T[q(\sigma)]} && \text{(by IH on second premise)} \\
    &\typing[\Gamma]{\lambda x.\,(t'[q(\sigma)])}{\Pi(x:S[\sigma]).\,(T[q(\sigma)])} && \text{(by \textsc{$\lambda$-I})}
  \end{align*}

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule
    {\typing[\Delta]{S}{\ensuremath{\texttt{Ty}_{i}}} \\ \typing[\Delta, x:S]{T}{\ensuremath{\texttt{Ty}_{i}}} \\ \typing[\Delta]{r}{\Pi(x:S).\,T} \\ \typing[\Delta]{s}{S}}
    {\typing[\Delta]{r\;s}{T[s/x]}}
  \end{mathpar}
  We must show $\typing[\Gamma]{(r\;s)[\sigma]}{(T[s/x])[\sigma]}$.
  Unfolding: $(r\;s)[\sigma] = r[\sigma]\;s[\sigma]$.
  \begin{align*}
    &\typing[\Gamma]{S[\sigma]}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by IH on first premise)} \\
    &\typing[\Gamma, x:S[\sigma]]{T[q(\sigma)]}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by IH on second premise using \Cref{lem:q-subst-typing})} \\
    &\typing[\Gamma]{r[\sigma]}{\Pi(x:S[\sigma]).\,(T[q(\sigma)])}
      && \text{(by IH on third premise)} \\
    &\typing[\Gamma]{s[\sigma]}{S[\sigma]}
      && \text{(by IH on fourth premise)} \\
    &\typing[\Gamma]{r[\sigma]\;s[\sigma]}{T[q(\sigma)][s[\sigma]/x]}
      && \text{(by \textsc{$\lambda$-E})}
  \end{align*}
  It remains to show $T[q(\sigma)][s[\sigma]/x] = (T[s/x])[\sigma]$,
  which is \Cref{lem:subst-ext-comm}.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule
    {\typing[\Delta]{T}{\ensuremath{\texttt{Ty}_{i}}} \\ \typing[\Delta]{t}{S} \\ \subty[\Delta]{S}{T}}
    {\typing[\Delta]{t}{T}}
  \end{mathpar}
  \begin{align*}
    &\typing[\Gamma]{T[\sigma]}{\ensuremath{\texttt{Ty}_{i}}} && \text{(by IH on first premise)} \\
    &\typing[\Gamma]{t[\sigma]}{S[\sigma]} && \text{(by IH on second premise)} \\
    &
  \IfNoValueTF {S[\sigma]}
  {\Gamma \vdash T[\sigma] \subseteq &}
  {S[\sigma] \vdash T[\sigma] \subseteq &}
& \text{(by IH, statement (3))} \\
    &\typing[\Gamma]{t[\sigma]}{T[\sigma]} && \text{(by \textsc{Subsump})}
  \end{align*}

  \medskip\noindent
  The remaining cases (\textsc{U-Wf}, \textsc{N-Wf}, \textsc{Ze-I}, \textsc{Su-I})
  are straightforward applications of the IH.

  \medskip
  We now show representative cases for statement (2).
  The congruence cases follow directly from the IH.
  We show the computation and uniqueness rules.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule
    {\typing[\Delta]{S}{\ensuremath{\texttt{Ty}_{i}}} \\ \typing[\Delta, x:S]{T}{\ensuremath{\texttt{Ty}_{i}}} \\
     \typing[\Delta, x:S]{t}{T} \\ \typing[\Delta]{s}{S}}
    {\tyequiv[\Delta]{(\lambda x.\,t)\;s}{t[s/x]}{T[s/x]}}
  \end{mathpar}
  We must show $\tyequiv[\Gamma]{((\lambda x.\,t)\;s)[\sigma]}{t[s/x][\sigma]}{T[s/x][\sigma]}$.
  Unfolding:
  \begin{align*}
    &((\lambda x.\,t)\;s)[\sigma] = (\lambda x.\,(t[q(\sigma)]))\;(s[\sigma]) \\
    t[s/x][\sigma]
    &= t[(\ensuremath{\textsf{id}},s/x) \circ \sigma]
      \tag{by \Cref{lem:subst-assoc}} \\
    &= t[\ensuremath{\textsf{id}} \circ \sigma, s[\sigma]/x]
      \tag{by \Cref{lem:ext-comp}} \\
    &= t[\sigma, s[\sigma]/x]
      \tag{by \Cref{lem:subst-cat} (left identity)}
  \end{align*}
  Now:
  \begin{align*}
    &\typing[\Gamma]{S[\sigma]}{\ensuremath{\texttt{Ty}_{i}}} && \text{(by IH)} \\
    &\typing[\Gamma, x:S[\sigma]]{T[q(\sigma)]}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by IH using \Cref{lem:q-subst-typing})} \\
    &\typing[\Gamma, x:S[\sigma]]{t[q(\sigma)]}{T[q(\sigma)]}
      && \text{(by IH using \Cref{lem:q-subst-typing})} \\
    &\typing[\Gamma]{s[\sigma]}{S[\sigma]} && \text{(by IH)} \\
    &\tyequiv[\Gamma]{(\lambda x.\,(t[q(\sigma)]))\;(s[\sigma])}{t[q(\sigma)][s[\sigma]/x]}{T[q(\sigma)][s[\sigma]/x]}
      && \text{(by \textsc{$\Pi$-$\beta$})}
  \end{align*}
  By \Cref{lem:subst-ext-comm}:
  $t[q(\sigma)][s[\sigma]/x] = (t[s/x])[\sigma]$ and
  $T[q(\sigma)][s[\sigma]/x] = (T[s/x])[\sigma]$.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule
    {\typing[\Delta]{S}{\ensuremath{\texttt{Ty}_{i}}} \\ \typing[\Delta, x:S]{T}{\ensuremath{\texttt{Ty}_{i}}} \\
     \typing[\Delta]{t}{\Pi(x:S).\,T}}
    {\tyequiv[\Delta]{t}{\lambda x.\,(t[\Uparrow]\;x)}{\Pi(x:S).\,T}}
  \end{mathpar}
  We must show $\tyequiv[\Gamma]{t[\sigma]}{(\lambda x.\,(t[\Uparrow]\;x))[\sigma]}{(\Pi(x:S).\,T)[\sigma]}$.
  Unfolding the right-hand side:
  \begin{align*}
    (\lambda x.\,(t[\Uparrow]\;x))[\sigma]
    &= \lambda x.\,((t[\Uparrow]\;x)[q(\sigma)]) \\
    &= \lambda x.\,(t[\Uparrow][q(\sigma)]\;x) \\
    &= \lambda x.\,(t[\sigma][\Uparrow]\;x)
      \tag{by \Cref{lem:wk-subst-comm}}
  \end{align*}
  Now:
  \begin{align*}
    &\typing[\Gamma]{S[\sigma]}{\ensuremath{\texttt{Ty}_{i}}} && \text{(by IH)} \\
    &\typing[\Gamma, x:S[\sigma]]{T[q(\sigma)]}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by IH using \Cref{lem:q-subst-typing})} \\
    &\typing[\Gamma]{t[\sigma]}{\Pi(x:S[\sigma]).\,(T[q(\sigma)])} && \text{(by IH)} \\
    &\tyequiv[\Gamma]{t[\sigma]}{\lambda x.\,(t[\sigma][\Uparrow]\;x)}{\Pi(x:S[\sigma]).\,(T[q(\sigma)])}
      && \text{(by \textsc{$\Pi$-$\eta$})}
  \end{align*}

  \medskip
  We now show representative cases for statement (3).

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule
    {\vdash \Delta \\ i \le j}
    {\subty[\Delta]{\ensuremath{\texttt{Ty}_{i}}}{\ensuremath{\texttt{Ty}_{j}}}}
  \end{mathpar}
  Then $\ensuremath{\texttt{Ty}_{i}}[\sigma] = \ensuremath{\texttt{Ty}_{i}}$ and $\ensuremath{\texttt{Ty}_{j}}[\sigma] = \ensuremath{\texttt{Ty}_{j}}$.
  From $\judge[\Gamma]{\sigma : \Delta}$, we have $\vdash \Gamma$.
  By \textsc{Sub-Univ}, $
  \IfNoValueTF {\ensuremath{\texttt{Ty}_{i}}}
  {\Gamma \vdash \ensuremath{\texttt{Ty}_{j}} \subseteq $}
  {\ensuremath{\texttt{Ty}_{i}} \vdash \ensuremath{\texttt{Ty}_{j}} \subseteq $}
.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule
    {\typing[\Delta]{S}{\ensuremath{\texttt{Ty}_{i}}} \\
     \typing[\Delta]{S'}{\ensuremath{\texttt{Ty}_{i}}} \\
     \tyequiv[\Delta]{S}{S'}{\ensuremath{\texttt{Ty}_{i}}} \\
     \typing[\Delta, x:S]{T}{\ensuremath{\texttt{Ty}_{i}}} \\
     \typing[\Delta, x:S']{T'}{\ensuremath{\texttt{Ty}_{i}}} \\
     \subty[\Delta, x:S]{T}{T'}}
    {\subty[\Delta]{\Pi(x:S).\,T}{\Pi(x:S').\,T'}}
  \end{mathpar}
  \begin{align*}
    &\typing[\Gamma]{S[\sigma]}{\ensuremath{\texttt{Ty}_{i}}} && \text{(by IH)} \\
    &\typing[\Gamma]{S'[\sigma]}{\ensuremath{\texttt{Ty}_{i}}} && \text{(by IH)} \\
    &\tyequiv[\Gamma]{S[\sigma]}{S'[\sigma]}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by IH, statement (2))} \\
    &\typing[\Gamma, x:S[\sigma]]{T[q(\sigma)]}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by IH using \Cref{lem:q-subst-typing})} \\
    &\typing[\Gamma, x:S'[\sigma]]{T'[q(\sigma)]}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by IH using \Cref{lem:q-subst-typing})} \\
    &\subty[\Gamma, x:S[\sigma]]{T[q(\sigma)]}{T'[q(\sigma)]}
      && \text{(by IH, statement (3), using \Cref{lem:q-subst-typing})} \\
    &
  \IfNoValueTF {\Pi(x:S[\sigma]).\,(T[q(\sigma)])}
  {\Gamma \vdash \Pi(x:S'[\sigma]).\,(T'[q(\sigma)]) \subseteq &}
  {\Pi(x:S[\sigma]).\,(T[q(\sigma)]) \vdash \Pi(x:S'[\sigma]).\,(T'[q(\sigma)]) \subseteq &}
& \text{(by \textsc{Sub-Pi})}
  \end{align*}
  This is $
  \IfNoValueTF {(\Pi(x:S).\,T)[\sigma]}
  {\Gamma \vdash (\Pi(x:S').\,T')[\sigma] \subseteq $}
  {(\Pi(x:S).\,T)[\sigma] \vdash (\Pi(x:S').\,T')[\sigma] \subseteq $}
.

  \medskip\noindent
  \textbf{Case} \textsc{Sub-Trans}: By two applications of the IH and \textsc{Sub-Trans}.

  \medskip\noindent
  \textbf{Case} \textsc{Sub-Eq}: By statement (2) and \textsc{Sub-Eq}.

\label{lem:subst-comp-wt}
  If $\judge[\Gamma]{\sigma : \Delta}$ and $\judge[\Gamma']{\tau : \Gamma}$, then
  $\judge[\Gamma']{\sigma \circ \tau : \Delta}$.

We must show: for all $x : T \in \Delta$,
  $\typing[\Gamma']{(\sigma \circ \tau)(x)}{T[\sigma \circ \tau]}$.
  \begin{align*}
    &\typing[\Gamma]{\sigma(x)}{T[\sigma]}
      && \text{(from $\judge[\Gamma]{\sigma : \Delta}$)} \\
    &\typing[\Gamma']{\sigma(x)[\tau]}{T[\sigma][\tau]}
      && \text{(by \Cref{lem:subst-preserves})} \\
    &(\sigma \circ \tau)(x) = \sigma(x)[\tau]
      && \text{(by definition)} \\
    &T[\sigma \circ \tau] = T[\sigma][\tau]
      && \text{(by \Cref{lem:subst-assoc})}
  \end{align*}

\label{cor:single-subst}
  If $\typing[\Gamma, x : S]{t}{T}$ and $\typing[\Gamma]{s}{S}$, then
  $\typing[\Gamma]{t[s/x]}{T[s/x]}$.

\label{lem:presup}
  \begin{itemize}
  \@idxitem If $\typing[\Gamma]{t}{T}$, then $\vdash \Gamma$ and $\typing[\Gamma]{T}{\ensuremath{\texttt{Ty}_{i}}}$
    for some~$i$.
  \@idxitem If $\tyequiv[\Gamma]{t}{t'}{T}$, then $\vdash \Gamma$,
    $\typing[\Gamma]{t}{T}$, $\typing[\Gamma]{t'}{T}$, and
    $\typing[\Gamma]{T}{\ensuremath{\texttt{Ty}_{i}}}$ for some~$i$.
  \@idxitem If $
  \IfNoValueTF {S}
  {\Gamma \vdash T \subseteq $}
  {S \vdash T \subseteq $}
, then $\vdash \Gamma$,
    $\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}}$ and $\typing[\Gamma]{T}{\ensuremath{\texttt{Ty}_{i}}}$ for some $i$.
  \end{itemize}

By mutual induction on the derivation.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule
    {\vdash \Gamma \\ x : T \in \Gamma}
    {\typing[\Gamma]{x}{T}}
  \end{mathpar}
  We have $\vdash \Gamma$ immediately from the premise.
  For $\typing[\Gamma]{T}{\ensuremath{\texttt{Ty}_{i}}}$, we do induction on $x : T \in \Gamma$.
  If $\Gamma = \Gamma', x : T$, then $\vdash \Gamma', x : T$ was derived by
  \textsc{Ctx-Ext} from $\typing[\Gamma']{T}{\ensuremath{\texttt{Ty}_{i}}}$; weakening gives
  $\typing[\Gamma]{T}{\ensuremath{\texttt{Ty}_{i}}}$.
  If $\Gamma = \Gamma', y : S$ and $x : T \in \Gamma'$, then by IH on the smaller
  context $\typing[\Gamma']{T}{\ensuremath{\texttt{Ty}_{i}}}$; weakening gives $\typing[\Gamma]{T}{\ensuremath{\texttt{Ty}_{i}}}$.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule
    {\vdash \Gamma}
    {\typing[\Gamma]{\ensuremath{\texttt{Ty}_{i}}}{\ensuremath{\texttt{Ty}_{1+i}}}}
  \end{mathpar}
  We have $\vdash \Gamma$ from the premise.
  The type of the conclusion is $\ensuremath{\texttt{Ty}_{1+i}}$, and $\typing[\Gamma]{\ensuremath{\texttt{Ty}_{1+i}}}{\ensuremath{\texttt{Ty}_{2+i}}}$
  by another application of \textsc{U-Wf}.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule
    {\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}} \\ \typing[\Gamma, x : S]{T}{\ensuremath{\texttt{Ty}_{i}}}}
    {\typing[\Gamma]{\Pi(x:S).\,T}{\ensuremath{\texttt{Ty}_{i}}}}
  \end{mathpar}
  \begin{align*}
    &\vdash \Gamma && \text{(by IH on first premise)} \\
    &\typing[\Gamma]{\ensuremath{\texttt{Ty}_{i}}}{\ensuremath{\texttt{Ty}_{1+i}}} && \text{(by \textsc{U-Wf})}
  \end{align*}

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule
    {\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}} \\ \typing[\Gamma, x : S]{t}{T}}
    {\typing[\Gamma]{\lambda x.\,t}{\Pi(x:S).\,T}}
  \end{mathpar}
  \begin{align*}
    &\vdash \Gamma && \text{(by IH on first premise)} \\
    &\typing[\Gamma, x:S]{T}{\ensuremath{\texttt{Ty}_{j}}} \text{ for some } j
      && \text{(by IH on second premise)} \\
    &\typing[\Gamma]{\Pi(x:S).\,T}{\ensuremath{\texttt{Ty}_{\max(i,j)}}}
      && \text{(by \textsc{$\Pi$-Wf} + \textsc{Subsump})}
  \end{align*}

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule
    {\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}} \\ \typing[\Gamma, x:S]{T}{\ensuremath{\texttt{Ty}_{i}}} \\\\ \typing[\Gamma]{r}{\Pi(x:S).\,T} \\ \typing[\Gamma]{s}{S}}
    {\typing[\Gamma]{r\;s}{T[s/x]}}
  \end{mathpar}
  \begin{align*}
    &\vdash \Gamma && \text{(by IH on first premise)} \\
    &\typing[\Gamma, x:S]{T}{\ensuremath{\texttt{Ty}_{i}}} && \text{(directly from second premise)} \\
    &\judge[\Gamma]{(\ensuremath{\textsf{id}}, s/x) : (\Gamma, x:S)} && \text{(by \Cref{lem:single-subst-wt})} \\
    &\typing[\Gamma]{T[s/x]}{\ensuremath{\texttt{Ty}_{i}}} && \text{(by \Cref{lem:subst-preserves})}
  \end{align*}

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule
    {\typing[\Gamma, x:\ensuremath{\texttt{Nat}}]{T}{\ensuremath{\texttt{Ty}_{i}}} \\
     \typing[\Gamma]{z}{T[\textsf{zero}/x]} \\
     \typing[\Gamma, x:\ensuremath{\texttt{Nat}}, y:T]{s}{T[\Uparrow \circ \Uparrow, \textsf{succ}~x_1/x]} \\
     \typing[\Gamma]{t}{\ensuremath{\texttt{Nat}}}}
    {\typing[\Gamma]{\ensuremath{\textsf{elim}_{\ensuremath{\texttt{Nat}}}~(x.\,T)~z~(x,y.\,s)~t}}{T[t/x]}}
  \end{mathpar}
  \begin{align*}
    &\vdash \Gamma && \text{(by IH on last premise)} \\
    &\judge[\Gamma]{(\ensuremath{\textsf{id}}, t/x) : (\Gamma, x:\ensuremath{\texttt{Nat}})} && \text{(by \Cref{lem:single-subst-wt})} \\
    &\typing[\Gamma]{T[t/x]}{\ensuremath{\texttt{Ty}_{i}}} && \text{(by \Cref{lem:subst-preserves} on first premise)}
  \end{align*}

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule
    {\typing[\Gamma]{T}{\ensuremath{\texttt{Ty}_{i}}} \\ \typing[\Gamma]{t}{S} \\ \subty{S}{T}}
    {\typing[\Gamma]{t}{T}}
  \end{mathpar}
  \begin{align*}
    &\vdash \Gamma && \text{(by IH on first premise)} \\
    &\typing[\Gamma]{T}{\ensuremath{\texttt{Ty}_{i}}} && \text{(directly from first premise)}
  \end{align*}

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{Var-Cong}]
    {\vdash \Gamma \\ x : T \in \Gamma}
    {\tyequiv[\Gamma]{x}{x}{T}}
  \end{mathpar}
  We have $\vdash \Gamma$ from the premise.
  $\typing[\Gamma]{x}{T}$ by \textsc{Var}.
  $\typing[\Gamma]{T}{\ensuremath{\texttt{Ty}_{i}}}$ by the same argument as the \textsc{Var} typing case above.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{$\Pi$-$\beta$}]
    {\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}} \\ \typing[\Gamma, x:S]{T}{\ensuremath{\texttt{Ty}_{i}}} \\
     \typing[\Gamma, x:S]{t}{T} \\ \typing[\Gamma]{s}{S}}
    {\tyequiv[\Gamma]{(\lambda x.\,t)\;s}{t[s/x]}{T[s/x]}}
  \end{mathpar}
  \begin{align*}
    &\vdash \Gamma && \text{(by IH on first premise)} \\
    &\typing[\Gamma]{(\lambda x.\,t)\;s}{T[s/x]}
      && \text{(by \textsc{$\lambda$-E} on \textsc{$\lambda$-I})} \\
    &\typing[\Gamma]{t[s/x]}{T[s/x]}
      && \text{(by \Cref{cor:single-subst} on third premise)} \\
    &\typing[\Gamma]{T[s/x]}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by \Cref{cor:single-subst} on second premise)}
  \end{align*}

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{$\Pi$-$\eta$}]
    {\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}} \\ \typing[\Gamma, x:S]{T}{\ensuremath{\texttt{Ty}_{i}}} \\
     \typing[\Gamma]{t}{\Pi(x:S).\,T}}
    {\tyequiv[\Gamma]{t}{\lambda x.\,(t[\Uparrow]\;x)}{\Pi(x:S).\,T}}
  \end{mathpar}
  \begin{align*}
    &\vdash \Gamma && \text{(by IH on first premise)} \\
    &\typing[\Gamma]{t}{\Pi(x:S).\,T} && \text{(directly from third premise)} \\
    &\weakening[\Gamma, x:S] \Uparrow \Gamma
      && \text{(by \Cref{lem:wk-shift-wt})} \\
    &\typing[\Gamma, x:S]{t[\Uparrow]}{\Pi(x:S[\Uparrow]).\,(T[q(\Uparrow)])}
      && \text{(by \Cref{lem:wk-typing})} \\
    &x_0 : S[\Uparrow] \in \Gamma, x_0 : S
      && \text{(by lookup)} \\
    &\typing[\Gamma, x:S]{x}{S[\Uparrow]}
      && \text{(by \textsc{Var})} \\
    &\typing[\Gamma, x:S]{t[\Uparrow]\;x}{T[q(\Uparrow)][x/x]}
      && \text{(by \textsc{$\lambda$-E})} \\
    &T[q(\Uparrow)][x/x] = T[q(\Uparrow)][\ensuremath{\textsf{id}}, x/x] = T[\Uparrow, x/x]
      && \text{(by \Cref{lem:q-ext})} \\
    &(\Uparrow, x/x) = \ensuremath{\textsf{id}}
      && \text{(by \Cref{lem:subst-ext-eta} at $\sigma = \ensuremath{\textsf{id}}$)} \\
    &T[\Uparrow, x/x] = T[\ensuremath{\textsf{id}}] = T
      && \text{(by \Cref{lem:subst-id})} \\
    &\typing[\Gamma, x:S]{t[\Uparrow]\;x}{T}
      \\
    &\typing[\Gamma]{\lambda x.\,(t[\Uparrow]\;x)}{\Pi(x:S).\,T}
      && \text{(by \textsc{$\lambda$-I})} \\
    &\typing[\Gamma]{\Pi(x:S).\,T}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by \textsc{$\Pi$-Wf} on first two premises)}
  \end{align*}

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{Tm-Subsump}]
    {\typing[\Gamma]{T}{\ensuremath{\texttt{Ty}_{i}}} \\ \tyequiv[\Gamma]{t}{t'}{S} \\ \subty{S}{T}}
    {\tyequiv[\Gamma]{t}{t'}{T}}
  \end{mathpar}
  \begin{align*}
    &\vdash \Gamma && \text{(by IH on first premise)} \\
    &\typing[\Gamma]{t}{S} \text{ and } \typing[\Gamma]{t'}{S}
      && \text{(by IH on second premise)} \\
    &\typing[\Gamma]{t}{T} \text{ and } \typing[\Gamma]{t'}{T}
      && \text{(by \textsc{Subsump} with third premise)} \\
    &\typing[\Gamma]{T}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(directly from first premise)}
  \end{align*}

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{Sub-Pi}]
    {\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}} \\
     \typing[\Gamma]{S'}{\ensuremath{\texttt{Ty}_{i}}} \\
     \tyequiv[\Gamma]{S}{S'}{\ensuremath{\texttt{Ty}_{i}}} \\
     \typing[\Gamma, x:S]{T}{\ensuremath{\texttt{Ty}_{i}}} \\
     \typing[\Gamma, x:S']{T'}{\ensuremath{\texttt{Ty}_{i}}} \\
     \subty[\Gamma, x:S]{T}{T'}}
    {\subty[\Gamma]{\Pi(x:S).\,T}{\Pi(x:S').\,T'}}
  \end{mathpar}
  \begin{align*}
    &\vdash \Gamma && \text{(by IH on first premise)} \\
    &\typing[\Gamma]{\Pi(x:S).\,T}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by \textsc{$\Pi$-Wf} on premises 1 and 4)} \\
    &\typing[\Gamma]{\Pi(x:S').\,T'}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by \textsc{$\Pi$-Wf} on premises 2 and 5, using \textsc{Subsump})}
  \end{align*}

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{Sub-Univ}]
    {\vdash \Gamma \\ i \le j}
    {\subty{\ensuremath{\texttt{Ty}_{i}}}{\ensuremath{\texttt{Ty}_{j}}}}
  \end{mathpar}
  \begin{align*}
    &\vdash \Gamma && \text{(directly from premise)} \\
    &\typing[\Gamma]{\ensuremath{\texttt{Ty}_{i}}}{\ensuremath{\texttt{Ty}_{1+i}}}
      && \text{(by \textsc{U-Wf})} \\
    &\typing[\Gamma]{\ensuremath{\texttt{Ty}_{j}}}{\ensuremath{\texttt{Ty}_{1+j}}}
      && \text{(by \textsc{U-Wf})} \\
    &\typing[\Gamma]{\ensuremath{\texttt{Ty}_{i}}}{\ensuremath{\texttt{Ty}_{1+j}}} \text{ and } \typing[\Gamma]{\ensuremath{\texttt{Ty}_{j}}}{\ensuremath{\texttt{Ty}_{1+j}}}
      && \text{(by \textsc{Subsump} with \textsc{Sub-Univ}, since $1+i \le 1+j$)}
  \end{align*}

  \medskip\noindent
  The remaining cases follow similar patterns.

\label{def:subst-equiv}
  $\judge[\Gamma]{\sigma \approx \sigma' : \Delta}$ holds when:
  \begin{enumerate}
  \@idxitem $\judge[\Gamma]{\sigma : \Delta}$ and
    $\judge[\Gamma]{\sigma' : \Delta}$, and
  \@idxitem for every $x : T \in \Delta$,
    $\tyequiv[\Gamma]{\sigma(x)}{\sigma'(x)}{T[\sigma]}$.
  \end{enumerate}

By mutual induction on the syntactic derivation, parallel to
  \Cref{lem:subst-preserves}. We show representative cases for
  statement~(1).

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule
    {\vdash \Delta \\ x : T \in \Delta}
    {\typing[\Delta]{x}{T}}
  \end{mathpar}
  Then $x[\sigma] = \sigma(x)$ and $x[\sigma'] = \sigma'(x)$.
  \begin{align*}
    &\tyequiv[\Gamma]{\sigma(x)}{\sigma'(x)}{T[\sigma]}
      && \text{(by clause~(2) of \Cref{def:subst-equiv})}
  \end{align*}

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule
    {\typing[\Delta]{S}{\ensuremath{\texttt{Ty}_{i}}} \\ \typing[\Delta, x : S]{t}{T}}
    {\typing[\Delta]{\lambda x.\,t}{\Pi(x:S).\,T}}
  \end{mathpar}
  We must show
  $\tyequiv[\Gamma]{(\lambda x.\,t)[\sigma]}{(\lambda x.\,t)[\sigma']}
  {(\Pi(x:S).\,T)[\sigma]}$.
  We first lift the equivalence under $q$:
  \begin{align*}
    &\judge[\Gamma, x:S[\sigma]]{q(\sigma) \approx q(\sigma') :
      (\Delta, x:S)}
      && \text{(by \Cref{lem:q-subst-equiv})} \\
    &\tyequiv[\Gamma, x:S[\sigma]]{t[q(\sigma)]}{t[q(\sigma')]}
      {T[q(\sigma)]}
      && \text{(by IH on the second premise)} \\
    &\tyequiv[\Gamma]{S[\sigma]}{S[\sigma']}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by IH on the first premise)} \\
    &\tyequiv[\Gamma]{\lambda x.\,(t[q(\sigma)])}
      {\lambda x.\,(t[q(\sigma')])}
      {\Pi(x:S[\sigma]).\,(T[q(\sigma)])}
      && \text{(by \textsc{$\lambda$-Cong})} \\
    &(\lambda x.\,t)[\sigma] = \lambda x.\,(t[q(\sigma)]),\;
      (\lambda x.\,t)[\sigma'] = \lambda x.\,(t[q(\sigma')])
      && \text{(syntactic substitution)} \\
    &(\Pi(x:S).\,T)[\sigma] = \Pi(x:S[\sigma]).\,(T[q(\sigma)])
      && \text{(syntactic substitution)}
  \end{align*}

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule
    {\typing[\Delta]{S}{\ensuremath{\texttt{Ty}_{i}}} \\ \typing[\Delta, x:S]{T}{\ensuremath{\texttt{Ty}_{i}}} \\\\
     \typing[\Delta]{r}{\Pi(x:S).\,T} \\ \typing[\Delta]{s}{S}}
    {\typing[\Delta]{r\;s}{T[s/x]}}
  \end{mathpar}
  We must show
  $\tyequiv[\Gamma]{(r\;s)[\sigma]}{(r\;s)[\sigma']}{T[s/x][\sigma]}$.
  \begin{align*}
    &\tyequiv[\Gamma]{r[\sigma]}{r[\sigma']}
      {(\Pi(x:S).\,T)[\sigma]}
      && \text{(by IH on the third premise)} \\
    &\tyequiv[\Gamma]{s[\sigma]}{s[\sigma']}{S[\sigma]}
      && \text{(by IH on the fourth premise)} \\
    &\tyequiv[\Gamma]{r[\sigma]\;s[\sigma]}{r[\sigma']\;s[\sigma']}
      {T[q(\sigma)][s[\sigma]/x]}
      && \text{(by \textsc{App-Cong})} \\
    &(r\;s)[\sigma] = r[\sigma]\;s[\sigma],\;
      (r\;s)[\sigma'] = r[\sigma']\;s[\sigma']
      && \text{(syntactic substitution on application)} \\
    &T[q(\sigma)][s[\sigma]/x] = T[s/x][\sigma]
      && \text{(by \Cref{lem:subst-ext-comm})}
  \end{align*}

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{U-Wf}]
    {\vdash \Delta}
    {\typing[\Delta]{\ensuremath{\texttt{Ty}_{i}}}{\ensuremath{\texttt{Ty}_{1+i}}}}
  \end{mathpar}
  $\ensuremath{\texttt{Ty}_{i}}[\sigma] = \ensuremath{\texttt{Ty}_{i}}$ and $\ensuremath{\texttt{Ty}_{i}}[\sigma'] = \ensuremath{\texttt{Ty}_{i}}$.
  \begin{align*}
    &\vdash \Gamma
      && \text{(from $\judge[\Gamma]{\sigma : \Delta}$ inside
        \Cref{def:subst-equiv})} \\
    &\tyequiv[\Gamma]{\ensuremath{\texttt{Ty}_{i}}}{\ensuremath{\texttt{Ty}_{i}}}{\ensuremath{\texttt{Ty}_{1+i}}}
      && \text{(by \textsc{U-Cong})}
  \end{align*}

  \medskip\noindent
  \textbf{Case} \textsc{N-Wf}: Analogous to \textsc{U-Wf}, with
  $\ensuremath{\texttt{Nat}}[\sigma] = \ensuremath{\texttt{Nat}} = \ensuremath{\texttt{Nat}}[\sigma']$ and reflexivity by
  \textsc{N-Cong}.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{$\Pi$-Wf}]
    {\typing[\Delta]{S}{\ensuremath{\texttt{Ty}_{i}}} \\ \typing[\Delta, x:S]{T}{\ensuremath{\texttt{Ty}_{i}}}}
    {\typing[\Delta]{\Pi(x:S).\,T}{\ensuremath{\texttt{Ty}_{i}}}}
  \end{mathpar}
  \begin{align*}
    &\tyequiv[\Gamma]{S[\sigma]}{S[\sigma']}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by IH on first premise)} \\
    &\judge[\Gamma, x:S[\sigma]]{q(\sigma) \approx q(\sigma') :
      (\Delta, x:S)}
      && \text{(by lifting, as in the $\lambda$-I case)} \\
    &\tyequiv[\Gamma, x:S[\sigma]]{T[q(\sigma)]}{T[q(\sigma')]}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by IH on second premise)} \\
    &\tyequiv[\Gamma]{\Pi(x:S[\sigma]).\,(T[q(\sigma)])}
      {\Pi(x:S[\sigma']).\,(T[q(\sigma')])}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by \textsc{$\Pi$-Cong})} \\
    &(\Pi(x:S).\,T)[\sigma] = \Pi(x:S[\sigma]).\,(T[q(\sigma)])
      && \text{(syntactic substitution on $\Pi$)}
  \end{align*}

  \medskip\noindent
  \textbf{Case} \textsc{Ze-I}: $\textsf{zero}[\sigma] = \textsf{zero} = \textsf{zero}[\sigma']$;
  apply \textsc{Ze-Cong}. The type
  $\ensuremath{\texttt{Nat}}[\sigma] = \ensuremath{\texttt{Nat}}$.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{Su-I}]
    {\typing[\Delta]{t}{\ensuremath{\texttt{Nat}}}}
    {\typing[\Delta]{\textsf{succ}~t}{\ensuremath{\texttt{Nat}}}}
  \end{mathpar}
  \begin{align*}
    &\tyequiv[\Gamma]{t[\sigma]}{t[\sigma']}{\ensuremath{\texttt{Nat}}}
      && \text{(by IH on premise; using $\ensuremath{\texttt{Nat}}[\sigma] = \ensuremath{\texttt{Nat}}$)} \\
    &\tyequiv[\Gamma]{\textsf{succ}~t[\sigma]}{\textsf{succ}~t[\sigma']}{\ensuremath{\texttt{Nat}}}
      && \text{(by \textsc{Su-Cong})} \\
    &(\textsf{succ}~t)[\sigma] = \textsf{succ}~t[\sigma],\;
      (\textsf{succ}~t)[\sigma'] = \textsf{succ}~t[\sigma']
      && \text{(syntactic substitution on $\textsf{succ}~$)}
  \end{align*}

  \medskip\noindent
  \textbf{Case} \textsc{N-E}: analogous to \textsc{$\lambda$-E},
  applying the IH to each premise (motive, zero branch, step branch,
  scrutinee), lifting via $q(\sigma) \approx q(\sigma')$ and
  $q^2(\sigma) \approx q^2(\sigma')$, and concluding by \textsc{N-E-Cong}.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{Subsump}]
    {\typing[\Delta]{T}{\ensuremath{\texttt{Ty}_{i}}} \\
     \typing[\Delta]{t}{S} \\
     \subty[\Delta]{S}{T}}
    {\typing[\Delta]{t}{T}}
  \end{mathpar}
  \begin{align*}
    &\tyequiv[\Gamma]{t[\sigma]}{t[\sigma']}{S[\sigma]}
      && \text{(by IH on second premise)} \\
    &\subty[\Gamma]{S[\sigma]}{T[\sigma]}
      && \text{(by IH on third premise via statement~(3),} \\
    & && \text{instantiated at $\sigma \approx \sigma$, reflexive)} \\
    &\typing[\Gamma]{T[\sigma]}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by \Cref{lem:subst-preserves} on first premise)} \\
    &\tyequiv[\Gamma]{t[\sigma]}{t[\sigma']}{T[\sigma]}
      && \text{(by \textsc{Tm-Subsump})}
  \end{align*}

  \medskip
  \textbf{Statement~(2): term-equality preservation.} By induction on
  the term-equality derivation.

  \medskip\noindent
  \textbf{Case} (Congruence rules: \textsc{Var-Cong}, \textsc{U-Cong},
  \textsc{N-Cong}, \textsc{$\Pi$-Cong}, \textsc{Ze-Cong},
  \textsc{Su-Cong}, \textsc{$\lambda$-Cong}, \textsc{App-Cong},
  \textsc{N-E-Cong}). Each follows by IH on the premises and the same
  congruence rule, with substitution-on-syntax computed exactly as in
  statement~(1).

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{$\Pi$-$\beta$}]
    {\typing[\Delta]{S}{\ensuremath{\texttt{Ty}_{i}}} \\ \typing[\Delta, x:S]{T}{\ensuremath{\texttt{Ty}_{i}}} \\
     \typing[\Delta, x:S]{t}{T} \\ \typing[\Delta]{s}{S}}
    {\tyequiv[\Delta]{(\lambda x.\,t)\;s}{t[s/x]}{T[s/x]}}
  \end{mathpar}
  We must show
  $\tyequiv[\Gamma]{((\lambda x.\,t)\;s)[\sigma]}{t[s/x][\sigma']}
  {T[s/x][\sigma]}$.

  By \Cref{lem:q-subst-equiv} on $\sigma \approx \sigma'$ at $S$:
  $\judge[\Gamma, x:S[\sigma]]{q(\sigma) \approx q(\sigma') :
    (\Delta, x:S)}$. Apply IH statement~(1) to the third premise
  $\typing[\Delta, x:S]{t}{T}$ and to the fourth premise
  $\typing[\Delta]{s}{S}$:
  \begin{align*}
    &\tyequiv[\Gamma, x:S[\sigma]]{t[q(\sigma)]}{t[q(\sigma')]}
      {T[q(\sigma)]}
      && \text{(by IH on third premise)} \\
    &\tyequiv[\Gamma]{s[\sigma]}{s[\sigma']}{S[\sigma]}
      && \text{(by IH on fourth premise)}
  \end{align*}
  Build the head-extended substitution equivalence:
  \begin{align*}
    &\judge[\Gamma]{(\sigma, s[\sigma]/x) \approx (\sigma', s[\sigma']/x)
      : (\Delta, x:S)}
      && \text{(at every $y \in \Delta$, both yield $\sigma(y),
        \sigma'(y)$,} \\
    & && \text{equated by \Cref{def:subst-equiv} clause~(2) on
        $\sigma \approx \sigma'$;} \\
    & && \text{at $x$, the heads $s[\sigma], s[\sigma']$ are equated
        above)}
  \end{align*}
  Apply IH statement~(1) on the third premise
  $\typing[\Delta, x:S]{t}{T}$ at this equivalence:
  \begin{align*}
    &\tyequiv[\Gamma]{t[(\sigma, s[\sigma]/x)]}
      {t[(\sigma', s[\sigma']/x)]}
      {T[(\sigma, s[\sigma]/x)]}
      && \text{(by IH on third premise at the head-extended
        equivalence)} \\
    &t[s/x][\sigma] = t[(\sigma, s[\sigma]/x)]
      && \text{(by \Cref{lem:subst-ext-comm})} \\
    &t[s/x][\sigma'] = t[(\sigma', s[\sigma']/x)]
      && \text{(by \Cref{lem:subst-ext-comm})} \\
    &T[s/x][\sigma] = T[(\sigma, s[\sigma]/x)]
      && \text{(by \Cref{lem:subst-ext-comm})} \\
    &\tyequiv[\Gamma]{t[s/x][\sigma]}{t[s/x][\sigma']}{T[s/x][\sigma]}
      && \text{(rewriting the previous equality line)} \\
    &\tyequiv[\Gamma]{((\lambda x.\,t)\;s)[\sigma]}{t[s/x][\sigma]}
      {T[s/x][\sigma]}
      && \text{(by \Cref{lem:subst-preserves} statement~(2) on the
        original $\beta$, at $\sigma$)} \\
    &\tyequiv[\Gamma]{((\lambda x.\,t)\;s)[\sigma]}{t[s/x][\sigma']}
      {T[s/x][\sigma]}
      && \text{(by \textsc{Tm-Trans})}
  \end{align*}

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{$\Pi$-$\eta$}]
    {\typing[\Delta]{S}{\ensuremath{\texttt{Ty}_{i}}} \\
     \typing[\Delta, x:S]{T}{\ensuremath{\texttt{Ty}_{i}}} \\
     \typing[\Delta]{t}{\Pi(x:S).\,T}}
    {\tyequiv[\Delta]{t}{\lambda x.\,(t[\Uparrow]\;x)}
      {\Pi(x:S).\,T}}
  \end{mathpar}
  We must show
  $\tyequiv[\Gamma]{t[\sigma]}{(\lambda x.\,(t[\Uparrow]\;x))[\sigma']}
  {(\Pi(x:S).\,T)[\sigma]}$.

  By IH statement~(1) on the third premise:
  \begin{align*}
    &\tyequiv[\Gamma]{t[\sigma]}{t[\sigma']}{(\Pi(x:S).\,T)[\sigma]}
      && \text{(by IH on $\typing[\Delta]{t}{\Pi(x:S).\,T}$)}
  \end{align*}
  Apply \Cref{lem:subst-preserves} statement~(2) on the original
  $\eta$-rule at $\sigma'$ (a well-typed substitution since
  $\judge[\Gamma]{\sigma' : \Delta}$ by \Cref{def:subst-equiv} clause~(1)):
  \begin{align*}
    &\tyequiv[\Gamma]{t[\sigma']}{(\lambda x.\,(t[\Uparrow]\;x))[\sigma']}
      {(\Pi(x:S).\,T)[\sigma']}
      && \text{(by \Cref{lem:subst-preserves} statement~(2)
        on $\eta$ at $\sigma'$)}
  \end{align*}
  Bridge the type from $\sigma'$ to $\sigma$ via the $\Pi$-Wf case of
  statement~(1), already proved on
  $\typing[\Delta]{\Pi(x:S).\,T}{\ensuremath{\texttt{Ty}_{i}}}$ (derivable from the first two
  $\eta$-premises by \textsc{$\Pi$-Wf}):
  \begin{align*}
    &\tyequiv[\Gamma]{(\Pi(x:S).\,T)[\sigma]}{(\Pi(x:S).\,T)[\sigma']}
      {\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by the $\Pi$-Wf case of statement~(1))} \\
    &\tyequiv[\Gamma]{t[\sigma']}{(\lambda x.\,(t[\Uparrow]\;x))[\sigma']}
      {(\Pi(x:S).\,T)[\sigma]}
      && \text{(by \textsc{Tm-Subsump} with \textsc{Sub-Eq})} \\
    &\tyequiv[\Gamma]{t[\sigma]}{(\lambda x.\,(t[\Uparrow]\;x))[\sigma']}
      {(\Pi(x:S).\,T)[\sigma]}
      && \text{(by \textsc{Tm-Trans})}
  \end{align*}

  \medskip\noindent
  \textbf{Case} \textsc{N-$\beta$-ze}, \textsc{N-$\beta$-su}: analogous
  to $\beta$ above. Apply \Cref{lem:subst-preserves} statement~(2) to
  the original reduction rule at $\sigma$ to get equality at the
  contractum-substituted-by-$\sigma$. Then apply IH (statement~(1)) to
  the typing of the contractum (derivable from the reduction rule and
  \Cref{lem:presup}) to bridge the contractum from $\sigma$ to
  $\sigma'$.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{Tm-Sym}]
    {\tyequiv[\Delta]{t}{t'}{T}}
    {\tyequiv[\Delta]{t'}{t}{T}}
  \end{mathpar}
  By IH on the premise (with the roles of $\sigma, \sigma'$ swapped):
  $\tyequiv[\Gamma]{t[\sigma']}{t'[\sigma]}{T[\sigma']}$. By
  \Cref{lem:subst-preserves} statement~(2), $\tyequiv[\Gamma]{T[\sigma]}
  {T[\sigma']}{\ensuremath{\texttt{Ty}_{i}}}$ (from the reflexive closure on the
  type-formation of $T$ via presupposition). By \textsc{Tm-Subsump}
  with \textsc{Sub-Eq}, transport to the goal type $T[\sigma]$:
  $\tyequiv[\Gamma]{t'[\sigma]}{t[\sigma']}{T[\sigma]}$, then apply
  \textsc{Tm-Sym}.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{Tm-Trans}]
    {\tyequiv[\Delta]{t}{t'}{T} \\\\ \tyequiv[\Delta]{t'}{t''}{T}}
    {\tyequiv[\Delta]{t}{t''}{T}}
  \end{mathpar}
  By IH on the first premise:
  $\tyequiv[\Gamma]{t[\sigma]}{t'[\sigma]}{T[\sigma]}$ (instantiated at
  $\sigma \approx \sigma$, reflexive). By IH on the second premise:
  $\tyequiv[\Gamma]{t'[\sigma]}{t''[\sigma']}{T[\sigma]}$. By
  \textsc{Tm-Trans}: $\tyequiv[\Gamma]{t[\sigma]}{t''[\sigma']}{T[\sigma]}$.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{Tm-Subsump}]
    {\typing[\Delta]{T}{\ensuremath{\texttt{Ty}_{i}}} \\\\
     \tyequiv[\Delta]{t}{t'}{S} \\
     \subty[\Delta]{S}{T}}
    {\tyequiv[\Delta]{t}{t'}{T}}
  \end{mathpar}
  \begin{align*}
    &\tyequiv[\Gamma]{t[\sigma]}{t'[\sigma']}{S[\sigma]}
      && \text{(by IH on the second premise)} \\
    &\subty[\Gamma]{S[\sigma]}{T[\sigma]}
      && \text{(by IH on the third premise via statement~(3),
        instantiated} \\
    & && \text{at $\sigma \approx \sigma$, reflexive)} \\
    &\typing[\Gamma]{T[\sigma]}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by \Cref{lem:subst-preserves} on the first premise)} \\
    &\tyequiv[\Gamma]{t[\sigma]}{t'[\sigma']}{T[\sigma]}
      && \text{(by \textsc{Tm-Subsump})}
  \end{align*}

  \medskip
  \textbf{Statement~(3): subtyping preservation.} By induction on the
  subtyping derivation.

  \medskip\noindent
  \textbf{Case} \textsc{Sub-Univ}: $\ensuremath{\texttt{Ty}_{i}}[\sigma] = \ensuremath{\texttt{Ty}_{i}}$,
  $\ensuremath{\texttt{Ty}_{j}}[\sigma'] = \ensuremath{\texttt{Ty}_{j}}$, and the conclusion follows from
  \textsc{Sub-Univ} at $i \le j$ (the same hypothesis), with $\vdash
  \Gamma$ from $\judge[\Gamma]{\sigma : \Delta}$.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{Sub-Pi}]
    {\typing[\Delta]{S}{\ensuremath{\texttt{Ty}_{i}}} \\
     \typing[\Delta]{S'}{\ensuremath{\texttt{Ty}_{i}}} \\
     \tyequiv[\Delta]{S}{S'}{\ensuremath{\texttt{Ty}_{i}}} \\\\
     \typing[\Delta, x:S]{T}{\ensuremath{\texttt{Ty}_{i}}} \\
     \typing[\Delta, x:S']{T'}{\ensuremath{\texttt{Ty}_{i}}} \\
     \subty[\Delta, x:S]{T}{T'}}
    {\subty[\Delta]{\Pi(x:S).\,T}{\Pi(x:S').\,T'}}
  \end{mathpar}
  \begin{align*}
    &\tyequiv[\Gamma]{S[\sigma]}{S'[\sigma']}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by IH on third premise, statement~(2))} \\
    &\judge[\Gamma, x:S[\sigma]]{q(\sigma) \approx q(\sigma') :
      (\Delta, x:S)}
      && \text{(by lifting)} \\
    &\subty[\Gamma, x:S[\sigma]]{T[q(\sigma)]}{T'[q(\sigma')]}
      && \text{(by IH on sixth premise)} \\
    &\subty[\Gamma]{\Pi(x:S[\sigma]).\,(T[q(\sigma)])}
      {\Pi(x:S'[\sigma']).\,(T'[q(\sigma')])}
      && \text{(by \textsc{Sub-Pi} on the previous lines and IH on
        the well-formedness} \\
    & && \text{premises 1, 2, 4, 5)} \\
    &(\Pi(x:S).\,T)[\sigma] = \Pi(x:S[\sigma]).\,(T[q(\sigma)])
      && \text{(syntactic)} \\
    &(\Pi(x:S').\,T')[\sigma'] = \Pi(x:S'[\sigma']).\,(T'[q(\sigma')])
      && \text{(syntactic)}
  \end{align*}

  \medskip\noindent
  \textbf{Case} \textsc{Sub-Trans}: by IH on both premises and
  \textsc{Sub-Trans}, using a shared middle subtype evaluated at
  $\sigma$ on both sides.

  \medskip\noindent
  \textbf{Case} \textsc{Sub-Eq}: by IH on the premise via statement~(2)
  and \textsc{Sub-Eq}.

\label{def:per-nf}
  Two annotated normal forms $d, d' \in \ensuremath{\mathrm{D}}_f$ are related in $\textsf{Nf}$ if they read back to
  the same syntactic normal form at every name supply level:
  \[
    d \approx d' \in \textsf{Nf}
    \;:=\;
    \forall\, n \in \mathbb{N}.\; \exists\, w.\;
    \textsf{R}^{\textsf{Nf}}_n(d) \searrow w \;\wedge\; \textsf{R}^{\textsf{Nf}}_n(d') \searrow w
  \]

\label{def:per-ne}
  Two neutral domain values $e, e'$ are related in $\textsf{Ne}$ if they read back to the same
  neutral normal form at every name supply level:
  \[
    e \approx e' \in \textsf{Ne}
    \;:=\;
    \forall\, n \in \mathbb{N}.\; \exists\, u.\;
    \textsf{R}^{\textsf{Ne}}_n(e) \searrow u \;\wedge\; \textsf{R}^{\textsf{Ne}}_n(e') \searrow u
  \]

\label{def:per-ty}
  Two domain values $A, A'$ representing types are related in $\textsf{Ty}$ if they
  read back to the same type normal form:
  \[
    A \approx A' \in \textsf{Ty}
    \;:=\;
    \forall\, n \in \mathbb{N}.\; \exists\, W.\;
    \textsf{R}^{\textsf{Ty}}_n(A) \searrow W
    \;\wedge\;
    \textsf{R}^{\textsf{Ty}}_n(A') \searrow W
  \]

\label{def:per-neu}
  \[
    {\uparrow}^A(e) \approx {\uparrow}^{A'}(e') \in \textsf{Neu}
    \;:=\;
    e \approx e' \in \textsf{Ne}
  \]

\label{def:per-nat}
  The relation $a \approx a' \in \textsf{Nat}$ is defined inductively by:
  \begin{mathpar}
    \inferrule[\textsc{Nat-Ze}]
    { }
    {\texttt{ze} \approx \texttt{ze} \in \textsf{Nat}}
    ; \gdef, {, }
    \inferrule[\textsc{Nat-Su}]
    {a \approx a' \in \textsf{Nat}}
    {\texttt{su}(a) \approx \texttt{su}(a') \in \textsf{Nat}}
    ; \gdef, {, }
    \inferrule[\textsc{Nat-Ne}]
    {e \approx e' \in \textsf{Ne}}
    {{\uparrow}^N(e) \approx {\uparrow}^N(e') \in \textsf{Nat}}
  \end{mathpar}

By induction on the derivation.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{Nat-Ze}]
    { }
    {\texttt{ze} \approx \texttt{ze} \in \textsf{Nat}}
  \end{mathpar}
  Symmetry and transitivity are immediate.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{Nat-Su}]
    {a \approx a' \in \textsf{Nat}}
    {\texttt{su}(a) \approx \texttt{su}(a') \in \textsf{Nat}}
  \end{mathpar}
  \begin{align*}
    &a' \approx a \in \textsf{Nat}
      && \text{(by IH, symmetry)} \\
    &\texttt{su}(a') \approx \texttt{su}(a) \in \textsf{Nat}
      && \text{(by \textsc{Nat-Su})}
  \end{align*}
  Transitivity: given additionally $\texttt{su}(a') \approx \texttt{su}(a'') \in \textsf{Nat}$
  (hence $a' \approx a'' \in \textsf{Nat}$), by the IH $a \approx a'' \in \textsf{Nat}$,
  so $\texttt{su}(a) \approx \texttt{su}(a'') \in \textsf{Nat}$.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{Nat-Ne}]
    {e \approx e' \in \textsf{Ne}}
    {{\uparrow}^N(e) \approx {\uparrow}^N(e') \in \textsf{Nat}}
  \end{mathpar}
  \begin{align*}
    &e' \approx e \in \textsf{Ne}
      && \text{(by symmetry of $\textsf{Ne}$, \Cref{lem:base-per})} \\
    &{\uparrow}^N(e') \approx {\uparrow}^N(e) \in \textsf{Nat}
      && \text{(by \textsc{Nat-Ne})}
  \end{align*}
  Transitivity follows analogously from transitivity of $\textsf{Ne}$.

\label{lem:nat-readback}
  If $a \approx a' \in \textsf{Nat}$, then
  ${\downarrow}^N(a) \approx {\downarrow}^N(a') \in \textsf{Nf}$.

By induction on the derivation of $a \approx a' \in \textsf{Nat}$.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{Nat-Ze}]
    { }
    {\texttt{ze} \approx \texttt{ze} \in \textsf{Nat}}
  \end{mathpar}
  Both sides read back to $\textsf{zero}$ at every level $n$, so
  ${\downarrow}^N(\texttt{ze}) \approx {\downarrow}^N(\texttt{ze}) \in \textsf{Nf}$.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{Nat-Su}]
    {a \approx a' \in \textsf{Nat}}
    {\texttt{su}(a) \approx \texttt{su}(a') \in \textsf{Nat}}
  \end{mathpar}
  \begin{align*}
    &{\downarrow}^N(a) \approx {\downarrow}^N(a') \in \textsf{Nf}
      && \text{(by IH)} \\
    &\forall\, n.\; \exists\, w.\;
      \textsf{R}^{\textsf{Nf}}_n({\downarrow}^N(a)) \searrow w \;\wedge\;
      \textsf{R}^{\textsf{Nf}}_n({\downarrow}^N(a')) \searrow w
      && \text{(by definition of $\textsf{Nf}$)} \\
    &\textsf{R}^{\textsf{Nf}}_n({\downarrow}^N(\texttt{su}(a))) \searrow \textsf{succ}~w \;\wedge\;
      \textsf{R}^{\textsf{Nf}}_n({\downarrow}^N(\texttt{su}(a'))) \searrow \textsf{succ}~w
      && \text{(by \textsc{Rf-su})}
  \end{align*}

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{Nat-Ne}]
    {e \approx e' \in \textsf{Ne}}
    {{\uparrow}^N(e) \approx {\uparrow}^N(e') \in \textsf{Nat}}
  \end{mathpar}
  \begin{align*}
    &e \approx e' \in \textsf{Ne}
      && \text{(by hypothesis)} \\
    &\forall\, n.\; \exists\, u.\;
      \textsf{R}^{\textsf{Ne}}_n(e) \searrow u \;\wedge\; \textsf{R}^{\textsf{Ne}}_n(e') \searrow u
      && \text{(by definition of $\textsf{Ne}$)} \\
    &\textsf{R}^{\textsf{Nf}}_n({\downarrow}^N({\uparrow}^N(e))) \searrow u \;\wedge\;
      \textsf{R}^{\textsf{Nf}}_n({\downarrow}^N({\uparrow}^N(e'))) \searrow u
      && \text{(by \textsc{Rf-ne})}
  \end{align*}

\label{def:per-univ}
  The relation $A \approx A' \in \mathcal{U}_i \searrow R$ is defined inductively by the following
  four cases.
  The returned $R$ is unique only up to $\Leftrightarrow$ (not definitional equality).
  \begin{mathpar}
    \inferrule[\textsc{U-Ne}]
    {b \approx b' \in \textsf{Ne} \\ R \Leftrightarrow \textsf{Neu}}
    {{\uparrow}^A(b) \approx {\uparrow}^{A'}(b') \in \mathcal{U}_i
      \searrow R}

    \inferrule[\textsc{U-Univ}]
    {j < i \\ R \Leftrightarrow \mathcal{U}_j}
    {U_j \approx U_j \in \mathcal{U}_i \searrow R}

    \inferrule[\textsc{U-Nat}]
    {R \Leftrightarrow \textsf{Nat}}
    {N \approx N \in \mathcal{U}_i \searrow R}

    \inferrule[\textsc{U-Pi}]
    {A \approx A' \in \mathcal{U}_i \searrow R_I \\
     R_I \text{ is a PER} \\\\
     \forall\, \ensuremath{\mathcal{D}} :: a \approx a' \in R_I.\;
       \ensuremath{\llbracket T \rrbracket(\rho, a/x)} \approx \ensuremath{\llbracket T' \rrbracket(\rho', a'/x)} \in \mathcal{U}_i \searrow R_O(\ensuremath{\mathcal{D}}) \\\\
     \forall\, f, f'.\; f \approx f' \in R \;\leftrightarrow\;
       (\forall\, \ensuremath{\mathcal{D}} :: a \approx a' \in R_I.\;
        f \cdot a \approx f' \cdot a' \in R_O(\ensuremath{\mathcal{D}}))}
    {\Pi(A, T, \rho) \approx \Pi(A', T', \rho') \in \mathcal{U}_i \searrow R}
  \end{mathpar}
  In the $\textsc{U-Pi}$ case, $\Pi(A, T, \rho)$ is the closure form: the codomain
  fiber at input $b$ is obtained by evaluating $T$ in $(\rho, b/x)$.
  The notation $\ensuremath{\mathcal{D}} :: a \approx a' \in R_I$ means that $\ensuremath{\mathcal{D}}$ is the proof/evidence
  that $a \approx a' \in R_I$ holds; $R_O(\ensuremath{\mathcal{D}})$ may depend on this evidence.
  The fourth premise characterizes $R$ as the PER on functions: $f, f'$ are
  related in $R$ if and only if applying them to related inputs yields related outputs.
  We write $f \cdot a$ for semantic application (i.e., there exists $c$ with
  $f \cdot a \searrow c$, and $c$ participates in $R_O(\ensuremath{\mathcal{D}})$).

\label{lem:cumul}
  If $A \approx A' \in \mathcal{U}_i \searrow R$ and $i \le j$, then
  $A \approx A' \in \mathcal{U}_j \searrow R$.

By induction on the derivation of $A \approx A' \in \mathcal{U}_i \searrow R$.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{U-Ne}]
    {b \approx b' \in \textsf{Ne} \\ R \Leftrightarrow \textsf{Neu}}
    {{\uparrow}^A(b) \approx {\uparrow}^{A'}(b') \in \mathcal{U}_i \searrow R}
  \end{mathpar}
  The same derivation works at level $j$ (neutrals are level-independent):
  ${\uparrow}^A(b) \approx {\uparrow}^{A'}(b') \in \mathcal{U}_j \searrow R$ by \textsc{U-Ne}.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{U-Univ}]
    {k < i \\ R \Leftrightarrow \mathcal{U}_k}
    {U_k \approx U_k \in \mathcal{U}_i \searrow R}
  \end{mathpar}
  \begin{align*}
    &k < i \le j
      && \text{(by hypothesis)} \\
    &U_k \approx U_k \in \mathcal{U}_j \searrow R
      && \text{(by \textsc{U-Univ}, since $k < j$)}
  \end{align*}

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{U-Nat}]
    {R \Leftrightarrow \textsf{Nat}}
    {N \approx N \in \mathcal{U}_i \searrow R}
  \end{mathpar}
  Level-independent: $N \approx N \in \mathcal{U}_j \searrow R$ by \textsc{U-Nat}.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{U-Pi}]
    {A \approx A' \in \mathcal{U}_i \searrow R_I \\
     R_I \text{ is a PER} \\\\
     \forall\, \ensuremath{\mathcal{D}} :: a \approx a' \in R_I.\;
       \ensuremath{\llbracket T \rrbracket(\rho, a/x)} \approx \ensuremath{\llbracket T' \rrbracket(\rho', a'/x)} \in \mathcal{U}_i \searrow R_O(\ensuremath{\mathcal{D}}) \\\\
     \forall\, f, f'.\; f \approx f' \in R \;\leftrightarrow\;
       (\forall\, \ensuremath{\mathcal{D}} :: a \approx a' \in R_I.\;
        f \cdot a \approx f' \cdot a' \in R_O(\ensuremath{\mathcal{D}}))}
    {\Pi(A, T, \rho) \approx \Pi(A', T', \rho') \in \mathcal{U}_i \searrow R}
  \end{mathpar}
  \begin{align*}
    &A \approx A' \in \mathcal{U}_j \searrow R_I
      && \text{(by IH on domain)} \\
    &\forall\, \ensuremath{\mathcal{D}} :: a \approx a' \in R_I.\;
      \ensuremath{\llbracket T \rrbracket(\rho, a/x)} \approx \ensuremath{\llbracket T' \rrbracket(\rho', a'/x)} \in \mathcal{U}_j \searrow R_O(\ensuremath{\mathcal{D}})
      && \text{(by IH on codomain)} \\
    &\Pi(A, T, \rho) \approx \Pi(A', T', \rho') \in \mathcal{U}_j \searrow R
      && \text{(by \textsc{U-Pi})}
  \end{align*}

\label{def:sem-subty}
  The relation $A \mathrel{<:_i} A'$ is defined inductively by:
  \begin{mathpar}
    \inferrule[\textsc{$<$:-Ne}]
    {b \approx b' \in \textsf{Ne}}
    {{\uparrow}^A(b) \mathrel{<:_i} {\uparrow}^{A'}(b')}

    \inferrule[\textsc{$<$:-Univ}]
    {j \le k \\ k < i}
    {U_j \mathrel{<:_i} U_k}

    \inferrule[\textsc{$<$:-Nat}]
    { }
    {N \mathrel{<:_i} N}

    \inferrule[\textsc{$<$:-Pi}]
    {A \approx A' \in \mathcal{U}_i \searrow R_I \\
     \forall\, \ensuremath{\mathcal{D}} :: a \approx a' \in R_I.\;
       \ensuremath{\llbracket T \rrbracket(\rho, a/x)} \mathrel{<:_i} \ensuremath{\llbracket T' \rrbracket(\rho', a'/x)} \\\\
     \Pi(A, T, \rho) \approx \Pi(A, T, \rho) \in \mathcal{U}_i \\
     \Pi(A', T', \rho') \approx \Pi(A', T', \rho') \in \mathcal{U}_i}
    {\Pi(A, T, \rho) \mathrel{<:_i} \Pi(A', T', \rho')}
  \end{mathpar}

\label{lem:univ-functional}
  If $A \approx B \in \mathcal{U}_i \searrow R$ and $A \approx B' \in \mathcal{U}_j \searrow R'$,
  then $R \Leftrightarrow R'$.

By induction on the two derivations simultaneously.
  The cases are forced: $N$ can only match $\textsc{U-Nat}$, a neutral can only match
  $\textsc{U-Ne}$, etc.

  \medskip\noindent
  \textbf{Case} $\textsc{U-Ne}$.
  \begin{mathpar}
    \inferrule[\textsc{U-Ne}]
    {b \approx b' \in \textsf{Ne} \\ R \Leftrightarrow \textsf{Neu}}
    {{\uparrow}^A(b) \approx {\uparrow}^{A'}(b') \in \mathcal{U}_i \searrow R}
  \end{mathpar}
  Both derivations force $R \Leftrightarrow \textsf{Neu}$ and
  $R' \Leftrightarrow \textsf{Neu}$, so $R \Leftrightarrow R'$.

  \medskip\noindent
  \textbf{Case} $\textsc{U-Nat}$.
  Both derivations force $R \Leftrightarrow \textsf{Nat}$ and
  $R' \Leftrightarrow \textsf{Nat}$, so $R \Leftrightarrow R'$.

  \medskip\noindent
  \textbf{Case} $\textsc{U-Univ}$.
  Both derivations force $R \Leftrightarrow \mathcal{U}_j$ and
  $R' \Leftrightarrow \mathcal{U}_j$, so $R \Leftrightarrow R'$.

  \medskip\noindent
  \textbf{Case} $\textsc{U-Pi}$.
  \begin{mathpar}
    \inferrule[\textsc{U-Pi}]
    {A \approx A' \in \mathcal{U}_i \searrow R_I \\
     R_I \text{ is a PER} \\\\
     \forall\, \ensuremath{\mathcal{D}} :: a \approx a' \in R_I.\;
       \ensuremath{\llbracket T \rrbracket(\rho, a/x)} \approx \ensuremath{\llbracket T' \rrbracket(\rho', a'/x)} \in \mathcal{U}_i \searrow R_O(\ensuremath{\mathcal{D}}) \\\\
     \forall\, f, f'.\; f \approx f' \in R \;\leftrightarrow\;
       (\forall\, \ensuremath{\mathcal{D}} :: a \approx a' \in R_I.\;
        f \cdot a \approx f' \cdot a' \in R_O(\ensuremath{\mathcal{D}}))}
    {\Pi(A, T, \rho) \approx \Pi(A', T', \rho') \in \mathcal{U}_i \searrow R}
  \end{mathpar}
  From the second derivation we get $R_I'$ with
  $A \approx A' \in \mathcal{U}_i \searrow R_I'$.
  \begin{align*}
    &R_I \Leftrightarrow R_I'
      && \text{(by IH on domain)} \\
    &\forall\, \ensuremath{\mathcal{D}} :: a \approx a' \in R_I.\;
      R_O(\ensuremath{\mathcal{D}}) \Leftrightarrow R_O'(\ensuremath{\mathcal{D}})
      && \text{(by IH on codomain at each input)} \\
    &R \Leftrightarrow R'
      && \text{(by the biconditional characterizations and transitivity of $\Leftrightarrow$)}
  \end{align*}

\label{lem:univ-sym}
  If $A \approx A' \in \mathcal{U}_i \searrow R$, then:
  \begin{enumerate}
  \@idxitem $A' \approx A \in \mathcal{U}_i \searrow R$, and
  \@idxitem $a \approx a' \in R$ implies $a' \approx a \in R$.
  \end{enumerate}

By induction on the derivation.  We prove both statements simultaneously.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{U-Ne}]
    {b \approx b' \in \textsf{Ne} \\ R \Leftrightarrow \textsf{Neu}}
    {{\uparrow}^A(b) \approx {\uparrow}^{A'}(b') \in \mathcal{U}_i \searrow R}
  \end{mathpar}
  For (1):
  \begin{align*}
    &b' \approx b \in \textsf{Ne}
      && \text{(by symmetry of $\textsf{Ne}$)} \\
    &{\uparrow}^{A'}(b') \approx {\uparrow}^A(b) \in \mathcal{U}_i \searrow R
      && \text{(by \textsc{U-Ne})}
  \end{align*}
  For (2): Suppose $a \approx a' \in R$, i.e.\ $a \approx a' \in \textsf{Neu}$
  (since $R \Leftrightarrow \textsf{Neu}$).
  Then $a = {\uparrow}^B(e)$ and $a' = {\uparrow}^{B'}(e')$ with $e \approx e' \in \textsf{Ne}$.
  By symmetry of $\textsf{Ne}$, $e' \approx e \in \textsf{Ne}$, so $a' \approx a \in \textsf{Neu}$,
  i.e.\ $a' \approx a \in R$.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{U-Univ}]
    {j < i \\ R \Leftrightarrow \mathcal{U}_j}
    {U_j \approx U_j \in \mathcal{U}_i \searrow R}
  \end{mathpar}
  For (1): Immediate ($U_j \approx U_j$ is symmetric).

  For (2): Suppose $a \approx a' \in R$, i.e.\ $a \approx a' \in \mathcal{U}_j \searrow R_0$
  for some $R_0$.
  By the IH at level $j$ (which is structurally smaller), $a' \approx a \in \mathcal{U}_j \searrow R_0$,
  so $a' \approx a \in R$.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{U-Nat}]
    {R \Leftrightarrow \textsf{Nat}}
    {N \approx N \in \mathcal{U}_i \searrow R}
  \end{mathpar}
  For (1): Immediate.

  For (2): Suppose $a \approx a' \in R$, i.e.\ $a \approx a' \in \textsf{Nat}$.
  By symmetry of $\textsf{Nat}$ (\Cref{lem:nat-per}), $a' \approx a \in \textsf{Nat}$,
  so $a' \approx a \in R$.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{U-Pi}]
    {A \approx A' \in \mathcal{U}_i \searrow R_I \\
     R_I \text{ is a PER} \\\\
     \forall\, \ensuremath{\mathcal{D}} :: a \approx a' \in R_I.\;
       \ensuremath{\llbracket T \rrbracket(\rho, a/x)} \approx \ensuremath{\llbracket T' \rrbracket(\rho', a'/x)} \in \mathcal{U}_i \searrow R_O(\ensuremath{\mathcal{D}}) \\\\
     \forall\, f, f'.\; f \approx f' \in R \;\leftrightarrow\;
       (\forall\, \ensuremath{\mathcal{D}} :: a \approx a' \in R_I.\;
        f \cdot a \approx f' \cdot a' \in R_O(\ensuremath{\mathcal{D}}))}
    {\Pi(A, T, \rho) \approx \Pi(A', T', \rho') \in \mathcal{U}_i \searrow R}
  \end{mathpar}
  For (1): We construct a \textsc{U-Pi} derivation of
  $\Pi(A', T', \rho') \approx \Pi(A, T, \rho) \in \mathcal{U}_i \searrow R$.
  We verify the four premises.

  \emph{Premise 1} (domain):
  \begin{align*}
    &A' \approx A \in \mathcal{U}_i \searrow R_I
      && \text{(by IH (1) on domain; same $R_I$ by \Cref{lem:univ-functional})}
  \end{align*}

  \emph{Premise 2}: $R_I$ is a PER (by hypothesis).

  \emph{Premise 3} (codomain): Let $\ensuremath{\mathcal{D}}' :: a' \approx a \in R_I$.
  \begin{align*}
    &a \approx a' \in R_I
      && \text{(by symmetry of $R_I$; call this $\ensuremath{\mathrm{D}}_0$)} \\
    &\ensuremath{\llbracket T \rrbracket(\rho, a/x)} \approx \ensuremath{\llbracket T' \rrbracket(\rho', a'/x)} \in \mathcal{U}_i \searrow R_O(\ensuremath{\mathrm{D}}_0)
      && \text{(original codomain premise at $\ensuremath{\mathrm{D}}_0$)} \\
    &\ensuremath{\llbracket T' \rrbracket(\rho', a'/x)} \approx \ensuremath{\llbracket T \rrbracket(\rho, a/x)} \in \mathcal{U}_i \searrow R_O(\ensuremath{\mathrm{D}}_0)
      && \text{(by IH (1) on codomain; same $R_O(\ensuremath{\mathrm{D}}_0)$ returned)}
  \end{align*}
  Define $R_O'(\ensuremath{\mathcal{D}}') := R_O(\ensuremath{\mathrm{D}}_0)$.

  \emph{Premise 4} (biconditional): We must show
  \[
    \forall\, f, f'.\; f \approx f' \in R \;\leftrightarrow\;
    (\forall\, \ensuremath{\mathcal{D}}' :: a' \approx a \in R_I.\; f \cdot a' \approx f' \cdot a \in R_O'(\ensuremath{\mathcal{D}}'))
  \]
  Since $R_I$ is a PER, the set of pairs $\{(a, a') \mid a \approx a' \in R_I\}$ is
  closed under swapping: $(a, a') \in R_I$ iff $(a', a) \in R_I$.
  By right irrelevance (\Cref{lem:univ-functional}), $R_O(\ensuremath{\mathcal{D}})$ depends only on the pair
  $(a, a')$, not the specific evidence $\ensuremath{\mathcal{D}}$.
  Hence the right-hand side
  ``$\forall\, \ensuremath{\mathcal{D}}' :: a' \approx a \in R_I.\; f \cdot a' \approx f' \cdot a \in R_O'(\ensuremath{\mathcal{D}}')$''
  is, after renaming bound variables $(a' \mapsto b, a \mapsto b')$, equivalent to
  ``$\forall\, \ensuremath{\mathcal{D}}'':: b \approx b' \in R_I.\; f \cdot b \approx f' \cdot b' \in R_O(\ensuremath{\mathcal{D}}'')$''
  which is exactly the original right-hand side.
  Therefore the same $R$ satisfies both biconditionals.
  \begin{align*}
    &\Pi(A', T', \rho') \approx \Pi(A, T, \rho) \in \mathcal{U}_i \searrow R
      && \text{(by \textsc{U-Pi})}
  \end{align*}

  \medskip
  For (2): Suppose $f \approx f' \in R$.
  We must show $f' \approx f \in R$, i.e.\ for all $\ensuremath{\mathcal{D}} :: a \approx a' \in R_I$,
  $f' \cdot a \approx f \cdot a' \in R_O(\ensuremath{\mathcal{D}})$.
  \begin{align*}
    &a' \approx a \in R_I
      && \text{(by symmetry of $R_I$)} \\
    &\text{let } \ensuremath{\mathcal{D}}' :: a' \approx a \in R_I \\
    &f \cdot a' \approx f' \cdot a \in R_O(\ensuremath{\mathcal{D}}')
      && \text{(from $f \approx f' \in R$, applied to $\ensuremath{\mathcal{D}}'$)} \\
    &R_O(\ensuremath{\mathcal{D}}) \Leftrightarrow R_O(\ensuremath{\mathcal{D}}')
      && \text{(by \Cref{lem:univ-functional}: both have same left type $\ensuremath{\llbracket T \rrbracket(\rho, a/x)}$)} \\
    &f' \cdot a \approx f \cdot a' \in R_O(\ensuremath{\mathcal{D}}')
      && \text{(by IH (2) on $R_O(\ensuremath{\mathcal{D}}')$)} \\
    &f' \cdot a \approx f \cdot a' \in R_O(\ensuremath{\mathcal{D}})
      && \text{(by $R_O(\ensuremath{\mathcal{D}}) \Leftrightarrow R_O(\ensuremath{\mathcal{D}}')$)}
  \end{align*}

\label{lem:univ-trans}
  If $A_1 \approx A_2 \in \mathcal{U}_i \searrow R$, then:
  \begin{enumerate}
  \@idxitem $A_2 \approx A_3 \in \mathcal{U}_j \searrow R'$ implies
    $A_1 \approx A_3 \in \mathcal{U}_i \searrow R$, and
  \@idxitem $a_1 \approx a_2 \in R$ and $a_2 \approx a_3 \in R$ implies
    $a_1 \approx a_3 \in R$.
  \end{enumerate}

By induction on the two derivations.
  We must case-split on both; by the structure of the definition, matching cases are forced
  (e.g., $N$ can only relate to $N$).

  \medskip\noindent
  \textbf{Case} $\textsc{U-Ne}$.
  \begin{mathpar}
    \inferrule[\textsc{U-Ne}]
    {b \approx b' \in \textsf{Ne} \\ R \Leftrightarrow \textsf{Neu}}
    {{\uparrow}^A(b) \approx {\uparrow}^{A'}(b') \in \mathcal{U}_i \searrow R}
  \end{mathpar}
  and
  \begin{mathpar}
    \inferrule[\textsc{U-Ne}]
    {b' \approx b'' \in \textsf{Ne} \\ R' \Leftrightarrow \textsf{Neu}}
    {{\uparrow}^{A'}(b') \approx {\uparrow}^{A''}(b'') \in \mathcal{U}_i \searrow R'}
  \end{mathpar}
  \begin{align*}
    &b \approx b'' \in \textsf{Ne}
      && \text{(by transitivity of $\textsf{Ne}$)} \\
    &{\uparrow}^A(b) \approx {\uparrow}^{A''}(b'') \in \mathcal{U}_i \searrow R
      && \text{(by \textsc{U-Ne})} \\
    &R \Leftrightarrow \textsf{Neu} \Leftrightarrow R'
      && \text{(hence $R \Leftrightarrow R'$)}
  \end{align*}

  \medskip\noindent
  \textbf{Case} $\textsc{U-Nat}$ and $\textsc{U-Univ}$: immediate.

  \medskip\noindent
  \textbf{Case} $\textsc{U-Pi}$.
  The first derivation is:
  \begin{mathpar}
    \inferrule[\textsc{U-Pi}]
    {A_1 \approx A_2 \in \mathcal{U}_i \searrow R_I \\
     R_I \text{ is a PER} \\\\
     \forall\, \ensuremath{\mathcal{D}} :: a \approx a' \in R_I.\;
       \ensuremath{\llbracket T_1 \rrbracket(\rho_1, a/x)} \approx \ensuremath{\llbracket T_2 \rrbracket(\rho_2, a'/x)} \in \mathcal{U}_i \searrow R_O(\ensuremath{\mathcal{D}}) \\\\
     \forall\, f, f'.\; f \approx f' \in R \;\leftrightarrow\;
       (\forall\, \ensuremath{\mathcal{D}} :: a \approx a' \in R_I.\;
        f \cdot a \approx f' \cdot a' \in R_O(\ensuremath{\mathcal{D}}))}
    {\Pi(A_1, T_1, \rho_1) \approx \Pi(A_2, T_2, \rho_2) \in \mathcal{U}_i \searrow R}
  \end{mathpar}
  The second derivation is:
  \begin{mathpar}
    \inferrule[\textsc{U-Pi}]
    {A_2 \approx A_3 \in \mathcal{U}_j \searrow R_I' \\
     R_I' \text{ is a PER} \\\\
     \forall\, \ensuremath{\mathcal{D}}' :: a \approx a' \in R_I'.\;
       \ensuremath{\llbracket T_2 \rrbracket(\rho_2, a/x)} \approx \ensuremath{\llbracket T_3 \rrbracket(\rho_3, a'/x)} \in \mathcal{U}_j \searrow R_O'(\ensuremath{\mathcal{D}}') \\\\
     \forall\, f, f'.\; f \approx f' \in R' \;\leftrightarrow\;
       (\forall\, \ensuremath{\mathcal{D}}' :: a \approx a' \in R_I'.\;
        f \cdot a \approx f' \cdot a' \in R_O'(\ensuremath{\mathcal{D}}'))}
    {\Pi(A_2, T_2, \rho_2) \approx \Pi(A_3, T_3, \rho_3) \in \mathcal{U}_j \searrow R'}
  \end{mathpar}

  For (1): We construct a \textsc{U-Pi} derivation of
  $\Pi(A_1, T_1, \rho_1) \approx \Pi(A_3, T_3, \rho_3) \in \mathcal{U}_i \searrow R$.

  \emph{Premise 1} (domain):
  \begin{align*}
    &R_I \Leftrightarrow R_I'
      && \text{(by \Cref{lem:univ-functional}: both have left type $A_2$)} \\
    &A_1 \approx A_3 \in \mathcal{U}_i \searrow R_I
      && \text{(by IH (1) on domain)}
  \end{align*}

  \emph{Premise 2}: $R_I$ is a PER (by hypothesis).

  \emph{Premise 3} (codomain): Let $\ensuremath{\mathcal{D}} :: a \approx a' \in R_I$.
  We must show $\ensuremath{\llbracket T_1 \rrbracket(\rho_1, a/x)} \approx \ensuremath{\llbracket T_3 \rrbracket(\rho_3, a'/x)} \in \mathcal{U}_i \searrow R_O''(\ensuremath{\mathcal{D}})$
  for some $R_O''$.
  \begin{align*}
    &a \approx a \in R_I
      && \text{(by symmetry + transitivity of $R_I$; let this be $\ensuremath{\mathrm{D}}_1$)} \\
    &\ensuremath{\llbracket T_1 \rrbracket(\rho_1, a/x)} \approx \ensuremath{\llbracket T_2 \rrbracket(\rho_2, a/x)} \in \mathcal{U}_i \searrow R_O(\ensuremath{\mathrm{D}}_1)
      && \text{(from first codomain at $\ensuremath{\mathrm{D}}_1$)} \\
    &a \approx a' \in R_I'
      && \text{(by $R_I \Leftrightarrow R_I'$; let evidence in $R_I'$ be $\ensuremath{\mathcal{D}}'$)} \\
    &\ensuremath{\llbracket T_2 \rrbracket(\rho_2, a/x)} \approx \ensuremath{\llbracket T_3 \rrbracket(\rho_3, a'/x)} \in \mathcal{U}_j \searrow R_O'(\ensuremath{\mathcal{D}}')
      && \text{(from second codomain at $\ensuremath{\mathcal{D}}'$)} \\
    &\ensuremath{\llbracket T_1 \rrbracket(\rho_1, a/x)} \approx \ensuremath{\llbracket T_3 \rrbracket(\rho_3, a'/x)} \in \mathcal{U}_i \searrow R_O(\ensuremath{\mathrm{D}}_1)
      && \text{(by IH (1) on codomain)}
  \end{align*}
  Set $R_O''(\ensuremath{\mathcal{D}}) := R_O(\ensuremath{\mathrm{D}}_1)$.

  \emph{Premise 4} (biconditional): We must show
  $f \approx f' \in R \;\leftrightarrow\;
  (\forall\, \ensuremath{\mathcal{D}} :: a \approx a' \in R_I.\; f \cdot a \approx f' \cdot a' \in R_O''(\ensuremath{\mathcal{D}}))$.
  Since $R_O''(\ensuremath{\mathcal{D}}) = R_O(\ensuremath{\mathrm{D}}_1)$ and by right irrelevance $R_O(\ensuremath{\mathrm{D}}_1) \Leftrightarrow R_O(\ensuremath{\mathcal{D}})$
  (both have the same left type $\ensuremath{\llbracket T_1 \rrbracket(\rho_1, a/x)}$), the right-hand side is equivalent
  to the original biconditional for $R$.  Hence the same $R$ works.
  \begin{align*}
    &\Pi(A_1, T_1, \rho_1) \approx \Pi(A_3, T_3, \rho_3) \in \mathcal{U}_i \searrow R
      && \text{(by \textsc{U-Pi})}
  \end{align*}

  For (2): Suppose $f_1 \approx f_2 \in R$ and $f_2 \approx f_3 \in R$.
  We must show $f_1 \approx f_3 \in R$, i.e.\ for all $\ensuremath{\mathcal{D}} :: a \approx a' \in R_I$,
  $f_1 \cdot a \approx f_3 \cdot a' \in R_O(\ensuremath{\mathcal{D}})$.
  \begin{align*}
    &a \approx a \in R_I
      && \text{(by symmetry + transitivity of $R_I$; let this be $\ensuremath{\mathrm{D}}_1$)} \\
    &f_1 \cdot a \approx f_2 \cdot a \in R_O(\ensuremath{\mathrm{D}}_1)
      && \text{(from $f_1 \approx f_2 \in R$ at $\ensuremath{\mathrm{D}}_1$)} \\
    &f_2 \cdot a \approx f_3 \cdot a' \in R_O(\ensuremath{\mathcal{D}})
      && \text{(from $f_2 \approx f_3 \in R$ at $\ensuremath{\mathcal{D}}$)} \\
    &R_O(\ensuremath{\mathrm{D}}_1) \Leftrightarrow R_O(\ensuremath{\mathcal{D}})
      && \text{(by \Cref{lem:univ-functional}: same left type $\ensuremath{\llbracket T_1 \rrbracket(\rho_1, a/x)}$)} \\
    &f_1 \cdot a \approx f_2 \cdot a \in R_O(\ensuremath{\mathcal{D}})
      && \text{(by $R_O(\ensuremath{\mathrm{D}}_1) \Leftrightarrow R_O(\ensuremath{\mathcal{D}})$)} \\
    &f_1 \cdot a \approx f_3 \cdot a' \in R_O(\ensuremath{\mathcal{D}})
      && \text{(by IH (2) on $R_O(\ensuremath{\mathcal{D}})$: transitivity)}
  \end{align*}

By induction on the derivation of $A \mathrel{<:_i} A'$.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{$<$:-Ne}]
    {b \approx b' \in \textsf{Ne}}
    {{\uparrow}^A(b) \mathrel{<:_i} {\uparrow}^{A'}(b')}
  \end{mathpar}
  \begin{align*}
    &e \approx e \in \textsf{Ne}
      && \text{(by symmetry + transitivity of $\textsf{Ne}$)} \\
    &{\uparrow}^{U_i}(e) \approx {\uparrow}^{U_i}(e) \in \mathcal{U}_i \searrow R
      \text{ with } R \Leftrightarrow \textsf{Neu}
      && \text{(by \textsc{U-Ne})} \\
    &e' \approx e' \in \textsf{Ne}
      && \text{(by symmetry + transitivity of $\textsf{Ne}$)} \\
    &{\uparrow}^{U_i}(e') \approx {\uparrow}^{U_i}(e') \in \mathcal{U}_i \searrow R'
      \text{ with } R' \Leftrightarrow \textsf{Neu}
      && \text{(by \textsc{U-Ne})} \\
    &R \Leftrightarrow \textsf{Neu} \Leftrightarrow R'
      && \text{(hence $R \subseteq R'$)}
  \end{align*}

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{$<$:-Univ}]
    {j \le k \\ k < i}
    {U_j \mathrel{<:_i} U_k}
  \end{mathpar}
  \begin{align*}
    &U_j \approx U_j \in \mathcal{U}_i \searrow R
      \text{ with } R \Leftrightarrow (\lambda a\,a'.\, \exists R.\, a \approx a' \in \mathcal{U}_j \searrow R)
      && \text{(by \textsc{U-Univ}, $j < i$)} \\
    &U_k \approx U_k \in \mathcal{U}_i \searrow R'
      \text{ with } R' \Leftrightarrow (\lambda a\,a'.\, \exists R.\, a \approx a' \in \mathcal{U}_k \searrow R)
      && \text{(by \textsc{U-Univ}, $k < i$)} \\
    &R \subseteq R'
      && \text{(by cumulativity, \Cref{lem:cumul}, since $j \le k$)}
  \end{align*}

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{$<$:-Nat}]
    { }
    {N \mathrel{<:_i} N}
  \end{mathpar}
  Both sides are in $\mathcal{U}_i$ (via \textsc{U-Nat}) returning $\textsf{Nat}$,
  and $\textsf{Nat} \subseteq \textsf{Nat}$.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{$<$:-Pi}]
    {A \approx A' \in \mathcal{U}_i \searrow R_I \\
     \forall\, \ensuremath{\mathcal{D}} :: a \approx a' \in R_I.\;
       \ensuremath{\llbracket T \rrbracket(\rho, a/x)} \mathrel{<:_i} \ensuremath{\llbracket T' \rrbracket(\rho', a'/x)} \\\\
     \Pi(A, T, \rho) \approx \Pi(A, T, \rho) \in \mathcal{U}_i \\
     \Pi(A', T', \rho') \approx \Pi(A', T', \rho') \in \mathcal{U}_i}
    {\Pi(A, T, \rho) \mathrel{<:_i} \Pi(A', T', \rho')}
  \end{mathpar}
  The domain PERs coincide by hypothesis.  For the function PERs:
  \begin{align*}
    &\text{Given } f \approx f' \in R
      && \text{(i.e., $\forall\, \ensuremath{\mathcal{D}} :: a \approx a' \in R_I.\;
        f \cdot a \approx f' \cdot a' \in R_O(\ensuremath{\mathcal{D}})$)} \\
    &\text{Given } \ensuremath{\mathcal{D}} :: a \approx a' \in R_I \\
    &f \cdot a \approx f' \cdot a' \in R_O(\ensuremath{\mathcal{D}})
      && \text{(by above)} \\
    &R_O(\ensuremath{\mathcal{D}}) \subseteq R_{O'}(\ensuremath{\mathcal{D}})
      && \text{(by IH on codomain subtyping)} \\
    &f \cdot a \approx f' \cdot a' \in R_{O'}(\ensuremath{\mathcal{D}})
      && \text{(by inclusion)}
  \end{align*}

By induction on the derivation of $A \mathrel{<:_i} B$, with case
  analysis on the constructor of $B \mathrel{<:_i} C$ that must agree on
  the shape of $B$.  

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{$<$:-Ne}]
    {b \approx b' \in \textsf{Ne}}
    {{\uparrow}^{A_0}(b) \mathrel{<:_i} {\uparrow}^{B_0}(b')}
  \end{mathpar}
  Here $B = {\uparrow}^{B_0}(b')$, so $B \mathrel{<:_i} C$ must also be by
  \textsc{$<$:-Ne}, with $C = {\uparrow}^{C_0}(b'')$ and $b' \approx b''
  \in \textsf{Ne}$.  
  By transitivity of the neutral PER (\Cref{lem:base-per}),
  $b \approx b'' \in \textsf{Ne}$.  
  By \textsc{$<$:-Ne},
  ${\uparrow}^{A_0}(b) \mathrel{<:_i} {\uparrow}^{C_0}(b'')$.  

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{$<$:-Univ}]
    {j \le k \\ k < i}
    {U_j \mathrel{<:_i} U_k}
  \end{mathpar}
  Here $B = U_k$, so $B \mathrel{<:_i} C$ must be by \textsc{$<$:-Univ},
  with $C = U_{k'}$, $k \le k'$, and $k' < i$.  
  By transitivity of $\le$ on $\mathbb{N}$, $j \le k'$, and $k' < i$ by hypothesis.  
  By \textsc{$<$:-Univ}, $U_j \mathrel{<:_i} U_{k'}$.  

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{$<$:-Nat}]
    { }
    {N \mathrel{<:_i} N}
  \end{mathpar}
  Here $B = N$, so $B \mathrel{<:_i} C$ must be by \textsc{$<$:-Nat} with
  $C = N$.  
  By \textsc{$<$:-Nat}, $N \mathrel{<:_i} N$.  

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{$<$:-Pi}]
    {A_I \approx B_I \in \mathcal{U}_i \searrow R_I \\
     \forall\, \ensuremath{\mathcal{D}} :: a \approx a' \in R_I.\;
       \ensuremath{\llbracket T_A \rrbracket(\rho_A, a/x)} \mathrel{<:_i} \ensuremath{\llbracket T_B \rrbracket(\rho_B, a'/x)} \\\\
     \Pi(A_I, T_A, \rho_A) \approx \Pi(A_I, T_A, \rho_A) \in \mathcal{U}_i \\
     \Pi(B_I, T_B, \rho_B) \approx \Pi(B_I, T_B, \rho_B) \in \mathcal{U}_i}
    {\Pi(A_I, T_A, \rho_A) \mathrel{<:_i} \Pi(B_I, T_B, \rho_B)}
  \end{mathpar}
  Here $B = \Pi(B_I, T_B, \rho_B)$, so $B \mathrel{<:_i} C$ must be by
  \textsc{$<$:-Pi}, with $C = \Pi(C_I, T_C, \rho_C)$ and:
  \begin{align*}
    &B_I \approx C_I \in \mathcal{U}_i \searrow R_I'
      && \text{(domain of the second derivation)} \\
    &\forall\, \ensuremath{\mathcal{D}}' :: a \approx a' \in R_I'.\;
      \ensuremath{\llbracket T_B \rrbracket(\rho_B, a/x)} \mathrel{<:_i} \ensuremath{\llbracket T_C \rrbracket(\rho_C, a'/x)}
      && \text{(codomain)} \\
    &\Pi(C_I, T_C, \rho_C) \approx \Pi(C_I, T_C, \rho_C) \in \mathcal{U}_i
      && \text{(self-relatedness)}
  \end{align*}

  \emph{Domain.}  
  By \Cref{lem:univ-trans} applied to
  $A_I \approx B_I \in \mathcal{U}_i \searrow R_I$ and
  $B_I \approx C_I \in \mathcal{U}_i \searrow R_I'$:
  $A_I \approx C_I \in \mathcal{U}_i$, with output PER (call it
  $R_I^*$) determined up to logical equivalence by
  \Cref{lem:univ-functional}; in particular,
  $R_I^* \Leftrightarrow R_I \Leftrightarrow R_I'$.  

  \emph{Codomain.}  
  Let $\ensuremath{\mathcal{D}}^* :: a \approx a' \in R_I^*$ be given.  
  By the equivalence $R_I^* \Leftrightarrow R_I$, $\ensuremath{\mathcal{D}}^*$ also witnesses
  $a \approx a' \in R_I$, and by $R_I^* \Leftrightarrow R_I'$ it also
  witnesses some $\ensuremath{\mathcal{D}}' :: a \approx a' \in R_I'$.  
  Apply the codomain hypothesis of the first derivation at this $\ensuremath{\mathcal{D}}^*$
  (used as $\ensuremath{\mathcal{D}}$ in $R_I$):
  \begin{align*}
    &\ensuremath{\llbracket T_A \rrbracket(\rho_A, a/x)} \mathrel{<:_i} \ensuremath{\llbracket T_B \rrbracket(\rho_B, a'/x)}
      && \text{(codomain of the first derivation)}
  \end{align*}
  Apply the codomain hypothesis of the second derivation at $\ensuremath{\mathcal{D}}'$:
  \begin{align*}
    &\ensuremath{\llbracket T_B \rrbracket(\rho_B, a'/x)} \mathrel{<:_i} \ensuremath{\llbracket T_C \rrbracket(\rho_C, a''/x)}
      && \text{(codomain of the second derivation, with $a' \approx a'' \in R_I'$)}
  \end{align*}
  Since $\ensuremath{\mathcal{D}}^*$ witnesses both pairs we have $a' = a''$ at this
  instantiation; the inductive hypothesis composes the two:
  \begin{align*}
    &\ensuremath{\llbracket T_A \rrbracket(\rho_A, a/x)} \mathrel{<:_i} \ensuremath{\llbracket T_C \rrbracket(\rho_C, a'/x)}
      && \text{(by IH on the codomain)}
  \end{align*}

  \emph{Self-relatedness.}  
  Already given: $\Pi(A_I, T_A, \rho_A) \approx \Pi(A_I, T_A, \rho_A) \in \mathcal{U}_i$
  from the first derivation and $\Pi(C_I, T_C, \rho_C) \approx \Pi(C_I,
  T_C, \rho_C) \in \mathcal{U}_i$ from the second.  

  \emph{Conclusion.}  
  By \textsc{$<$:-Pi} with the four ingredients (domain in
  $\mathcal{U}_i \searrow R_I^*$, codomain pointwise subtyping at every $\ensuremath{\mathcal{D}}^*$,
  and the two self-relatedness facts):
  \[
    \Pi(A_I, T_A, \rho_A) \mathrel{<:_i} \Pi(C_I, T_C, \rho_C). \qedhere
  \]

\label{lem:realizability}
  Given $A \approx A' \in \mathcal{U}_i \searrow R$:
  \begin{enumerate}
  \@idxitem\label{lem:R-readback}
    (Elements of $R$ read back)\; If $a \approx a' \in R$, then
    ${\downarrow}^A(a) \approx {\downarrow}^{A'}(a') \in \textsf{Nf}$.
  \@idxitem\label{lem:ne-in-R}
    (Neutrals inhabit $R$)\; If $e \approx e' \in \textsf{Ne}$, then
    ${\uparrow}^A(e) \approx {\uparrow}^{A'}(e') \in R$.
  \@idxitem\label{lem:type-readback}
    (Types read back)\; $A \approx A' \in \textsf{Ty}$.
  \end{enumerate}

By simultaneous induction on the derivation of $A \approx A' \in \mathcal{U}_i \searrow R$.
  We also need an auxiliary lemma that $a \approx a' \in \textsf{Nat}$ implies
  ${\downarrow}^N(a) \approx {\downarrow}^N(a') \in \textsf{Nf}$, which is \Cref{lem:nat-readback}.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{U-Ne}]
    {b \approx b' \in \textsf{Ne} \\ R \Leftrightarrow \textsf{Neu}}
    {{\uparrow}^A(b) \approx {\uparrow}^{A'}(b') \in \mathcal{U}_i \searrow R}
  \end{mathpar}
  For (1): Since $R \Leftrightarrow \textsf{Neu}$, we have $a = {\uparrow}^B(e)$ and
  $a' = {\uparrow}^{B'}(e')$ with $e \approx e' \in \textsf{Ne}$.
  Reading back ${\downarrow}^{{\uparrow}^A(b)}({\uparrow}^B(e))$ at a neutral type
  reads $e$ as a neutral (by \textsc{Rf-ne}), and both sides produce the same
  neutral normal form since $e \approx e' \in \textsf{Ne}$.

  For (2): We need ${\uparrow}^{{\uparrow}^A(b)}(e) \approx {\uparrow}^{{\uparrow}^{A'}(b')}(e') \in R$.
  Since $R \Leftrightarrow \textsf{Neu}$, this reduces to $e \approx e' \in \textsf{Ne}$,
  which holds by hypothesis.

  For (3): We must show ${\uparrow}^A(b) \approx {\uparrow}^{A'}(b') \in \textsf{Ty}$,
  i.e.\ reading back both sides as types produces the same result.
  Since $b \approx b' \in \textsf{Ne}$, reading both as neutrals produces the same neutral
  normal form.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{U-Univ}]
    {j < i \\ R \Leftrightarrow \mathcal{U}_j}
    {U_j \approx U_j \in \mathcal{U}_i \searrow R}
  \end{mathpar}
  For (1): We have $a \approx a' \in R$, i.e.\ $a \approx a' \in \mathcal{U}_j \searrow R_0$
  for some $R_0$.  By IH (3) on the $\mathcal{U}_j$ derivation (structurally smaller since $j < i$),
  $a \approx a' \in \textsf{Ty}_j$.  Reading back ${\downarrow}^{U_j}(a)$ as a normal form
  reads $a$ as a type, hence ${\downarrow}^{U_j}(a) \approx {\downarrow}^{U_j}(a') \in \textsf{Nf}$.

  For (2): We need ${\uparrow}^{U_j}(e) \approx {\uparrow}^{U_j}(e') \in R$,
  i.e.\ ${\uparrow}^{U_j}(e) \approx {\uparrow}^{U_j}(e') \in \mathcal{U}_j \searrow R_0$ for some $R_0$.
  \begin{align*}
    &e \approx e' \in \textsf{Ne}
      && \text{(by hypothesis)} \\
    &{\uparrow}^{U_j}(e) \approx {\uparrow}^{U_j}(e') \in \mathcal{U}_j \searrow \textsf{Neu}
      && \text{(by \textsc{U-Ne}, taking $R_0 \Leftrightarrow \textsf{Neu}$)}
  \end{align*}

  For (3): $A = A' = U_j$.  Both sides read back to $\ensuremath{\texttt{Ty}_{j}}$.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{U-Nat}]
    {R \Leftrightarrow \textsf{Nat}}
    {N \approx N \in \mathcal{U}_i \searrow R}
  \end{mathpar}
  For (1): Since $R \Leftrightarrow \textsf{Nat}$, we have $a \approx a' \in \textsf{Nat}$.
  By \Cref{lem:nat-readback}, ${\downarrow}^N(a) \approx {\downarrow}^N(a') \in \textsf{Nf}$.

  For (2): We need ${\uparrow}^N(e) \approx {\uparrow}^N(e') \in \textsf{Nat}$.
  \begin{align*}
    &e \approx e' \in \textsf{Ne}
      && \text{(by hypothesis)} \\
    &{\uparrow}^N(e) \approx {\uparrow}^N(e') \in \textsf{Nat}
      && \text{(by \textsc{Nat-Ne})}
  \end{align*}

  For (3): $A = A' = N$.  Both sides read back to $\ensuremath{\texttt{Nat}}$.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{U-Pi}]
    {A_0 \approx A_0' \in \mathcal{U}_i \searrow R_I \\
     R_I \text{ is a PER} \\\\
     \forall\, \ensuremath{\mathcal{D}} :: a \approx a' \in R_I.\;
       \ensuremath{\llbracket T \rrbracket(\rho, a/x)} \approx \ensuremath{\llbracket T' \rrbracket(\rho', a'/x)} \in \mathcal{U}_i \searrow R_O(\ensuremath{\mathcal{D}}) \\\\
     \forall\, f, f'.\; f \approx f' \in R \;\leftrightarrow\;
       (\forall\, \ensuremath{\mathcal{D}} :: a \approx a' \in R_I.\;
        f \cdot a \approx f' \cdot a' \in R_O(\ensuremath{\mathcal{D}}))}
    {\Pi(A_0, T, \rho) \approx \Pi(A_0', T', \rho') \in \mathcal{U}_i \searrow R}
  \end{mathpar}
  For (1): We have $f \approx f' \in R$, i.e.\ for all $\ensuremath{\mathcal{D}} :: a \approx a' \in R_I$,
  $f \cdot a \approx f' \cdot a' \in R_O(\ensuremath{\mathcal{D}})$.
  Reading back ${\downarrow}^{\Pi(A_0,T,\rho)}(f)$ at level $n$:
  \begin{align*}
    &\ell_n \approx \ell_n \in \textsf{Ne}
      && \text{(a level variable reads back to itself)} \\
    &{\uparrow}^{A_0}(\ell_n) \approx {\uparrow}^{A_0'}(\ell_n) \in R_I
      && \text{(by IH (2) on domain)} \\
    &\text{Let } \ensuremath{\mathrm{D}}_n :: {\uparrow}^{A_0}(\ell_n) \approx {\uparrow}^{A_0'}(\ell_n) \in R_I \\
    &f \cdot {\uparrow}^{A_0}(\ell_n) \approx f' \cdot {\uparrow}^{A_0'}(\ell_n) \in R_O(\ensuremath{\mathrm{D}}_n)
      && \text{(from $f \approx f' \in R$ at $\ensuremath{\mathrm{D}}_n$)} \\
    &\ensuremath{\llbracket T \rrbracket(\rho, {\uparrow}^{A_0}(\ell_n)/x)} \approx
      \ensuremath{\llbracket T' \rrbracket(\rho', {\uparrow}^{A_0'}(\ell_n)/x)} \in \mathcal{U}_i \searrow R_O(\ensuremath{\mathrm{D}}_n)
      && \text{(codomain premise at $\ensuremath{\mathrm{D}}_n$)} \\
    &{\downarrow}^{\ensuremath{\llbracket T \rrbracket(\rho, {\uparrow}^{A_0}(\ell_n)/x)}}(f \cdot {\uparrow}^{A_0}(\ell_n))
      \approx
      {\downarrow}^{\ensuremath{\llbracket T' \rrbracket(\rho', {\uparrow}^{A_0'}(\ell_n)/x)}}(f' \cdot {\uparrow}^{A_0'}(\ell_n))
      \in \textsf{Nf}
      && \text{(by IH (1) on codomain)}
  \end{align*}
  The readback rule for $\Pi$-types assembles these into
  $\textsf{R}^{\textsf{Nf}}_n({\downarrow}^{\Pi(A_0,T,\rho)}(f)) \searrow \lambda x.\, w$ and
  $\textsf{R}^{\textsf{Nf}}_n({\downarrow}^{\Pi(A_0',T',\rho')}(f')) \searrow \lambda x.\, w$
  with the same body $w$.

  For (2): By the biconditional, we must show that for all $\ensuremath{\mathcal{D}} :: a \approx a' \in R_I$,
  $({\uparrow}^{\Pi(A_0,T,\rho)}(e)) \cdot a
  \approx ({\uparrow}^{\Pi(A_0',T',\rho')}(e')) \cdot a' \in R_O(\ensuremath{\mathcal{D}})$.
  \begin{align*}
    &\text{Let } \ensuremath{\llbracket T \rrbracket(\rho, a/x)} \searrow B \text{ and }
      \ensuremath{\llbracket T' \rrbracket(\rho', a'/x)} \searrow B' \\
    &({\uparrow}^{\Pi(A_0,T,\rho)}(e)) \cdot a = {\uparrow}^B(e \;\$\; {\downarrow}^{A_0}(a))
      && \text{(by \textsc{app-ne})} \\
    &({\uparrow}^{\Pi(A_0',T',\rho')}(e')) \cdot a' = {\uparrow}^{B'}(e' \;\$\; {\downarrow}^{A_0'}(a'))
      && \text{(by \textsc{app-ne})} \\
    &{\downarrow}^{A_0}(a) \approx {\downarrow}^{A_0'}(a') \in \textsf{Nf}
      && \text{(by IH (1) on domain: $a \approx a' \in R_I$)} \\
    &e \;\$\; {\downarrow}^{A_0}(a) \approx e' \;\$\; {\downarrow}^{A_0'}(a') \in \textsf{Ne}
      && \text{(by $e \approx e' \in \textsf{Ne}$ and above)} \\
    &B \approx B' \in \mathcal{U}_i \searrow R_O(\ensuremath{\mathcal{D}})
      && \text{(codomain premise at $\ensuremath{\mathcal{D}}$)} \\
    &{\uparrow}^B(e \;\$\; {\downarrow}^{A_0}(a)) \approx
      {\uparrow}^{B'}(e' \;\$\; {\downarrow}^{A_0'}(a')) \in R_O(\ensuremath{\mathcal{D}})
      && \text{(by IH (2) on codomain)}
  \end{align*}

  For (3): Reading back $\Pi(A_0, T, \rho)$ as a type at level $n$:
  \begin{align*}
    &A_0 \approx A_0' \in \textsf{Ty}
      && \text{(by IH (3) on domain)} \\
    &\ell_n \approx \ell_n \in \textsf{Ne}
      && \text{(reflexivity of level variable)} \\
    &{\uparrow}^{A_0}(\ell_n) \approx {\uparrow}^{A_0'}(\ell_n) \in R_I
      && \text{(by IH (2) on domain)} \\
    &\text{Let } \ensuremath{\mathrm{D}}_n :: {\uparrow}^{A_0}(\ell_n) \approx {\uparrow}^{A_0'}(\ell_n) \in R_I \\
    &\ensuremath{\llbracket T \rrbracket(\rho, {\uparrow}^{A_0}(\ell_n)/x)} \approx
      \ensuremath{\llbracket T' \rrbracket(\rho', {\uparrow}^{A_0'}(\ell_n)/x)} \in \mathcal{U}_i \searrow R_O(\ensuremath{\mathrm{D}}_n)
      && \text{(codomain premise at $\ensuremath{\mathrm{D}}_n$)} \\
    &\ensuremath{\llbracket T \rrbracket(\rho, {\uparrow}^{A_0}(\ell_n)/x)} \approx
      \ensuremath{\llbracket T' \rrbracket(\rho', {\uparrow}^{A_0'}(\ell_n)/x)} \in \textsf{Ty}
      && \text{(by IH (3) on codomain)}
  \end{align*}
  The type readback rule for $\Pi$-types reads back the domain and codomain separately;
  both agree by the above.

\label{def:ctx-per}
  The relation $\Gamma \approx \Gamma' \searrow R$ is defined inductively:
  \begin{mathpar}
    \inferrule[\textsc{Ctx-Emp}]
    { }
    {\cdot \approx \cdot \searrow \top}

    \inferrule[\textsc{Ctx-Ext}]
    {\Gamma \approx \Gamma' \searrow R_T \\
     R_T \text{ is a PER} \\
     \forall\, \ensuremath{\mathcal{D}} :: \rho \approx \rho' \in R_T.\;
       \ensuremath{\llbracket S \rrbracket(\rho)} \approx \ensuremath{\llbracket S' \rrbracket(\rho')} \in \mathcal{U}_i \searrow R_H(\ensuremath{\mathcal{D}}) \\\\
     \forall\, \rho, \rho'.\; \rho \approx \rho' \in R \;\leftrightarrow\;
       (\ensuremath{\mathcal{D}} :: \rho[\Uparrow] \approx \rho'[\Uparrow] \in R_T \wedge
        \rho(0) \approx \rho'(0) \in R_H(\ensuremath{\mathcal{D}}))}
    {\Gamma, x : S \approx \Gamma', x : S' \searrow R}
  \end{mathpar}
  Here $\top$ is the total relation (any two environments are related),
  $\rho[\Uparrow]$ is the weakened environment (dropping the head), and $\rho(0)$ is the head value.
  The universe level $i$ at which the heads are related is implicit in the conclusion.

\label{def:ctx-subty}
  The relation $\Gamma <: \Gamma'$ is defined inductively:
  \begin{mathpar}
    \inferrule[\textsc{Ctx-$<$:-Emp}]
    { }
    {\cdot <: \cdot}

    \inferrule[\textsc{Ctx-$<$:-Ext}]
    {\Gamma <: \Gamma' \\
     \Gamma \approx \Gamma \searrow R_T \\
     \forall\, \ensuremath{\mathcal{D}} :: \rho \approx \rho' \in R_T.\;
       \ensuremath{\llbracket S \rrbracket(\rho)} \mathrel{<:_i} \ensuremath{\llbracket S' \rrbracket(\rho')} \\\\
     \Gamma, x : S \approx \Gamma, x : S \searrow R_1 \\
     \Gamma', x : S' \approx \Gamma', x : S' \searrow R_2}
    {\Gamma, x : S <: \Gamma', x : S'}
  \end{mathpar}

\label{lem:ctx-functional}
  If $\Gamma \approx \Gamma' \searrow R$ and $\Gamma \approx \Gamma'' \searrow R'$,
  then $R \Leftrightarrow R'$.

By induction on the first derivation.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{Ctx-Emp}]
    { }
    {\cdot \approx \cdot \searrow \top}
  \end{mathpar}
  The second derivation also concludes $\cdot \approx \cdot \searrow \top$,
  so $R = R' = \top$ and $\top \Leftrightarrow \top$.

  \medskip\noindent
  \textbf{Case}
  The first derivation is:
  \begin{mathpar}
    \inferrule[\textsc{Ctx-Ext}]
    {\Gamma \approx \Gamma' \searrow R_T \\
     R_T \text{ is a PER} \\\\
     \forall\, \ensuremath{\mathcal{D}} :: \rho \approx \rho' \in R_T.\;
       \ensuremath{\llbracket S \rrbracket(\rho)} \approx \ensuremath{\llbracket S' \rrbracket(\rho')} \in \mathcal{U}_i \searrow R_H(\ensuremath{\mathcal{D}}) \\\\
     \forall\, \rho, \rho'.\; \rho \approx \rho' \in R \;\leftrightarrow\;
       (\ensuremath{\mathcal{D}} :: \rho[\Uparrow] \approx \rho'[\Uparrow] \in R_T \;\wedge\;
        \rho(0) \approx \rho'(0) \in R_H(\ensuremath{\mathcal{D}}))}
    {\Gamma, x : S \approx \Gamma', x : S' \searrow R}
  \end{mathpar}
  The second derivation is:
  \begin{mathpar}
    \inferrule[\textsc{Ctx-Ext}]
    {\Gamma \approx \Gamma'' \searrow R_T' \\
     R_T' \text{ is a PER} \\\\
     \forall\, \ensuremath{\mathcal{D}}' :: \rho \approx \rho' \in R_T'.\;
       \ensuremath{\llbracket S \rrbracket(\rho)} \approx \ensuremath{\llbracket S'' \rrbracket(\rho')} \in \mathcal{U}_j \searrow R_H'(\ensuremath{\mathcal{D}}') \\\\
     \forall\, \rho, \rho'.\; \rho \approx \rho' \in R' \;\leftrightarrow\;
       (\ensuremath{\mathcal{D}}' :: \rho[\Uparrow] \approx \rho'[\Uparrow] \in R_T' \;\wedge\;
        \rho(0) \approx \rho'(0) \in R_H'(\ensuremath{\mathcal{D}}'))}
    {\Gamma, x : S \approx \Gamma'', x : S'' \searrow R'}
  \end{mathpar}
  We show $R \Leftrightarrow R'$, i.e.\ $\rho \approx \rho' \in R$ iff $\rho \approx \rho' \in R'$.
  \begin{align*}
    &R_T \Leftrightarrow R_T'
      && \text{(by IH on the tails)}
  \end{align*}

  $(\Rightarrow)$: Suppose $\rho \approx \rho' \in R$.
  By the first biconditional, we obtain $\ensuremath{\mathcal{D}} :: \rho[\Uparrow] \approx \rho'[\Uparrow] \in R_T$
  with $\rho(0) \approx \rho'(0) \in R_H(\ensuremath{\mathcal{D}})$.
  \begin{align*}
    &\rho[\Uparrow] \approx \rho'[\Uparrow] \in R_T'
      && \text{(by $R_T \Leftrightarrow R_T'$; call this evidence $\ensuremath{\mathcal{D}}'$)} \\
    &\ensuremath{\llbracket S \rrbracket(\rho[\Uparrow])} \approx \ensuremath{\llbracket S' \rrbracket(\rho'[\Uparrow])} \in \mathcal{U}_i \searrow R_H(\ensuremath{\mathcal{D}})
      && \text{(from the first head premise at $\ensuremath{\mathcal{D}}$)} \\
    &\ensuremath{\llbracket S \rrbracket(\rho[\Uparrow])} \approx \ensuremath{\llbracket S'' \rrbracket(\rho'[\Uparrow])} \in \mathcal{U}_j \searrow R_H'(\ensuremath{\mathcal{D}}')
      && \text{(from the second head premise at $\ensuremath{\mathcal{D}}'$)} \\
    &R_H(\ensuremath{\mathcal{D}}) \Leftrightarrow R_H'(\ensuremath{\mathcal{D}}')
      && \text{(by \Cref{lem:univ-functional}: same left type $\ensuremath{\llbracket S \rrbracket(\rho[\Uparrow])}$)} \\
    &\rho(0) \approx \rho'(0) \in R_H'(\ensuremath{\mathcal{D}}')
      && \text{(by $R_H(\ensuremath{\mathcal{D}}) \Leftrightarrow R_H'(\ensuremath{\mathcal{D}}')$)} \\
    &\rho \approx \rho' \in R'
      && \text{(by the second biconditional, with witness $\ensuremath{\mathcal{D}}'$)}
  \end{align*}

  $(\Leftarrow)$: Symmetric, swapping the roles of the two derivations.

\label{lem:ctx-sym}
  If $\Gamma \approx \Gamma' \searrow R$, then:
  \begin{enumerate}
  \@idxitem $\Gamma' \approx \Gamma \searrow R$, and
  \@idxitem $\rho \approx \rho' \in R$ implies $\rho' \approx \rho \in R$.
  \end{enumerate}

By induction on the derivation.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{Ctx-Emp}]
    { }
    {\cdot \approx \cdot \searrow \top}
  \end{mathpar}
  Both statements are immediate ($\top$ is symmetric).

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{Ctx-Ext}]
    {\Gamma \approx \Gamma' \searrow R_T \\
     R_T \text{ is a PER} \\\\
     \forall\, \ensuremath{\mathcal{D}} :: \rho \approx \rho' \in R_T.\;
       \ensuremath{\llbracket S \rrbracket(\rho)} \approx \ensuremath{\llbracket S' \rrbracket(\rho')} \in \mathcal{U}_i \searrow R_H(\ensuremath{\mathcal{D}}) \\\\
     \forall\, \rho, \rho'.\; \rho \approx \rho' \in R \;\leftrightarrow\;
       (\ensuremath{\mathcal{D}} :: \rho[\Uparrow] \approx \rho'[\Uparrow] \in R_T \;\wedge\;
        \rho(0) \approx \rho'(0) \in R_H(\ensuremath{\mathcal{D}}))}
    {\Gamma, x : S \approx \Gamma', x : S' \searrow R}
  \end{mathpar}
  For (1): We construct a \textsc{Ctx-Ext} derivation of
  $\Gamma', x : S' \approx \Gamma, x : S \searrow R$.
  We verify each of the four premises.

  \emph{Premise 1} (tail):
  \begin{align*}
    &\Gamma' \approx \Gamma \searrow R_T
      && \text{(by IH (1) on the tail; same $R_T$ by \Cref{lem:ctx-functional})}
  \end{align*}

  \emph{Premise 2}: $R_T$ is a PER (by hypothesis).

  \emph{Premise 3} (head): Given $\ensuremath{\mathcal{D}}' :: \rho' \approx \rho \in R_T$, we must show
  $\ensuremath{\llbracket S' \rrbracket(\rho')} \approx \ensuremath{\llbracket S \rrbracket(\rho)} \in \mathcal{U}_i \searrow R_H'(\ensuremath{\mathcal{D}}')$
  for some $R_H'$.
  \begin{align*}
    &\rho \approx \rho' \in R_T
      && \text{(by IH (2) on the tail applied to $\ensuremath{\mathcal{D}}'$; call this $\ensuremath{\mathrm{D}}_0$)} \\
    &\ensuremath{\llbracket S \rrbracket(\rho)} \approx \ensuremath{\llbracket S' \rrbracket(\rho')} \in \mathcal{U}_i \searrow R_H(\ensuremath{\mathrm{D}}_0)
      && \text{(from the original head premise at $\ensuremath{\mathrm{D}}_0$)} \\
    &\ensuremath{\llbracket S' \rrbracket(\rho')} \approx \ensuremath{\llbracket S \rrbracket(\rho)} \in \mathcal{U}_i \searrow R_H(\ensuremath{\mathrm{D}}_0)
      && \text{(by \Cref{lem:univ-sym} (1); same $R_H(\ensuremath{\mathrm{D}}_0)$ returned)}
  \end{align*}
  Set $R_H'(\ensuremath{\mathcal{D}}') := R_H(\ensuremath{\mathrm{D}}_0)$.

  \emph{Premise 4} (biconditional): We must verify
  \[
    \forall\, \rho, \rho'.\; \rho \approx \rho' \in R \;\leftrightarrow\;
    (\ensuremath{\mathcal{D}}' :: \rho[\Uparrow] \approx \rho'[\Uparrow] \in R_T \;\wedge\;
     \rho(0) \approx \rho'(0) \in R_H'(\ensuremath{\mathcal{D}}'))
  \]
  The original biconditional states:
  \[
    \rho \approx \rho' \in R \;\leftrightarrow\;
    (\ensuremath{\mathcal{D}} :: \rho[\Uparrow] \approx \rho'[\Uparrow] \in R_T \;\wedge\;
     \rho(0) \approx \rho'(0) \in R_H(\ensuremath{\mathcal{D}}))
   \]
   $\ensuremath{\mathcal{D}}$ and $\ensuremath{\mathcal{D}}'$ already discharge.  
  Moreover $R_H'(\ensuremath{\mathcal{D}}') = R_H(\ensuremath{\mathrm{D}}_0) \Leftrightarrow R_H(\ensuremath{\mathcal{D}})$ by right irrelevance.
  Hence both biconditionals characterize the same $R$.
  \begin{align*}
    &\Gamma', x : S' \approx \Gamma, x : S \searrow R
      && \text{(by \textsc{Ctx-Ext})}
  \end{align*}

  \medskip
  For (2): Suppose $\rho \approx \rho' \in R$.
  By the biconditional, there exists $\ensuremath{\mathcal{D}} :: \rho[\Uparrow] \approx \rho'[\Uparrow] \in R_T$
  with $\rho(0) \approx \rho'(0) \in R_H(\ensuremath{\mathcal{D}})$.
  We must show $\rho' \approx \rho \in R$, i.e.\ exhibit evidence for
  $\rho'[\Uparrow] \approx \rho[\Uparrow] \in R_T$ together with the heads being related.
  \begin{align*}
    &\rho'[\Uparrow] \approx \rho[\Uparrow] \in R_T
      && \text{(by IH (2) on tail applied to $\ensuremath{\mathcal{D}}$; call this $\ensuremath{\mathcal{D}}'$)} \\
    &\rho'(0) \approx \rho(0) \in R_H(\ensuremath{\mathcal{D}})
      && \text{(by \Cref{lem:univ-sym} (2))} \\
    &R_H(\ensuremath{\mathcal{D}}) \Leftrightarrow R_H(\ensuremath{\mathcal{D}}')
      && \text{(by \Cref{lem:univ-functional})} \\
    &\rho'(0) \approx \rho(0) \in R_H(\ensuremath{\mathcal{D}}')
      && \text{(by equivalence)}
  \end{align*}
  The tail evidence $\ensuremath{\mathcal{D}}'$ and the head relatedness $\rho'(0) \approx \rho(0) \in R_H(\ensuremath{\mathcal{D}}')$
  together witness $\rho' \approx \rho \in R$ by the biconditional.

\label{lem:ctx-trans}
  If $\Gamma_1 \approx \Gamma_2 \searrow R$, then:
  \begin{enumerate}
  \@idxitem $\Gamma_2 \approx \Gamma_3 \searrow R'$ implies
    $\Gamma_1 \approx \Gamma_3 \searrow R$, and
  \@idxitem $\rho_1 \approx \rho_2 \in R$ and $\rho_2 \approx \rho_3 \in R$ implies
    $\rho_1 \approx \rho_3 \in R$.
  \end{enumerate}

By induction on the first derivation.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{Ctx-Emp}]
    { }
    {\cdot \approx \cdot \searrow \top}
  \end{mathpar}
  Both statements are immediate ($\top$ is transitive).

  \medskip\noindent
  \textbf{Case}
  The first derivation is:
  \begin{mathpar}
    \inferrule[\textsc{Ctx-Ext}]
    {\Gamma_1 \approx \Gamma_2 \searrow R_T \\
     R_T \text{ is a PER} \\\\
     \forall\, \ensuremath{\mathcal{D}} :: \rho \approx \rho' \in R_T.\;
       \ensuremath{\llbracket S_1 \rrbracket(\rho)} \approx \ensuremath{\llbracket S_2 \rrbracket(\rho')} \in \mathcal{U}_i \searrow R_H(\ensuremath{\mathcal{D}}) \\\\
     \forall\, \rho, \rho'.\; \rho \approx \rho' \in R \;\leftrightarrow\;
       (\ensuremath{\mathcal{D}} :: \rho[\Uparrow] \approx \rho'[\Uparrow] \in R_T \;\wedge\;
        \rho(0) \approx \rho'(0) \in R_H(\ensuremath{\mathcal{D}}))}
    {\Gamma_1, x : S_1 \approx \Gamma_2, x : S_2 \searrow R}
  \end{mathpar}
  The second derivation is:
  \begin{mathpar}
    \inferrule[\textsc{Ctx-Ext}]
    {\Gamma_2 \approx \Gamma_3 \searrow R_T' \\
     R_T' \text{ is a PER} \\\\
     \forall\, \ensuremath{\mathcal{D}}' :: \rho \approx \rho' \in R_T'.\;
       \ensuremath{\llbracket S_2 \rrbracket(\rho)} \approx \ensuremath{\llbracket S_3 \rrbracket(\rho')} \in \mathcal{U}_j \searrow R_H'(\ensuremath{\mathcal{D}}') \\\\
     \forall\, \rho, \rho'.\; \rho \approx \rho' \in R' \;\leftrightarrow\;
       (\ensuremath{\mathcal{D}}' :: \rho[\Uparrow] \approx \rho'[\Uparrow] \in R_T' \;\wedge\;
        \rho(0) \approx \rho'(0) \in R_H'(\ensuremath{\mathcal{D}}'))}
    {\Gamma_2, x : S_2 \approx \Gamma_3, x : S_3 \searrow R'}
  \end{mathpar}

  For (1): We construct a \textsc{Ctx-Ext} derivation of
  $\Gamma_1, x : S_1 \approx \Gamma_3, x : S_3 \searrow R$.

  \emph{Premise 1} (tail):
  \begin{align*}
    &\Gamma_1 \approx \Gamma_3 \searrow R_T
      && \text{(by IH (1) on the tail)}
  \end{align*}

  \emph{Premise 2}: $R_T$ is a PER (by hypothesis).

  \emph{Premise 3} (head): Given $\ensuremath{\mathcal{D}} :: \rho \approx \rho' \in R_T$, we must show
  $\ensuremath{\llbracket S_1 \rrbracket(\rho)} \approx \ensuremath{\llbracket S_3 \rrbracket(\rho')} \in \mathcal{U}_i \searrow R_H''(\ensuremath{\mathcal{D}})$.
  \begin{align*}
    &\rho \approx \rho \in R_T
      && \text{(by symmetry + transitivity of $R_T$)} \\
    &\text{Let } \ensuremath{\mathrm{D}}_1 :: \rho \approx \rho \in R_T \\
    &\ensuremath{\llbracket S_1 \rrbracket(\rho)} \approx \ensuremath{\llbracket S_2 \rrbracket(\rho)} \in \mathcal{U}_i \searrow R_H(\ensuremath{\mathrm{D}}_1)
      && \text{(from first head premise at $\ensuremath{\mathrm{D}}_1$)} \\
    &R_T \Leftrightarrow R_T'
      && \text{(by \Cref{lem:univ-functional} on tails: same left context $\Gamma_2$)} \\
    &\rho \approx \rho' \in R_T'
      && \text{(from $\rho \approx \rho' \in R_T$ and $R_T \Leftrightarrow R_T'$)} \\
    &\text{Let } \ensuremath{\mathrm{D}}_2 :: \rho \approx \rho' \in R_T' \\
    &\ensuremath{\llbracket S_2 \rrbracket(\rho)} \approx \ensuremath{\llbracket S_3 \rrbracket(\rho')} \in \mathcal{U}_j \searrow R_H'(\ensuremath{\mathrm{D}}_2)
      && \text{(from second head premise at $\ensuremath{\mathrm{D}}_2$)} \\
    &\ensuremath{\llbracket S_1 \rrbracket(\rho)} \approx \ensuremath{\llbracket S_3 \rrbracket(\rho')} \in \mathcal{U}_i \searrow R_H(\ensuremath{\mathrm{D}}_1)
      && \text{(by \Cref{lem:univ-trans} (1))}
  \end{align*}
  Set $R_H''(\ensuremath{\mathcal{D}}) := R_H(\ensuremath{\mathrm{D}}_1)$.

  \emph{Premise 4} (biconditional): The biconditional characterizes the same $R$.
  Since $R_T$ is a PER, the quantification ranges over the same set of pairs.
  By \Cref{lem:univ-functional}, $R_H''(\ensuremath{\mathcal{D}}) \Leftrightarrow R_H(\ensuremath{\mathcal{D}})$ (both have the same
  left type $\ensuremath{\llbracket S_1 \rrbracket(\rho[\Uparrow])}$), so the biconditional is equivalent to the original.
  \begin{align*}
    &\Gamma_1, x : S_1 \approx \Gamma_3, x : S_3 \searrow R
      && \text{(by \textsc{Ctx-Ext})}
  \end{align*}

  \medskip
  For (2): Suppose $\rho_1 \approx \rho_2 \in R$ and $\rho_2 \approx \rho_3 \in R$.
  We must show $\rho_1 \approx \rho_3 \in R$, i.e.\ exhibit
  $\ensuremath{\mathcal{D}} :: \rho_1[\Uparrow] \approx \rho_3[\Uparrow] \in R_T$ with
  $\rho_1(0) \approx \rho_3(0) \in R_H(\ensuremath{\mathcal{D}})$.

  By the biconditional, from $\rho_1 \approx \rho_2 \in R$ we get
  $\ensuremath{\mathrm{D}}_1 :: \rho_1[\Uparrow] \approx \rho_2[\Uparrow] \in R_T$ with
  $\rho_1(0) \approx \rho_2(0) \in R_H(\ensuremath{\mathrm{D}}_1)$.
  From $\rho_2 \approx \rho_3 \in R$ we get
  $\ensuremath{\mathrm{D}}_2 :: \rho_2[\Uparrow] \approx \rho_3[\Uparrow] \in R_T$ with
  $\rho_2(0) \approx \rho_3(0) \in R_H(\ensuremath{\mathrm{D}}_2)$.
  \begin{align*}
    &\rho_1[\Uparrow] \approx \rho_3[\Uparrow] \in R_T
      && \text{(by IH (2) on tail; call this $\ensuremath{\mathcal{D}}$)} \\
    &R_H(\ensuremath{\mathrm{D}}_1) \Leftrightarrow R_H(\ensuremath{\mathrm{D}}_2) \Leftrightarrow R_H(\ensuremath{\mathcal{D}})
      && \text{(by \Cref{lem:univ-functional}: same left type)} \\
    &\rho_2(0) \approx \rho_3(0) \in R_H(\ensuremath{\mathrm{D}}_1)
      && \text{(from $R_H(\ensuremath{\mathrm{D}}_2) \Leftrightarrow R_H(\ensuremath{\mathrm{D}}_1)$)} \\
    &\rho_1(0) \approx \rho_3(0) \in R_H(\ensuremath{\mathrm{D}}_1)
      && \text{(by \Cref{lem:univ-trans} (2))} \\
    &\rho_1(0) \approx \rho_3(0) \in R_H(\ensuremath{\mathcal{D}})
      && \text{(by $R_H(\ensuremath{\mathrm{D}}_1) \Leftrightarrow R_H(\ensuremath{\mathcal{D}})$)}
  \end{align*}
  Hence $\rho_1 \approx \rho_3 \in R$ by the biconditional (with witness $\ensuremath{\mathcal{D}}$).

By induction on the context subtyping derivation.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{Ctx-$<$:-Emp}]
    { }
    {\cdot <: \cdot}
  \end{mathpar}
  Both $R$ and $R'$ are $\top$, so the inclusion is trivial.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{Ctx-$<$:-Ext}]
    {\Gamma <: \Gamma' \\
     \Gamma \approx \Gamma \searrow R_T \\\\
     \forall\, \ensuremath{\mathcal{D}} :: \rho \approx \rho' \in R_T.\;
       \ensuremath{\llbracket S \rrbracket(\rho)} \mathrel{<:_i} \ensuremath{\llbracket S' \rrbracket(\rho')} \\\\
     \Gamma, x : S \approx \Gamma, x : S \searrow R_1 \\
     \Gamma', x : S' \approx \Gamma', x : S' \searrow R_2}
    {\Gamma, x : S <: \Gamma', x : S'}
  \end{mathpar}
  Suppose $\rho \approx \rho' \in R$.
  By \Cref{lem:ctx-functional}, $R \Leftrightarrow R_1$
  (both derive from $\Gamma, x : S \approx \Gamma, x : S$), so $\rho \approx \rho' \in R_1$.
  We must show $\rho \approx \rho' \in R'$.
  By \Cref{lem:ctx-functional}, $R' \Leftrightarrow R_2$, so it suffices to show
  $\rho \approx \rho' \in R_2$.

  By the biconditional of $R_1$: from $\rho \approx \rho' \in R_1$ we obtain
  $\ensuremath{\mathcal{D}} :: \rho[\Uparrow] \approx \rho'[\Uparrow] \in R_T$ with
  $\rho(0) \approx \rho'(0) \in R_H(\ensuremath{\mathcal{D}})$,
  where $\ensuremath{\llbracket S \rrbracket(\rho[\Uparrow])} \approx \ensuremath{\llbracket S \rrbracket(\rho'[\Uparrow])} \in \mathcal{U}_i \searrow R_H(\ensuremath{\mathcal{D}})$.

  By the IH on the tail: from $\rho[\Uparrow] \approx \rho'[\Uparrow] \in R_T$ we get
  $\rho[\Uparrow] \approx \rho'[\Uparrow] \in R_T'$
  (where $R_T'$ is the tail PER of $R_2$; call this evidence $\ensuremath{\mathcal{D}}'$).

  By the subtyping premise: $\ensuremath{\llbracket S \rrbracket(\rho[\Uparrow])} \mathrel{<:_i} \ensuremath{\llbracket S' \rrbracket(\rho'[\Uparrow])}$.
  By the head premise of $R_2$ at $\ensuremath{\mathcal{D}}'$:
  $\ensuremath{\llbracket S' \rrbracket(\rho[\Uparrow])} \approx \ensuremath{\llbracket S' \rrbracket(\rho'[\Uparrow])} \in \mathcal{U}_i \searrow R_H'(\ensuremath{\mathcal{D}}')$.
  \begin{align*}
    &\rho(0) \approx \rho'(0) \in R_H(\ensuremath{\mathcal{D}})
      && \text{(from above)} \\
    &\rho(0) \approx \rho'(0) \in R_H'(\ensuremath{\mathcal{D}}')
      && \text{(by \Cref{lem:subty-respects}: $\ensuremath{\llbracket S \rrbracket(\rho[\Uparrow])} \mathrel{<:_i} \ensuremath{\llbracket S' \rrbracket(\rho[\Uparrow])}$)}
  \end{align*}
  Hence $\rho \approx \rho' \in R_2$ by the biconditional of $R_2$
  (with witness $\ensuremath{\mathcal{D}}'$ and head $\rho(0) \approx \rho'(0) \in R_H'(\ensuremath{\mathcal{D}}')$),
  and thus $\rho \approx \rho' \in R'$.

\label{lem:init-in-per}
  If $\Gamma \approx \Gamma \searrow R$, then
  ${\uparrow}^\Gamma \approx {\uparrow}^\Gamma \in R$.

\label{def:sem-wk-judge}
  The semantic judgment for weakening asks related environments respect weakenings:
  \begin{mathpar}
    \inferrule
    {\Gamma \approx \Gamma \searrow R \\ \Delta \approx \Delta \searrow R' \\
    \forall \rho \approx \rho' \in R, \ensuremath{\llbracket \psi \rrbracket(\rho)} \approx \ensuremath{\llbracket \psi \rrbracket(\rho')} \in R'}
    {\semweak \psi \Delta}
  \end{mathpar}

\label{lem:sem-wk-id}
  If $\Gamma \approx \Gamma \searrow R$, then $
  \singlejudge[\ensuremath{\textsf{id}}]{\vDash_w}{\Gamma : $}
.

\label{lem:sem-wk-comp}
  If $
  \singlejudge[\psi]{\vDash_w}{\Gamma' : $}
 and $\semweak[\Gamma']{\phi}{\Gamma''}$, then
  $
  \singlejudge[\phi \circ \psi]{\vDash_w}{\Gamma'' : $}
.

\label{def:sem-subst-eq}
  The semantic judgment for substitutions asks substitutions to be related under any
  semantic weakenings:
  \begin{mathpar}
    \inferrule
    {\Gamma \approx \Gamma \searrow R \\ \Delta \approx \Delta \searrow R_O \\
      \forall \Gamma' \approx \Gamma' \searrow R'. \forall
      \semweak[\Gamma']\psi\Gamma. \forall 
    \rho \approx \rho' \in R'. \{\ensuremath{\llbracket \sigma[\psi] \rrbracket(\rho)},
    \ensuremath{\llbracket \sigma \rrbracket(\ensuremath{\llbracket \psi \rrbracket(\rho)})}, \ensuremath{\llbracket \sigma' \rrbracket(\ensuremath{\llbracket \psi \rrbracket(\rho')})},
    \ensuremath{\llbracket \sigma'[\psi] \rrbracket(\rho')}\} \subseteq R_O}
    {\semtyeq \sigma{\sigma'}\Delta}
  \end{mathpar}

\label{def:sem-term-eq}
  The semantic judgment for terms requires stability under semantic substitutions:
  \begin{mathpar}
    \inferrule
    {\Gamma \approx \Gamma \searrow R \\ \exists i \\
      \parbox{0.95\textwidth}{\raggedright$\forall \Gamma' \approx \Gamma' \searrow
  R'. \forall \semtyeq[\Gamma'] \sigma{\sigma'}\Gamma. \forall \ensuremath{\mathcal{D}} :: \rho \approx \rho' \in R'.$ \\ \raggedleft$\{\ensuremath{\llbracket T[\sigma] \rrbracket(\rho)},
    \ensuremath{\llbracket T \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})}, \ensuremath{\llbracket T \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})},
    \ensuremath{\llbracket T[\sigma'] \rrbracket(\rho')}\} \subseteq \mathcal{U}_i \searrow R_T$ \\
  $ \wedge \{\ensuremath{\llbracket t[\sigma] \rrbracket(\rho)},
    \ensuremath{\llbracket t \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})}, \ensuremath{\llbracket t' \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})},
    \ensuremath{\llbracket t'[\sigma'] \rrbracket(\rho')}\} \subseteq R_T$}
}
    {\semtyeq{t}{t'}T}
  \end{mathpar}

\label{def:sem-subty-judge}
  The semantic subtyping judgment holds when the evaluations of the two types
  commute with their respective substitutions and are related by semantic subtyping:
  \begin{mathpar}
    \inferrule
    {\Gamma \approx \Gamma \searrow R \\ \exists i \\\\
      \parbox{0.90\textwidth}{\raggedright$\forall \Gamma' \approx \Gamma' \searrow
  R'. \forall \semtyeq[\Gamma'] \sigma{\sigma'}\Gamma. \forall \ensuremath{\mathcal{D}} :: \rho \approx \rho' \in R'.$ \\ \raggedleft
  $\ensuremath{\llbracket S[\sigma] \rrbracket(\rho)} \approx \ensuremath{\llbracket S \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})} \in \mathcal{U}_i$ \\
  $\wedge\; \ensuremath{\llbracket T[\sigma'] \rrbracket(\rho')} \approx \ensuremath{\llbracket T \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})} \in \mathcal{U}_i$ \\
  $\wedge\; \ensuremath{\llbracket S \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})} \mathrel{<:_i} \ensuremath{\llbracket T \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})}$}
}
    {\Gamma \vDash S \subseteq T}
  \end{mathpar}

\label{def:sem-ctx}
  The judgment $\ensuremath{\vDash \Gamma}$ is defined inductively:
  \begin{mathpar}
    \inferrule[\textsc{Sem-Ctx-Emp}]
    { }
    {\ensuremath{\vDash \cdot}}

    \inferrule[\textsc{Sem-Ctx-Ext}]
    {\ensuremath{\vDash \Gamma} \\
     (\Gamma, x : S) \approx (\Gamma, x : S) \searrow R \\
     \semtyeq[\Gamma]{S}{S}{\ensuremath{\texttt{Ty}_{i}}}}
    {\ensuremath{\vDash \Gamma, x : S}}
  \end{mathpar}

\label{lem:sem-wk}
  If $\semweak[\Delta]{\psi}{\Gamma}$, then
  $\semtyeq[\Delta]{\psi}{\psi}{\Gamma}$.

\label{lem:sem-wk-subst-pre}
  If $\semtyeq[\Gamma]{\sigma}{\sigma'}{\Delta, x:T}$, then
  $\semtyeq[\Gamma]{\Uparrow \circ \sigma}{\Uparrow \circ \sigma'}{\Delta}$.

Let $\Gamma' \approx \Gamma' \searrow R'$, $\semweak[\Gamma']{\phi}{\Gamma}$,
  and $\rho \approx \rho' \in R'$ be given.
  We must show
  \[
    \{\ensuremath{\llbracket (\Uparrow \circ \sigma)[\phi] \rrbracket(\rho)},\;
    \ensuremath{\llbracket \Uparrow \circ \sigma \rrbracket(\ensuremath{\llbracket \phi \rrbracket(\rho)})},\;
    \ensuremath{\llbracket \Uparrow \circ \sigma' \rrbracket(\ensuremath{\llbracket \phi \rrbracket(\rho')})},\;
    \ensuremath{\llbracket (\Uparrow \circ \sigma')[\phi] \rrbracket(\rho')}\} \subseteq R_\Delta.
  \]

  By \Cref{lem:wk-subst-interact}\,(2) and associativity (\Cref{lem:subst-assoc}):
  $(\Uparrow \circ \sigma)[\phi] = (\Uparrow \circ \sigma) \circ \phi
  = \Uparrow \circ (\sigma \circ \phi) = \Uparrow \circ \sigma[\phi]$.
  For any substitution $\tau$ and any environment $\rho_0$,
  the pointwise definitions give
  \begin{align*}
    \ensuremath{\llbracket \Uparrow \circ \tau \rrbracket(\rho_0)}(y)
    &= \ensuremath{\llbracket (\Uparrow \circ \tau)(y) \rrbracket(\rho_0)}
      && \text{(pointwise definition of substitution evaluation)} \\
    &= \ensuremath{\llbracket \Uparrow(y)[\tau] \rrbracket(\rho_0)}
      && \text{(definition of composition)} \\
    &= \ensuremath{\llbracket \tau(y+1) \rrbracket(\rho_0)}
      && \text{(since $\Uparrow(y) = y+1$ is a variable)} \\
    &= \ensuremath{\llbracket \tau \rrbracket(\rho_0)}(y+1)
      && \text{(pointwise definition again)} \\
    &= (\ensuremath{\llbracket \tau \rrbracket(\rho_0)})[\Uparrow](y)
      && \text{(definition of $\rho[\Uparrow]$)}
  \end{align*}
  Hence $\ensuremath{\llbracket \Uparrow \circ \tau \rrbracket(\rho_0)} = (\ensuremath{\llbracket \tau \rrbracket(\rho_0)})[\Uparrow]$
  definitionally.
  Specialising:
  \begin{align*}
    \ensuremath{\llbracket (\Uparrow \circ \sigma)[\phi] \rrbracket(\rho)}
      &= \ensuremath{\llbracket \Uparrow \circ \sigma[\phi] \rrbracket(\rho)}
      = (\ensuremath{\llbracket \sigma[\phi] \rrbracket(\rho)})[\Uparrow], \\
    \ensuremath{\llbracket \Uparrow \circ \sigma \rrbracket(\ensuremath{\llbracket \phi \rrbracket(\rho)})}
      &= (\ensuremath{\llbracket \sigma \rrbracket(\ensuremath{\llbracket \phi \rrbracket(\rho)})})[\Uparrow],
  \end{align*}
  and analogously for the primed pair.
  So it suffices to show
  \[
    \{(\ensuremath{\llbracket \sigma[\phi] \rrbracket(\rho)})[\Uparrow],\;
    (\ensuremath{\llbracket \sigma \rrbracket(\ensuremath{\llbracket \phi \rrbracket(\rho)})})[\Uparrow],\;
    (\ensuremath{\llbracket \sigma' \rrbracket(\ensuremath{\llbracket \phi \rrbracket(\rho')})})[\Uparrow],\;
    (\ensuremath{\llbracket \sigma'[\phi] \rrbracket(\rho')})[\Uparrow]\} \subseteq R_\Delta.
  \]

  Apply $\semtyeq[\Gamma]{\sigma}{\sigma'}{\Delta, x:T}$ at $\Gamma'$, $\phi$, and
  $\rho \approx \rho' \in R'$: writing $R_{\Delta,x:T}$ for the context PER of
  $\Delta, x:T$,
  \[
    \{\ensuremath{\llbracket \sigma[\phi] \rrbracket(\rho)},\; \ensuremath{\llbracket \sigma \rrbracket(\ensuremath{\llbracket \phi \rrbracket(\rho)})},\;
    \ensuremath{\llbracket \sigma' \rrbracket(\ensuremath{\llbracket \phi \rrbracket(\rho')})},\; \ensuremath{\llbracket \sigma'[\phi] \rrbracket(\rho')}\}
    \subseteq R_{\Delta,x:T}.
  \]
  By the biconditional of $R_{\Delta,x:T}$ (from \textsc{Ctx-Ext}), every pair
  $\rho_0 \approx \rho_0' \in R_{\Delta,x:T}$ satisfies
  $\rho_0[\Uparrow] \approx \rho_0'[\Uparrow] \in R_\Delta$.
  Applying this pairwise to the four $R_{\Delta,x:T}$-related values above yields the
  desired $R_\Delta$-relatedness of the four shifted values.

\label{lem:sem-sym}
  If $\semtyeq[\Gamma]{\sigma}{\sigma'}{\Delta}$, then
  $\semtyeq[\Gamma]{\sigma'}{\sigma}{\Delta}$.

\label{lem:sem-wk-q}
  If $\semweak[\Gamma]{\psi}{\Delta}$ and $\semtyeq[\Delta]{S}{S}{\ensuremath{\texttt{Ty}_{i}}}$,
  then $\semweak[\Gamma, x : S[\psi]]{q(\psi)}{\Delta, x : S}$.

\label{lem:sem-ext-pre2}
  If $\semtyeq[\Gamma]{\sigma}{\sigma'}{\Delta}$,
  $\semtyeq[\Delta]{t}{t'}{T}$, and
  $\semtyeq[\Delta, x : T]{s}{s'}{S}$, then
  \[
    \semtyeq[\Gamma]
      {(\sigma,\, t[\sigma]/x,\, s[\sigma,\, t[\sigma]/x]/y)}
      {(\sigma',\, t'[\sigma']/x,\, s'[\sigma',\, t'[\sigma']/x]/y)}
      {\Delta, x : T, y : S}.
  \]

\label{lem:fund-trans}
  If $\semtyeq[\Gamma]{t}{t'}{T}$ and $\semtyeq[\Gamma]{t'}{t''}{T}$,
  then $\semtyeq[\Gamma]{t}{t''}{T}$.

Let $\Gamma' \approx \Gamma' \searrow R'$,
  $\semtyeq[\Gamma']{\sigma}{\sigma'}{\Gamma}$, and $\ensuremath{\mathcal{D}} :: \rho \approx \rho' \in R'$.

  Apply the first hypothesis at $\sigma \approx \sigma'$, $\rho \approx \rho'$:
  \begin{align*}
    &\ensuremath{\llbracket t[\sigma] \rrbracket(\rho)} \approx \ensuremath{\llbracket t'[\sigma'] \rrbracket(\rho')} \in R_T
      && \text{(four-value pattern, outer-LHS vs outer-RHS)}
  \end{align*}
  Apply the second hypothesis at $\sigma' \approx \sigma'$ (reflexive,
  by \Cref{lem:sem-sym,lem:sem-trans}) and $\rho' \approx \rho'$ (reflexive,
  by symmetry of $R'$):
  \begin{align*}
    &\ensuremath{\llbracket t'[\sigma'] \rrbracket(\rho')} \approx \ensuremath{\llbracket t''[\sigma'] \rrbracket(\rho')} \in R_T
      && \text{(four-value pattern, outer-LHS vs outer-RHS)}
  \end{align*}
  By transitivity of $R_T$ (\Cref{lem:univ-trans}):
  \begin{align*}
    &\ensuremath{\llbracket t[\sigma] \rrbracket(\rho)} \approx \ensuremath{\llbracket t''[\sigma'] \rrbracket(\rho')} \in R_T
      && \text{(transitivity)}
  \end{align*}
  This is the outer-LHS vs outer-RHS of the goal's four-value pattern.
  The other three pairs follow by combining the first hypothesis (giving
  $\ensuremath{\llbracket t[\sigma] \rrbracket(\rho)}, \ensuremath{\llbracket t \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})}, \ensuremath{\llbracket t' \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})},
  \ensuremath{\llbracket t'[\sigma'] \rrbracket(\rho')}$ pairwise in $R_T$) with the above transitivity step.

\label{lem:fund-ctx-ext}
  If $\ensuremath{\vDash \Gamma}$ and $\semtyeq[\Gamma]{S}{S}{\ensuremath{\texttt{Ty}_{i}}}$, then
  $\ensuremath{\vDash \Gamma, x:S}$.

By \Cref{lem:sem-ctx-per}, $\Gamma \approx \Gamma \searrow R$ for some $R$.
  Let $\Gamma' \approx \Gamma' \searrow R'$,
  $\semtyeq[\Gamma']{\sigma}{\sigma'}{\Gamma}$, and
  $\ensuremath{\mathcal{D}} :: \rho \approx \rho' \in R'$ be given.
  We must exhibit $R_T$ such that
  \[
    \{\ensuremath{\llbracket \ensuremath{\texttt{Ty}_{1+i}}[\sigma] \rrbracket(\rho)},\;
    \ensuremath{\llbracket \ensuremath{\texttt{Ty}_{1+i}} \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})},\;
    \ensuremath{\llbracket \ensuremath{\texttt{Ty}_{1+i}} \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})},\;
    \ensuremath{\llbracket \ensuremath{\texttt{Ty}_{1+i}}[\sigma'] \rrbracket(\rho')}\}
    \subseteq \mathcal{U}_{2+i} \searrow R_T
  \]
  and
  \[
    \{\ensuremath{\llbracket \ensuremath{\texttt{Ty}_{i}}[\sigma] \rrbracket(\rho)},\;
    \ensuremath{\llbracket \ensuremath{\texttt{Ty}_{i}} \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})},\;
    \ensuremath{\llbracket \ensuremath{\texttt{Ty}_{i}} \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})},\;
    \ensuremath{\llbracket \ensuremath{\texttt{Ty}_{i}}[\sigma'] \rrbracket(\rho')}\}
    \subseteq R_T.
  \]

  \emph{Type part.}
  Since $\ensuremath{\texttt{Ty}_{1+i}}$ is closed (it has no free variables), we compute:
  \begin{align*}
    &\ensuremath{\llbracket \ensuremath{\texttt{Ty}_{1+i}}[\sigma] \rrbracket(\rho)}
      = \ensuremath{\llbracket \ensuremath{\texttt{Ty}_{1+i}} \rrbracket(\rho)}
      && \text{(since $\ensuremath{\texttt{Ty}_{1+i}}[\sigma] = \ensuremath{\texttt{Ty}_{1+i}}$)} \\
    &\quad = U_{1+i}
      && \text{(by evaluation of $\ensuremath{\texttt{Ty}_{1+i}}$)} \\
    &\ensuremath{\llbracket \ensuremath{\texttt{Ty}_{1+i}} \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})} = U_{1+i}
      && \text{(by evaluation of $\ensuremath{\texttt{Ty}_{1+i}}$)}
  \end{align*}
  Identical computations apply to the other two type values.
  Hence all four type values collapse to $U_{1+i}$, and we need
  $U_{1+i} \approx U_{1+i} \in \mathcal{U}_{2+i} \searrow R_T$ for some $R_T$.
  \begin{align*}
    &U_{1+i} \approx U_{1+i} \in \mathcal{U}_{2+i} \searrow R_T
      \text{ with } R_T \Leftrightarrow \mathcal{U}_{1+i}
      && \text{(by \textsc{U-Univ}, since $1{+}i < 2{+}i$)}
  \end{align*}

  \emph{Term part.}
  Since $\ensuremath{\texttt{Ty}_{i}}$ is closed, the same computation gives
  \begin{align*}
    &\ensuremath{\llbracket \ensuremath{\texttt{Ty}_{i}}[\sigma] \rrbracket(\rho)}
      = \ensuremath{\llbracket \ensuremath{\texttt{Ty}_{i}} \rrbracket(\rho)}
      = U_i
      && \text{(closed term, by evaluation)} \\
    &\ensuremath{\llbracket \ensuremath{\texttt{Ty}_{i}} \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})} = U_i
      && \text{(by evaluation)}
  \end{align*}
  and similarly for the primed values, so all four term values collapse to $U_i$.
  Since $R_T \Leftrightarrow \mathcal{U}_{1+i}$, it suffices to show
  $U_i \approx U_i \in \mathcal{U}_{1+i}$, i.e.\ $\exists R_0.\; U_i \approx U_i \in \mathcal{U}_{1+i} \searrow R_0$.
  \begin{align*}
    &U_i \approx U_i \in \mathcal{U}_{1+i} \searrow R_0
      \text{ with } R_0 \Leftrightarrow \mathcal{U}_i
      && \text{(by \textsc{U-Univ}, since $i < 1{+}i$)}
  \end{align*}
  Hence $U_i \approx U_i \in R_T$, and the four-value pattern follows.

By \Cref{lem:sem-ctx-per}, $\Gamma \approx \Gamma \searrow R$ for some $R$.
  Let $\Gamma' \approx \Gamma' \searrow R'$,
  $\semtyeq[\Gamma']{\sigma}{\sigma'}{\Gamma}$, and
  $\ensuremath{\mathcal{D}} :: \rho \approx \rho' \in R'$ be given.
  We must exhibit $R_T$ such that
  \[
    \{\ensuremath{\llbracket \ensuremath{\texttt{Ty}_{0}}[\sigma] \rrbracket(\rho)},\;
    \ensuremath{\llbracket \ensuremath{\texttt{Ty}_{0}} \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})},\;
    \ensuremath{\llbracket \ensuremath{\texttt{Ty}_{0}} \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})},\;
    \ensuremath{\llbracket \ensuremath{\texttt{Ty}_{0}}[\sigma'] \rrbracket(\rho')}\}
    \subseteq \mathcal{U}_1 \searrow R_T
  \]
  and
  \[
    \{\ensuremath{\llbracket \ensuremath{\texttt{Nat}}[\sigma] \rrbracket(\rho)},\;
    \ensuremath{\llbracket \ensuremath{\texttt{Nat}} \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})},\;
    \ensuremath{\llbracket \ensuremath{\texttt{Nat}} \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})},\;
    \ensuremath{\llbracket \ensuremath{\texttt{Nat}}[\sigma'] \rrbracket(\rho')}\}
    \subseteq R_T.
  \]

  \emph{Type part.}
  Since $\ensuremath{\texttt{Ty}_{0}}$ is closed, we compute:
  \begin{align*}
    &\ensuremath{\llbracket \ensuremath{\texttt{Ty}_{0}}[\sigma] \rrbracket(\rho)}
      = \ensuremath{\llbracket \ensuremath{\texttt{Ty}_{0}} \rrbracket(\rho)}
      = U_0
      && \text{(closed term, by evaluation)} \\
    &\ensuremath{\llbracket \ensuremath{\texttt{Ty}_{0}} \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})} = U_0
      && \text{(by evaluation)}
  \end{align*}
  Identical computations give the same value for the other two type values.
  All four type values collapse to $U_0$, and we need
  $U_0 \approx U_0 \in \mathcal{U}_1 \searrow R_T$.
  \begin{align*}
    &U_0 \approx U_0 \in \mathcal{U}_1 \searrow R_T
      \text{ with } R_T \Leftrightarrow \mathcal{U}_0
      && \text{(by \textsc{U-Univ}, since $0 < 1$)}
  \end{align*}

  \emph{Term part.}
  Since $\ensuremath{\texttt{Nat}}$ is closed, all four term values collapse to $N$:
  \begin{align*}
    &\ensuremath{\llbracket \ensuremath{\texttt{Nat}}[\sigma] \rrbracket(\rho)}
      = \ensuremath{\llbracket \ensuremath{\texttt{Nat}} \rrbracket(\rho)}
      = N
      && \text{(closed term, by evaluation)} \\
    &\ensuremath{\llbracket \ensuremath{\texttt{Nat}} \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})} = N
      && \text{(by evaluation)}
  \end{align*}
  Since $R_T \Leftrightarrow \mathcal{U}_0$, it suffices to show $N \approx N \in \mathcal{U}_0$,
  i.e.\ $\exists R_0.\; N \approx N \in \mathcal{U}_0 \searrow R_0$.
  \begin{align*}
    &N \approx N \in \mathcal{U}_0 \searrow R_0
      \text{ with } R_0 \Leftrightarrow \textsf{Nat}
      && \text{(by \textsc{U-Nat})}
  \end{align*}
  Hence $N \approx N \in R_T$, and the four-value pattern follows.

\label{lem:fund-pi-wf}
  If $\semtyeq[\Gamma]{S}{S'}{\ensuremath{\texttt{Ty}_{i}}}$ and $\semtyeq[\Gamma, x:S]{T}{T'}{\ensuremath{\texttt{Ty}_{i}}}$,
  then $\semtyeq[\Gamma]{\Pi(x:S).\,T}{\Pi(x:S').\,T'}{\ensuremath{\texttt{Ty}_{i}}}$.

\label{lem:fund-var-lookup}
  Suppose $\ensuremath{\vDash \Gamma}$, $\Gamma' \approx \Gamma' \searrow R'$,
  $\semtyeq[\Gamma']{\sigma}{\sigma'}{\Gamma}$, and
  $\ensuremath{\mathcal{D}} :: \rho \approx \rho' \in R'$.
  Then for every $x : T \in \Gamma$, there exists $R_T$ such that
  \begin{align*}
    &\{\ensuremath{\llbracket T[\sigma] \rrbracket(\rho)},\; \ensuremath{\llbracket T \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})},\;
      \ensuremath{\llbracket T \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})},\; \ensuremath{\llbracket T[\sigma'] \rrbracket(\rho')}\}
      \subseteq \mathcal{U}_i \searrow R_T \\
    &\text{and}\quad
      \{\ensuremath{\llbracket x[\sigma] \rrbracket(\rho)},\; \ensuremath{\llbracket x \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})},\;
      \ensuremath{\llbracket x \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})},\; \ensuremath{\llbracket x[\sigma'] \rrbracket(\rho')}\} \subseteq R_T.
  \end{align*}

By induction on the lookup derivation $x : T \in \Gamma$, with $\Gamma'$, $R'$,
  $\sigma$, $\sigma'$, $\rho$, $\rho'$, and the witness $\ensuremath{\mathcal{D}}$ fixed throughout.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule
    { }
    {x_0 : S[\Uparrow] \in \Delta, x_0 : S}
  \end{mathpar}
  Here $\Gamma = \Delta, x_0 : S$, $x = x_0$, and $T = S[\Uparrow]$.
  Inverting $\ensuremath{\vDash \Delta, x_0 : S}$ via \textsc{Sem-Ctx-Ext} gives
  $\ensuremath{\vDash \Delta}$, the packaged context PER
  $(\Delta, x_0 : S) \approx (\Delta, x_0 : S) \searrow R_\Gamma$, and
  $\semtyeq[\Delta]{S}{S}{\ensuremath{\texttt{Ty}_{i}}}$ for some $i$.
  Inverting the context PER via \textsc{Ctx-Ext} gives
  $\Delta \approx \Delta \searrow R_\Delta$, a head family $R_H$ with
  $\ensuremath{\llbracket S \rrbracket(\rho_0)} \approx \ensuremath{\llbracket S \rrbracket(\rho_0')} \in \mathcal{U}_i \searrow R_H(\ensuremath{\mathcal{D}}_\Delta)$
  for $\ensuremath{\mathcal{D}}_\Delta :: \rho_0 \approx \rho_0' \in R_\Delta$, and the biconditional
  \begin{align*}
    &\rho_1 \approx \rho_1' \in R_\Gamma
      \;\leftrightarrow\;
      (\ensuremath{\mathcal{D}}_\Delta :: \rho_1[\Uparrow] \approx \rho_1'[\Uparrow] \in R_\Delta
        \;\wedge\;
        \rho_1(0) \approx \rho_1'(0) \in R_H(\ensuremath{\mathcal{D}}_\Delta)).
  \end{align*}

  Instantiate $\semtyeq[\Gamma']{\sigma}{\sigma'}{\Gamma}$ at $\Gamma'$,
  $\semweak[\Gamma']{\ensuremath{\textsf{id}}}{\Gamma'}$ (\Cref{lem:sem-wk-id}), and $\ensuremath{\mathcal{D}}$:
  using $\sigma[\ensuremath{\textsf{id}}] = \sigma$ and $\ensuremath{\llbracket \ensuremath{\textsf{id}} \rrbracket(\rho)} = \rho$ we obtain
  $\ensuremath{\llbracket \sigma \rrbracket(\rho)} \approx \ensuremath{\llbracket \sigma' \rrbracket(\rho')} \in R_\Gamma$.
  By the biconditional of $R_\Gamma$, there exists $\ensuremath{\mathcal{D}}_\Delta$ with
  \begin{align*}
    &\ensuremath{\mathcal{D}}_\Delta :: (\ensuremath{\llbracket \sigma \rrbracket(\rho)})[\Uparrow] \approx (\ensuremath{\llbracket \sigma' \rrbracket(\rho')})[\Uparrow]
      \in R_\Delta
      && \text{(tail)} \\
    &(\ensuremath{\llbracket \sigma \rrbracket(\rho)})(0) \approx (\ensuremath{\llbracket \sigma' \rrbracket(\rho')})(0) \in R_H(\ensuremath{\mathcal{D}}_\Delta)
      && \text{(head)}
  \end{align*}
  Set $R_T := R_H(\ensuremath{\mathcal{D}}_\Delta)$.

  \emph{Type part.}
  We must show
  $\{\ensuremath{\llbracket  \rrbracket(\rho)},\; \ensuremath{\llbracket S[\Uparrow] \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})},\;
    \ensuremath{\llbracket S[\Uparrow] \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})},\; \ensuremath{\llbracket  \rrbracket(\rho')}\}
   \subseteq \mathcal{U}_i \searrow R_T$.
  We obtain this by two instantiations of $\semtyeq[\Delta]{S}{S}{\ensuremath{\texttt{Ty}_{i}}}$, bridged
  through a shared inner value.

  By \Cref{lem:sem-ctx-per}, $\Gamma \approx \Gamma \searrow R_\Gamma$.
  By \Cref{lem:sem-wk-shift}, $\semweak[\Gamma]{\Uparrow}{\Delta}$.
  By \Cref{lem:sem-wk-subst-pre} on $\semweak[\Gamma]{\Uparrow}{\Delta}$ and
  $\semtyeq[\Gamma']{\sigma}{\sigma'}{\Gamma}$:
  $\semtyeq[\Gamma']{\Uparrow \circ \sigma}{\Uparrow \circ \sigma'}{\Delta}$.

  \emph{First instantiation.}
  Apply $\semtyeq[\Delta]{S}{S}{\ensuremath{\texttt{Ty}_{i}}}$ at $\Gamma'$,
  $\semtyeq[\Gamma']{\Uparrow \circ \sigma}{\Uparrow \circ \sigma'}{\Delta}$, and $\ensuremath{\mathcal{D}}$:
  for some $R_1$,
  \begin{align*}
    &\{\ensuremath{\llbracket S[\Uparrow \circ \sigma] \rrbracket(\rho)},\;
      \ensuremath{\llbracket S \rrbracket(\ensuremath{\llbracket \Uparrow \circ \sigma \rrbracket(\rho)})},\;
      \ensuremath{\llbracket S \rrbracket(\ensuremath{\llbracket \Uparrow \circ \sigma' \rrbracket(\rho')})},\;
      \ensuremath{\llbracket S[\Uparrow \circ \sigma'] \rrbracket(\rho')}\} \subseteq \mathcal{U}_i \searrow R_1.
  \end{align*}
  By \Cref{lem:wk-subst-interact}\,(1), $ = S[\Uparrow \circ \sigma]$,
  so the outer values of the first instantiation match the goal's outer values.

  \emph{Second instantiation.}
  By \Cref{lem:sem-wk} on $\semweak[\Gamma]{\Uparrow}{\Delta}$:
  $\semtyeq[\Gamma]{\Uparrow}{\Uparrow}{\Delta}$.
  From $\semtyeq[\Gamma']{\sigma}{\sigma'}{\Gamma}$ at $\Gamma'$, $\ensuremath{\textsf{id}}$, $\ensuremath{\mathcal{D}}$:
  $\ensuremath{\llbracket \sigma \rrbracket(\rho)} \approx \ensuremath{\llbracket \sigma' \rrbracket(\rho')} \in R_\Gamma$.
  Apply $\semtyeq[\Delta]{S}{S}{\ensuremath{\texttt{Ty}_{i}}}$ at $\Gamma$ (using $R_\Gamma$),
  $\semtyeq[\Gamma]{\Uparrow}{\Uparrow}{\Delta}$, and
  $\ensuremath{\llbracket \sigma \rrbracket(\rho)} \approx \ensuremath{\llbracket \sigma' \rrbracket(\rho')} \in R_\Gamma$:
  for some $R_2$,
  \begin{align*}
    &\{\ensuremath{\llbracket S[\Uparrow] \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})},\;
      \ensuremath{\llbracket S \rrbracket(\ensuremath{\llbracket \Uparrow \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})})},\;
      \ensuremath{\llbracket S \rrbracket(\ensuremath{\llbracket \Uparrow \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})})},\;
      \ensuremath{\llbracket S[\Uparrow] \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})}\} \subseteq \mathcal{U}_i \searrow R_2.
  \end{align*}
  The outer values here are exactly the goal's inner values.

  \emph{Bridge.}
  We have already established
  $\ensuremath{\llbracket \Uparrow \circ \sigma \rrbracket(\rho_0)} = \ensuremath{\llbracket \Uparrow \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho_0)})}$
  (from the proof of \Cref{lem:sem-wk-subst-pre}).
  Hence the inner-left values of both instantiations coincide:
  \[
    \ensuremath{\llbracket S \rrbracket(\ensuremath{\llbracket \Uparrow \circ \sigma \rrbracket(\rho)})}
    = \ensuremath{\llbracket S \rrbracket(\ensuremath{\llbracket \Uparrow \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})})}.
  \]
  Analogously for the primed side.
  By \Cref{lem:univ-functional}, $R_1 \Leftrightarrow R_2$; set $R_T := R_1$.
  By symmetry and transitivity of $\mathcal{U}_i$ through the shared inner-left value, all
  four goal values are related in $\mathcal{U}_i \searrow R_T$.

  \emph{Term part.}
  Compute:
  \begin{align*}
    &\ensuremath{\llbracket x_0[\sigma] \rrbracket(\rho)}
      = \ensuremath{\llbracket \sigma(x_0) \rrbracket(\rho)}
      = (\ensuremath{\llbracket \sigma \rrbracket(\rho)})(0)
      && \text{(by definition of substitution and ev-var)} \\
    &\ensuremath{\llbracket x_0 \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})}
      = (\ensuremath{\llbracket \sigma \rrbracket(\rho)})(0)
      && \text{(by ev-var)}
  \end{align*}
  The outer-left and inner-left values coincide as $(\ensuremath{\llbracket \sigma \rrbracket(\rho)})(0)$; the
  primed pair coincides as $(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})(0)$.
  By the head clause,
  $(\ensuremath{\llbracket \sigma \rrbracket(\rho)})(0) \approx (\ensuremath{\llbracket \sigma' \rrbracket(\rho')})(0) \in R_T$, so all four
  term values are related in $R_T$.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule
    {y : S \in \Delta}
    {1{+}y : S[\Uparrow] \in \Delta, x_0 : U}
  \end{mathpar}
  Here $\Gamma = \Delta, x_0 : U$, $x = 1{+}y$, and $T = S[\Uparrow]$.
  Inverting $\ensuremath{\vDash \Delta, x_0 : U}$ gives $\ensuremath{\vDash \Delta}$, the packaged
  context PER $\Gamma \approx \Gamma \searrow R_\Gamma$, and
  $\semtyeq[\Delta]{U}{U}{\ensuremath{\texttt{Ty}_{j}}}$.

  By \Cref{lem:sem-wk-shift}, $\semweak[\Gamma]{\Uparrow}{\Delta}$.
  By \Cref{lem:sem-wk-subst-pre} on $\semweak[\Gamma]{\Uparrow}{\Delta}$ and
  $\semtyeq[\Gamma']{\sigma}{\sigma'}{\Gamma}$:
  $\semtyeq[\Gamma']{\Uparrow \circ \sigma}{\Uparrow \circ \sigma'}{\Delta}$.
  By \Cref{lem:sem-wk} on $\semweak[\Gamma]{\Uparrow}{\Delta}$:
  $\semtyeq[\Gamma]{\Uparrow}{\Uparrow}{\Delta}$.
  From $\semtyeq[\Gamma']{\sigma}{\sigma'}{\Gamma}$ at $\Gamma'$, $\ensuremath{\textsf{id}}$, $\ensuremath{\mathcal{D}}$:
  $\ensuremath{\llbracket \sigma \rrbracket(\rho)} \approx \ensuremath{\llbracket \sigma' \rrbracket(\rho')} \in R_\Gamma$.

  We apply the IH on $y : S \in \Delta$ \emph{twice}, paralleling the two
  instantiations used in the Base case.

  \emph{First IH instantiation.}
  Apply the IH to $y : S \in \Delta$ at $\Gamma'$, the semantic substitution
  $\semtyeq[\Gamma']{\Uparrow \circ \sigma}{\Uparrow \circ \sigma'}{\Delta}$,
  and $\ensuremath{\mathcal{D}}$: for some $R_1$,
  \begin{align*}
    &\{\ensuremath{\llbracket S[\Uparrow \circ \sigma] \rrbracket(\rho)},\;
      \ensuremath{\llbracket S \rrbracket(\ensuremath{\llbracket \Uparrow \circ \sigma \rrbracket(\rho)})},\;
      \ensuremath{\llbracket S \rrbracket(\ensuremath{\llbracket \Uparrow \circ \sigma' \rrbracket(\rho')})},\;
      \ensuremath{\llbracket S[\Uparrow \circ \sigma'] \rrbracket(\rho')}\} \subseteq \mathcal{U}_i \searrow R_1, \\
    &\{\ensuremath{\llbracket y[\Uparrow \circ \sigma] \rrbracket(\rho)},\;
      \ensuremath{\llbracket y \rrbracket(\ensuremath{\llbracket \Uparrow \circ \sigma \rrbracket(\rho)})},\;
      \ensuremath{\llbracket y \rrbracket(\ensuremath{\llbracket \Uparrow \circ \sigma' \rrbracket(\rho')})},\;
      \ensuremath{\llbracket y[\Uparrow \circ \sigma'] \rrbracket(\rho')}\} \subseteq R_1.
  \end{align*}

  \emph{Second IH instantiation.}
  Apply the IH to $y : S \in \Delta$ at $\Gamma$ (using $R_\Gamma$),
  the semantic substitution $\semtyeq[\Gamma]{\Uparrow}{\Uparrow}{\Delta}$, and
  $\ensuremath{\llbracket \sigma \rrbracket(\rho)} \approx \ensuremath{\llbracket \sigma' \rrbracket(\rho')} \in R_\Gamma$:
  for some $R_2$,
  \begin{align*}
    &\{\ensuremath{\llbracket S[\Uparrow] \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})},\;
      \ensuremath{\llbracket S \rrbracket(\ensuremath{\llbracket \Uparrow \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})})},\;
      \ensuremath{\llbracket S \rrbracket(\ensuremath{\llbracket \Uparrow \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})})},\;
      \ensuremath{\llbracket S[\Uparrow] \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})}\} \subseteq \mathcal{U}_i \searrow R_2, \\
    &\{\ensuremath{\llbracket y[\Uparrow] \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})},\;
      \ensuremath{\llbracket y \rrbracket(\ensuremath{\llbracket \Uparrow \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})})},\;
      \ensuremath{\llbracket y \rrbracket(\ensuremath{\llbracket \Uparrow \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})})},\;
      \ensuremath{\llbracket y[\Uparrow] \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})}\} \subseteq R_2.
  \end{align*}

  \emph{Match outer values to the goal.}
  By \Cref{lem:wk-subst-interact}\,(1):
  $ = S[\Uparrow \circ \sigma]$, so the first IH instantiation's
  outer-type values are exactly the goal's outer-type values.
  The second IH instantiation's outer-type values
  $\ensuremath{\llbracket S[\Uparrow] \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})}$ are exactly the goal's inner-type values.

  For the term values:
  \begin{align*}
    &\ensuremath{\llbracket (1{+}y)[\sigma] \rrbracket(\rho)}
      = \ensuremath{\llbracket \sigma(1{+}y) \rrbracket(\rho)}
      = \ensuremath{\llbracket (\Uparrow \circ \sigma)(y) \rrbracket(\rho)}
      = \ensuremath{\llbracket y[\Uparrow \circ \sigma] \rrbracket(\rho)} \\
    &\ensuremath{\llbracket 1{+}y \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})}
      = (\ensuremath{\llbracket \sigma \rrbracket(\rho)})(1{+}y)
      = \ensuremath{\llbracket y[\Uparrow] \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})}
  \end{align*}
  (using $(\Uparrow \circ \sigma)(y) = \sigma(y+1)$ and
  $\ensuremath{\llbracket y[\Uparrow] \rrbracket(\rho_0)} = \ensuremath{\llbracket \Uparrow(y) \rrbracket(\rho_0)} = \rho_0(y+1)$).
  Hence the first IH's outer-term values equal the goal's outer-term values, and
  the second IH's outer-term values equal the goal's inner-term values.

  \emph{Bridge via shared inner.}
  By the identity established in the proof of \Cref{lem:sem-wk-subst-pre},
  $\ensuremath{\llbracket \Uparrow \circ \sigma \rrbracket(\rho_0)} = (\ensuremath{\llbracket \sigma \rrbracket(\rho_0)})[\Uparrow]$
  for any $\rho_0$.
  Also $\ensuremath{\llbracket \Uparrow \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})} = (\ensuremath{\llbracket \sigma \rrbracket(\rho)})[\Uparrow]$
  by the pointwise definition of weakening evaluation.
  Hence the inner values of the two IH instantiations coincide:
  \begin{align*}
    &\ensuremath{\llbracket S \rrbracket(\ensuremath{\llbracket \Uparrow \circ \sigma \rrbracket(\rho)})}
      = \ensuremath{\llbracket S \rrbracket(\ensuremath{\llbracket \Uparrow \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})})}, \\
    &\ensuremath{\llbracket y \rrbracket(\ensuremath{\llbracket \Uparrow \circ \sigma \rrbracket(\rho)})}
      = \ensuremath{\llbracket y \rrbracket(\ensuremath{\llbracket \Uparrow \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})})},
  \end{align*}
  and analogously for the primed side.
  By \Cref{lem:univ-functional}, $R_1 \Leftrightarrow R_2$; set $R_T := R_1$.
  By symmetry and transitivity through the shared inner value, all four goal type
  values are related in $\mathcal{U}_i \searrow R_T$, and all four goal term values are
  related in $R_T$.

By \Cref{lem:sem-ctx-per}, $\Gamma \approx \Gamma \searrow R$ for some $R$.
  Let $\Gamma' \approx \Gamma' \searrow R'$,
  $\semtyeq[\Gamma']{\sigma}{\sigma'}{\Gamma}$, and
  $\ensuremath{\mathcal{D}} :: \rho \approx \rho' \in R'$ be given.
  We must show
  \[
    \{\ensuremath{\llbracket \ensuremath{\texttt{Nat}}[\sigma] \rrbracket(\rho)},\;
    \ensuremath{\llbracket \ensuremath{\texttt{Nat}} \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})},\;
    \ensuremath{\llbracket \ensuremath{\texttt{Nat}} \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})},\;
    \ensuremath{\llbracket \ensuremath{\texttt{Nat}}[\sigma'] \rrbracket(\rho')}\}
    \subseteq \mathcal{U}_0 \searrow R_T
  \]
  for some $R_T$, and
  \[
    \{\ensuremath{\llbracket \textsf{zero}[\sigma] \rrbracket(\rho)},\;
    \ensuremath{\llbracket \textsf{zero} \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})},\;
    \ensuremath{\llbracket \textsf{zero} \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})},\;
    \ensuremath{\llbracket \textsf{zero}[\sigma'] \rrbracket(\rho')}\}
    \subseteq R_T.
  \]

  \emph{Type part.}
  Since $\ensuremath{\texttt{Nat}}$ is closed, all four type values collapse to $N$:
  \begin{align*}
    &\ensuremath{\llbracket \ensuremath{\texttt{Nat}}[\sigma] \rrbracket(\rho)}
      = \ensuremath{\llbracket \ensuremath{\texttt{Nat}} \rrbracket(\rho)}
      = N
      && \text{(closed term, by evaluation)} \\
    &\ensuremath{\llbracket \ensuremath{\texttt{Nat}} \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})} = N
      && \text{(by evaluation)}
  \end{align*}
  and analogously for the primed pair.
  \begin{align*}
    &N \approx N \in \mathcal{U}_0 \searrow R_T
      \text{ with } R_T \Leftrightarrow \textsf{Nat}
      && \text{(by \textsc{U-Nat})}
  \end{align*}

  \emph{Term part.}
  Since $\textsf{zero}$ is closed, all four term values collapse to $\texttt{ze}$:
  \begin{align*}
    &\ensuremath{\llbracket \textsf{zero}[\sigma] \rrbracket(\rho)}
      = \ensuremath{\llbracket \textsf{zero} \rrbracket(\rho)}
      = \texttt{ze}
      && \text{(closed term, by evaluation)} \\
    &\ensuremath{\llbracket \textsf{zero} \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})} = \texttt{ze}
      && \text{(by evaluation)}
  \end{align*}
  Since $R_T \Leftrightarrow \textsf{Nat}$, it suffices to show $\texttt{ze} \approx \texttt{ze} \in \textsf{Nat}$.
  \begin{align*}
    &\texttt{ze} \approx \texttt{ze} \in \textsf{Nat}
      && \text{(by \textsc{Nat-Ze})}
  \end{align*}
  Hence $\texttt{ze} \approx \texttt{ze} \in R_T$, and the four-value pattern follows.

Let $\Gamma' \approx \Gamma' \searrow R'$,
  $\semtyeq[\Gamma']{\sigma}{\sigma'}{\Gamma}$, and
  $\ensuremath{\mathcal{D}} :: \rho \approx \rho' \in R'$ be given.

  \emph{Type part.}
  Identical to \Cref{lem:fund-ze}:
  $\{\ensuremath{\llbracket \ensuremath{\texttt{Nat}}[\sigma] \rrbracket(\rho)}, \ldots\} \subseteq \mathcal{U}_0 \searrow R_T$ with
  $R_T \Leftrightarrow \textsf{Nat}$ by \textsc{U-Nat}.

  \emph{Term part.}
  We compute the four term values, using that substitution and evaluation distribute
  over $\textsf{su}$:
  \begin{align*}
    &\ensuremath{\llbracket (\textsf{succ}~t)[\sigma] \rrbracket(\rho)}
      = \ensuremath{\llbracket \textsf{succ}~t[\sigma] \rrbracket(\rho)}
      && \text{(by definition of substitution on $\textsf{su}$)} \\
    &\quad = \texttt{su}(\ensuremath{\llbracket t[\sigma] \rrbracket(\rho)})
      && \text{(by evaluation of $\textsf{su}$)} \\[4pt]
    &\ensuremath{\llbracket \textsf{succ}~t \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})}
      = \texttt{su}(\ensuremath{\llbracket t \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})})
      && \text{(by evaluation of $\textsf{su}$)}
  \end{align*}
  Analogous computations apply to the primed pair, giving
  $\texttt{su}(\ensuremath{\llbracket t' \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})})$ and $\texttt{su}(\ensuremath{\llbracket t'[\sigma'] \rrbracket(\rho')})$.

  By the hypothesis $\semtyeq[\Gamma]{t}{t'}{\ensuremath{\texttt{Nat}}}$ applied at $\Gamma'$,
  $\sigma \approx \sigma'$, and $\rho \approx \rho' \in R'$, the term part gives
  \begin{align*}
    &\{\ensuremath{\llbracket t[\sigma] \rrbracket(\rho)},\;
      \ensuremath{\llbracket t \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})},\;
      \ensuremath{\llbracket t' \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})},\;
      \ensuremath{\llbracket t'[\sigma'] \rrbracket(\rho')}\}
      \subseteq \textsf{Nat}
      && \text{(by hypothesis on $t, t'$)}
  \end{align*}
  Applying \textsc{Nat-Su} pointwise (using transitivity of $\textsf{Nat}$,
  \Cref{lem:nat-per}, to chain the four values):
  \begin{align*}
    &\texttt{su}(\ensuremath{\llbracket t[\sigma] \rrbracket(\rho)}) \approx \texttt{su}(\ensuremath{\llbracket t \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})}) \in \textsf{Nat}
      && \text{(by \textsc{Nat-Su})} \\
    &\texttt{su}(\ensuremath{\llbracket t \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})}) \approx \texttt{su}(\ensuremath{\llbracket t' \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})}) \in \textsf{Nat}
      && \text{(by \textsc{Nat-Su})} \\
    &\texttt{su}(\ensuremath{\llbracket t' \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})}) \approx \texttt{su}(\ensuremath{\llbracket t'[\sigma'] \rrbracket(\rho')}) \in \textsf{Nat}
      && \text{(by \textsc{Nat-Su})}
  \end{align*}
  By transitivity of $\textsf{Nat}$, all four are related in $\textsf{Nat}$, hence in $R_T$.

\label{lem:fund-lam}
  If $\semtyeq[\Gamma]{S}{S}{\ensuremath{\texttt{Ty}_{i}}}$ and $\semtyeq[\Gamma, x:S]{t}{t'}{T}$,
  then $\semtyeq[\Gamma]{\lambda x.\,t}{\lambda x.\,t'}{\Pi(x:S).\,T}$.

Let $\Gamma' \approx \Gamma' \searrow R'$,
  $\semtyeq[\Gamma']{\sigma}{\sigma'}{\Gamma}$, and
  $\ensuremath{\mathcal{D}} :: \rho \approx \rho' \in R'$ be given.

  By $\semtyeq[\Gamma]{s}{s'}{S}$ at $\Gamma'$, $\sigma \approx \sigma' : \Gamma$,
  $\rho \approx \rho' \in R'$:
  \begin{align*}
    &\{\ensuremath{\llbracket S[\sigma] \rrbracket(\rho)},\;
      \ensuremath{\llbracket S \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})},\;
      \ensuremath{\llbracket S \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})},\;
      \ensuremath{\llbracket S[\sigma'] \rrbracket(\rho')}\}
      \subseteq \mathcal{U}_i \searrow R_I
      && \text{(by hypothesis on $S$)} \\
    &\{\ensuremath{\llbracket s[\sigma] \rrbracket(\rho)},\;
      \ensuremath{\llbracket s \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})},\;
      \ensuremath{\llbracket s' \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})},\;
      \ensuremath{\llbracket s'[\sigma'] \rrbracket(\rho')}\}
      \subseteq R_I
      && \text{(by hypothesis on $s, s'$)}
  \end{align*}
  In particular, let $\ensuremath{\mathcal{D}}_I :: \ensuremath{\llbracket s[\sigma] \rrbracket(\rho)} \approx \ensuremath{\llbracket s'[\sigma'] \rrbracket(\rho')} \in R_I$.

  By $\semtyeq[\Gamma]{r}{r'}{\Pi(x:S).\,T}$ at the same data, the four evaluations of
  $r, r'$ are related in the function PER $R$ for $\Pi(\ensuremath{\llbracket S[\sigma] \rrbracket(\rho)}, T[q(\sigma)], \rho)$:
  \begin{align*}
    &\{\ensuremath{\llbracket r[\sigma] \rrbracket(\rho)},\;
      \ensuremath{\llbracket r \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})},\;
      \ensuremath{\llbracket r' \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})},\;
      \ensuremath{\llbracket r'[\sigma'] \rrbracket(\rho')}\}
      \subseteq R
      && \text{(by hypothesis on $r, r'$)}
  \end{align*}

  \emph{Term part.}
  We compute the four term values:
  \begin{align*}
    &\ensuremath{\llbracket (r\;s)[\sigma] \rrbracket(\rho)}
      = \ensuremath{\llbracket r[\sigma]\;s[\sigma] \rrbracket(\rho)}
      && \text{(by definition of substitution on app)} \\
    &\quad = \ensuremath{\llbracket r[\sigma] \rrbracket(\rho)} \cdot \ensuremath{\llbracket s[\sigma] \rrbracket(\rho)}
      && \text{(by evaluation of app)} \\[4pt]
    &\ensuremath{\llbracket r\;s \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})}
      = \ensuremath{\llbracket r \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})} \cdot \ensuremath{\llbracket s \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})}
      && \text{(by evaluation of app)}
  \end{align*}
  Analogous computations for the primed pair (with $r', s'$), yielding
  $\ensuremath{\llbracket r' \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})} \cdot \ensuremath{\llbracket s' \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})}$ and
  $\ensuremath{\llbracket r'[\sigma'] \rrbracket(\rho')} \cdot \ensuremath{\llbracket s'[\sigma'] \rrbracket(\rho')}$.

  Denote the four $r$/$r'$-values as $f_1, f_2, f_3, f_4$ (in order) and the four
  $s$/$s'$-values as $a_1, a_2, a_3, a_4$.
  By hypothesis, $\{f_1, f_2, f_3, f_4\} \subseteq R$ and
  $\{a_1, a_2, a_3, a_4\} \subseteq R_I$.
  For each pair $(i, j)$ with $1 \leq i < j \leq 4$, we have $f_i \approx f_j \in R$
  and $a_i \approx a_j \in R_I$; let $\ensuremath{\mathcal{D}}_I^{ij} :: a_i \approx a_j \in R_I$.
  By the biconditional of $R$ applied to $f_i \approx f_j \in R$ and $\ensuremath{\mathcal{D}}_I^{ij}$:
  $f_i \cdot a_i \approx f_j \cdot a_j \in R_O(\ensuremath{\mathcal{D}}_I^{ij})$.
  By \Cref{lem:univ-functional} (right irrelevance), $R_O(\ensuremath{\mathcal{D}}_I^{ij})$ is independent
  of the witness, agreeing with $R_O(\ensuremath{\mathcal{D}}_I)$ for any fixed
  $\ensuremath{\mathcal{D}}_I :: a_1 \approx a_4 \in R_I$.
  Hence
  \begin{align*}
    &\{\ensuremath{\llbracket r[\sigma] \rrbracket(\rho)} \cdot \ensuremath{\llbracket s[\sigma] \rrbracket(\rho)},\;
      \ensuremath{\llbracket r \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})} \cdot \ensuremath{\llbracket s \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})},\\
    &\quad \ensuremath{\llbracket r' \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})} \cdot \ensuremath{\llbracket s' \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})},\;
      \ensuremath{\llbracket r'[\sigma'] \rrbracket(\rho')} \cdot \ensuremath{\llbracket s'[\sigma'] \rrbracket(\rho')}\}
      \subseteq R_O(\ensuremath{\mathcal{D}}_I).
  \end{align*}

  \emph{Type part.}
  We instantiate $\semtyeq[\Gamma, x:S]{T}{T}{\ensuremath{\texttt{Ty}_{i}}}$ at two semantic substitutions
  to obtain the goal's outer and inner values, then bridge via \Cref{lem:sem-ty-id}.

  \emph{Pattern A (outer instantiation): $(\sigma, s[\sigma]/x)$ vs $(\sigma', s'[\sigma']/x)$.}
  \begin{align*}
    &\semtyeq[\Gamma']{(\sigma, s[\sigma]/x)}{(\sigma', s'[\sigma']/x)}{\Gamma, x:S}
      && \text{(by \Cref{lem:sem-ext-pre} on $\sigma \approx \sigma'$ and $s \approx s'$)}
  \end{align*}
  Apply $\semtyeq[\Gamma, x:S]{T}{T}{\ensuremath{\texttt{Ty}_{i}}}$ at $\Gamma'$, this semantic substitution,
  and $\rho \approx \rho' \in R'$:
  \begin{align*}
    \{&\ensuremath{\llbracket T[\sigma, s[\sigma]/x] \rrbracket(\rho)},\;
      \ensuremath{\llbracket T \rrbracket(\ensuremath{\llbracket (\sigma, s[\sigma]/x) \rrbracket(\rho)})}, \\
    &\ensuremath{\llbracket T \rrbracket(\ensuremath{\llbracket (\sigma', s'[\sigma']/x) \rrbracket(\rho')})},\;
      \ensuremath{\llbracket T[\sigma', s'[\sigma']/x] \rrbracket(\rho')}\}
      &&\subseteq \mathcal{U}_i \searrow R_O(\ensuremath{\mathcal{D}}_I).
  \end{align*}

  Identify the four values syntactically and definitionally:
  \begin{align*}
    &T[\sigma, s[\sigma]/x] = 
      && \text{(by \Cref{lem:subst-ext-comm})} \\
    &T[\sigma', s'[\sigma']/x] = 
      && \text{(by \Cref{lem:subst-ext-comm})} \\
    &\ensuremath{\llbracket (\sigma, s[\sigma]/x) \rrbracket(\rho)}
      = (\ensuremath{\llbracket \sigma \rrbracket(\rho)}, \ensuremath{\llbracket s[\sigma] \rrbracket(\rho)}/x)
      && \text{(by pointwise definition of substitution evaluation)}
  \end{align*}
  Hence the four-value pattern reads:
  \begin{align*}
    \{&\ensuremath{\llbracket  \rrbracket(\rho)},\;
      \ensuremath{\llbracket T \rrbracket((\ensuremath{\llbracket \sigma \rrbracket(\rho)}, \ensuremath{\llbracket s[\sigma] \rrbracket(\rho)}/x))}, \\
    &\ensuremath{\llbracket T \rrbracket((\ensuremath{\llbracket \sigma' \rrbracket(\rho')}, \ensuremath{\llbracket s'[\sigma'] \rrbracket(\rho')}/x))},\;
      \ensuremath{\llbracket  \rrbracket(\rho')}\}
      &&\subseteq \mathcal{U}_i \searrow R_O(\ensuremath{\mathcal{D}}_I).
  \end{align*}
  The outer-left value matches the goal's outer-left
  $\ensuremath{\llbracket  \rrbracket(\rho)}$.
  The outer-right value $\ensuremath{\llbracket  \rrbracket(\rho')}$
  governs the same PER as
  $\ensuremath{\llbracket  \rrbracket(\rho')}$ by
  \Cref{lem:univ-functional} once we establish
  \[
    \ensuremath{\llbracket  \rrbracket(\rho')} \approx
    \ensuremath{\llbracket  \rrbracket(\rho')} \in \mathcal{U}_i,
  \]
  which holds by another instantiation of
  $\semtyeq[\Gamma, x:S]{T}{T}{\ensuremath{\texttt{Ty}_{i}}}$ at the related env-pair
  \[
    (\ensuremath{\llbracket \sigma' \rrbracket(\rho')}, \ensuremath{\llbracket s[\sigma'] \rrbracket(\rho')}/x) \approx
    (\ensuremath{\llbracket \sigma' \rrbracket(\rho')}, \ensuremath{\llbracket s'[\sigma'] \rrbracket(\rho')}/x)
    \in R_{\Gamma, x:S}
  \]
  (using the four-value relatedness of $s, s'$).

  \emph{Pattern B (inner instantiation): $(\ensuremath{\textsf{id}}, s/x)$ vs $(\ensuremath{\textsf{id}}, s'/x)$.}
  By \Cref{lem:sem-ext-pre} on $\semtyeq[\Gamma]{\ensuremath{\textsf{id}}}{\ensuremath{\textsf{id}}}{\Gamma}$ and
  $\semtyeq[\Gamma]{s}{s'}{S}$:
  $\semtyeq[\Gamma]{(\ensuremath{\textsf{id}}, s/x)}{(\ensuremath{\textsf{id}}, s'/x)}{\Gamma, x:S}$
  (using $s[\ensuremath{\textsf{id}}] = s$ and $s'[\ensuremath{\textsf{id}}] = s'$).
  From $\semtyeq[\Gamma']{\sigma}{\sigma'}{\Gamma}$ at $\ensuremath{\textsf{id}}$, $\ensuremath{\mathcal{D}}$:
  $\ensuremath{\llbracket \sigma \rrbracket(\rho)} \approx \ensuremath{\llbracket \sigma' \rrbracket(\rho')} \in R_\Gamma$.
  Apply $\semtyeq[\Gamma, x:S]{T}{T}{\ensuremath{\texttt{Ty}_{i}}}$ at $\Gamma$ (with $R_\Gamma$),
  this semantic substitution, and
  $\ensuremath{\llbracket \sigma \rrbracket(\rho)} \approx \ensuremath{\llbracket \sigma' \rrbracket(\rho')} \in R_\Gamma$:
  \begin{align*}
    \{&\ensuremath{\llbracket T[\ensuremath{\textsf{id}}, s/x] \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})},\;
      \ensuremath{\llbracket T \rrbracket(\ensuremath{\llbracket (\ensuremath{\textsf{id}}, s/x) \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})})}, \\
    &\ensuremath{\llbracket T \rrbracket(\ensuremath{\llbracket (\ensuremath{\textsf{id}}, s'/x) \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})})},\;
      \ensuremath{\llbracket T[\ensuremath{\textsf{id}}, s'/x] \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})}\}
      &&\subseteq \mathcal{U}_i \searrow R_O^B.
  \end{align*}
  Identify $T[\ensuremath{\textsf{id}}, s/x] = T[s/x]$, $T[\ensuremath{\textsf{id}}, s'/x] = T[s'/x]$, and
  $\ensuremath{\llbracket (\ensuremath{\textsf{id}}, s/x) \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})}
  = (\ensuremath{\llbracket \sigma \rrbracket(\rho)}, \ensuremath{\llbracket s \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})}/x)$ (pointwise;
  $\ensuremath{\llbracket \ensuremath{\textsf{id}} \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})} = \ensuremath{\llbracket \sigma \rrbracket(\rho)}$).
  So the four-value pattern reads:
  \begin{align*}
    \{&\ensuremath{\llbracket T[s/x] \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})},\;
      \ensuremath{\llbracket T \rrbracket((\ensuremath{\llbracket \sigma \rrbracket(\rho)}, \ensuremath{\llbracket s \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})}/x))}, \\
    &\ensuremath{\llbracket T \rrbracket((\ensuremath{\llbracket \sigma' \rrbracket(\rho')}, \ensuremath{\llbracket s' \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})}/x))},\;
      \ensuremath{\llbracket T[s'/x] \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})}\}
      &&\subseteq \mathcal{U}_i \searrow R_O^B.
  \end{align*}
  The outer values match the goal's inner-left
  $\ensuremath{\llbracket T[s/x] \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})}$ and inner-right
  $\ensuremath{\llbracket T[s'/x] \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})}$ (modulo
  \Cref{lem:univ-functional} on $T[s/x]$ vs $T[s'/x]$ at
  $\ensuremath{\llbracket \sigma' \rrbracket(\rho')}$, established as in Pattern A).

  \emph{Bridging Pattern A and Pattern B.}
  Pattern A's inner-left is
  \[
    \ensuremath{\llbracket T \rrbracket((\ensuremath{\llbracket \sigma \rrbracket(\rho)}, \ensuremath{\llbracket s[\sigma] \rrbracket(\rho)}/x))}
  \]
  and Pattern B's inner-left is
  \[
    \ensuremath{\llbracket T \rrbracket((\ensuremath{\llbracket \sigma \rrbracket(\rho)}, \ensuremath{\llbracket s \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})}/x))}.
  \]
  We bridge them via \Cref{lem:sem-ty-id}. We show
  \[
    (\ensuremath{\llbracket \sigma \rrbracket(\rho)}, \ensuremath{\llbracket s[\sigma] \rrbracket(\rho)}/x) \approx
    (\ensuremath{\llbracket \sigma \rrbracket(\rho)}, \ensuremath{\llbracket s \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})}/x)
    \in R_{\Gamma, x:S}
  \]
  by \textsc{Ctx-Ext}'s biconditional:
  \begin{align*}
    &\ensuremath{\llbracket \sigma \rrbracket(\rho)} \approx \ensuremath{\llbracket \sigma \rrbracket(\rho)} \in R_\Gamma
      && \text{(reflexive; let $\ensuremath{\mathcal{D}}_\Gamma$ be this witness)} \\
    &\ensuremath{\llbracket s[\sigma] \rrbracket(\rho)} \approx \ensuremath{\llbracket s \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})} \in R_I
      && \text{(outer-left vs inner-left of the four-value pattern of $s$)} \\
    &\ensuremath{\llbracket S[\sigma] \rrbracket(\rho)} \approx \ensuremath{\llbracket S \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})} \in \mathcal{U}_i
      && \text{(outer-left vs inner-left of the type part of $s$)} \\
    &R_I \Leftrightarrow R_H^\Gamma(\ensuremath{\mathcal{D}}_\Gamma)
      && \text{(by \Cref{lem:univ-functional}, both governed by $\ensuremath{\llbracket S[\sigma] \rrbracket(\rho)}$)} \\
    &\ensuremath{\llbracket s[\sigma] \rrbracket(\rho)} \approx \ensuremath{\llbracket s \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})}
      \in R_H^\Gamma(\ensuremath{\mathcal{D}}_\Gamma)
      && \text{(transferring across the biconditional)}
  \end{align*}
  Apply \Cref{lem:sem-ty-id} on $\semtyeq[\Gamma, x:S]{T}{T}{\ensuremath{\texttt{Ty}_{i}}}$ at this
  related pair:
  \begin{multline*}
    \ensuremath{\llbracket T \rrbracket((\ensuremath{\llbracket \sigma \rrbracket(\rho)}, \ensuremath{\llbracket s[\sigma] \rrbracket(\rho)}/x))}
    \approx \\
    \ensuremath{\llbracket T \rrbracket((\ensuremath{\llbracket \sigma \rrbracket(\rho)}, \ensuremath{\llbracket s \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})}/x))}
    \in \mathcal{U}_i.
  \end{multline*}
  Analogously on the primed side, bridging Pattern A's
  inner-right and Pattern B's inner-right:
  \begin{multline*}
    \ensuremath{\llbracket T \rrbracket((\ensuremath{\llbracket \sigma' \rrbracket(\rho')}, \ensuremath{\llbracket s'[\sigma'] \rrbracket(\rho')}/x))}
    \approx \\
    \ensuremath{\llbracket T \rrbracket((\ensuremath{\llbracket \sigma' \rrbracket(\rho')}, \ensuremath{\llbracket s' \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})}/x))}
    \in \mathcal{U}_i.
  \end{multline*}

  \emph{Combining.}
  By transitivity of $\mathcal{U}_i \searrow R_O(\ensuremath{\mathcal{D}}_I)$ through the bridges:
  \begin{align*}
    &\ensuremath{\llbracket  \rrbracket(\rho)} \approx
      \ensuremath{\llbracket T \rrbracket((\ensuremath{\llbracket \sigma \rrbracket(\rho)}, \ensuremath{\llbracket s[\sigma] \rrbracket(\rho)}/x))}
      && \text{(Pattern A: outer-left vs inner-left)} \\
    &\ensuremath{\llbracket T \rrbracket((\ensuremath{\llbracket \sigma \rrbracket(\rho)}, \ensuremath{\llbracket s[\sigma] \rrbracket(\rho)}/x))} \approx
      \ensuremath{\llbracket T \rrbracket((\ensuremath{\llbracket \sigma \rrbracket(\rho)}, \ensuremath{\llbracket s \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})}/x))}
      && \text{(bridge above)} \\
    &\ensuremath{\llbracket T \rrbracket((\ensuremath{\llbracket \sigma \rrbracket(\rho)}, \ensuremath{\llbracket s \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})}/x))} \approx
      \ensuremath{\llbracket T[s/x] \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})}
      && \text{(Pattern B, with $R_O^B \Leftrightarrow R_O(\ensuremath{\mathcal{D}}_I)$
        by \Cref{lem:univ-functional})}
  \end{align*}
  Hence the goal's outer-left $\approx$ goal's inner-left in
  $\mathcal{U}_i \searrow R_O(\ensuremath{\mathcal{D}}_I)$.
  Analogously for outer-right $\approx$ inner-right (using the primed bridge).
  Combined with Pattern A's outer pair and Pattern B's outer pair (which directly
  relate inner-left to inner-right in their respective four-value patterns), all
  four type values lie pairwise in $\mathcal{U}_i \searrow R_O(\ensuremath{\mathcal{D}}_I)$.

We first establish the second claim.
  \begin{align*}
    &(\Gamma, x:\ensuremath{\texttt{Nat}}) \approx (\Gamma, x:\ensuremath{\texttt{Nat}}) \searrow R_{\Gamma, x:\ensuremath{\texttt{Nat}}}
      && \text{(by \Cref{lem:fund-ctx-ext} on $\semtyeq[\Gamma]{\ensuremath{\texttt{Nat}}}{\ensuremath{\texttt{Nat}}}{\ensuremath{\texttt{Ty}_{0}}}$)} \\
    &\text{the head PER of $R_{\Gamma, x:\ensuremath{\texttt{Nat}}}$ is $\textsf{Nat}$}
      && \text{(by \textsc{U-Nat})} \\
    &(\rho, a/x) \approx (\rho', a'/x) \in R_{\Gamma, x:\ensuremath{\texttt{Nat}}}
      && \text{(by \textsc{Ctx-Ext}'s biconditional)} \\
    &\ensuremath{\llbracket T \rrbracket((\rho, a/x))} \approx \ensuremath{\llbracket T' \rrbracket((\rho', a'/x))} \in \mathcal{U}_i \searrow R_T
      && \text{(by \Cref{lem:sem-ty-id} on $\semtyeq[\Gamma, x:\ensuremath{\texttt{Nat}}]{T}{T'}{\ensuremath{\texttt{Ty}_{i}}}$)}
  \end{align*}
  for some $R_T$.

  We prove the first claim by induction on $a \approx a' \in \textsf{Nat}$.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{Nat-Ze}]
    { }
    {\texttt{ze} \approx \texttt{ze} \in \textsf{Nat}}
  \end{mathpar}
  Here $a = a' = \texttt{ze}$.
  \begin{align*}
    &\ensuremath{\llbracket z \rrbracket(\rho)} \searrow b
      && \text{(some $b$, by termination via \Cref{lem:sem-ty-id})} \\
    &\ensuremath{\llbracket z' \rrbracket(\rho')} \searrow b'
      && \text{(some $b'$)} \\
    &\mathsf{rec}(\texttt{ze},\, T,\, z,\, s,\, \rho) \searrow b
      && \text{(by \textsc{rec-ze})} \\
    &\mathsf{rec}(\texttt{ze},\, T',\, z',\, s',\, \rho') \searrow b'
      && \text{(by \textsc{rec-ze})}
  \end{align*}
  We must show $b \approx b' \in R_T$.
  \begin{align*}
    &\ensuremath{\llbracket z \rrbracket(\rho)} \approx \ensuremath{\llbracket z' \rrbracket(\rho')} \in R_z
      && \text{(by \Cref{lem:sem-ty-id})} \\
    &\ensuremath{\llbracket T[\textsf{zero}/x] \rrbracket(\rho)} \approx \ensuremath{\llbracket T[\textsf{zero}/x] \rrbracket(\rho')}
      \in \mathcal{U}_i \searrow R_z
      && \text{(type part of \Cref{lem:sem-ty-id})}
  \end{align*}
  Hence $b \approx b' \in R_z$.
  We show $R_z \Leftrightarrow R_T$.
  \begin{align*}
    &\semtyeq[\Gamma]{(\ensuremath{\textsf{id}}, \textsf{zero}/x)}{(\ensuremath{\textsf{id}}, \textsf{zero}/x)}{\Gamma, x:\ensuremath{\texttt{Nat}}}
      && \text{(by \Cref{lem:sem-ext-pre} on $\ensuremath{\textsf{id}}$ and \Cref{lem:fund-ze})} \\
    &\ensuremath{\llbracket T[\textsf{zero}/x] \rrbracket(\rho)} \approx \ensuremath{\llbracket T \rrbracket((\rho, \texttt{ze}/x))} \in \mathcal{U}_i
      && \text{(outer-vs-inner of $T$ at $(\ensuremath{\textsf{id}}, \textsf{zero}/x)$, $\rho \approx \rho'$,} \\
    & && \text{using $T[\ensuremath{\textsf{id}}, \textsf{zero}/x] = T[\textsf{zero}/x]$ and ev-ze)} \\
    &R_z \Leftrightarrow R_T
      && \text{(by \Cref{lem:univ-functional})}
  \end{align*}
  Hence $b \approx b' \in R_T$.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{Nat-Su}]
    {a_0 \approx a_0' \in \textsf{Nat}}
    {\texttt{su}(a_0) \approx \texttt{su}(a_0') \in \textsf{Nat}}
  \end{mathpar}
  with $a = \texttt{su}(a_0)$, $a' = \texttt{su}(a_0')$.
  By IH on $a_0 \approx a_0'$, there exist $b_0, b_0'$ with
  \begin{align*}
    &\mathsf{rec}(a_0,\, T,\, z,\, s,\, \rho) \searrow b_0
      && \text{(by IH)} \\
    &\mathsf{rec}(a_0',\, T',\, z',\, s',\, \rho') \searrow b_0'
      && \text{(by IH)} \\
    &b_0 \approx b_0' \in R_T^0
      && \text{(by IH, with $R_T^0$ governed by $\ensuremath{\llbracket T \rrbracket((\rho, a_0/x))}$)}
  \end{align*}
  By \textsc{rec-su}:
  \begin{align*}
    &\ensuremath{\llbracket s \rrbracket((\rho, a_0/x, b_0/y))} \searrow b
      && \text{(some $b$)} \\
    &\ensuremath{\llbracket s' \rrbracket((\rho', a_0'/x, b_0'/y))} \searrow b'
      && \text{(some $b'$)} \\
    &\mathsf{rec}(\texttt{su}(a_0),\, T,\, z,\, s,\, \rho) \searrow b
      && \text{(by \textsc{rec-su})} \\
    &\mathsf{rec}(\texttt{su}(a_0'),\, T',\, z',\, s',\, \rho') \searrow b'
      && \text{(by \textsc{rec-su})}
  \end{align*}
  We must show $b \approx b' \in R_T$.
  Build the env-pair in $R_{\Gamma, x:\ensuremath{\texttt{Nat}}, y:T}$:
  \begin{align*}
    &(\rho, a_0/x) \approx (\rho', a_0'/x) \in R_{\Gamma, x:\ensuremath{\texttt{Nat}}}
      && \text{(by \textsc{Ctx-Ext}, head PER $\textsf{Nat}$)} \\
    &(\rho, a_0/x, b_0/y) \approx (\rho', a_0'/x, b_0'/y) \\
    & \quad \in R_{\Gamma, x:\ensuremath{\texttt{Nat}}, y:T}
      && \text{(by \textsc{Ctx-Ext}, head PER $R_T^0$)}
  \end{align*}
  Apply \Cref{lem:sem-ty-id} on
  $\semtyeq[\Gamma, x:\ensuremath{\texttt{Nat}}, y:T]{s}{s'}
  {T[\Uparrow \circ \Uparrow, \textsf{succ}~x_1/x]}$ at this env-pair:
  \begin{align*}
    &\ensuremath{\llbracket T[\Uparrow \circ \Uparrow, \textsf{succ}~x_1/x] \rrbracket((\rho, a_0/x, b_0/y))} \\
    & \quad \approx
      \ensuremath{\llbracket T[\Uparrow \circ \Uparrow, \textsf{succ}~x_1/x] \rrbracket((\rho', a_0'/x, b_0'/y))} \\
    & \quad \in \mathcal{U}_i \searrow R_s
      && \text{(type part of \Cref{lem:sem-ty-id})} \\
    &\ensuremath{\llbracket s \rrbracket((\rho, a_0/x, b_0/y))} \approx
      \ensuremath{\llbracket s' \rrbracket((\rho', a_0'/x, b_0'/y))} \in R_s
      && \text{(term part of \Cref{lem:sem-ty-id})}
  \end{align*}
  where $R_s$ is the PER governed by
  \[
    \ensuremath{\llbracket T[\Uparrow \circ \Uparrow, \textsf{succ}~x_1/x] \rrbracket((\rho, a_0/x, b_0/y))}.
  \]
  Hence $b \approx b' \in R_s$.

  We show $R_s \Leftrightarrow R_T$ by instantiating hypothesis on $T$ at the
  substitution $\tau := (\Uparrow \circ \Uparrow, \textsf{succ}~x_1/x)$ over
  $\Gamma, x:\ensuremath{\texttt{Nat}}, y:T$ (mapping into $\Gamma, x:\ensuremath{\texttt{Nat}}$).
  Semantic well-formedness of $\tau$:
  \begin{align*}
    &\semtyeq[\Gamma, x:\ensuremath{\texttt{Nat}}, y:T]{\Uparrow \circ \Uparrow}{\Uparrow \circ \Uparrow}{\Gamma}
      && \text{(by \Cref{lem:sem-wk-shift} (twice), \Cref{lem:sem-wk-comp}, and \Cref{lem:sem-wk})} \\
    &\semtyeq[\Gamma, x:\ensuremath{\texttt{Nat}}, y:T]{x_1}{x_1}{\ensuremath{\texttt{Nat}}}
      && \text{(by \Cref{lem:fund-var}, lookup $x_1 : \ensuremath{\texttt{Nat}}[\Uparrow] = \ensuremath{\texttt{Nat}}$)} \\
    &\semtyeq[\Gamma, x:\ensuremath{\texttt{Nat}}, y:T]{\textsf{succ}~x_1}{\textsf{succ}~x_1}{\ensuremath{\texttt{Nat}}}
      && \text{(by \Cref{lem:fund-su})} \\
    &\semtyeq[\Gamma, x:\ensuremath{\texttt{Nat}}, y:T]{\tau}{\tau}{\Gamma, x:\ensuremath{\texttt{Nat}}}
      && \text{(by \Cref{lem:sem-ext-pre})}
  \end{align*}
  Apply $\semtyeq[\Gamma, x:\ensuremath{\texttt{Nat}}]{T}{T}{\ensuremath{\texttt{Ty}_{i}}}$ at $\Gamma, x:\ensuremath{\texttt{Nat}}, y:T$,
  $\tau \approx \tau$, and the env-pair
  $(\rho, a_0/x, b_0/y) \approx (\rho, a_0/x, b_0/y) \in R_{\Gamma, x:\ensuremath{\texttt{Nat}}, y:T}$
  (reflexive):
  \begin{align*}
    &\ensuremath{\llbracket T[\tau] \rrbracket((\rho, a_0/x, b_0/y))} \approx
      \ensuremath{\llbracket T \rrbracket(\ensuremath{\llbracket \tau \rrbracket((\rho, a_0/x, b_0/y))})} \in \mathcal{U}_i \searrow R'
      && \text{(outer-left vs inner-left)} \\
    &\ensuremath{\llbracket \tau \rrbracket((\rho, a_0/x, b_0/y))} = (\rho, \texttt{su}(a_0)/x)
      && \text{(by pointwise eval: $\Uparrow \circ \Uparrow$ projects to $\rho$,} \\
    & && \text{$\textsf{succ}~x_1$ evaluates to $\texttt{su}(a_0)$ via ev-su, ev-var)}
  \end{align*}
  Hence:
  \begin{align*}
    &\ensuremath{\llbracket T[\Uparrow \circ \Uparrow, \textsf{succ}~x_1/x] \rrbracket((\rho, a_0/x, b_0/y))} \approx
      \ensuremath{\llbracket T \rrbracket((\rho, \texttt{su}(a_0)/x))} \in \mathcal{U}_i \searrow R'
      && \text{(by the above)}
  \end{align*}
  Combining with the second claim
  $\ensuremath{\llbracket T \rrbracket((\rho, \texttt{su}(a_0)/x))} \approx \ensuremath{\llbracket T \rrbracket((\rho', \texttt{su}(a_0')/x))} \in \mathcal{U}_i \searrow R_T$
  (applied at $\texttt{su}(a_0) \approx \texttt{su}(a_0')$):
  \begin{align*}
    &R_s \Leftrightarrow R' \Leftrightarrow R_T
      && \text{(by \Cref{lem:univ-functional} on shared values)}
  \end{align*}
  Hence $b \approx b' \in R_T$.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{Nat-Ne}]
    {e \approx e' \in \textsf{Ne}}
    {{\uparrow}^N(e) \approx {\uparrow}^N(e') \in \textsf{Nat}}
  \end{mathpar}
  with $a = {\uparrow}^N(e)$, $a' = {\uparrow}^N(e')$.
  Compute the eliminator outputs by \textsc{rec-ne}:
  \begin{align*}
    &\ensuremath{\llbracket T \rrbracket((\rho, {\uparrow}^N(e)/x))} \searrow A
      && \text{(by the second claim, governing $R_T$)} \\
    &\ensuremath{\llbracket T \rrbracket((\rho', {\uparrow}^N(e')/x))} \searrow A'
      && \text{(analogously)} \\
    &A \approx A' \in \mathcal{U}_i \searrow R_T
      && \text{(by the second claim at ${\uparrow}^N(e) \approx {\uparrow}^N(e')$)} \\
    &\ensuremath{\llbracket z \rrbracket(\rho)} \searrow a_z,\;\; \ensuremath{\llbracket z' \rrbracket(\rho')} \searrow a_z',\;\;
      a_z \approx a_z' \in R_z
      && \text{(by \Cref{lem:sem-ty-id} on $\semtyeq[\Gamma]{z}{z'}{T[\textsf{zero}/x]}$)} \\
    &b = {\uparrow}^A(\mathsf{rec}(T, a_z, s, \rho, e))
      && \text{(by \textsc{rec-ne})} \\
    &b' = {\uparrow}^{A'}(\mathsf{rec}(T, a_z', s', \rho', e'))
      && \text{(by \textsc{rec-ne})}
  \end{align*}

  We must show $b \approx b' \in R_T$.
  By \Cref{lem:ne-in-R} on $A \approx A' \in \mathcal{U}_i \searrow R_T$, it suffices to show
  \begin{align*}
    &\mathsf{rec}(T, a_z, s, \rho, e) \approx \mathsf{rec}(T, a_z', s', \rho', e') \in \textsf{Ne},
  \end{align*}
  i.e.\ for every depth $n$ both sides read back via $\textsf{R}^{\textsf{Ne}}_n$ to the same neutral
  normal form.
  By rule \textsc{Re-rec}:
  \begin{align*}
    &\textsf{R}^{\textsf{Ne}}_n(\mathsf{rec}(T, a_z, s, \rho, e))
      \searrow \ensuremath{\textsf{elim}_{\ensuremath{\texttt{Nat}}}~(x.\,W_T)~w_z~(x, y.\,w_s)~u}
  \end{align*}
  whenever
  \begin{align*}
    &\textsf{R}^{\textsf{Ty}}_{n+1}(A_x) \searrow W_T
      && \text{where $\ensuremath{\llbracket T \rrbracket((\rho, {\uparrow}^N(\ell_n)/x))} \searrow A_x$} \\
    &\textsf{R}^{\textsf{Nf}}_n({\downarrow}^{A_z}(a_z)) \searrow w_z
      && \text{where $\ensuremath{\llbracket T \rrbracket((\rho, \texttt{ze}/x))} \searrow A_z$} \\
    &\ensuremath{\llbracket s \rrbracket((\rho, {\uparrow}^N(\ell_n)/x, {\uparrow}^{A_x}(\ell_{n+1})/y))} \searrow b_s \\
    &\textsf{R}^{\textsf{Nf}}_{n+2}({\downarrow}^{A_x^{\textsf{succ}~}}(b_s)) \searrow w_s
      && \text{where $\ensuremath{\llbracket T \rrbracket((\rho, \texttt{su}({\uparrow}^N(\ell_n))/x))} \searrow A_x^{\textsf{succ}~}$} \\
    &\textsf{R}^{\textsf{Ne}}_n(e) \searrow u
  \end{align*}
  (and analogously for the primed side, producing
  $\ensuremath{\textsf{elim}_{\ensuremath{\texttt{Nat}}}~(x.\,W_T')~w_z'~(x, y.\,w_s')~u'}$).
  We show each component reads back to the same syntactic form.

  \emph{Motive $W_T = W_T'$.}
  Apply $\semtyeq[\Gamma, x:\ensuremath{\texttt{Nat}}]{T}{T}{\ensuremath{\texttt{Ty}_{i}}}$ at the env-pair extended with the
  fresh level $\ell_n$:
  \begin{align*}
    &{\uparrow}^N(\ell_n) \approx {\uparrow}^N(\ell_n) \in \textsf{Nat}
      && \text{(by \textsc{Nat-Ne}, $\ell_n \approx \ell_n \in \textsf{Ne}$)} \\
    &(\rho, {\uparrow}^N(\ell_n)/x) \approx (\rho', {\uparrow}^N(\ell_n)/x) \in R_{\Gamma, x:\ensuremath{\texttt{Nat}}}
      && \text{(by \textsc{Ctx-Ext})} \\
    &\ensuremath{\llbracket T \rrbracket((\rho, {\uparrow}^N(\ell_n)/x))} \approx
      \ensuremath{\llbracket T \rrbracket((\rho', {\uparrow}^N(\ell_n)/x))} \in \mathcal{U}_i \searrow R_T^\ell
      && \text{(by \Cref{lem:sem-ty-id})} \\
    &W_T = W_T'
      && \text{(by \Cref{lem:type-readback})}
  \end{align*}

  \emph{Zero branch $w_z = w_z'$.}
  Apply $\semtyeq[\Gamma]{z}{z'}{T[\textsf{zero}/x]}$ at $\Gamma$, $\ensuremath{\textsf{id}}$, and
  $\rho \approx \rho' \in R_\Gamma$ (term and type parts):
  \begin{align*}
    &\ensuremath{\llbracket  \rrbracket(\rho)} \approx \ensuremath{\llbracket T[\textsf{zero}/x] \rrbracket(\rho')}
      \in \mathcal{U}_i \searrow R_z
      && \text{(type part)} \\
    &\ensuremath{\llbracket z[\ensuremath{\textsf{id}}] \rrbracket(\rho)} \approx \ensuremath{\llbracket z' \rrbracket(\rho')} \in R_z
      && \text{(term part)} \\
    &a_z \approx a_z' \in R_z
      && \text{(using $z[\ensuremath{\textsf{id}}] = z$, $z'[\ensuremath{\textsf{id}}] = z'$)}
  \end{align*}
  Bridge $R_z \Leftrightarrow R_T$-at-$\texttt{ze}$ via the same outer-vs-inner pattern as
  the \textsc{Nat-Ze} case (instantiate $T$ at $(\ensuremath{\textsf{id}}, \textsf{zero}/x)$).
  By \Cref{lem:R-readback} on $a_z \approx a_z' \in R_T$-at-$\texttt{ze}$:
  \begin{align*}
    &w_z = w_z'
      && \text{(by \Cref{lem:R-readback})}
  \end{align*}

  \emph{Step branch $w_s = w_s'$.}
  Build the env-pair at fresh levels:
  \begin{align*}
    &(\rho, {\uparrow}^N(\ell_n)/x) \approx (\rho', {\uparrow}^N(\ell_n)/x) \in R_{\Gamma, x:\ensuremath{\texttt{Nat}}}
      && \text{(as above)} \\
    &(\rho, {\uparrow}^N(\ell_n)/x, {\uparrow}^{A_x}(\ell_{n+1})/y) \approx \\
    &\quad (\rho', {\uparrow}^N(\ell_n)/x, {\uparrow}^{A_x'}(\ell_{n+1})/y) \in R_{\Gamma, x:\ensuremath{\texttt{Nat}}, y:T}
      && \text{(by \textsc{Ctx-Ext}, head PER $R_T^\ell$;} \\
    & && \text{${\uparrow}^{A_x}(\ell_{n+1}) \approx {\uparrow}^{A_x'}(\ell_{n+1}) \in R_T^\ell$} \\
    & && \text{by \Cref{lem:ne-in-R})}
  \end{align*}
  Apply $\semtyeq[\Gamma, x:\ensuremath{\texttt{Nat}}, y:T]{s}{s'}{T[\Uparrow \circ \Uparrow, \textsf{succ}~x_1/x]}$ at this env-pair
  (term and type parts, after bridging $T[\Uparrow \circ \Uparrow, \textsf{succ}~x_1/x]$ to $T$ at
  $\texttt{su}({\uparrow}^N(\ell_n))/x$ as in the \textsc{Nat-Su} case):
  \begin{align*}
    &b_s \approx b_s' \in R_T \text{-at-} \texttt{su}({\uparrow}^N(\ell_n))
      && \text{(by \Cref{lem:sem-ty-id} and bridging)}
  \end{align*}
  By \Cref{lem:R-readback}:
  \begin{align*}
    &w_s = w_s'
      && \text{(by \Cref{lem:R-readback})}
  \end{align*}

  \emph{Underlying neutral $u = u'$.}
  By hypothesis $e \approx e' \in \textsf{Ne}$:
  \begin{align*}
    &\textsf{R}^{\textsf{Ne}}_n(e) \searrow u,\;\; \textsf{R}^{\textsf{Ne}}_n(e') \searrow u
      && \text{(by definition of $\textsf{Ne}$)}
  \end{align*}

  Combining:
  \begin{align*}
    &\textsf{R}^{\textsf{Ne}}_n(\mathsf{rec}(T, a_z, s, \rho, e)) \searrow
      \ensuremath{\textsf{elim}_{\ensuremath{\texttt{Nat}}}~(x.\,W_T)~w_z~(x, y.\,w_s)~u} \\
    &\textsf{R}^{\textsf{Ne}}_n(\mathsf{rec}(T, a_z', s', \rho', e')) \searrow
      \ensuremath{\textsf{elim}_{\ensuremath{\texttt{Nat}}}~(x.\,W_T)~w_z~(x, y.\,w_s)~u}
      && \text{(same syntactic form)} \\
    &\mathsf{rec}(T, a_z, s, \rho, e) \approx \mathsf{rec}(T, a_z', s', \rho', e') \in \textsf{Ne}
      && \text{(by definition of $\textsf{Ne}$)}
  \end{align*}
  Hence $b \approx b' \in R_T$.

We first establish the lifted substitution and the second claim.
  \begin{align*}
    &\semtyeq[\Gamma', x:\ensuremath{\texttt{Nat}}]{q(\sigma)}{q(\sigma')}{\Gamma, x:\ensuremath{\texttt{Nat}}}
      && \text{(by \Cref{lem:sem-q} on $\sigma \approx \sigma'$ and $\ensuremath{\texttt{Nat}}$,
        using $\ensuremath{\texttt{Nat}}[\sigma] = \ensuremath{\texttt{Nat}}$)} \\
    &(\Gamma', x:\ensuremath{\texttt{Nat}}) \approx (\Gamma', x:\ensuremath{\texttt{Nat}}) \searrow R_{\Gamma', x:\ensuremath{\texttt{Nat}}}
      && \text{(carried by the lifted substitution)} \\
    &(\Gamma, x:\ensuremath{\texttt{Nat}}) \approx (\Gamma, x:\ensuremath{\texttt{Nat}}) \searrow R_{\Gamma, x:\ensuremath{\texttt{Nat}}}
      && \text{(carried by the lifted substitution)} \\
    &\text{both head PERs are $\textsf{Nat}$}
      && \text{(by \textsc{U-Nat})} \\
    &(\rho, a/x) \approx (\rho', a'/x) \in R_{\Gamma', x:\ensuremath{\texttt{Nat}}}
      && \text{(by \textsc{Ctx-Ext}'s biconditional)}
  \end{align*}
  Apply $\semtyeq[\Gamma, x:\ensuremath{\texttt{Nat}}]{T}{T'}{\ensuremath{\texttt{Ty}_{i}}}$ at $\Gamma', x:\ensuremath{\texttt{Nat}}$, the lifted
  substitution, and the env-pair above:
  \begin{align*}
    &\ensuremath{\llbracket T[q(\sigma)] \rrbracket((\rho, a/x))} \approx
      \ensuremath{\llbracket T' \rrbracket(\ensuremath{\llbracket q(\sigma') \rrbracket((\rho', a'/x))})} \in \mathcal{U}_i \searrow R_T
      && \text{(outer-left vs inner-right of the four-value pattern)}
  \end{align*}
  Bridge $\ensuremath{\llbracket q(\sigma') \rrbracket((\rho', a'/x))}$ to $(\ensuremath{\llbracket \sigma' \rrbracket(\rho')}, a'/x)$:
  \begin{align*}
    &\ensuremath{\llbracket q(\sigma') \rrbracket((\rho', a'/x))} \approx (\ensuremath{\llbracket \sigma' \rrbracket(\rho')}, a'/x)
      \in R_{\Gamma, x:\ensuremath{\texttt{Nat}}}
      && \text{(by \textsc{Ctx-Ext}, tail via $\sigma'$ at $\Uparrow$, head $a' \approx a'$)} \\
    &\ensuremath{\llbracket T' \rrbracket(\ensuremath{\llbracket q(\sigma') \rrbracket((\rho', a'/x))})} \approx
      \ensuremath{\llbracket T' \rrbracket((\ensuremath{\llbracket \sigma' \rrbracket(\rho')}, a'/x))} \in \mathcal{U}_i
      && \text{(by \Cref{lem:sem-ty-id} on $T' \approx T'$, derived from} \\
    & && \text{$T \approx T'$ via symmetry and transitivity)}
  \end{align*}
  By transitivity of $\mathcal{U}_i$ and \Cref{lem:univ-functional},
  $\ensuremath{\llbracket T[q(\sigma)] \rrbracket((\rho, a/x))} \approx
  \ensuremath{\llbracket T' \rrbracket((\ensuremath{\llbracket \sigma' \rrbracket(\rho')}, a'/x))} \in \mathcal{U}_i \searrow R_T$,
  establishing the second claim.

  We prove the first claim by induction on $a \approx a' \in \textsf{Nat}$.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{Nat-Ze}]
    { }
    {\texttt{ze} \approx \texttt{ze} \in \textsf{Nat}}
  \end{mathpar}
  Here $a = a' = \texttt{ze}$.
  Apply $\semtyeq[\Gamma]{z}{z'}{T[\textsf{zero}/x]}$ at $\Gamma'$, $\sigma \approx \sigma'$,
  and $\rho \approx \rho' \in R'$ (this gives the four-value pattern of $z, z'$):
  \begin{align*}
    &\ensuremath{\llbracket z[\sigma] \rrbracket(\rho)} \searrow b,\;\; \ensuremath{\llbracket z' \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})} \searrow b'
      && \text{(termination, by hypothesis on $z, z'$)} \\
    &b \approx b' \in R_z
      && \text{(outer-left vs inner-right of $z, z'$)} \\
    &\ensuremath{\llbracket  \rrbracket(\rho)} \approx
      \ensuremath{\llbracket T[\textsf{zero}/x] \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})} \in \mathcal{U}_i \searrow R_z
      && \text{(corresponding type part)}
  \end{align*}
  Then by \textsc{rec-ze} applied to these evaluations:
  \begin{align*}
    &\mathsf{rec}(\texttt{ze},\, T[q(\sigma)],\, z[\sigma],\, s[q^2(\sigma)],\, \rho)
      \searrow b
      && \text{(by \textsc{rec-ze}, using $\ensuremath{\llbracket z[\sigma] \rrbracket(\rho)} \searrow b$)} \\
    &\mathsf{rec}(\texttt{ze},\, T',\, z',\, s',\, \ensuremath{\llbracket \sigma' \rrbracket(\rho')}) \searrow b'
      && \text{(by \textsc{rec-ze}, using $\ensuremath{\llbracket z' \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})} \searrow b'$)}
  \end{align*}
  We must show $b \approx b' \in R_T$.
  Currently $b \approx b' \in R_z$ where $R_z$ is governed by
  $\ensuremath{\llbracket  \rrbracket(\rho)}$, while $R_T$ is governed by
  $\ensuremath{\llbracket T[q(\sigma)] \rrbracket((\rho, \texttt{ze}/x))}$ (substituted left, second-claim instance
  at $a = a' = \texttt{ze}$).
  We bridge $R_z \Leftrightarrow R_T$ via two type-hypothesis instantiations.

  \emph{Left bridge.}
  By \Cref{lem:sem-ext-pre} on $\semtyeq[\Gamma']{\sigma}{\sigma}{\Gamma}$
  (reflexive instance via \Cref{lem:sem-sym,lem:sem-trans}) and
  $\semtyeq[\Gamma']{\textsf{zero}[\sigma]}{\textsf{zero}[\sigma]}{\ensuremath{\texttt{Nat}}[\sigma]}$
  (using $\textsf{zero}[\sigma] = \textsf{zero}$, $\ensuremath{\texttt{Nat}}[\sigma] = \ensuremath{\texttt{Nat}}$, and \Cref{lem:fund-ze}):
  \begin{align*}
    &\semtyeq[\Gamma']{(\sigma, \textsf{zero}/x)}{(\sigma, \textsf{zero}/x)}{\Gamma, x:\ensuremath{\texttt{Nat}}}
      && \text{(by \Cref{lem:sem-ext-pre})}
  \end{align*}
  Apply $\semtyeq[\Gamma, x:\ensuremath{\texttt{Nat}}]{T}{T}{\ensuremath{\texttt{Ty}_{i}}}$ at $\Gamma'$, this substitution,
  and $\rho \approx \rho \in R'$ (reflexive):
  \begin{align*}
    &\ensuremath{\llbracket T[(\sigma, \textsf{zero}/x)] \rrbracket(\rho)} \approx
      \ensuremath{\llbracket T \rrbracket(\ensuremath{\llbracket (\sigma, \textsf{zero}/x) \rrbracket(\rho)})} \in \mathcal{U}_i \searrow R_z'
      && \text{(outer-left vs inner-left)} \\
    &T[(\sigma, \textsf{zero}/x)] = 
      && \text{(by \Cref{lem:subst-ext-comm})} \\
    &\ensuremath{\llbracket (\sigma, \textsf{zero}/x) \rrbracket(\rho)} = (\ensuremath{\llbracket \sigma \rrbracket(\rho)}, \texttt{ze}/x)
      && \text{(by pointwise eval, ev-ze)} \\
    &R_z' \Leftrightarrow R_z
      && \text{(by \Cref{lem:univ-functional} on shared
        $\ensuremath{\llbracket  \rrbracket(\rho)}$)}
  \end{align*}
  Hence
  $\ensuremath{\llbracket  \rrbracket(\rho)} \approx \ensuremath{\llbracket T \rrbracket((\ensuremath{\llbracket \sigma \rrbracket(\rho)}, \texttt{ze}/x))}
   \in \mathcal{U}_i \searrow R_z$.

  \emph{Right bridge.}
  Symmetrically, instantiate $T$ at $(\ensuremath{\textsf{id}}, \textsf{zero}/x)$ over $\Gamma$ at the env-pair
  $\ensuremath{\llbracket \sigma \rrbracket(\rho)} \approx \ensuremath{\llbracket \sigma' \rrbracket(\rho')} \in R_\Gamma$ (carried by the
  semantic-substitution hypothesis):
  \begin{align*}
    &\semtyeq[\Gamma]{(\ensuremath{\textsf{id}}, \textsf{zero}/x)}{(\ensuremath{\textsf{id}}, \textsf{zero}/x)}{\Gamma, x:\ensuremath{\texttt{Nat}}}
      && \text{(by \Cref{lem:sem-ext-pre} and \Cref{lem:fund-ze})} \\
    &\ensuremath{\llbracket T[\textsf{zero}/x] \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})} \approx
      \ensuremath{\llbracket T \rrbracket((\ensuremath{\llbracket \sigma' \rrbracket(\rho')}, \texttt{ze}/x))} \in \mathcal{U}_i
      && \text{(outer-vs-inner of the four-value pattern of $T$)}
  \end{align*}

  \emph{Combining via the second claim.}
  The second claim (proved above) gives:
  \begin{align*}
    &\ensuremath{\llbracket T[q(\sigma)] \rrbracket((\rho, \texttt{ze}/x))} \approx
      \ensuremath{\llbracket T' \rrbracket((\ensuremath{\llbracket \sigma' \rrbracket(\rho')}, \texttt{ze}/x))} \in \mathcal{U}_i \searrow R_T
  \end{align*}
  Chaining via the bridges (using \Cref{lem:univ-functional},
  \Cref{lem:univ-trans}, \Cref{lem:univ-sym}):
  \begin{align*}
    &\ensuremath{\llbracket  \rrbracket(\rho)}
      \approx \ensuremath{\llbracket T \rrbracket((\ensuremath{\llbracket \sigma \rrbracket(\rho)}, \texttt{ze}/x))} \\
    & \quad \approx \ensuremath{\llbracket T \rrbracket((\ensuremath{\llbracket \sigma' \rrbracket(\rho')}, \texttt{ze}/x))} \\
    & \quad \approx \ensuremath{\llbracket T[q(\sigma)] \rrbracket((\rho, \texttt{ze}/x))} \in \mathcal{U}_i \\
    &R_z \Leftrightarrow R_T
      && \text{(by \Cref{lem:univ-functional})}
  \end{align*}
  Hence $b \approx b' \in R_T$.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{Nat-Su}]
    {a_0 \approx a_0' \in \textsf{Nat}}
    {\texttt{su}(a_0) \approx \texttt{su}(a_0') \in \textsf{Nat}}
  \end{mathpar}
  with $a = \texttt{su}(a_0)$, $a' = \texttt{su}(a_0')$.
  By IH on $a_0 \approx a_0'$, there exist $b_0, b_0'$ with
  \begin{align*}
    &\mathsf{rec}(a_0,\, T[q(\sigma)],\, z[\sigma],\, s[q^2(\sigma)],\, \rho)
      \searrow b_0
      && \text{(by IH)} \\
    &\mathsf{rec}(a_0',\, T',\, z',\, s',\, \ensuremath{\llbracket \sigma' \rrbracket(\rho')}) \searrow b_0'
      && \text{(by IH)} \\
    &b_0 \approx b_0' \in R_T^0
      && \text{(by IH, with $R_T^0$ governed by $\ensuremath{\llbracket T[q(\sigma)] \rrbracket((\rho, a_0/x))}$)}
  \end{align*}
  We derive the evaluations of $s[q^2(\sigma)]$ and $s'$ from the hypothesis on $s, s'$.
  First, lift $\sigma, \sigma'$ over $\ensuremath{\texttt{Nat}}$ and $T$:
  \begin{align*}
    &\semtyeq[\Gamma', x:\ensuremath{\texttt{Nat}}]{q(\sigma)}{q(\sigma')}{\Gamma, x:\ensuremath{\texttt{Nat}}}
      && \text{(by \Cref{lem:sem-q} on
        $\sigma \approx \sigma'$ and $\ensuremath{\texttt{Nat}}$;} \\
    & && \text{using $\ensuremath{\texttt{Nat}}[\sigma] = \ensuremath{\texttt{Nat}}$)} \\
    &\semtyeq[\Gamma', x:\ensuremath{\texttt{Nat}}, y:T[q(\sigma)]]
        {q^2(\sigma)}{q^2(\sigma')}{\Gamma, x:\ensuremath{\texttt{Nat}}, y:T}
      && \text{(by \Cref{lem:sem-q} again on $T$)}
  \end{align*}
  Build the env-pair via two applications of \textsc{Ctx-Ext}:
  \begin{align*}
    &(\rho, a_0/x) \approx (\rho', a_0'/x) \in R_{\Gamma', x:\ensuremath{\texttt{Nat}}}
      && \text{(by \textsc{Ctx-Ext}, head PER $\textsf{Nat}$)} \\
    &(\rho, a_0/x, b_0/y) \approx (\rho', a_0'/x, b_0'/y)
      \in R_{\Gamma', x:\ensuremath{\texttt{Nat}}, y:T[q(\sigma)]}
      && \text{(by \textsc{Ctx-Ext}, head PER $R_T^0$)}
  \end{align*}
  Apply $\semtyeq[\Gamma, x:\ensuremath{\texttt{Nat}}, y:T]{s}{s'}{T[\Uparrow \circ \Uparrow, \textsf{succ}~x_1/x]}$ at $\Gamma', x:\ensuremath{\texttt{Nat}}, y:T[q(\sigma)]$,
  the doubly-lifted substitution $q^2(\sigma) \approx q^2(\sigma')$, and this env-pair
  (this gives the four-value pattern of $s, s'$):
  \begin{align*}
    &\ensuremath{\llbracket s[q^2(\sigma)] \rrbracket((\rho, a_0/x, b_0/y))} \searrow b
      && \text{(termination, by hypothesis on $s$)} \\
    &\ensuremath{\llbracket s' \rrbracket(\ensuremath{\llbracket q^2(\sigma') \rrbracket((\rho', a_0'/x, b_0'/y))})} \searrow b'_0
      && \text{(termination, by hypothesis on $s'$)} \\
    &\ensuremath{\llbracket s' \rrbracket((\ensuremath{\llbracket \sigma' \rrbracket(\rho')}, a_0'/x, b_0'/y))} \searrow b'
      && \text{(termination, by reflexive instance $\semtyeq[\ldots]{s'}{s'}{\ldots}$)}
  \end{align*}
  By \textsc{rec-su}:
  \begin{align*}
    &\mathsf{rec}(\texttt{su}(a_0),\, T[q(\sigma)],\, z[\sigma],\, s[q^2(\sigma)],\, \rho)
      \searrow b
      && \text{(by \textsc{rec-su}, using $\ensuremath{\llbracket s[q^2(\sigma)] \rrbracket((\rho, a_0/x, b_0/y))} \searrow b$)} \\
    &\mathsf{rec}(\texttt{su}(a_0'),\, T',\, z',\, s',\, \ensuremath{\llbracket \sigma' \rrbracket(\rho')}) \searrow b'
      && \text{(by \textsc{rec-su}, using $\ensuremath{\llbracket s' \rrbracket((\ensuremath{\llbracket \sigma' \rrbracket(\rho')}, a_0'/x, b_0'/y))} \searrow b'$)}
  \end{align*}

  We must show $b \approx b' \in R_T$.
  Outer-left vs inner-right of the four-value pattern of $s, s'$:
  \begin{align*}
    &\ensuremath{\llbracket (T[\Uparrow \circ \Uparrow, \textsf{succ}~x_1/x])[q^2(\sigma)] \rrbracket((\rho, a_0/x, b_0/y))} \approx \\
    &\quad
      \ensuremath{\llbracket T[\Uparrow \circ \Uparrow, \textsf{succ}~x_1/x] \rrbracket(\ensuremath{\llbracket q^2(\sigma') \rrbracket((\rho', a_0'/x, b_0'/y))})}
      \in \mathcal{U}_i \searrow R_s
      && \text{(type part)} \\
    &\ensuremath{\llbracket s[q^2(\sigma)] \rrbracket((\rho, a_0/x, b_0/y))} \approx
      \ensuremath{\llbracket s' \rrbracket(\ensuremath{\llbracket q^2(\sigma') \rrbracket((\rho', a_0'/x, b_0'/y))})} \in R_s
      && \text{(term part, by hypothesis on $s, s'$)}
  \end{align*}
  where $R_s$ is the PER governed by $\ensuremath{\llbracket (T[\Uparrow \circ \Uparrow, \textsf{succ}~x_1/x])[q^2(\sigma)] \rrbracket((\rho, a_0/x, b_0/y))}$.
  Bridge $\ensuremath{\llbracket q^2(\sigma') \rrbracket((\rho', a_0'/x, b_0'/y))}$ to
  $(\ensuremath{\llbracket \sigma' \rrbracket(\rho')}, a_0'/x, b_0'/y)$ in $R_{\Gamma, x:\ensuremath{\texttt{Nat}}, y:T}$ analogously,
  then apply \Cref{lem:sem-ty-id} on $\semtyeq[\Gamma, x:\ensuremath{\texttt{Nat}}, y:T]{s'}{s'}{T[\Uparrow \circ \Uparrow, \textsf{succ}~x_1/x]}$
  (the reflexive instance):
  \begin{align*}
    &\ensuremath{\llbracket s' \rrbracket(\ensuremath{\llbracket q^2(\sigma') \rrbracket((\rho', a_0'/x, b_0'/y))})} \approx
      \ensuremath{\llbracket s' \rrbracket((\ensuremath{\llbracket \sigma' \rrbracket(\rho')}, a_0'/x, b_0'/y))} \in R_s
      && \text{(by \Cref{lem:sem-ty-id})}
  \end{align*}
  By transitivity, $b \approx b' \in R_s$.

  We bridge $R_s \Leftrightarrow R_T$, where $R_s$ is governed by
  $\ensuremath{\llbracket (T[\Uparrow \circ \Uparrow, \textsf{succ}~x_1/x])[q^2(\sigma)] \rrbracket((\rho, a_0/x, b_0/y))}$ and $R_T$ is
  governed by $\ensuremath{\llbracket T[q(\sigma)] \rrbracket((\rho, \texttt{su}(a_0)/x))}$ (the second-claim
  pattern instantiated at $\texttt{su}(a_0) \approx \texttt{su}(a_0')$):
  \begin{align*}
    &\ensuremath{\llbracket T[q(\sigma)] \rrbracket((\rho, \texttt{su}(a_0)/x))} \\
    &\quad \approx \ensuremath{\llbracket T' \rrbracket((\ensuremath{\llbracket \sigma' \rrbracket(\rho')}, \texttt{su}(a_0')/x))}
      \in \mathcal{U}_i \searrow R_T
      && \text{(second claim)}
  \end{align*}
  All bridging uses syntactic substitution-composition lemmas
  (\Cref{lem:subst-assoc,lem:ext-comp,lem:subst-cat}) and instantiations of
  hypothesis on $T$.

  \emph{Bridge B1: collapse $(T[\Uparrow \circ \Uparrow, \textsf{succ}~x_1/x])[q^2(\sigma)]$ into a single substitution.}
  \begin{align*}
    (T[\Uparrow \circ \Uparrow, \textsf{succ}~x_1/x])[q^2(\sigma)]
    &= T[(\Uparrow \circ \Uparrow, \textsf{succ}~x_1/x) \circ q^2(\sigma)]
      \tag{by \Cref{lem:subst-assoc}} \\
    &= T[(\Uparrow \circ \Uparrow) \circ q^2(\sigma),\;
       \textsf{succ}~x_1[q^2(\sigma)]/x]
      \tag{by \Cref{lem:ext-comp}} \\
    &= T[\sigma \circ (\Uparrow \circ \Uparrow),\; \textsf{succ}~x_1/x]
      \tag{using $\textsf{succ}~x_1[q^2(\sigma)] = \textsf{succ}~x_1$ (since $q^2(\sigma)(1) = x_1$)} \\
    & \tag{and $(\Uparrow \circ \Uparrow) \circ q^2(\sigma) = \sigma \circ (\Uparrow \circ \Uparrow)$
       (\Cref{lem:wk-subst-comm})}
  \end{align*}
  Denote the collapsed substitution by
  $\tau := (\sigma \circ (\Uparrow \circ \Uparrow),\, \textsf{succ}~x_1/x)$, with
  $\judge[\Gamma', x:\ensuremath{\texttt{Nat}}, y:T[q(\sigma)]]{\tau : \Gamma, x:\ensuremath{\texttt{Nat}}}$.

  \emph{Bridge B2: instantiate hypothesis on $T$ via $\tau$.}
  We show $\tau$ is a semantic substitution from $\Gamma', x:\ensuremath{\texttt{Nat}}, y:T[q(\sigma)]$
  to $\Gamma, x:\ensuremath{\texttt{Nat}}$.
  By \Cref{lem:sem-wk-shift} (twice) and \Cref{lem:sem-wk-comp}:
  $\semweak[\Gamma', x:\ensuremath{\texttt{Nat}}, y:T[q(\sigma)]]{\Uparrow \circ \Uparrow}{\Gamma'}$.
  Apply \Cref{lem:sem-wk-subst} to $\semtyeq[\Gamma']{\sigma}{\sigma}{\Gamma}$
  (reflexive, by \Cref{lem:sem-sym,lem:sem-trans}) and this semantic weakening:
  \begin{align*}
    &\semtyeq[\Gamma', x:\ensuremath{\texttt{Nat}}, y:T[q(\sigma)]]
       {\sigma \circ (\Uparrow \circ \Uparrow)}
       {\sigma \circ (\Uparrow \circ \Uparrow)}
       {\Gamma}
  \end{align*}
  By \Cref{lem:fund-var}, \Cref{lem:fund-su}:
  $\semtyeq[\Gamma', x:\ensuremath{\texttt{Nat}}, y:T[q(\sigma)]]
  {\textsf{succ}~x_1}{\textsf{succ}~x_1}{\ensuremath{\texttt{Nat}}}$
  (lookup $x_1 : \ensuremath{\texttt{Nat}}$ at the second slot of
  $\Gamma', x:\ensuremath{\texttt{Nat}}, y:T[q(\sigma)]$, with
  $\ensuremath{\texttt{Nat}}[\Uparrow] = \ensuremath{\texttt{Nat}}$).
  By \Cref{lem:sem-ext-pre}:
  \begin{align*}
    &\semtyeq[\Gamma', x:\ensuremath{\texttt{Nat}}, y:T[q(\sigma)]]{\tau}{\tau}{\Gamma, x:\ensuremath{\texttt{Nat}}}
      && \text{(\Cref{lem:sem-ext-pre})}
  \end{align*}
  Apply $\semtyeq[\Gamma, x:\ensuremath{\texttt{Nat}}]{T}{T}{\ensuremath{\texttt{Ty}_{i}}}$ at
  $\Gamma', x:\ensuremath{\texttt{Nat}}, y:T[q(\sigma)]$, $\tau \approx \tau$, and the
  reflexive env-pair
  $(\rho, a_0/x, b_0/y) \approx (\rho, a_0/x, b_0/y)
  \in R_{\Gamma', x:\ensuremath{\texttt{Nat}}, y:T[q(\sigma)]}$.
  Outer-left vs inner-left:
  \begin{align*}
    &\ensuremath{\llbracket T[\tau] \rrbracket((\rho, a_0/x, b_0/y))} \\
    &\quad \approx \ensuremath{\llbracket T \rrbracket(\ensuremath{\llbracket \tau \rrbracket((\rho, a_0/x, b_0/y))})}
      \in \mathcal{U}_i \searrow R_{B2}
  \end{align*}
  By Bridge B1,
  \[
    T[\tau] = (T[\Uparrow \circ \Uparrow, \textsf{succ}~x_1/x])[q^2(\sigma)],
  \]
  so the outer-left is exactly
  \[
    \ensuremath{\llbracket (T[\Uparrow \circ \Uparrow, \textsf{succ}~x_1/x])[q^2(\sigma)] \rrbracket((\rho, a_0/x, b_0/y))}
  \]
  --- the value governing $R_s$.
  Hence $R_s \Leftrightarrow R_{B2}$.

  By pointwise definition of substitution evaluation:
  \begin{align*}
    &\ensuremath{\llbracket \tau \rrbracket((\rho, a_0/x, b_0/y))}
      = (\ensuremath{\llbracket \sigma \circ (\Uparrow \circ \Uparrow) \rrbracket((\rho, a_0/x, b_0/y))},\,
       \texttt{su}(a_0)/x) \\
    & \text{(pointwise; head: $\ensuremath{\llbracket \textsf{succ}~x_1 \rrbracket((\rho, a_0/x, b_0/y))} = \texttt{su}(a_0)$ via ev-su, ev-var)}
  \end{align*}
  We do \emph{not} equate the tail
  $\ensuremath{\llbracket \sigma \circ (\Uparrow \circ \Uparrow) \rrbracket((\rho, a_0/x, b_0/y))}$ with
  $\ensuremath{\llbracket \sigma \rrbracket(\rho)}$ definitionally --- such an equality is a
  substitution--evaluation commutation that does not hold for operational
  substitutions. Instead, we relate them in $R_\Gamma$ via the four-value
  pattern of $\sigma \circ (\Uparrow \circ \Uparrow) := \sigma[\Uparrow \circ \Uparrow]$
  established by \Cref{lem:sem-wk-subst}, and the four-value pattern of
  $\sigma$ itself:
  \begin{align*}
    &\ensuremath{\llbracket \sigma[\Uparrow \circ \Uparrow] \rrbracket((\rho, a_0/x, b_0/y))}
      \approx \ensuremath{\llbracket \sigma \rrbracket(\ensuremath{\llbracket \Uparrow \circ \Uparrow \rrbracket((\rho, a_0/x, b_0/y))})} \in R_\Gamma
      && \text{(four-value pattern of $\sigma[\Uparrow \circ \Uparrow]$,} \\
    & && \text{outer-left vs inner-left)} \\
    &\ensuremath{\llbracket \Uparrow \circ \Uparrow \rrbracket((\rho, a_0/x, b_0/y))}
      \approx \rho \in R_{\Gamma'}
      && \text{(four-value pattern of $\Uparrow \circ \Uparrow$,} \\
    & && \text{by \Cref{lem:sem-shift,lem:sem-wk-comp})} \\
    &\ensuremath{\llbracket \sigma \rrbracket(\ensuremath{\llbracket \Uparrow \circ \Uparrow \rrbracket((\rho, a_0/x, b_0/y))})}
      \approx \ensuremath{\llbracket \sigma \rrbracket(\rho)} \in R_\Gamma
      && \text{(by \Cref{lem:sem-ty-id} on the reflexive $\sigma$)}
  \end{align*}
  By transitivity of $R_\Gamma$:
  \begin{align*}
    &\ensuremath{\llbracket \sigma \circ (\Uparrow \circ \Uparrow) \rrbracket((\rho, a_0/x, b_0/y))}
      \approx \ensuremath{\llbracket \sigma \rrbracket(\rho)} \in R_\Gamma \\
    &\ensuremath{\llbracket \tau \rrbracket((\rho, a_0/x, b_0/y))} \approx (\ensuremath{\llbracket \sigma \rrbracket(\rho)},\, \texttt{su}(a_0)/x)
      \in R_{\Gamma, x:\ensuremath{\texttt{Nat}}}
      && \text{(by \textsc{Ctx-Ext}, head $\texttt{su}(a_0) \approx \texttt{su}(a_0)$)}
  \end{align*}

  \emph{Bridge B3: instantiate hypothesis on $T$ via $q(\sigma)$.}
  Apply $\semtyeq[\Gamma, x:\ensuremath{\texttt{Nat}}]{T}{T}{\ensuremath{\texttt{Ty}_{i}}}$ at $\Gamma', x:\ensuremath{\texttt{Nat}}$, the lifted
  $q(\sigma) \approx q(\sigma)$, and reflexive
  $(\rho, \texttt{su}(a_0)/x) \approx (\rho, \texttt{su}(a_0)/x) \in R_{\Gamma', x:\ensuremath{\texttt{Nat}}}$
  (head $\texttt{su}(a_0) \approx \texttt{su}(a_0)$ via \Cref{lem:nat-per} reflexivity).
  Outer-left vs inner-left:
  \begin{align*}
    &\ensuremath{\llbracket T[q(\sigma)] \rrbracket((\rho, \texttt{su}(a_0)/x))} \\
    &\quad \approx \ensuremath{\llbracket T \rrbracket(\ensuremath{\llbracket q(\sigma) \rrbracket((\rho, \texttt{su}(a_0)/x))})}
      \in \mathcal{U}_i \searrow R_{B3} \\
    &\ensuremath{\llbracket q(\sigma) \rrbracket((\rho, \texttt{su}(a_0)/x))}
      \approx (\ensuremath{\llbracket \sigma \rrbracket(\rho)}, \texttt{su}(a_0)/x) \in R_{\Gamma, x:\ensuremath{\texttt{Nat}}}
      && \text{(by \textsc{Ctx-Ext})}
  \end{align*}

  \emph{Combining B2 and B3.}
  By B2's bridging,
  $\ensuremath{\llbracket \tau \rrbracket((\rho, a_0/x, b_0/y))} \approx (\ensuremath{\llbracket \sigma \rrbracket(\rho)}, \texttt{su}(a_0)/x)
   \in R_{\Gamma, x:\ensuremath{\texttt{Nat}}}$.
  By B3's \textsc{Ctx-Ext} computation,
  $\ensuremath{\llbracket q(\sigma) \rrbracket((\rho, \texttt{su}(a_0)/x))} \approx (\ensuremath{\llbracket \sigma \rrbracket(\rho)}, \texttt{su}(a_0)/x)
   \in R_{\Gamma, x:\ensuremath{\texttt{Nat}}}$ (PER-related, via the lifted-substitution evidence).
  Apply \Cref{lem:sem-ty-id} on $T$ to bridge the B3 inner-left:
  \begin{align*}
    &\ensuremath{\llbracket T \rrbracket(\ensuremath{\llbracket q(\sigma) \rrbracket((\rho, \texttt{su}(a_0)/x))})}
      \approx \ensuremath{\llbracket T \rrbracket((\ensuremath{\llbracket \sigma \rrbracket(\rho)}, \texttt{su}(a_0)/x))} \in \mathcal{U}_i
      && \text{(\Cref{lem:sem-ty-id})}
  \end{align*}
  Both B2 and B3 inner-left values are now $\mathcal{U}_i$-related to the common value
  $\ensuremath{\llbracket T \rrbracket((\ensuremath{\llbracket \sigma \rrbracket(\rho)}, \texttt{su}(a_0)/x))}$, so by transitivity and
  \Cref{lem:univ-functional}, $R_{B2} \Leftrightarrow R_{B3}$.

  Chaining: $R_s \Leftrightarrow R_{B2} \Leftrightarrow R_{B3} \Leftrightarrow R_T$.
  Hence $b \approx b' \in R_T$.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{Nat-Ne}]
    {e \approx e' \in \textsf{Ne}}
    {{\uparrow}^N(e) \approx {\uparrow}^N(e') \in \textsf{Nat}}
  \end{mathpar}
  with $a = {\uparrow}^N(e)$, $a' = {\uparrow}^N(e')$.
  Compute the eliminator outputs by \textsc{rec-ne}:
  \begin{align*}
    &\ensuremath{\llbracket T[q(\sigma)] \rrbracket((\rho, {\uparrow}^N(e)/x))} \searrow A
      && \text{(governing the left motive)} \\
    &\ensuremath{\llbracket T' \rrbracket((\ensuremath{\llbracket \sigma' \rrbracket(\rho')}, {\uparrow}^N(e')/x))} \searrow A'
      && \text{(governing the right motive)} \\
    &A \approx A' \in \mathcal{U}_i \searrow R_T
      && \text{(by the second claim at ${\uparrow}^N(e) \approx {\uparrow}^N(e')$)} \\
    &\ensuremath{\llbracket z[\sigma] \rrbracket(\rho)} \searrow a_z,\;\;
      \ensuremath{\llbracket z' \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})} \searrow a_z',\;\;
      a_z \approx a_z' \in R_z
      && \text{(by hypothesis on $z, z'$)} \\
    &b = {\uparrow}^A(\mathsf{rec}(T[q(\sigma)], a_z, s[q^2(\sigma)], \rho, e))
      && \text{(by \textsc{rec-ne})} \\
    &b' = {\uparrow}^{A'}(\mathsf{rec}(T', a_z', s', \ensuremath{\llbracket \sigma' \rrbracket(\rho')}, e'))
      && \text{(by \textsc{rec-ne})}
  \end{align*}

  We must show $b \approx b' \in R_T$.
  By \Cref{lem:ne-in-R} on $A \approx A' \in \mathcal{U}_i \searrow R_T$, it suffices to show
  \begin{align*}
    &\mathsf{rec}(T[q(\sigma)], a_z, s[q^2(\sigma)], \rho, e)
      \approx
      \mathsf{rec}(T', a_z', s', \ensuremath{\llbracket \sigma' \rrbracket(\rho')}, e') \in \textsf{Ne},
  \end{align*}
  i.e.\ for every depth $n$ both sides read back via $\textsf{R}^{\textsf{Ne}}_n$ to the same
  neutral normal form.
  By rule \textsc{Re-rec}:
  \begin{align*}
    &\textsf{R}^{\textsf{Ne}}_n(\mathsf{rec}(T[q(\sigma)], a_z, s[q^2(\sigma)], \rho, e))
      \searrow \ensuremath{\textsf{elim}_{\ensuremath{\texttt{Nat}}}~(x.\,W_T)~w_z~(x, y.\,w_s)~u}
  \end{align*}
  whenever
  \begin{align*}
    &\textsf{R}^{\textsf{Ty}}_{n+1}(A_x) \searrow W_T
      && \text{where $\ensuremath{\llbracket T[q(\sigma)] \rrbracket((\rho, {\uparrow}^N(\ell_n)/x))} \searrow A_x$} \\
    &\textsf{R}^{\textsf{Nf}}_n({\downarrow}^{A_z}(a_z)) \searrow w_z
      && \text{where $\ensuremath{\llbracket T[q(\sigma)] \rrbracket((\rho, \texttt{ze}/x))} \searrow A_z$} \\
    &\ensuremath{\llbracket s[q^2(\sigma)] \rrbracket((\rho, {\uparrow}^N(\ell_n)/x, {\uparrow}^{A_x}(\ell_{n+1})/y))}
      \searrow b_s \\
    &\textsf{R}^{\textsf{Nf}}_{n+2}({\downarrow}^{A_x^{\textsf{succ}~}}(b_s)) \searrow w_s
      && \text{where $\ensuremath{\llbracket T[q(\sigma)] \rrbracket((\rho, \texttt{su}({\uparrow}^N(\ell_n))/x))}
        \searrow A_x^{\textsf{succ}~}$} \\
    &\textsf{R}^{\textsf{Ne}}_n(e) \searrow u
  \end{align*}
  and analogously for the primed side, producing
  $\ensuremath{\textsf{elim}_{\ensuremath{\texttt{Nat}}}~(x.\,W_T')~w_z'~(x, y.\,w_s')~u'}$.
  We show each component reads back to the same syntactic form.

  \emph{Motive $W_T = W_T'$.}
  Apply the second claim of this lemma at the fresh-level relation
  ${\uparrow}^N(\ell_n) \approx {\uparrow}^N(\ell_n) \in \textsf{Nat}$ (by
  \textsc{Nat-Ne}, $\ell_n \approx \ell_n \in \textsf{Ne}$):
  \begin{align*}
    &\ensuremath{\llbracket T[q(\sigma)] \rrbracket((\rho, {\uparrow}^N(\ell_n)/x))} \approx
      \ensuremath{\llbracket T' \rrbracket((\ensuremath{\llbracket \sigma' \rrbracket(\rho')}, {\uparrow}^N(\ell_n)/x))}
      \in \mathcal{U}_i \searrow R_T^\ell
      && \text{(second claim at $\ell_n$)} \\
    &W_T = W_T'
      && \text{(by \Cref{lem:type-readback})}
  \end{align*}
  No separate env-pair construction is needed: the second claim is parametric
  in $a \approx a' \in \textsf{Nat}$ and directly relates the two motive values
  at envs over the heterogeneous source--target contexts.

  \emph{Zero branch $w_z = w_z'$.}
  By the \textsc{Nat-Ze} sub-case proved above,
  $a_z \approx a_z' \in R_T$-at-$\texttt{ze}$ (the PER governed by
  $\ensuremath{\llbracket T[q(\sigma)] \rrbracket((\rho, \texttt{ze}/x))}$, which equals $A_z$).
  By \Cref{lem:R-readback}:
  \begin{align*}
    &w_z = w_z'
      && \text{(by \Cref{lem:R-readback})}
  \end{align*}

  \emph{Step branch $w_s = w_s'$.}
  We obtain $b_s \approx b_s'$ at fresh levels by replaying the
  \textsc{Nat-Su} case with $a_0 := {\uparrow}^N(\ell_n)$.
  First, lift $\sigma, \sigma'$ to handle the binders of $s$:
  \begin{align*}
    &\semtyeq[\Gamma', x:\ensuremath{\texttt{Nat}}]{q(\sigma)}{q(\sigma')}{\Gamma, x:\ensuremath{\texttt{Nat}}}
      && \text{(by \Cref{lem:sem-q} on $\sigma \approx \sigma'$ and $\ensuremath{\texttt{Nat}}$)} \\
    &\semtyeq[\Gamma', x:\ensuremath{\texttt{Nat}}, y:T[q(\sigma)]]
       {q^2(\sigma)}{q^2(\sigma')}{\Gamma, x:\ensuremath{\texttt{Nat}}, y:T}
      && \text{(by \Cref{lem:sem-q} again on $T$)}
  \end{align*}
  Build the env-pair via two applications of \textsc{Ctx-Ext}:
  \begin{align*}
    &{\uparrow}^N(\ell_n) \approx {\uparrow}^N(\ell_n) \in \textsf{Nat}
      && \text{(\textsc{Nat-Ne}, $\ell_n \approx \ell_n \in \textsf{Ne}$)} \\
    &(\rho, {\uparrow}^N(\ell_n)/x) \approx (\rho', {\uparrow}^N(\ell_n)/x)
      \in R_{\Gamma', x:\ensuremath{\texttt{Nat}}}
      && \text{(\textsc{Ctx-Ext}, head $\textsf{Nat}$)} \\
    &{\uparrow}^{A_x}(\ell_{n+1}) \approx {\uparrow}^{A_x'}(\ell_{n+1}) \in R_T^\ell
      && \text{(by \Cref{lem:ne-in-R} on $\ell_{n+1} \approx \ell_{n+1} \in \textsf{Ne}$)} \\
    &(\rho, {\uparrow}^N(\ell_n)/x, {\uparrow}^{A_x}(\ell_{n+1})/y) \\
    &\quad \approx (\rho', {\uparrow}^N(\ell_n)/x, {\uparrow}^{A_x'}(\ell_{n+1})/y)
      \in R_{\Gamma', x:\ensuremath{\texttt{Nat}}, y:T[q(\sigma)]}
      && \text{(\textsc{Ctx-Ext}, head $R_T^\ell$)}
  \end{align*}
  Apply $\semtyeq[\Gamma, x:\ensuremath{\texttt{Nat}}, y:T]{s}{s'}{T[\Uparrow \circ \Uparrow, \textsf{succ}~x_1/x]}$
  at $\Gamma', x:\ensuremath{\texttt{Nat}}, y:T[q(\sigma)]$, the doubly-lifted substitution
  $q^2(\sigma) \approx q^2(\sigma')$, and this env-pair.
  The four-value pattern of $s, s'$ gives:
  \begin{align*}
    &b_s \approx b_s' \in R_T^{step}
      && \text{(outer-left vs inner-right, parallel to the helper's} \\
    & && \text{Nat-Su case)}
  \end{align*}
  where $R_T^{step}$ is governed by
  $\ensuremath{\llbracket (T[\Uparrow \circ \Uparrow, \textsf{succ}~x_1/x])[q^2(\sigma)] \rrbracket((\rho, {\uparrow}^N(\ell_n)/x, {\uparrow}^{A_x}(\ell_{n+1})/y))}$.

  By the B1/B2/B3 bridging of the \textsc{Nat-Su} case (with $a_0$ replaced by
  ${\uparrow}^N(\ell_n)$):
  \begin{align*}
    &R_T^{step} \Leftrightarrow R_T^\ell\text{-at-}\texttt{su}({\uparrow}^N(\ell_n))
      && \text{(B1/B2/B3 bridges, \Cref{lem:univ-functional})}
  \end{align*}
  i.e.\ the PER at $\ensuremath{\llbracket T[q(\sigma)] \rrbracket((\rho, \texttt{su}({\uparrow}^N(\ell_n))/x))}$,
  which equals $A_x^{\textsf{succ}~}$.
  Hence $b_s \approx b_s' \in R_T^\ell$-at-$\texttt{su}(\ell_n)$, and:
  \begin{align*}
    &w_s = w_s'
      && \text{(by \Cref{lem:R-readback})}
  \end{align*}

  \emph{Underlying neutral $u = u'$.}
  By hypothesis $e \approx e' \in \textsf{Ne}$:
  \begin{align*}
    &\textsf{R}^{\textsf{Ne}}_n(e) \searrow u,\;\; \textsf{R}^{\textsf{Ne}}_n(e') \searrow u
      && \text{(by definition of $\textsf{Ne}$)}
  \end{align*}

  Combining:
  \begin{align*}
    &\textsf{R}^{\textsf{Ne}}_n(\mathsf{rec}(T[q(\sigma)], a_z, s[q^2(\sigma)], \rho, e))
      \searrow \ensuremath{\textsf{elim}_{\ensuremath{\texttt{Nat}}}~(x.\,W_T)~w_z~(x, y.\,w_s)~u} \\
    &\textsf{R}^{\textsf{Ne}}_n(\mathsf{rec}(T', a_z', s', \ensuremath{\llbracket \sigma' \rrbracket(\rho')}, e'))
      \searrow \ensuremath{\textsf{elim}_{\ensuremath{\texttt{Nat}}}~(x.\,W_T)~w_z~(x, y.\,w_s)~u}
      && \text{(same syntactic form)} \\
    &\mathsf{rec}(T[q(\sigma)], a_z, s[q^2(\sigma)], \rho, e)
      \approx \mathsf{rec}(T', a_z', s', \ensuremath{\llbracket \sigma' \rrbracket(\rho')}, e') \in \textsf{Ne}
      && \text{(definition of $\textsf{Ne}$)}
  \end{align*}
  Hence $b \approx b' \in R_T$.

Let $\Gamma' \approx \Gamma' \searrow R'$,
  $\semtyeq[\Gamma']{\sigma}{\sigma'}{\Gamma}$, and
  $\ensuremath{\mathcal{D}} :: \rho \approx \rho' \in R'$ be given.
  Write $\rho_\sigma := \ensuremath{\llbracket \sigma \rrbracket(\rho)}$ and $\rho_{\sigma'} := \ensuremath{\llbracket \sigma' \rrbracket(\rho')}$.
  From $\semtyeq[\Gamma']{\sigma}{\sigma'}{\Gamma}$ at $\ensuremath{\textsf{id}}$, $\ensuremath{\mathcal{D}}$:
  $\rho_\sigma \approx \rho_{\sigma'} \in R_\Gamma$ where
  $\Gamma \approx \Gamma \searrow R_\Gamma$.

  By $\semtyeq[\Gamma]{t}{t'}{\ensuremath{\texttt{Nat}}}$ applied at $\Gamma'$, $\sigma \approx \sigma'$,
  $\rho \approx \rho' \in R'$:
  \begin{align*}
    &\{\ensuremath{\llbracket t[\sigma] \rrbracket(\rho)},\;
      \ensuremath{\llbracket t \rrbracket(\rho_\sigma)},\;
      \ensuremath{\llbracket t' \rrbracket(\rho_{\sigma'})},\;
      \ensuremath{\llbracket t'[\sigma'] \rrbracket(\rho')}\}
      \subseteq \textsf{Nat}
      && \text{(by hypothesis on $t, t'$)}
  \end{align*}

  Compute the four eliminator term values:
  \begin{align*}
    &\ensuremath{\llbracket (\ensuremath{\textsf{elim}_{\ensuremath{\texttt{Nat}}}~(x.\,T)~z~(x, y.\, s)~t})[\sigma] \rrbracket(\rho)}
      && \text{(definition of substitution} \\
    & \quad = \ensuremath{\llbracket \ensuremath{\textsf{elim}_{\ensuremath{\texttt{Nat}}}~(x.\,T[q(\sigma)])~z[\sigma]~(x, y.\, s[q^2(\sigma)])~t[\sigma]} \rrbracket(\rho)}
      && \text{on $\textsf{elim}_{\ensuremath{\texttt{Nat}}}$)} \\
    &\quad = \mathsf{rec}(\ensuremath{\llbracket t[\sigma] \rrbracket(\rho)},\,
      T[q(\sigma)],\, z[\sigma],\, s[q^2(\sigma)],\, \rho)
      && \text{(by ev-rec)} \\[4pt]
    &\ensuremath{\llbracket \ensuremath{\textsf{elim}_{\ensuremath{\texttt{Nat}}}~(x.\,T)~z~(x, y.\, s)~t} \rrbracket(\rho_\sigma)} \\
    & \quad = \mathsf{rec}(\ensuremath{\llbracket t \rrbracket(\rho_\sigma)},\, T,\, z,\, s,\, \rho_\sigma)
      && \text{(by ev-rec)}
  \end{align*}
  Analogous computations for the primed pair (using $z', s', t'$):
  $\mathsf{rec}(\ensuremath{\llbracket t'[\sigma'] \rrbracket(\rho')},\, T[q(\sigma')],\,
  z'[\sigma'],\, s'[q^2(\sigma')],\, \rho')$ and
  $\mathsf{rec}(\ensuremath{\llbracket t' \rrbracket(\rho_{\sigma'})},\, T,\, z',\, s',\,
  \rho_{\sigma'})$.

  Before applying the helpers, derive reflexive instances of all hypotheses
  (the helpers' RHS are in primed form; we sometimes need
  unprimed-to-unprimed instances):
  \begin{align*}
    &\semtyeq[\Gamma, x:\ensuremath{\texttt{Nat}}]{T}{T}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(reflexive, by \Cref{lem:fund-sym,lem:fund-trans} on $T \approx T'$)} \\
    &\semtyeq[\Gamma]{z}{z}{T[\textsf{zero}/x]}
      && \text{(reflexive)} \\
    &\semtyeq[\Gamma, x:\ensuremath{\texttt{Nat}}, y:T]{s}{s}{T[\Uparrow \circ \Uparrow, \textsf{succ}~x_1/x]}
      && \text{(reflexive)} \\
    &\semtyeq[\Gamma]{t}{t}{\ensuremath{\texttt{Nat}}}
      && \text{(reflexive)} \\
    &\semtyeq[\Gamma']{\sigma}{\sigma}{\Gamma}
      && \text{(reflexive)}
  \end{align*}
  (Primed analogues hold symmetrically.)

  \emph{Inner pair via the unsubstituted helper.}
  Apply \Cref{lem:sem-rec} at $T \approx T$ (reflexive), $z \approx z'$,
  $s \approx s'$, $R_\Gamma$, env-pair $\rho_\sigma \approx \rho_{\sigma'}$,
  and witness $\ensuremath{\llbracket t \rrbracket(\rho_\sigma)} \approx \ensuremath{\llbracket t' \rrbracket(\rho_{\sigma'})}
  \in \textsf{Nat}$ (inner-left vs inner-right of the four-value pattern of
  $t, t'$):
  \begin{align*}
    &\mathsf{rec}(\ensuremath{\llbracket t \rrbracket(\rho_\sigma)},\, T,\, z,\, s,\, \rho_\sigma)
      \searrow b_i \\
    &\mathsf{rec}(\ensuremath{\llbracket t' \rrbracket(\rho_{\sigma'})},\, T,\, z',\, s',\, \rho_{\sigma'})
      \searrow b_i' \\
    &b_i \approx b_i' \in R_T
      && \text{(by \Cref{lem:sem-rec})}
  \end{align*}
  where $R_T$ is governed by
  $\ensuremath{\llbracket T \rrbracket((\rho_\sigma, \ensuremath{\llbracket t \rrbracket(\rho_\sigma)}/x))} \approx
  \ensuremath{\llbracket T \rrbracket((\rho_{\sigma'}, \ensuremath{\llbracket t' \rrbracket(\rho_{\sigma'})}/x))} \in \mathcal{U}_i \searrow R_T$.
  These match the goal's inner-left and inner-right term values.

  \emph{Outer-vs-inner via the one-sided helper.}
  Apply \Cref{lem:sem-rec-subst} at $T \approx T$, $z \approx z$, $s \approx s$
  (all reflexive), $\Gamma' \approx \Gamma' \searrow R'$,
  $\sigma \approx \sigma$ (reflexive),
  $\rho \approx \rho \in R'$ (reflexive), and witness
  $\ensuremath{\llbracket t[\sigma] \rrbracket(\rho)} \approx \ensuremath{\llbracket t \rrbracket(\rho_\sigma)} \in \textsf{Nat}$
  (outer-left vs inner-left of the four-value pattern of $t$):
  \begin{align*}
    &\mathsf{rec}(\ensuremath{\llbracket t[\sigma] \rrbracket(\rho)},\, T[q(\sigma)],\, z[\sigma],\,
      s[q^2(\sigma)],\, \rho) \searrow b_o \\
    &\mathsf{rec}(\ensuremath{\llbracket t \rrbracket(\rho_\sigma)},\, T,\, z,\, s,\, \rho_\sigma) \searrow b_i \\
    &b_o \approx b_i \in R_T^{oi}
      && \text{(by \Cref{lem:sem-rec-subst})}
  \end{align*}
  where $R_T^{oi}$ is governed by
  $\ensuremath{\llbracket T[q(\sigma)] \rrbracket((\rho, \ensuremath{\llbracket t[\sigma] \rrbracket(\rho)}/x))} \approx
  \ensuremath{\llbracket T \rrbracket((\rho_\sigma, \ensuremath{\llbracket t \rrbracket(\rho_\sigma)}/x))} \in \mathcal{U}_i \searrow R_T^{oi}$.
  By \Cref{lem:univ-functional}, $R_T^{oi} \Leftrightarrow R_T$.
  Hence $b_o \approx b_i \in R_T$.

  Apply \Cref{lem:sem-rec-subst} symmetrically at the primed reflexive
  instances ($T' \approx T'$, $z' \approx z'$, $s' \approx s'$,
  $\sigma' \approx \sigma'$, $\rho' \approx \rho' \in R'$), with witness
  $\ensuremath{\llbracket t'[\sigma'] \rrbracket(\rho')} \approx \ensuremath{\llbracket t' \rrbracket(\rho_{\sigma'})} \in \textsf{Nat}$:
  \begin{align*}
    &b_o' \approx b_i' \in R_T
      && \text{(by \Cref{lem:sem-rec-subst} and \Cref{lem:univ-functional})}
  \end{align*}

  \emph{Combining.}
  We assemble the four goal term values:
  \begin{align*}
    &b_i \approx b_i' \in R_T
      && \text{(inner pair, above)} \\
    &b_o \approx b_i \in R_T
      && \text{(outer-vs-inner, left side, above)} \\
    &b_o' \approx b_i' \in R_T
      && \text{(outer-vs-inner, right side, above)} \\
    &b_o \approx b_o' \in R_T
      && \text{(by symmetry and transitivity of $R_T$)}
  \end{align*}
  Thus all four goal term values
  $\{b_o, b_i, b_i', b_o'\}$ are pairwise related in $R_T$.

  \emph{Type part.}
  The goal type is $T[t/x]$ on the LHS and $T[t'/x]$ on the RHS (by the syntactic
  conclusion's type, via the four-value pattern of the outer
  $\semtyeq[\Gamma]{\ensuremath{\textsf{elim}_{\ensuremath{\texttt{Nat}}}~(\ldots)~\ldots~(\ldots)~t}}{\ensuremath{\textsf{elim}_{\ensuremath{\texttt{Nat}}}~(\ldots)~\ldots~(\ldots)~t'}}{T[t/x]}$
  semantic judgment).
  We bridge the four goal type values via outer and inner instantiations of
  $T \approx T'$.

  \emph{Outer instantiation.}
  By \Cref{lem:sem-ext-pre} on $\semtyeq[\Gamma']{\sigma}{\sigma'}{\Gamma}$ and
  $\semtyeq[\Gamma]{t}{t'}{\ensuremath{\texttt{Nat}}}$:
  \begin{align*}
    &\semtyeq[\Gamma']{(\sigma, t[\sigma]/x)}{(\sigma', t'[\sigma']/x)}{\Gamma, x:\ensuremath{\texttt{Nat}}}
      && \text{(\Cref{lem:sem-ext-pre})}
  \end{align*}
  Apply $\semtyeq[\Gamma, x:\ensuremath{\texttt{Nat}}]{T}{T'}{\ensuremath{\texttt{Ty}_{i}}}$ at $\Gamma'$, this semantic
  substitution, and $\rho \approx \rho' \in R'$:
  \begin{align*}
    &\{\ensuremath{\llbracket T[\sigma, t[\sigma]/x] \rrbracket(\rho)},\;
      \ensuremath{\llbracket T \rrbracket((\rho_\sigma, \ensuremath{\llbracket t[\sigma] \rrbracket(\rho)}/x))}, \\
    &\quad
      \ensuremath{\llbracket T' \rrbracket((\rho_{\sigma'}, \ensuremath{\llbracket t'[\sigma'] \rrbracket(\rho')}/x))},\;
      \ensuremath{\llbracket T'[\sigma', t'[\sigma']/x] \rrbracket(\rho')}\}
      \subseteq \mathcal{U}_i \searrow R_T^{out}
      && \text{(by hypothesis on $T \approx T'$)} \\
    &T[\sigma, t[\sigma]/x] = 
      && \text{(by \Cref{lem:subst-ext-comm})} \\
    &T'[\sigma', t'[\sigma']/x] = (T'[t'/x])[\sigma']
      && \text{(by \Cref{lem:subst-ext-comm})}
  \end{align*}
  Now the goal's outer-RHS type is $\ensuremath{\llbracket  \rrbracket(\rho')}$, but the
  outer instantiation gives $\ensuremath{\llbracket (T'[t'/x])[\sigma'] \rrbracket(\rho')}$.
  We show these coincide modulo $\mathcal{U}_i$:
  \begin{align*}
    &\ensuremath{\llbracket  \rrbracket(\rho')} \approx \ensuremath{\llbracket (T'[t'/x])[\sigma'] \rrbracket(\rho')} \in \mathcal{U}_i
      && \text{(four-value pattern of $T \approx T'$ at } \\
    & && \text{the outer-RHS instantiation, applied} \\
    & && \text{at $(\sigma', t'[\sigma']/x)$ with $\rho' \approx \rho' \in R'$)}
  \end{align*}
  So the four values lie in $\mathcal{U}_i \searrow R_T^{out}$ with the outer-LHS value
  exactly matching the goal's $\ensuremath{\llbracket  \rrbracket(\rho)}$ and the outer-RHS
  value matching the goal's $\ensuremath{\llbracket  \rrbracket(\rho')}$ (modulo
  $\mathcal{U}_i$, hence by \Cref{lem:univ-functional}).

  \emph{Inner instantiation.}
  By \Cref{lem:sem-ext-pre} over $\Gamma$ on $\semtyeq[\Gamma]{\ensuremath{\textsf{id}}}{\ensuremath{\textsf{id}}}{\Gamma}$
  and $\semtyeq[\Gamma]{t}{t'}{\ensuremath{\texttt{Nat}}}$:
  \begin{align*}
    &\semtyeq[\Gamma]{(\ensuremath{\textsf{id}}, t/x)}{(\ensuremath{\textsf{id}}, t'/x)}{\Gamma, x:\ensuremath{\texttt{Nat}}}
      && \text{(\Cref{lem:sem-ext-pre})}
  \end{align*}
  Apply $\semtyeq[\Gamma, x:\ensuremath{\texttt{Nat}}]{T}{T'}{\ensuremath{\texttt{Ty}_{i}}}$ at $\Gamma$, this semantic
  substitution, and $\rho_\sigma \approx \rho_{\sigma'} \in R_\Gamma$:
  \begin{align*}
    &\{\ensuremath{\llbracket T[\ensuremath{\textsf{id}}, t/x] \rrbracket(\rho_\sigma)},\;
      \ensuremath{\llbracket T \rrbracket((\rho_\sigma, \ensuremath{\llbracket t \rrbracket(\rho_\sigma)}/x))}, \\
    &\quad
      \ensuremath{\llbracket T' \rrbracket((\rho_{\sigma'}, \ensuremath{\llbracket t' \rrbracket(\rho_{\sigma'})}/x))},\;
      \ensuremath{\llbracket T'[\ensuremath{\textsf{id}}, t'/x] \rrbracket(\rho_{\sigma'})}\}
      \subseteq \mathcal{U}_i \searrow R_T^{in}
      && \text{(by hypothesis on $T \approx T'$)} \\
    &T[\ensuremath{\textsf{id}}, t/x] = T[t/x]
      && \text{(definition of single substitution)} \\
    &T'[\ensuremath{\textsf{id}}, t'/x] = T'[t'/x]
      && \text{(definition of single substitution)}
  \end{align*}

  \emph{Bridging.}
  The inner-pair values
  $\ensuremath{\llbracket T \rrbracket((\rho_\sigma, \ensuremath{\llbracket t \rrbracket(\rho_\sigma)}/x))}$ (shared between outer and
  inner instantiations) and
  $\ensuremath{\llbracket T' \rrbracket((\rho_{\sigma'}, \ensuremath{\llbracket t' \rrbracket(\rho_{\sigma'})}/x))}$ (shared) bridge the
  PERs:
  \begin{align*}
    &R_T^{out} \Leftrightarrow R_T^{in}
      && \text{(by \Cref{lem:univ-functional} on shared inner values)} \\
    &\ensuremath{\llbracket T \rrbracket((\rho_\sigma, \ensuremath{\llbracket t \rrbracket(\rho_\sigma)}/x))} \approx
     \ensuremath{\llbracket T \rrbracket((\rho_{\sigma'}, \ensuremath{\llbracket t' \rrbracket(\rho_{\sigma'})}/x))} \in \mathcal{U}_i \searrow R_T
      && \text{(unsubstituted helper's $R_T$ governance)} \\
    &R_T^{in} \Leftrightarrow R_T
      && \text{(by \Cref{lem:univ-functional} on the shared} \\
    & && \text{inner-LHS value with the helper's $R_T$)}
  \end{align*}
  Hence all four goal type values lie in $\mathcal{U}_i \searrow R_T$,
  with the term values $\{b_o, b_i, b_i', b_o'\}$ in $R_T$ as established.

\label{lem:fund-subsump}
  If $\semtyeq[\Gamma]{T}{T}{\ensuremath{\texttt{Ty}_{i}}}$ and $\semtyeq[\Gamma]{t}{t}{S}$ and
  $\Gamma \vDash S \subseteq T$, then $\semtyeq[\Gamma]{t}{t}{T}$.

Let $\Gamma' \approx \Gamma' \searrow R'$,
  $\semtyeq[\Gamma']{\sigma}{\sigma'}{\Gamma}$, and
  $\ensuremath{\mathcal{D}} :: \rho \approx \rho' \in R'$ be given.

  \emph{Type part.}
  By $\semtyeq[\Gamma]{T}{T}{\ensuremath{\texttt{Ty}_{i}}}$ at the given data:
  \begin{align*}
    &\{\ensuremath{\llbracket T[\sigma] \rrbracket(\rho)},\;
      \ensuremath{\llbracket T \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})},\;
      \ensuremath{\llbracket T \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})},\;
      \ensuremath{\llbracket T[\sigma'] \rrbracket(\rho')}\}
      \subseteq \mathcal{U}_i \searrow R_T
      && \text{(by hypothesis on $T$)}
  \end{align*}

  \emph{Term part.}
  By $\semtyeq[\Gamma]{t}{t}{S}$ at the given data:
  \begin{align*}
    &\{\ensuremath{\llbracket S[\sigma] \rrbracket(\rho)},\;
      \ensuremath{\llbracket S \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})},\;
      \ensuremath{\llbracket S \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})},\;
      \ensuremath{\llbracket S[\sigma'] \rrbracket(\rho')}\}
      \subseteq \mathcal{U}_i \searrow R_S
      && \text{(by hypothesis on $S$)} \\
    &\{\ensuremath{\llbracket t[\sigma] \rrbracket(\rho)},\;
      \ensuremath{\llbracket t \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})},\;
      \ensuremath{\llbracket t \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})},\;
      \ensuremath{\llbracket t[\sigma'] \rrbracket(\rho')}\}
      \subseteq R_S
      && \text{(by hypothesis on $t$)}
  \end{align*}

  By $\Gamma \vDash S \subseteq T$ at the given data:
  \begin{align*}
    &\ensuremath{\llbracket S[\sigma] \rrbracket(\rho)} \approx \ensuremath{\llbracket S \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})} \in \mathcal{U}_i
      && \text{(by semantic subtyping, commutation)} \\
    &\ensuremath{\llbracket T[\sigma'] \rrbracket(\rho')} \approx \ensuremath{\llbracket T \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})} \in \mathcal{U}_i
      && \text{(by semantic subtyping, commutation)} \\
    &\ensuremath{\llbracket S \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})} \mathrel{<:_i} \ensuremath{\llbracket T \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})}
      && \text{(by semantic subtyping)}
  \end{align*}
  By \Cref{lem:subty-respects} applied to the subtyping
  $\ensuremath{\llbracket S \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})} \mathrel{<:_i} \ensuremath{\llbracket T \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})}$
  together with $\ensuremath{\llbracket S \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})} \approx \ensuremath{\llbracket S \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})} \in \mathcal{U}_i \searrow R_S$
  and $\ensuremath{\llbracket T \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})} \approx \ensuremath{\llbracket T \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})} \in \mathcal{U}_i \searrow R_T$:
  \begin{align*}
    &R_S \subseteq R_T
      && \text{(by \Cref{lem:subty-respects})}
  \end{align*}

  Hence the four term values, which lie in $R_S$, also lie in $R_T$:
  \begin{align*}
    &\{\ensuremath{\llbracket t[\sigma] \rrbracket(\rho)},\;
      \ensuremath{\llbracket t \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})},\;
      \ensuremath{\llbracket t \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})},\;
      \ensuremath{\llbracket t[\sigma'] \rrbracket(\rho')}\}
      \subseteq R_T
      && \text{(by $R_S \subseteq R_T$)}
  \end{align*}

Let $\Gamma' \approx \Gamma' \searrow R'$,
  $\semtyeq[\Gamma']{\sigma}{\sigma'}{\Gamma}$, and
  $\ensuremath{\mathcal{D}} :: \rho \approx \rho' \in R'$ be given.

  \emph{LHS computation at $\sigma, \rho$.}
  By the syntactic action of substitution on $\lambda$ and application, then
  ev-app/ev-lam/closure-application:
  \begin{align*}
    &((\lambda x.\,t)\;s)[\sigma]
      = (\lambda x.\,t[q(\sigma)])\;s[\sigma]
      && \text{(syntactic, definition of substitution)} \\
    &\ensuremath{\llbracket (\lambda x.\,t[q(\sigma)])\;s[\sigma] \rrbracket(\rho)}
      \searrow b_L
      \text{ where} \\
    &\quad \ensuremath{\llbracket \lambda x.\,t[q(\sigma)] \rrbracket(\rho)} \searrow \lambda(t[q(\sigma)], \rho)
      && \text{(ev-lam)} \\
    &\quad \ensuremath{\llbracket s[\sigma] \rrbracket(\rho)} \searrow a_s
      && \text{(some $a_s$)} \\
    &\quad \lambda(t[q(\sigma)], \rho) \cdot a_s \searrow b_L
      && \text{(closure application:} \\
    & && \text{$\ensuremath{\llbracket t[q(\sigma)] \rrbracket((\rho, a_s/x))} \searrow b_L$)}
  \end{align*}

  \emph{RHS expression at $\sigma, \rho$.}
  Using the sugar $[s/x] = [\ensuremath{\textsf{id}}, s/x]$ and \Cref{lem:subst-ext-comm,lem:q-ext}:
  \begin{align*}
    & = t[q(\sigma)][s[\sigma]/x] = t[\sigma, s[\sigma]/x]
      && \text{(by \Cref{lem:subst-ext-comm,lem:q-ext})}
  \end{align*}
  Let $b_R$ satisfy $\ensuremath{\llbracket t[\sigma, s[\sigma]/x] \rrbracket(\rho)} \searrow b_R$ (existence
  via the four-value pattern below).
  We relate $b_L$ and $b_R$ in the term PER via the four-value pattern of $t$
  on the extended substitution.

  \emph{Relatedness.}
  By \Cref{lem:sem-ext-pre} on $\semtyeq[\Gamma']{\sigma}{\sigma'}{\Gamma}$ and
  $\semtyeq[\Gamma]{s}{s}{S}$:
  \begin{align*}
    &\semtyeq[\Gamma']{(\sigma, s[\sigma]/x)}{(\sigma', s[\sigma']/x)}{\Gamma, x:S}
      && \text{(\Cref{lem:sem-ext-pre})}
  \end{align*}
  Apply $\semtyeq[\Gamma, x:S]{t}{t}{T}$ at $\Gamma'$, this extended substitution,
  and $\rho \approx \rho' \in R'$.
  Let $R_T$ be the PER governing the four-value pattern of $t$ at this
  instantiation; concretely, $R_T$ is determined by the type four-value pattern
  of $T$ at the same env-pair (carried by semantic typing of $t : T$):
  \begin{align*}
    &\{\ensuremath{\llbracket T[\sigma, s[\sigma]/x] \rrbracket(\rho)},\;
      \ensuremath{\llbracket T \rrbracket(\ensuremath{\llbracket (\sigma, s[\sigma]/x) \rrbracket(\rho)})}, \\
    &\quad \ensuremath{\llbracket T \rrbracket(\ensuremath{\llbracket (\sigma', s[\sigma']/x) \rrbracket(\rho')})},\;
      \ensuremath{\llbracket T[\sigma', s[\sigma']/x] \rrbracket(\rho')}\}
      \subseteq \mathcal{U}_i \searrow R_T
  \end{align*}
  The term four-value pattern then gives:
  \begin{align*}
    &\{\ensuremath{\llbracket t[\sigma, s[\sigma]/x] \rrbracket(\rho)},\;
      \ensuremath{\llbracket t \rrbracket(\ensuremath{\llbracket (\sigma, s[\sigma]/x) \rrbracket(\rho)})}, \\
    &\quad \ensuremath{\llbracket t \rrbracket(\ensuremath{\llbracket (\sigma', s[\sigma']/x) \rrbracket(\rho')})},\;
      \ensuremath{\llbracket t[\sigma', s[\sigma']/x] \rrbracket(\rho')}\}
      \subseteq R_T
      && \text{(by hypothesis on $t$)}
  \end{align*}
  By the syntactic identity above (and analogously at $\sigma', \rho'$), the
  outer values coincide with the goal's RHS outer-values
  $\{\ensuremath{\llbracket  \rrbracket(\rho)}, \ensuremath{\llbracket  \rrbracket(\rho')}\}$.

  \emph{LHS values via four-value pattern of $t$ at $q(\sigma)$.}
  We bridge $b_L = \ensuremath{\llbracket t[q(\sigma)] \rrbracket((\rho, a_s/x))}$ to the inner-left value
  $\ensuremath{\llbracket t \rrbracket(\ensuremath{\llbracket (\sigma, s[\sigma]/x) \rrbracket(\rho)})}$ above.
  By \Cref{lem:sem-q} on $\semtyeq[\Gamma']{\sigma}{\sigma}{\Gamma}$ (reflexive,
  via \Cref{lem:sem-sym,lem:sem-trans}) and $\semtyeq[\Gamma]{S}{S}{\ensuremath{\texttt{Ty}_{i}}}$:
  \begin{align*}
    &\semtyeq[\Gamma', x:S[\sigma]]{q(\sigma)}{q(\sigma)}{\Gamma, x:S}
      && \text{(\Cref{lem:sem-q})}
  \end{align*}
  The reflexive env-pair $(\rho, a_s/x) \approx (\rho, a_s/x)$ in
  $R_{\Gamma', x:S[\sigma]}$ holds via \textsc{Ctx-Ext} (head $a_s \approx a_s$
  reflexively in the head PER, tail $\rho \approx \rho \in R'$).
  Apply $\semtyeq[\Gamma, x:S]{t}{t}{T}$ at $\Gamma', x:S[\sigma]$,
  $q(\sigma) \approx q(\sigma)$, and this env-pair (four-value pattern of $t$,
  outer-left vs inner-left):
  \begin{align*}
    &\ensuremath{\llbracket t[q(\sigma)] \rrbracket((\rho, a_s/x))}
      \approx \ensuremath{\llbracket t \rrbracket(\ensuremath{\llbracket q(\sigma) \rrbracket((\rho, a_s/x))})} \in R_T
      && \text{(four-value pattern of $t$)}
  \end{align*}
  Bridge $\ensuremath{\llbracket q(\sigma) \rrbracket((\rho, a_s/x))}$ to $\ensuremath{\llbracket (\sigma, s[\sigma]/x) \rrbracket(\rho)}$
  in $R_{\Gamma, x:S}$ pointwise. Both envs have head $a_s$:
  \begin{align*}
    &\ensuremath{\llbracket q(\sigma) \rrbracket((\rho, a_s/x))}
      = (\ensuremath{\llbracket \sigma[\Uparrow] \rrbracket((\rho, a_s/x))},\, a_s/x)
      && \text{(by $q(\sigma) = (\sigma[\Uparrow], 0/x)$, pointwise eval)} \\
    &\ensuremath{\llbracket (\sigma, s[\sigma]/x) \rrbracket(\rho)}
      = (\ensuremath{\llbracket \sigma \rrbracket(\rho)},\, a_s/x)
      && \text{(pointwise eval; $\ensuremath{\llbracket s[\sigma] \rrbracket(\rho)} = a_s$)} \\
    &\ensuremath{\llbracket \sigma[\Uparrow] \rrbracket((\rho, a_s/x))}
      \approx \ensuremath{\llbracket \sigma \rrbracket(\rho)} \in R_\Gamma
      && \text{(four-value pattern of $\sigma \approx \sigma$ at} \\
    & && \text{$\semweak[\Gamma', x:S[\sigma]]{\Uparrow}{\Gamma'}$, env} \\
    & && \text{$(\rho, a_s/x) \approx (\rho, a_s/x) \in R_{\Gamma', x:S[\sigma]}$;} \\
    & && \text{using $\ensuremath{\llbracket \Uparrow \rrbracket((\rho, a_s/x))} = \rho$ pointwise)} \\
    &\ensuremath{\llbracket q(\sigma) \rrbracket((\rho, a_s/x))}
      \approx \ensuremath{\llbracket (\sigma, s[\sigma]/x) \rrbracket(\rho)} \in R_{\Gamma, x:S}
      && \text{(by \textsc{Ctx-Ext}, head $a_s \approx a_s$ reflexively)}
  \end{align*}
  Apply \Cref{lem:sem-ty-id} on the reflexive instance
  $\semtyeq[\Gamma, x:S]{t}{t}{T}$ at this env-pair:
  \begin{align*}
    &\ensuremath{\llbracket t \rrbracket(\ensuremath{\llbracket q(\sigma) \rrbracket((\rho, a_s/x))})}
      \approx \ensuremath{\llbracket t \rrbracket(\ensuremath{\llbracket (\sigma, s[\sigma]/x) \rrbracket(\rho)})} \in R_T
      && \text{(\Cref{lem:sem-ty-id})}
  \end{align*}
  By transitivity, $b_L \approx \ensuremath{\llbracket t \rrbracket(\ensuremath{\llbracket (\sigma, s[\sigma]/x) \rrbracket(\rho)})}$
  in $R_T$ (the inner-left value of the relatedness pattern).
  Symmetrically for the primed side.

  Combining: all eight values (four LHS, four RHS) lie in $R_T$, so
  the LHS-RHS pair at each of the four positions is in $R_T$.

  \emph{Type part.}
  Already established: the type four-value pattern displayed above (in
  $\mathcal{U}_i \searrow R_T$) is the goal's $T[s/x]$ pattern, since
  $T[\sigma, s[\sigma]/x] = $ by the syntactic identity used for
  the term part.

Let $\Gamma' \approx \Gamma' \searrow R'$,
  $\semtyeq[\Gamma']{\sigma}{\sigma'}{\Gamma}$, and
  $\ensuremath{\mathcal{D}} :: \rho \approx \rho' \in R'$ be given.

  \emph{LHS values.}
  By $\semtyeq[\Gamma]{t}{t}{\Pi(x:S).\,T}$ at $\Gamma'$, $\sigma \approx \sigma'$,
  $\rho \approx \rho' \in R'$, the four evaluations of $t$ are related in the
  function PER $R$:
  \begin{align*}
    &\{\ensuremath{\llbracket t[\sigma] \rrbracket(\rho)},\;
      \ensuremath{\llbracket t \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})},\;
      \ensuremath{\llbracket t \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})},\;
      \ensuremath{\llbracket t[\sigma'] \rrbracket(\rho')}\}
      \subseteq R
      && \text{(by hypothesis on $t$)}
  \end{align*}
  with biconditional characterization
  $f \approx f' \in R \;\leftrightarrow\;
  (\forall \ensuremath{\mathcal{D}}_I :: a \approx a' \in R_I.\; f \cdot a \approx f' \cdot a' \in R_O(\ensuremath{\mathcal{D}}_I))$.

  \emph{RHS values.}
  The RHS evaluates on the $\sigma', \rho'$-side only:
  \begin{align*}
    &\ensuremath{\llbracket (\lambda x.\,(t[\Uparrow]\;x))[\sigma'] \rrbracket(\rho')}
      \searrow f_o
      && \text{(syntactic and ev-lam)} \\
    &\ensuremath{\llbracket \lambda x.\,(t[\Uparrow]\;x) \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})}
      \searrow f_i
      && \text{(ev-lam)}
  \end{align*}
  where $f_o := \lambda(t[\Uparrow][q(\sigma')]\;x,\, \rho')$ and
  $f_i := \lambda(t[\Uparrow]\;x,\, \ensuremath{\llbracket \sigma' \rrbracket(\rho')})$.

  \emph{Step 1: $\ensuremath{\llbracket t[\sigma'] \rrbracket(\rho')} \approx f_o$ in $R$.}
  By the biconditional, suffices to show: for every
  $\ensuremath{\mathcal{D}}_I :: a \approx a' \in R_I$,
  $\ensuremath{\llbracket t[\sigma'] \rrbracket(\rho')} \cdot a \approx f_o \cdot a' \in R_O(\ensuremath{\mathcal{D}}_I)$.

  Compute $f_o \cdot a'$:
  \begin{align*}
    &f_o \cdot a' = \ensuremath{\llbracket t[\Uparrow][q(\sigma')]\;x \rrbracket((\rho', a'/x))}
      && \text{(closure app)} \\
    &\quad = \ensuremath{\llbracket t[\Uparrow][q(\sigma')] \rrbracket((\rho', a'/x))} \cdot a'
      && \text{(ev-app)} \\
    &\quad = \ensuremath{\llbracket t[\sigma'[\Uparrow]] \rrbracket((\rho', a'/x))} \cdot a'
      && \text{(\Cref{lem:subst-assoc} and \Cref{lem:shift-ext}:} \\
    & && \text{$\Uparrow \circ q(\sigma') = \sigma'[\Uparrow]$)}
  \end{align*}
  Bridge $\ensuremath{\llbracket t[\sigma'[\Uparrow]] \rrbracket((\rho', a'/x))} \approx \ensuremath{\llbracket t[\sigma'] \rrbracket(\rho')}
   \in R$:
  \begin{align*}
    &\semweak[\Gamma', x:S[\sigma']]{\Uparrow}{\Gamma'}
      && \text{(\Cref{lem:sem-wk-shift})} \\
    &\semtyeq[\Gamma', x:S[\sigma']]{\sigma'[\Uparrow]}{\sigma'[\Uparrow]}{\Gamma}
      && \text{(\Cref{lem:sem-wk-subst} on $\sigma' \approx \sigma'$ refl.)}
  \end{align*}
  Apply hypothesis on $t$ at $\Gamma', x:S[\sigma']$, $\sigma'[\Uparrow] \approx
   \sigma'[\Uparrow]$, env-pair $(\rho', a'/x) \approx (\rho', a'/x) \in
   R_{\Gamma', x:S[\sigma']}$:
  \begin{align*}
    &\ensuremath{\llbracket t[\sigma'[\Uparrow]] \rrbracket((\rho', a'/x))} \\
    &\quad \approx \ensuremath{\llbracket t \rrbracket(\ensuremath{\llbracket \sigma'[\Uparrow] \rrbracket((\rho', a'/x))})} \in R
      && \text{(outer-left vs inner-left of $t$)}
  \end{align*}
  Apply hypothesis on $\sigma'$ at the same data
  ($\Uparrow$ as the weakening, env-pair as above), giving
  $\ensuremath{\llbracket \sigma'[\Uparrow] \rrbracket((\rho', a'/x))} \approx \ensuremath{\llbracket \sigma' \rrbracket(\rho')} \in R_\Gamma$
  (using $\ensuremath{\llbracket \Uparrow \rrbracket((\rho', a'/x))} = \rho'$ pointwise).
  By \Cref{lem:sem-ty-id} on $t$:
  \begin{align*}
    &\ensuremath{\llbracket t \rrbracket(\ensuremath{\llbracket \sigma'[\Uparrow] \rrbracket((\rho', a'/x))})}
      \approx \ensuremath{\llbracket t \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})} \in R
      && \text{(\Cref{lem:sem-ty-id})}
  \end{align*}
  Chained with $\ensuremath{\llbracket t \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})} \approx \ensuremath{\llbracket t[\sigma'] \rrbracket(\rho')}
   \in R$ (four-value pattern of $t$, inner-left vs outer-left):
  \begin{align*}
    &\ensuremath{\llbracket t[\sigma'[\Uparrow]] \rrbracket((\rho', a'/x))}
      \approx \ensuremath{\llbracket t[\sigma'] \rrbracket(\rho')} \in R
      && \text{(transitivity)}
  \end{align*}
  Apply the biconditional of $R$ at $\ensuremath{\mathcal{D}}_I$:
  $\ensuremath{\llbracket t[\sigma'[\Uparrow]] \rrbracket((\rho', a'/x))} \cdot a
   \approx \ensuremath{\llbracket t[\sigma'] \rrbracket(\rho')} \cdot a' \in R_O(\ensuremath{\mathcal{D}}_I)$.
  Since $f_o \cdot a' = \ensuremath{\llbracket t[\sigma'[\Uparrow]] \rrbracket((\rho', a'/x))} \cdot a'$, by
  symmetry of $R_O$ on the reflexive instance of
  $\ensuremath{\llbracket t[\sigma'] \rrbracket(\rho')} \approx \ensuremath{\llbracket t[\sigma'] \rrbracket(\rho')} \in R$ at
  $a \approx a'$:
  $\ensuremath{\llbracket t[\sigma'] \rrbracket(\rho')} \cdot a \approx f_o \cdot a' \in R_O(\ensuremath{\mathcal{D}}_I)$.

  \emph{Step 2: $\ensuremath{\llbracket t \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})} \approx f_i$ in $R$.}
  Suffices to show: for every $\ensuremath{\mathcal{D}}_I :: a \approx a' \in R_I$,
  $\ensuremath{\llbracket t \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})} \cdot a \approx f_i \cdot a' \in R_O(\ensuremath{\mathcal{D}}_I)$.

  Compute:
  \begin{align*}
    &f_i \cdot a' = \ensuremath{\llbracket t[\Uparrow]\;x \rrbracket((\ensuremath{\llbracket \sigma' \rrbracket(\rho')}, a'/x))}
      && \text{(closure app)} \\
    &\quad = \ensuremath{\llbracket t[\Uparrow] \rrbracket((\ensuremath{\llbracket \sigma' \rrbracket(\rho')}, a'/x))} \cdot a'
      && \text{(ev-app)}
  \end{align*}
  Bridge $\ensuremath{\llbracket t[\Uparrow] \rrbracket((\ensuremath{\llbracket \sigma' \rrbracket(\rho')}, a'/x))} \approx \ensuremath{\llbracket t \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})}
   \in R$ via the four-value pattern of $t$ (reflexive) at the new context
  $\Gamma, x:S$, $\semweak[\Gamma, x:S]{\Uparrow}{\Gamma}$, env-pair
  $(\ensuremath{\llbracket \sigma' \rrbracket(\rho')}, a'/x) \approx (\ensuremath{\llbracket \sigma' \rrbracket(\rho')}, a'/x)
   \in R_{\Gamma, x:S}$:
  outer-left $\ensuremath{\llbracket t[\Uparrow] \rrbracket((\ensuremath{\llbracket \sigma' \rrbracket(\rho')}, a'/x))}$, inner-left
  $\ensuremath{\llbracket t \rrbracket(\ensuremath{\llbracket \Uparrow \rrbracket((\ensuremath{\llbracket \sigma' \rrbracket(\rho')}, a'/x))})} = \ensuremath{\llbracket t \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})}$
  (pointwise).
  Apply biconditional at $\ensuremath{\mathcal{D}}_I$ and the reflexive
  $\ensuremath{\llbracket t \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})} \approx \ensuremath{\llbracket t \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})}$ at
  $a \approx a'$:
  $\ensuremath{\llbracket t \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})} \cdot a \approx f_i \cdot a' \in R_O(\ensuremath{\mathcal{D}}_I)$.

  \emph{Combining.}
  By the four-value pattern of $t$, all four LHS values are pairwise related
  in $R$. By Steps 1 and 2,
  $\ensuremath{\llbracket t[\sigma'] \rrbracket(\rho')} \approx f_o$ and
  $\ensuremath{\llbracket t \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})} \approx f_i$ in $R$.
  By symmetry and transitivity of $R$, every LHS-RHS pair (e.g.
  $\ensuremath{\llbracket t[\sigma] \rrbracket(\rho)} \approx f_o$, $\ensuremath{\llbracket t \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})} \approx f_i$,
  etc.) lies in $R$.

  \emph{Type part.}
  By \Cref{lem:fund-pi-wf} on $\semtyeq[\Gamma]{S}{S}{\ensuremath{\texttt{Ty}_{i}}}$ and
  $\semtyeq[\Gamma, x:S]{T}{T}{\ensuremath{\texttt{Ty}_{i}}}$, the four-value pattern of
  $\Pi(x:S).\,T$ in $\mathcal{U}_i$ is established. The goal's type is $\Pi(x:S).\,T$
  on both sides, exactly this pattern.

Let $\Gamma' \approx \Gamma' \searrow R'$,
  $\semtyeq[\Gamma']{\sigma}{\sigma'}{\Gamma}$, and
  $\ensuremath{\mathcal{D}} :: \rho \approx \rho' \in R'$ be given.
  Write $\rho_\sigma := \ensuremath{\llbracket \sigma \rrbracket(\rho)}$ and $\rho_{\sigma'} := \ensuremath{\llbracket \sigma' \rrbracket(\rho')}$.

  \emph{LHS computation on the $\sigma, \rho$- and $\rho_\sigma$-side.}
  The LHS is $\ensuremath{\textsf{elim}_{\ensuremath{\texttt{Nat}}}~(x.\,T)~z~(x, y.\, s)~\textsf{zero}}$.
  Outer-LHS at $\sigma, \rho$:
  \begin{align*}
    &\ensuremath{\llbracket (\ensuremath{\textsf{elim}_{\ensuremath{\texttt{Nat}}}~(x.\,T)~z~(x, y.\, s)~\textsf{zero}})[\sigma] \rrbracket(\rho)} \\
    &\quad = \ensuremath{\llbracket \ensuremath{\textsf{elim}_{\ensuremath{\texttt{Nat}}}~(x.\,T[q(\sigma)])~z[\sigma]~(x, y.\, s[q^2(\sigma)])~\textsf{zero}} \rrbracket(\rho)}
      && \text{(definition of substitution on $\textsf{elim}_{\ensuremath{\texttt{Nat}}}$)} \\
    &\quad \searrow b
      && \text{(by ev-rec, $\ensuremath{\llbracket \textsf{zero} \rrbracket(\rho)} = \texttt{ze}$;} \\
    & && \text{$\mathsf{rec}(\texttt{ze}, T[q(\sigma)], z[\sigma], s[q^2(\sigma)], \rho) \searrow b$)} \\
    &b = \ensuremath{\llbracket z[\sigma] \rrbracket(\rho)}
      && \text{(by \textsc{rec-ze})}
  \end{align*}
  Inner-LHS at $\rho_\sigma$:
  \begin{align*}
    &\ensuremath{\llbracket \ensuremath{\textsf{elim}_{\ensuremath{\texttt{Nat}}}~(x.\,T)~z~(x, y.\, s)~\textsf{zero}} \rrbracket(\rho_\sigma)}
      \searrow b'
      && \text{(by ev-rec;} \\
    & && \text{$\mathsf{rec}(\texttt{ze}, T, z, s, \rho_\sigma) \searrow b'$)} \\
    &b' = \ensuremath{\llbracket z \rrbracket(\rho_\sigma)}
      && \text{(by \textsc{rec-ze})}
  \end{align*}

  \emph{RHS values on the $\sigma', \rho'$- and $\rho_{\sigma'}$-side.}
  The RHS is $z$, evaluated directly:
  \begin{align*}
    &\ensuremath{\llbracket z[\sigma'] \rrbracket(\rho')}
      && \text{(outer-RHS)} \\
    &\ensuremath{\llbracket z \rrbracket(\rho_{\sigma'})}
      && \text{(inner-RHS)}
  \end{align*}

  \emph{Relatedness.}
  By $\semtyeq[\Gamma]{z}{z}{T[\textsf{zero}/x]}$ at $\Gamma'$, $\sigma \approx \sigma'$,
  $\rho \approx \rho' \in R'$ (four-value pattern of $z$):
  \begin{align*}
    &\{\ensuremath{\llbracket z[\sigma] \rrbracket(\rho)},\;
      \ensuremath{\llbracket z \rrbracket(\rho_\sigma)},\;
      \ensuremath{\llbracket z \rrbracket(\rho_{\sigma'})},\;
      \ensuremath{\llbracket z[\sigma'] \rrbracket(\rho')}\}
      \subseteq R_z
      && \text{(by hypothesis on $z$)}
  \end{align*}
  where $R_z$ is the PER governed by the type four-value pattern of $T[\textsf{zero}/x]$.
  The LHS values $b, b'$ coincide with $\ensuremath{\llbracket z[\sigma] \rrbracket(\rho)}$ and
  $\ensuremath{\llbracket z \rrbracket(\rho_\sigma)}$ (the unprimed-side outer-LHS and inner-LHS of the $z$
  pattern).
  The RHS values $\ensuremath{\llbracket z[\sigma'] \rrbracket(\rho')}$ and $\ensuremath{\llbracket z \rrbracket(\rho_{\sigma'})}$ are
  exactly the primed-side outer-RHS and inner-RHS of the same pattern.
  Hence all four LHS-RHS pairs lie in $R_z$.

  Bridge $R_z \Leftrightarrow R_T$ (where $R_T$ is the goal's type PER, governed
  by $\ensuremath{\llbracket T[\textsf{zero}/x][\sigma] \rrbracket(\rho)}$): the goal's type is also $T[\textsf{zero}/x]$, so
  $R_z = R_T$ (functionality of $\mathcal{U}_i$, \Cref{lem:univ-functional}).

\label{lem:fund-rec-su}
  If $\semtyeq[\Gamma, x:\ensuremath{\texttt{Nat}}]{T}{T}{\ensuremath{\texttt{Ty}_{i}}}$ and
  $\semtyeq[\Gamma]{z}{z}{T[\textsf{zero}/x]}$ and
  $\semtyeq[\Gamma, x:\ensuremath{\texttt{Nat}}, y:T]{s}{s}{T[\Uparrow \circ \Uparrow, \textsf{succ}~x_1/x]}$ and
  $\semtyeq[\Gamma]{t}{t}{\ensuremath{\texttt{Nat}}}$,
  then
  $\semtyeq[\Gamma]
    {\ensuremath{\textsf{elim}_{\ensuremath{\texttt{Nat}}}~(x.\,T)~z~(x, y.\, s)~(\textsf{succ}~t)}}
    {s[t/x,\, \ensuremath{\textsf{elim}_{\ensuremath{\texttt{Nat}}}~(x.\,T)~z~(x, y.\, s)~t}/y]}
    {T[\textsf{succ}~t/x]}$.

Let $\Gamma' \approx \Gamma' \searrow R'$,
  $\semtyeq[\Gamma']{\sigma}{\sigma'}{\Gamma}$, and
  $\ensuremath{\mathcal{D}} :: \rho \approx \rho' \in R'$ be given.
  Write $\rho_\sigma := \ensuremath{\llbracket \sigma \rrbracket(\rho)}$ and $\rho_{\sigma'} := \ensuremath{\llbracket \sigma' \rrbracket(\rho')}$.
  Let $a = \ensuremath{\llbracket t \rrbracket(\rho_\sigma)}$, $a' = \ensuremath{\llbracket t \rrbracket(\rho_{\sigma'})}$,
  $b_t = \ensuremath{\llbracket t[\sigma] \rrbracket(\rho)}$, $b_{t'} = \ensuremath{\llbracket t[\sigma'] \rrbracket(\rho')}$.

  Denote $E := \ensuremath{\textsf{elim}_{\ensuremath{\texttt{Nat}}}~(x.\,T)~z~(x, y.\, s)~t}$ (the inner eliminator with scrutinee
  $t$; this is the recursive call appearing in the $\beta$-su rule).
  Define
  $c_t := \ensuremath{\llbracket E[\sigma] \rrbracket(\rho)}$,
  $c_{t'} := \ensuremath{\llbracket E[\sigma'] \rrbracket(\rho')}$,
  $c := \ensuremath{\llbracket E \rrbracket(\rho_\sigma)}$,
  $c' := \ensuremath{\llbracket E \rrbracket(\rho_{\sigma'})}$
  (the four evaluations of $E$ at the corresponding positions; existence by
  termination of evaluation).

  \emph{LHS computation.}
  By the syntactic action of substitution on $\textsf{elim}_{\ensuremath{\texttt{Nat}}}$, ev-rec, and rec-su:
  \begin{align*}
    &\ensuremath{\llbracket (\ensuremath{\textsf{elim}_{\ensuremath{\texttt{Nat}}}~(x.\,T)~z~(x, y.\, s)~(\textsf{succ}~t)})[\sigma] \rrbracket(\rho)} \\
    &\quad = \ensuremath{\llbracket \ensuremath{\textsf{elim}_{\ensuremath{\texttt{Nat}}}~(x.\,T[q(\sigma)])~z[\sigma]~(x, y.\, s[q^2(\sigma)])~(\textsf{succ}~t[\sigma])} \rrbracket(\rho)}
      && \text{(definition of substitution on $\textsf{elim}_{\ensuremath{\texttt{Nat}}}$)} \\
    &\quad \searrow b_L
      && \text{(by ev-rec, $\ensuremath{\llbracket \textsf{succ}~t[\sigma] \rrbracket(\rho)} = \texttt{su}(b_t)$)} \\
    &\mathsf{rec}(\texttt{su}(b_t),\, T[q(\sigma)],\, z[\sigma],\, s[q^2(\sigma)],\, \rho)
      \searrow b_L
      && \text{(rec-su needs predecessor's rec value)} \\
    &\mathsf{rec}(b_t,\, T[q(\sigma)],\, z[\sigma],\, s[q^2(\sigma)],\, \rho)
      \searrow c_t
      && \text{(by ev-rec on $E[\sigma]$ evaluated at $\rho$;} \\
    & && \text{$\ensuremath{\llbracket t[\sigma] \rrbracket(\rho)} = b_t$)} \\
    &\ensuremath{\llbracket s[q^2(\sigma)] \rrbracket((\rho,\, b_t/x,\, c_t/y))} \searrow b_L
      && \text{(by \textsc{rec-su})}
  \end{align*}

  At the inner position:
  \begin{align*}
    &\ensuremath{\llbracket \ensuremath{\textsf{elim}_{\ensuremath{\texttt{Nat}}}~(x.\,T)~z~(x, y.\, s)~(\textsf{succ}~t)} \rrbracket(\rho_\sigma)}
      \searrow b_I
      && \text{(by ev-rec)} \\
    &\mathsf{rec}(\texttt{su}(a),\, T,\, z,\, s,\, \rho_\sigma) \searrow b_I
      && \text{(rec-su)} \\
    &\mathsf{rec}(a,\, T,\, z,\, s,\, \rho_\sigma) \searrow c
      && \text{(by ev-rec on $E$ at $\rho_\sigma$;
       $\ensuremath{\llbracket t \rrbracket(\rho_\sigma)} = a$)} \\
    &\ensuremath{\llbracket s \rrbracket((\rho_\sigma,\, a/x,\, c/y))} \searrow b_I
      && \text{(by \textsc{rec-su})}
  \end{align*}

  \emph{RHS expression on the $\sigma', \rho'$-side.}
  The RHS appears on the right of $\approx$ in the goal, so the four-value
  pattern's RHS values are $\ensuremath{\llbracket  \rrbracket(\rho')}$ (outer-RHS)
  and $\ensuremath{\llbracket s[t/x, E/y] \rrbracket(\rho_{\sigma'})}$ (inner-RHS).
  By \Cref{lem:subst-assoc,lem:ext-comp,lem:q-ext}:
  \begin{align*}
    &
      = s[\sigma',\, t[\sigma']/x,\, E[\sigma']/y]
      && \text{(syntactic, composition of substitutions)}
  \end{align*}

  \emph{Doubly-extended semantic substitution.}
  We need the recursive call to be semantically valid: by \Cref{lem:fund-var},
  $\semtyeq[\Gamma, x:\ensuremath{\texttt{Nat}}]{x}{x}{\ensuremath{\texttt{Nat}}}$.
  By \Cref{lem:fund-rec} on $T \approx T$, $z \approx z$, $s \approx s$
  (all reflexive hypotheses, using \Cref{lem:fund-sym,lem:fund-trans}) and
  $x \approx x$:
  \begin{align*}
    &\semtyeq[\Gamma, x:\ensuremath{\texttt{Nat}}]
      {\ensuremath{\textsf{elim}_{\ensuremath{\texttt{Nat}}}~(x.\,T)~z~(x, y.\, s)~x}}{\ensuremath{\textsf{elim}_{\ensuremath{\texttt{Nat}}}~(x.\,T)~z~(x, y.\, s)~x}}{T}
      && \text{(by \Cref{lem:fund-rec}, scrutinee $x$;} \\
    & && \text{conclusion type $T[x/x] = T$)}
  \end{align*}
  By \Cref{lem:sem-ext-pre2} on $\semtyeq[\Gamma']{\sigma}{\sigma'}{\Gamma}$,
  $\semtyeq[\Gamma]{t}{t}{\ensuremath{\texttt{Nat}}}$, and the above (with the head substitution
  computing $E[\sigma]$ on the LHS, $E[\sigma']$ on the RHS):
  \[
    \begin{aligned}
      &\Gamma' \vDash
       (\sigma,\, t[\sigma]/x,\, E[\sigma]/y) \\
      &\quad \approx
       (\sigma',\, t[\sigma']/x,\, E[\sigma']/y) :
       \Gamma, x:\ensuremath{\texttt{Nat}}, y:T.
    \end{aligned}
  \]

  \emph{Four-value pattern of $s$ at the doubly-extended substitution.}
  Apply $\semtyeq[\Gamma, x:\ensuremath{\texttt{Nat}}, y:T]{s}{s}{T[\Uparrow \circ \Uparrow, \textsf{succ}~x_1/x]}$
  at the above substitution and $\rho \approx \rho' \in R'$:
  \begin{align*}
    &\{\ensuremath{\llbracket s[\sigma, t[\sigma]/x, E[\sigma]/y] \rrbracket(\rho)},\;
      \ensuremath{\llbracket s \rrbracket(\ensuremath{\llbracket (\sigma, t[\sigma]/x, E[\sigma]/y) \rrbracket(\rho)})}, \\
    &\quad \ensuremath{\llbracket s \rrbracket(\ensuremath{\llbracket (\sigma', t[\sigma']/x, E[\sigma']/y) \rrbracket(\rho')})},\;
      \ensuremath{\llbracket s[\sigma', t[\sigma']/x, E[\sigma']/y] \rrbracket(\rho')}\}
      \subseteq R_O
      && \text{(by hypothesis on $s$)}
  \end{align*}
  By substitution-extension evaluation:
  \begin{align*}
    &\ensuremath{\llbracket (\sigma, t[\sigma]/x, E[\sigma]/y) \rrbracket(\rho)}
      = (\rho_\sigma, b_t/x, c_t/y)
      && \text{(pointwise; head eval, $\ensuremath{\llbracket E[\sigma] \rrbracket(\rho)} = c_t$)} \\
    &\ensuremath{\llbracket (\sigma', t[\sigma']/x, E[\sigma']/y) \rrbracket(\rho')}
      = (\rho_{\sigma'}, b_{t'}/x, c_{t'}/y)
      && \text{(symmetrically; $\ensuremath{\llbracket E[\sigma'] \rrbracket(\rho')} = c_{t'}$)}
  \end{align*}
  where $c_{t'}$ is the corresponding recursive-call value.
  Hence the four values of the pattern read:
  \begin{align*}
    &\{\ensuremath{\llbracket s[\sigma, t[\sigma]/x, E[\sigma]/y] \rrbracket(\rho)},\;
      \ensuremath{\llbracket s \rrbracket((\rho_\sigma, b_t/x, c_t/y))}, \\
    &\quad \ensuremath{\llbracket s \rrbracket((\rho_{\sigma'}, b_{t'}/x, c_{t'}/y))},\;
      \ensuremath{\llbracket s[\sigma', t[\sigma']/x, E[\sigma']/y] \rrbracket(\rho')}\}
      \subseteq R_O
  \end{align*}

  \emph{Identifying $R_O$.}
  $R_O$ is the PER returned by the type four-value pattern of
  $T[\Uparrow \circ \Uparrow, \textsf{succ}~x_1/x]$ at the same doubly-extended substitution.
  We bridge it to the PER at $\ensuremath{\llbracket T \rrbracket((\rho_\sigma, \texttt{su}(a)/x))}$ (which is the
  goal's type $T[\textsf{succ}~t/x]$ evaluated at the inner position) via two steps.

  \emph{Step (a): collapse the iterated substitution.}
  Denote $\tau_* := (\sigma, t[\sigma]/x, E[\sigma]/y)$ (the doubly-extended
  substitution from $\Gamma'$ to $\Gamma, x:\ensuremath{\texttt{Nat}}, y:T$). The value
  $\ensuremath{\llbracket (T[\Uparrow \circ \Uparrow, \textsf{succ}~x_1/x])[\tau_*] \rrbracket(\rho)}$ governs $R_O$.
  By \Cref{lem:subst-assoc} and \Cref{lem:ext-comp}:
  \begin{align*}
    &(T[\Uparrow \circ \Uparrow, \textsf{succ}~x_1/x])[\tau_*]
      = T[(\Uparrow \circ \Uparrow, \textsf{succ}~x_1/x) \circ \tau_*]
      && \text{(by \Cref{lem:subst-assoc})} \\
    &(\Uparrow \circ \Uparrow, \textsf{succ}~x_1/x) \circ \tau_*
      = ((\Uparrow \circ \Uparrow) \circ \tau_*,\,
         (\textsf{succ}~x_1)[\tau_*]/x)
      && \text{(by \Cref{lem:ext-comp})} \\
    &(\Uparrow \circ \Uparrow) \circ \tau_* = \sigma
      && \text{(by \Cref{lem:shift-ext} twice, dropping} \\
    & && \text{$E[\sigma]/y$ and $t[\sigma]/x$)} \\
    &(\textsf{succ}~x_1)[\tau_*] = \textsf{succ}~x_1[\tau_*] = \textsf{succ}~t[\sigma]
      && \text{(by syntactic substitution; $\tau_*(1) = t[\sigma]$)}
  \end{align*}
  Hence the collapsed substitution is $(\sigma,\, \textsf{succ}~t[\sigma]/x)$:
  \begin{align*}
    &(T[\Uparrow \circ \Uparrow, \textsf{succ}~x_1/x])[\tau_*]
      = T[\sigma,\, \textsf{succ}~t[\sigma]/x]
      && \text{(by combining the above)}
  \end{align*}

  \emph{Step (b): instantiate hypothesis on $T$ at the collapsed substitution.}
  By the IH on $\semtyeq[\Gamma, x:\ensuremath{\texttt{Nat}}]{T}{T}{\ensuremath{\texttt{Ty}_{i}}}$, applied at $\Gamma'$,
  the semantic substitution $\semtyeq[\Gamma']{(\sigma, \textsf{succ}~t[\sigma]/x)}{(\sigma', \textsf{succ}~t[\sigma']/x)}{\Gamma, x:\ensuremath{\texttt{Nat}}}$
  (by \Cref{lem:sem-ext-pre} on $\sigma \approx \sigma'$ and
  $\textsf{succ}~t[\sigma] \approx \textsf{succ}~t[\sigma'] \in \textsf{Nat}$ via \textsc{Nat-Su}
  on the $t$-pattern), and $\rho \approx \rho' \in R'$:
  \begin{align*}
    &\ensuremath{\llbracket T[\sigma, \textsf{succ}~t[\sigma]/x] \rrbracket(\rho)} \\
    & \quad \approx \ensuremath{\llbracket T \rrbracket(\ensuremath{\llbracket (\sigma, \textsf{succ}~t[\sigma]/x) \rrbracket(\rho)})}
      \in \mathcal{U}_i \searrow R_O
      && \text{(four-value of $T$, outer-LHS vs inner-LHS)} \\
    &\ensuremath{\llbracket (\sigma, \textsf{succ}~t[\sigma]/x) \rrbracket(\rho)}
      = (\rho_\sigma, \texttt{su}(b_t)/x)
      && \text{(pointwise eval; $\ensuremath{\llbracket \textsf{succ}~t[\sigma] \rrbracket(\rho)} = \texttt{su}(b_t)$)}
  \end{align*}
  Bridge $\texttt{su}(b_t)$ to $\texttt{su}(a)$: from the four-value pattern of $t$,
  \[
    b_t = \ensuremath{\llbracket t[\sigma] \rrbracket(\rho)} \approx a = \ensuremath{\llbracket t \rrbracket(\rho_\sigma)}
    \in \textsf{Nat}
  \]
  (outer-LHS vs inner-LHS), so $\texttt{su}(b_t) \approx \texttt{su}(a)
  \in \textsf{Nat}$ by
  \textsc{Nat-Su}. By \Cref{lem:sem-ty-id} on $T$:
  \begin{align*}
    &\ensuremath{\llbracket T \rrbracket((\rho_\sigma, \texttt{su}(b_t)/x))} \approx \ensuremath{\llbracket T \rrbracket((\rho_\sigma, \texttt{su}(a)/x))}
      \in \mathcal{U}_i
      && \text{(\Cref{lem:sem-ty-id})}
  \end{align*}
  By transitivity and \Cref{lem:univ-functional}, $R_O$ is the PER at
  $\ensuremath{\llbracket T \rrbracket((\rho_\sigma, \texttt{su}(a)/x))}$ --- the goal's type $T[\textsf{succ}~t/x]$ inner-LHS
  value (since $T[\textsf{succ}~t/x]$ evaluated at $\rho_\sigma$ equals $T$ at the
  inner-extended env, modulo the same bridge).

  \emph{LHS-RHS bridging.}
  The RHS outer-RHS value is
  $\ensuremath{\llbracket  \rrbracket(\rho')} = \ensuremath{\llbracket s[\sigma', t[\sigma']/x, E[\sigma']/y] \rrbracket(\rho')}$,
  which is the outer-RHS of the four-value pattern of $s$ above.
  Similarly, the RHS inner-RHS value
  $\ensuremath{\llbracket s[t/x, E/y] \rrbracket(\rho_{\sigma'})}$ relates to
  $\ensuremath{\llbracket s \rrbracket((\rho_{\sigma'}, b_{t'}/x, c_{t'}/y))}$ via the four-value pattern of
  $s$ on the primed side (analogous to the LHS-side bridging below).

  For LHS values (the $\sigma, \rho$- and $\rho_\sigma$-sides of the goal):
  the LHS computation gives $b_L = \ensuremath{\llbracket s[q^2(\sigma)] \rrbracket((\rho, b_t/x, c_t/y))}$
  at $\sigma, \rho$, and $b_I = \ensuremath{\llbracket s \rrbracket((\rho_\sigma, a/x, c/y))}$ at $\rho_\sigma$.
  We bridge $b_L$ to $\ensuremath{\llbracket s \rrbracket((\rho_\sigma, b_t/x, c_t/y))}$ (the inner-LHS of
  the four-value pattern) via the four-value pattern of $s \approx s$
  (reflexive) at $\Gamma', x:\ensuremath{\texttt{Nat}}, y:T[q(\sigma)]$, doubly-lifted substitution
  $q^2(\sigma) \approx q^2(\sigma)$, and reflexive env-pair
  $(\rho, b_t/x, c_t/y) \approx (\rho, b_t/x, c_t/y)$:
  \begin{align*}
    &\ensuremath{\llbracket s[q^2(\sigma)] \rrbracket((\rho, b_t/x, c_t/y))}
      \approx \ensuremath{\llbracket s \rrbracket(\ensuremath{\llbracket q^2(\sigma) \rrbracket((\rho, b_t/x, c_t/y))})} \in R_O
      && \text{(four-value pattern of $s$)} \\
    &\ensuremath{\llbracket q^2(\sigma) \rrbracket((\rho, b_t/x, c_t/y))}
      \approx (\rho_\sigma, b_t/x, c_t/y) \in R_{\Gamma, x:\ensuremath{\texttt{Nat}}, y:T}
      && \text{(by \textsc{Ctx-Ext} twice and the four-value} \\
    & && \text{pattern of $\sigma$ at $\Uparrow$ for the tail)} \\
    &\ensuremath{\llbracket s \rrbracket(\ensuremath{\llbracket q^2(\sigma) \rrbracket((\rho, b_t/x, c_t/y))})}
      \approx \ensuremath{\llbracket s \rrbracket((\rho_\sigma, b_t/x, c_t/y))} \in R_O
      && \text{(\Cref{lem:sem-ty-id} on $s$)}
  \end{align*}
  Hence by transitivity, $b_L \approx \ensuremath{\llbracket s \rrbracket((\rho_\sigma, b_t/x, c_t/y))}
   \in R_O$.

  For $b_I = \ensuremath{\llbracket s \rrbracket((\rho_\sigma, a/x, c/y))}$: bridge to
  $\ensuremath{\llbracket s \rrbracket((\rho_\sigma, b_t/x, c_t/y))}$ via \Cref{lem:sem-ty-id} on $s$ at
  the env-pair related by:
  \begin{align*}
    &b_t \approx a \in \textsf{Nat}
      && \text{(four-value pattern of $t$, outer-LHS vs inner-LHS)} \\
    &c_t \approx c \in R_T\text{-at-}a
      && \text{(four-value pattern of $E$ at $\sigma$, outer-LHS vs inner-LHS;} \\
    & && \text{using $E$ semantic by \Cref{lem:fund-rec})}
  \end{align*}
  giving $\ensuremath{\llbracket s \rrbracket((\rho_\sigma, b_t/x, c_t/y))} \approx \ensuremath{\llbracket s \rrbracket((\rho_\sigma, a/x, c/y))} = b_I
  \in R_O$.
  Hence $b_L \approx b_I$ in $R_O$, and both are PER-related to the four-value
  pattern's inner-LHS.

  Symmetrically for the primed side.
  Combining: all four LHS values ($\{b_L, b_I, b_I', b_L'\}$) are pairwise
  related to the four RHS values (the four-value pattern of $s$ outer/inner)
  in $R_O$, by transitivity through the inner-LHS/inner-RHS bridge.

  \emph{Type part.}
  The type four-value pattern is included in the application of
  $\semtyeq[\Gamma, x:\ensuremath{\texttt{Nat}}, y:T]{s}{s}{T[\Uparrow \circ \Uparrow, \textsf{succ}~x_1/x]}$
  above; by the same syntactic identity used for the term part, the goal's type
  $T[\textsf{succ}~t/x]$ pattern coincides with this type four-value pattern modulo the
  substitution-composition lemmas.

\label{lem:fund-sub-univ}
  If $\ensuremath{\vDash \Gamma}$ and $i \le j$, then
  $\Gamma \vDash \ensuremath{\texttt{Ty}_{i}} \subseteq \ensuremath{\texttt{Ty}_{j}}$.

By \Cref{lem:sem-ctx-per} on $\ensuremath{\vDash \Gamma}$ we obtain
  $\Gamma \approx \Gamma \searrow R_\Gamma$.  
  Let $\Gamma'$ with $\Gamma' \approx \Gamma' \searrow R'$,
  $\semtyeq[\Gamma']{\sigma}{\sigma'}{\Gamma}$, and
  $\ensuremath{\mathcal{D}} :: \rho \approx \rho' \in R'$ be given.  
  We verify the three clauses of $\Gamma \vDash \ensuremath{\texttt{Ty}_{i}} \subseteq \ensuremath{\texttt{Ty}_{j}}$ at
  the level $k := 1 + \max(i, j)$.  

  Since $\ensuremath{\texttt{Ty}_{i}}$ and $\ensuremath{\texttt{Ty}_{j}}$ are closed terms, for any substitution
  $\tau$ and any environment $\rho_0$ we have $\ensuremath{\texttt{Ty}_{i}}[\tau] = \ensuremath{\texttt{Ty}_{i}}$,
  $\ensuremath{\texttt{Ty}_{j}}[\tau] = \ensuremath{\texttt{Ty}_{j}}$, and by evaluation of the universe constructor
  $\ensuremath{\llbracket \ensuremath{\texttt{Ty}_{i}} \rrbracket(\rho_0)} = U_i$, $\ensuremath{\llbracket \ensuremath{\texttt{Ty}_{j}} \rrbracket(\rho_0)} = U_j$.  

  \emph{Part (1).}
  \begin{align*}
    &\ensuremath{\llbracket \ensuremath{\texttt{Ty}_{i}}[\sigma] \rrbracket(\rho)} = U_i
      && \text{(closed term + evaluation of $\ensuremath{\texttt{Ty}_{i}}$)} \\
    &\ensuremath{\llbracket \ensuremath{\texttt{Ty}_{i}} \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})} = U_i
      && \text{(evaluation of $\ensuremath{\texttt{Ty}_{i}}$)} \\
    &U_i \approx U_i \in \mathcal{U}_k \searrow (\mathcal{U}_i)
      && \text{(by \textsc{U-Univ}, since $i < k$)} \\
    &\ensuremath{\llbracket \ensuremath{\texttt{Ty}_{i}}[\sigma] \rrbracket(\rho)} \approx \ensuremath{\llbracket \ensuremath{\texttt{Ty}_{i}} \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})}
      \in \mathcal{U}_k
      && \text{(reflexivity of the previous line)}
  \end{align*}

  \emph{Part (2).} Symmetrically:
  \begin{align*}
    &\ensuremath{\llbracket \ensuremath{\texttt{Ty}_{j}}[\sigma'] \rrbracket(\rho')} = U_j = \ensuremath{\llbracket \ensuremath{\texttt{Ty}_{j}} \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})}
      && \text{(closed term + evaluation of $\ensuremath{\texttt{Ty}_{j}}$)} \\
    &U_j \approx U_j \in \mathcal{U}_k \searrow (\mathcal{U}_j)
      && \text{(by \textsc{U-Univ}, since $j < k$)} \\
    &\ensuremath{\llbracket \ensuremath{\texttt{Ty}_{j}}[\sigma'] \rrbracket(\rho')} \approx \ensuremath{\llbracket \ensuremath{\texttt{Ty}_{j}} \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})}
      \in \mathcal{U}_k
      && \text{(reflexivity)}
  \end{align*}

  \emph{Part (3).}
  By \textsc{$<$:-Univ} with $i \le j$ and $j < k$:
  \begin{align*}
    &\ensuremath{\llbracket \ensuremath{\texttt{Ty}_{i}} \rrbracket(\ensuremath{\llbracket \sigma \rrbracket(\rho)})} = U_i \mathrel{<:_k} U_j
      = \ensuremath{\llbracket \ensuremath{\texttt{Ty}_{j}} \rrbracket(\ensuremath{\llbracket \sigma' \rrbracket(\rho')})}
      && \text{(by \textsc{$<$:-Univ})}
  \end{align*}

Let $\Gamma'$ with $\Gamma' \approx \Gamma' \searrow R'$,
  $\semtyeq[\Gamma']{\sigma}{\sigma'}{\Gamma}$, and
  $\ensuremath{\mathcal{D}} :: \rho \approx \rho' \in R'$ be given.  
  Write $\rho_\sigma := \ensuremath{\llbracket \sigma \rrbracket(\rho)}$ and
  $\rho_{\sigma'} := \ensuremath{\llbracket \sigma' \rrbracket(\rho')}$.  

  We must verify the three clauses of
  $\Gamma \vDash \Pi(x:S_1).\,T_1 \subseteq \Pi(x:S_2).\,T_2$.  
  Computing the four type values via substitution and evaluation of
  $\Pi$:
  \begin{align*}
    &\ensuremath{\llbracket (\Pi(x:S_1).\,T_1)[\sigma] \rrbracket(\rho)}
      = \Pi(\ensuremath{\llbracket S_1[\sigma] \rrbracket(\rho)},\; T_1[q(\sigma)],\; \rho)
      && \text{(by definition of substitution and evaluation on $\Pi$)} \\
    &\ensuremath{\llbracket \Pi(x:S_1).\,T_1 \rrbracket(\rho_\sigma)}
      = \Pi(\ensuremath{\llbracket S_1 \rrbracket(\rho_\sigma)},\; T_1,\; \rho_\sigma)
      && \text{(by evaluation on $\Pi$)} \\
    &\ensuremath{\llbracket \Pi(x:S_2).\,T_2 \rrbracket(\rho_{\sigma'})}
      = \Pi(\ensuremath{\llbracket S_2 \rrbracket(\rho_{\sigma'})},\; T_2,\; \rho_{\sigma'})
      && \text{(by evaluation on $\Pi$)} \\
    &\ensuremath{\llbracket (\Pi(x:S_2).\,T_2)[\sigma'] \rrbracket(\rho')}
      = \Pi(\ensuremath{\llbracket S_2[\sigma'] \rrbracket(\rho')},\; T_2[q(\sigma')],\; \rho')
      && \text{(by definition of substitution and evaluation on $\Pi$)}
  \end{align*}

  \emph{Part (1).}  
  By \Cref{lem:fund-pi-wf} applied to $\semtyeq[\Gamma]{S_1}{S_1}{\ensuremath{\texttt{Ty}_{i}}}$
  and $\semtyeq[\Gamma, x:S_1]{T_1}{T_1}{\ensuremath{\texttt{Ty}_{i}}}$, we obtain
  $\semtyeq[\Gamma]{\Pi(x:S_1).\,T_1}{\Pi(x:S_1).\,T_1}{\ensuremath{\texttt{Ty}_{i}}}$.  
  Instantiating its type-side four-value relation at
  $\semtyeq[\Gamma']{\sigma}{\sigma'}{\Gamma}$ and $\ensuremath{\mathcal{D}}$, the
  outer-LHS-vs-inner-LHS leg yields:
  \begin{align*}
    &\Pi(\ensuremath{\llbracket S_1[\sigma] \rrbracket(\rho)},\, T_1[q(\sigma)],\, \rho)
      \approx \Pi(\ensuremath{\llbracket S_1 \rrbracket(\rho_\sigma)},\, T_1,\, \rho_\sigma)
      \in \mathcal{U}_i
      && \text{(part (1))}
  \end{align*}

  \emph{Part (2).}  
  Symmetrically, by \Cref{lem:fund-pi-wf} on $S_2$ and $T_2$ and the
  outer-RHS-vs-inner-RHS leg of its type-side four-value relation at the
  same data:
  \begin{align*}
    &\Pi(\ensuremath{\llbracket S_2 \rrbracket(\rho_{\sigma'})},\, T_2,\, \rho_{\sigma'})
      \approx \Pi(\ensuremath{\llbracket S_2[\sigma'] \rrbracket(\rho')},\, T_2[q(\sigma')],\, \rho')
      \in \mathcal{U}_i
      && \text{(part (2), via symmetry of $\mathcal{U}_i$)}
  \end{align*}

  \emph{Part (3).}  
  We must show
  $\Pi(\ensuremath{\llbracket S_1 \rrbracket(\rho_\sigma)}, T_1, \rho_\sigma) \mathrel{<:_i}
   \Pi(\ensuremath{\llbracket S_2 \rrbracket(\rho_{\sigma'})}, T_2, \rho_{\sigma'})$.  
  We apply \textsc{$<$:-Pi}, which requires:
  \begin{enumerate}
  \@idxitem[(a)] $\ensuremath{\llbracket S_1 \rrbracket(\rho_\sigma)} \approx \ensuremath{\llbracket S_2 \rrbracket(\rho_{\sigma'})}
    \in \mathcal{U}_i \searrow R_I$ for some $R_I$;
  \@idxitem[(b)] for every $\ensuremath{\mathcal{D}}_I :: a \approx a' \in R_I$,
    $\ensuremath{\llbracket T_1 \rrbracket(\rho_\sigma, a/x)} \mathrel{<:_i}
     \ensuremath{\llbracket T_2 \rrbracket(\rho_{\sigma'}, a'/x)}$;
  \@idxitem[(c)] $\Pi(\ensuremath{\llbracket S_1 \rrbracket(\rho_\sigma)}, T_1, \rho_\sigma)
    \approx \Pi(\ensuremath{\llbracket S_1 \rrbracket(\rho_\sigma)}, T_1, \rho_\sigma) \in \mathcal{U}_i$ and
    $\Pi(\ensuremath{\llbracket S_2 \rrbracket(\rho_{\sigma'})}, T_2, \rho_{\sigma'})
    \approx \Pi(\ensuremath{\llbracket S_2 \rrbracket(\rho_{\sigma'})}, T_2, \rho_{\sigma'}) \in \mathcal{U}_i$.
  \end{enumerate}

  \emph{(a) Domain.}  
  Instantiate the type-side four-value relation of
  $\semtyeq[\Gamma]{S_1}{S_2}{\ensuremath{\texttt{Ty}_{i}}}$ at
  $\semtyeq[\Gamma']{\sigma}{\sigma'}{\Gamma}$ and $\ensuremath{\mathcal{D}}$:
  \begin{align*}
    &\{\ensuremath{\llbracket S_1[\sigma] \rrbracket(\rho)},\;
      \ensuremath{\llbracket S_1 \rrbracket(\rho_\sigma)},\;
      \ensuremath{\llbracket S_2 \rrbracket(\rho_{\sigma'})},\;
      \ensuremath{\llbracket S_2[\sigma'] \rrbracket(\rho')}\}
      \subseteq \mathcal{U}_i \searrow R_I
      && \text{(by hypothesis on $S_1, S_2$)}
  \end{align*}
  The inner-LHS-vs-inner-RHS pair gives
  $\ensuremath{\llbracket S_1 \rrbracket(\rho_\sigma)} \approx \ensuremath{\llbracket S_2 \rrbracket(\rho_{\sigma'})} \in \mathcal{U}_i \searrow R_I$.  

  \emph{(b) Codomain.}  
  By \Cref{lem:sem-wk-q} on $\semtyeq[\Gamma']{\sigma}{\sigma'}{\Gamma}$ and
  $\semtyeq[\Gamma]{S_1}{S_1}{\ensuremath{\texttt{Ty}_{i}}}$:
  \[
    \semtyeq[\Gamma', x:S_1[\sigma]]{q(\sigma)}{q(\sigma')}{\Gamma, x:S_1}.
  \]
  By the first premise of the semantic substitution judgment, this carries
  $(\Gamma', x:S_1[\sigma]) \approx (\Gamma', x:S_1[\sigma]) \searrow R'_{x:S_1[\sigma]}$
  and $(\Gamma, x:S_1) \approx (\Gamma, x:S_1) \searrow R_{\Gamma,x:S_1}$.  

  Let $\ensuremath{\mathcal{D}}_I :: a \approx a' \in R_I$ be given.  
  By the biconditional of $R'_{x:S_1[\sigma]}$ from \textsc{Ctx-Ext},
  $(\rho, a/x) \approx (\rho', a'/x) \in R'_{x:S_1[\sigma]}$ requires
  $\rho \approx \rho' \in R'$ (which we have via $\ensuremath{\mathcal{D}}$) and
  $a \approx a' \in R_H'(\ensuremath{\mathcal{D}})$ where $R_H'$ is the head family for
  $R'_{x:S_1[\sigma]}$, governed by
  $\ensuremath{\llbracket S_1[\sigma] \rrbracket(\rho)} \approx \ensuremath{\llbracket S_1[\sigma] \rrbracket(\rho')}
   \in \mathcal{U}_i \searrow R_H'(\ensuremath{\mathcal{D}})$.  
  By \Cref{lem:univ-functional} on the same left type
  $\ensuremath{\llbracket S_1[\sigma] \rrbracket(\rho)}$ that governs both $R_I$
  (from \emph{(a)}) and $R_H'(\ensuremath{\mathcal{D}})$, $R_I \Leftrightarrow R_H'(\ensuremath{\mathcal{D}})$.  
  Hence $a \approx a' \in R_H'(\ensuremath{\mathcal{D}})$, and
  $(\rho, a/x) \approx (\rho', a'/x) \in R'_{x:S_1[\sigma]}$.  

  Apply $\Gamma, x:S_1 \vDash T_1 \subseteq T_2$ at $\Gamma', x:S_1[\sigma]$
  (with $R'_{x:S_1[\sigma]}$), the lifted substitution
  $\semtyeq[\Gamma', x:S_1[\sigma]]{q(\sigma)}{q(\sigma')}{\Gamma, x:S_1}$,
  and $(\rho, a/x) \approx (\rho', a'/x) \in R'_{x:S_1[\sigma]}$:
  \begin{align*}
    &\ensuremath{\llbracket T_1[q(\sigma)] \rrbracket(\rho, a/x)} \approx
      \ensuremath{\llbracket T_1 \rrbracket(\ensuremath{\llbracket q(\sigma) \rrbracket(\rho, a/x)})} \in \mathcal{U}_i
      && \text{(part (1) of $T_1 \subseteq T_2$)} \\
    &\ensuremath{\llbracket T_2[q(\sigma')] \rrbracket(\rho', a'/x)} \approx
      \ensuremath{\llbracket T_2 \rrbracket(\ensuremath{\llbracket q(\sigma') \rrbracket(\rho', a'/x)})} \in \mathcal{U}_i
      && \text{(part (2))} \\
    &\ensuremath{\llbracket T_1 \rrbracket(\ensuremath{\llbracket q(\sigma) \rrbracket(\rho, a/x)})} \mathrel{<:_i}
      \ensuremath{\llbracket T_2 \rrbracket(\ensuremath{\llbracket q(\sigma') \rrbracket(\rho', a'/x)})}
      && \text{(part (3))}
  \end{align*}

  We now bridge the inner-evaluations of $q(\sigma)$ and $q(\sigma')$ to the
  desired environments.  
  Using the lifted-substitution four-value pattern (instantiated at the
  identity weakening on $\Gamma', x:S_1[\sigma]$ with
  $(\rho, a/x) \approx (\rho', a'/x)$):
  \begin{align*}
    &\ensuremath{\llbracket q(\sigma) \rrbracket(\rho, a/x)} \approx (\rho_\sigma, a/x)
      \in R_{\Gamma, x:S_1}
      && \text{(outer-LHS vs inner-LHS in the four-value pattern)} \\
    &\ensuremath{\llbracket q(\sigma') \rrbracket(\rho', a'/x)} \approx (\rho_{\sigma'}, a'/x)
      \in R_{\Gamma, x:S_1}
      && \text{(outer-RHS vs inner-RHS, symmetrically)}
  \end{align*}
  By \Cref{lem:sem-ty-id} on $\semtyeq[\Gamma, x:S_1]{T_1}{T_1}{\ensuremath{\texttt{Ty}_{i}}}$
  applied to the first relation, and on
  $\semtyeq[\Gamma, x:S_2]{T_2}{T_2}{\ensuremath{\texttt{Ty}_{i}}}$ applied (after substituting
  $S_1$ for $S_2$ via the well-formedness premises) to the second:
  \begin{align*}
    &\ensuremath{\llbracket T_1 \rrbracket(\ensuremath{\llbracket q(\sigma) \rrbracket(\rho, a/x)})}
      \approx \ensuremath{\llbracket T_1 \rrbracket(\rho_\sigma, a/x)} \in \mathcal{U}_i
      && \text{(by \Cref{lem:sem-ty-id} on $T_1$)} \\
    &\ensuremath{\llbracket T_2 \rrbracket(\ensuremath{\llbracket q(\sigma') \rrbracket(\rho', a'/x)})}
      \approx \ensuremath{\llbracket T_2 \rrbracket(\rho_{\sigma'}, a'/x)} \in \mathcal{U}_i
      && \text{(by \Cref{lem:sem-ty-id} on $T_2$)}
  \end{align*}
  By \Cref{lem:subty-respects} applied to the codomain subtyping above and
  these two $\mathcal{U}_i$-equivalences:
  \begin{align*}
    &\ensuremath{\llbracket T_1 \rrbracket(\rho_\sigma, a/x)}
      \mathrel{<:_i} \ensuremath{\llbracket T_2 \rrbracket(\rho_{\sigma'}, a'/x)}
      && \text{(by \Cref{lem:subty-respects})}
  \end{align*}

  \emph{(c) Self-relatedness.}  
  By \Cref{lem:fund-pi-wf} on $\semtyeq[\Gamma]{S_1}{S_1}{\ensuremath{\texttt{Ty}_{i}}}$ and
  $\semtyeq[\Gamma, x:S_1]{T_1}{T_1}{\ensuremath{\texttt{Ty}_{i}}}$ instantiated at the same data,
  the inner-LHS-vs-inner-LHS leg of the resulting type-side four-value
  relation gives
  $\Pi(\ensuremath{\llbracket S_1 \rrbracket(\rho_\sigma)}, T_1, \rho_\sigma) \approx
   \Pi(\ensuremath{\llbracket S_1 \rrbracket(\rho_\sigma)}, T_1, \rho_\sigma) \in \mathcal{U}_i$.  
  Symmetrically for $S_2, T_2$:
  $\Pi(\ensuremath{\llbracket S_2 \rrbracket(\rho_{\sigma'})}, T_2, \rho_{\sigma'}) \approx
   \Pi(\ensuremath{\llbracket S_2 \rrbracket(\rho_{\sigma'})}, T_2, \rho_{\sigma'}) \in \mathcal{U}_i$.  

  \emph{Conclusion.}  
  By \textsc{$<$:-Pi} with the four ingredients (a)--(c):
  \begin{align*}
    &\Pi(\ensuremath{\llbracket S_1 \rrbracket(\rho_\sigma)}, T_1, \rho_\sigma) \mathrel{<:_i}
      \Pi(\ensuremath{\llbracket S_2 \rrbracket(\rho_{\sigma'})}, T_2, \rho_{\sigma'})
      && \text{(part (3))}
  \end{align*}

\label{lem:fund-sub-trans}
  If $\Gamma \vDash S \subseteq T'$ and $\Gamma \vDash T' \subseteq T$, then
  $\Gamma \vDash S \subseteq T$.

Let $\Gamma'$ with $\Gamma' \approx \Gamma' \searrow R'$,
  $\semtyeq[\Gamma']{\sigma}{\sigma'}{\Gamma}$, and
  $\ensuremath{\mathcal{D}} :: \rho \approx \rho' \in R'$ be given.  
  Write $\rho_\sigma := \ensuremath{\llbracket \sigma \rrbracket(\rho)}$ and
  $\rho_{\sigma'} := \ensuremath{\llbracket \sigma' \rrbracket(\rho')}$.  
  We must establish each clause of $\Gamma \vDash S \subseteq T$.  

  \emph{Part (1).}  
  Instantiate the first hypothesis $\Gamma \vDash S \subseteq T'$ at this
  data; its clause (1) gives the goal:
  \begin{align*}
    &\ensuremath{\llbracket S[\sigma] \rrbracket(\rho)} \approx \ensuremath{\llbracket S \rrbracket(\rho_\sigma)} \in \mathcal{U}_i
      && \text{(by clause (1) of $\Gamma \vDash S \subseteq T'$)}
  \end{align*}

  \emph{Part (2).}  
  Instantiate the second hypothesis $\Gamma \vDash T' \subseteq T$ at the
  same data; its clause (2) gives the goal:
  \begin{align*}
    &\ensuremath{\llbracket T[\sigma'] \rrbracket(\rho')} \approx \ensuremath{\llbracket T \rrbracket(\rho_{\sigma'})} \in \mathcal{U}_i
      && \text{(by clause (2) of $\Gamma \vDash T' \subseteq T$)}
  \end{align*}

  \emph{Part (3).}  
  From the two hypotheses at the same data:
  \begin{align*}
    &\ensuremath{\llbracket S \rrbracket(\rho_\sigma)} \mathrel{<:_i} \ensuremath{\llbracket T' \rrbracket(\rho_{\sigma'})}
      && \text{(by clause (3) of $\Gamma \vDash S \subseteq T'$)} \\
    &\ensuremath{\llbracket T' \rrbracket(\rho_{\sigma'})} \mathrel{<:_i} \ensuremath{\llbracket T \rrbracket(\rho_{\sigma'})}
      && \text{(by clause (3) of $\Gamma \vDash T' \subseteq T$)} \\
    &\ensuremath{\llbracket S \rrbracket(\rho_\sigma)} \mathrel{<:_i} \ensuremath{\llbracket T \rrbracket(\rho_{\sigma'})}
      && \text{(by transitivity of $<:_i$, \Cref{lem:subty-trans})}
  \end{align*}
  All three clauses of $\Gamma \vDash S \subseteq T$ are now
  established.

\label{lem:fund-sub-eq}
  If $\semtyeq[\Gamma]{T}{T}{\ensuremath{\texttt{Ty}_{i}}}$ and $\semtyeq[\Gamma]{S}{T}{\ensuremath{\texttt{Ty}_{i}}}$,
  then $\Gamma \vDash S \subseteq T$.

Let $\Gamma'$ with $\Gamma' \approx \Gamma' \searrow R'$,
  $\semtyeq[\Gamma']{\sigma}{\sigma'}{\Gamma}$, and
  $\ensuremath{\mathcal{D}} :: \rho \approx \rho' \in R'$ be given.  
  Write $\rho_\sigma := \ensuremath{\llbracket \sigma \rrbracket(\rho)}$ and
  $\rho_{\sigma'} := \ensuremath{\llbracket \sigma' \rrbracket(\rho')}$.  
  We establish each clause of $\Gamma \vDash S \subseteq T$.  

  \emph{Part (1).}  
  Instantiate the type-side four-value relation of
  $\semtyeq[\Gamma]{S}{T}{\ensuremath{\texttt{Ty}_{i}}}$ at
  $\semtyeq[\Gamma']{\sigma}{\sigma'}{\Gamma}$ and $\ensuremath{\mathcal{D}}$:
  \begin{align*}
    &\{\ensuremath{\llbracket S[\sigma] \rrbracket(\rho)},\;
      \ensuremath{\llbracket S \rrbracket(\rho_\sigma)},\;
      \ensuremath{\llbracket T \rrbracket(\rho_{\sigma'})},\;
      \ensuremath{\llbracket T[\sigma'] \rrbracket(\rho')}\}
      \subseteq \mathcal{U}_i \searrow R_T
      && \text{(by hypothesis on $S, T$)}
  \end{align*}
  The outer-LHS-vs-inner-LHS leg gives
  $\ensuremath{\llbracket S[\sigma] \rrbracket(\rho)} \approx \ensuremath{\llbracket S \rrbracket(\rho_\sigma)} \in \mathcal{U}_i$, which is
  clause (1).  

  \emph{Part (2).}  
  Instantiate the type-side four-value relation of
  $\semtyeq[\Gamma]{T}{T}{\ensuremath{\texttt{Ty}_{i}}}$ at the same data:
  \begin{align*}
    &\{\ensuremath{\llbracket T[\sigma] \rrbracket(\rho)},\;
      \ensuremath{\llbracket T \rrbracket(\rho_\sigma)},\;
      \ensuremath{\llbracket T \rrbracket(\rho_{\sigma'})},\;
      \ensuremath{\llbracket T[\sigma'] \rrbracket(\rho')}\}
      \subseteq \mathcal{U}_i \searrow R_T'
      && \text{(by hypothesis on $T, T$)}
  \end{align*}
  The outer-RHS-vs-inner-RHS leg gives
  $\ensuremath{\llbracket T[\sigma'] \rrbracket(\rho')} \approx \ensuremath{\llbracket T \rrbracket(\rho_{\sigma'})} \in \mathcal{U}_i$,
  which is clause (2).  

  \emph{Part (3).}  
  From the four-value relation in part (1), the inner-LHS-vs-inner-RHS leg
  gives:
  \begin{align*}
    &\ensuremath{\llbracket S \rrbracket(\rho_\sigma)} \approx \ensuremath{\llbracket T \rrbracket(\rho_{\sigma'})}
      \in \mathcal{U}_i \searrow R_T
      && \text{(inner-LHS vs inner-RHS in the four-value pattern)}
  \end{align*}
  By \Cref{lem:univ-implies-subty}:
  \begin{align*}
    &\ensuremath{\llbracket S \rrbracket(\rho_\sigma)} \mathrel{<:_i} \ensuremath{\llbracket T \rrbracket(\rho_{\sigma'})}
      && \text{(by \Cref{lem:univ-implies-subty})}
  \end{align*}
  This is clause (3).

\label{thm:fundamental}
  The following statements hold:
  \begin{enumerate}
  \@idxitem If $\vdash \Gamma$, then $\vDash \Gamma$.
  \@idxitem If $\typing[\Gamma]{t}{T}$, then $\semtyeq[\Gamma]{t}{t}{T}$.
  \@idxitem If $\tyequiv[\Gamma]{t}{t'}{T}$, then $\semtyeq[\Gamma]{t}{t'}{T}$.
  \@idxitem If $\subty[\Gamma]{S}{T}$, then $\Gamma \vDash S \subseteq T$.
  \end{enumerate}

\label{thm:completeness}
  If $\tyequiv[\Gamma]{s}{t}{T}$, then $\textsf{nbe}_\Gamma^T(s) = \textsf{nbe}_\Gamma^T(t)$.
  That is, judgmentally equal terms have the same normal form.

\label{def:kripke-wk}
  The judgment $\kweak[\Gamma]{\phi}{\Delta}$ states that $\phi$ is a
  \emph{Kripke weakening} from $\Delta$ to $\Gamma$ (i.e.\ $\phi$ extends $\Delta$
  to $\Gamma$ by appending entries on the left).
  It is defined inductively:
  \begin{mathpar}
    \inferrule[\textsc{KW-Id}]
    {\vdash \Gamma}
    {\kweak[\Gamma]{\ensuremath{\textsf{id}}}{\Gamma}}

    \inferrule[\textsc{KW-Shift}]
    {\kweak[\Gamma]{\phi}{\Delta} \\
     \typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}}}
    {\kweak[\Gamma, x:S]{\phi \circ \Uparrow}{\Delta}}
  \end{mathpar}
  Equivalently, every Kripke weakening is a finite composition
  $\Uparrow \circ \cdots \circ \Uparrow$ of $\Uparrow$'s (with $\ensuremath{\textsf{id}}$ as the empty
  composition); no $q(\phi)$ lifting is permitted.

By induction on $\kweak[\Gamma]{\phi}{\Delta}$.
  \begin{align*}
    &\textsc{KW-Id}: \weakening[\Gamma]{\ensuremath{\textsf{id}}}{\Gamma}
      && \text{(by \Cref{lem:wk-id-wt})} \\
    &\textsc{KW-Shift}: \weakening[\Gamma]{\phi}{\Delta} \text{ (IH)}
      && \\
    &\quad \weakening[\Gamma, x:S]{\Uparrow}{\Gamma}
      && \text{(by \Cref{lem:wk-shift-wt})} \\
    &\quad \weakening[\Gamma, x:S]{\phi \circ \Uparrow}{\Delta}
      && \text{(by \Cref{lem:wk-comp-wt})}
  \end{align*}

\label{lem:kweak-comp}
  If $\kweak[\Gamma]{\psi}{\Delta}$ and $\kweak[\Delta']{\phi}{\Gamma}$, then
  $\kweak[\Delta']{\psi \circ \phi}{\Delta}$.

By induction on $\kweak[\Delta']{\phi}{\Gamma}$.
  \begin{align*}
    &\textsc{KW-Id} \text{ (}\phi = \ensuremath{\textsf{id}}\text{): } \psi \circ \ensuremath{\textsf{id}} = \psi
      && \text{(by left-id of $\circ$)} \\
    &\quad \kweak[\Delta']{\psi}{\Delta}
      && \text{(by hypothesis)} \\[2pt]
    &\textsc{KW-Shift} \text{ (}\phi = \phi_0 \circ \Uparrow\text{, } \Delta' = \Delta_0, x:S\text{)}: \\
    &\quad \kweak[\Delta_0]{\psi \circ \phi_0}{\Delta}
      && \text{(by IH on $\phi_0$)} \\
    &\quad \kweak[\Delta_0, x:S]{(\psi \circ \phi_0) \circ \Uparrow}{\Delta}
      && \text{(by \textsc{KW-Shift})} \\
    &\quad \psi \circ (\phi_0 \circ \Uparrow) = (\psi \circ \phi_0) \circ \Uparrow
      && \text{(by associativity of $\circ$)} \\
    &\quad \kweak[\Delta']{\psi \circ \phi}{\Delta}
      && \text{(by the above)}
  \end{align*}

\label{def:gluing-univ}
  The relation $a \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El}$ is defined inductively by:
  \begin{mathpar}
    \inferrule[\textsc{G-Ne}]
    {{\uparrow}^A(e) \in \ensuremath{\mathrm{D}} \\
     P \Leftrightarrow \textsf{Neu}_i^e \\
     \textbf{El} \Leftrightarrow \textsf{Neu}_i^e}
    {{\uparrow}^A(e) \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El}}

    \inferrule[\textsc{G-Nat}]
    {P \Leftrightarrow \textsf{Nat}_i \\
     \textbf{El} \Leftrightarrow \textsf{Nat}_i}
    {N \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El}}

    \inferrule[\textsc{G-Univ}]
    {j < i \\
     P \Leftrightarrow \textsf{Univ}_{i,j} \\
     \textbf{El} \Leftrightarrow \textsf{Univ}_{i,j}^{\textbf{El}}}
    {U_j \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El}}

    \inferrule[\textsc{G-Pi}]
    {a \in \mathcal{U}_i^\ast \searrow P_I \searrow \textbf{El}_I \\
     a \approx a \in \mathcal{U}_i \searrow R_I \\\\
     \forall\, \ensuremath{\mathcal{D}} :: b \approx b \in R_I,\; c.\;
       \ensuremath{\llbracket T \rrbracket(\rho, b/x)} \searrow c \implies
       c \in \mathcal{U}_i^\ast \searrow P_O(\ensuremath{\mathcal{D}}) \searrow \textbf{El}_O(\ensuremath{\mathcal{D}}) \\\\
     \Pi(a, T, \rho) \approx \Pi(a, T, \rho) \in \mathcal{U}_i \searrow R \\\\
     P \Leftrightarrow \Pi_i(R_I, P_I, \textbf{El}_I, P_O) \\
     \textbf{El} \Leftrightarrow \Pi_i^{\textbf{El}}(R, R_I, P_I, \textbf{El}_I, \textbf{El}_O)}
    {\Pi(a, T, \rho) \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El}}
  \end{mathpar}

\label{def:neu-type-pred}
  The judgment $\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; \textsf{Neu}_i^e$
  holds when:
  \begin{enumerate}
  \@idxitem $\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}}$, and
  \@idxitem for all $\Delta, \phi$ with $\kweak[\Delta]{\phi}{\Gamma}$, there exists $u$
    with $\textsf{R}^{\textsf{Ne}}_{|\Delta|}(e) \searrow u$ and $\tyequiv[\Delta]{S[\phi]}{u}{\ensuremath{\texttt{Ty}_{i}}}$.
  \end{enumerate}

\label{def:neu-term-pred}
  The judgment $\typing[\Gamma]{t}{S} \;\circledR\; {\uparrow}^A(w) \in \textsf{Neu}_i^e$
  holds when:
  \begin{enumerate}
  \@idxitem $\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; \textsf{Neu}_i^e$,
  \@idxitem $\typing[\Gamma]{t}{S}$,
  \@idxitem $w \approx w \in \textsf{Ne}$, and
  \@idxitem for all $\Delta, \phi$ with $\kweak[\Delta]{\phi}{\Gamma}$, there exists $u$
    with $\textsf{R}^{\textsf{Ne}}_{|\Delta|}(w) \searrow u$ and $\tyequiv[\Delta]{t[\phi]}{u}{S[\phi]}$.
  \end{enumerate}

\label{def:nat-type-pred}
  $\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; \textsf{Nat}_i$ holds when
  $\tyequiv[\Gamma]{S}{\ensuremath{\texttt{Nat}}}{\ensuremath{\texttt{Ty}_{i}}}$.

\label{def:nat-term-pred}
  The judgment $\typing[\Gamma]{t}{S} \;\circledR\; b \in \textsf{Nat}_i$ holds
  when $\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; \textsf{Nat}_i$ and
  $\typing[\Gamma]{t}{S} \;\circledR\; b \in \textsf{Nat}$, where the latter is
  defined by:
  \begin{mathpar}
    \inferrule[\textsc{GN-Ze}]
    {\tyequiv[\Gamma]{t}{\textsf{zero}}{S}}
    {\typing[\Gamma]{t}{S} \;\circledR\; \texttt{ze} \in \textsf{Nat}}

    \inferrule[\textsc{GN-Su}]
    {\typing[\Gamma]{t'}{S} \;\circledR\; b' \in \textsf{Nat} \\
     \tyequiv[\Gamma]{t}{\textsf{succ}~t'}{S}}
    {\typing[\Gamma]{t}{S} \;\circledR\; \texttt{su}(b') \in \textsf{Nat}}

    \inferrule[\textsc{GN-Ne}]
    {\typing[\Gamma]{t}{S} \;\circledR\; {\uparrow}^N(w) \in \textsf{Neu}_i^e}
    {\typing[\Gamma]{t}{S} \;\circledR\; {\uparrow}^N(w) \in \textsf{Nat}}
  \end{mathpar}

\label{def:univ-type-pred}
  $\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; \textsf{Univ}_{i,j}$ holds when
  $\tyequiv[\Gamma]{S}{\ensuremath{\texttt{Ty}_{j}}}{\ensuremath{\texttt{Ty}_{i}}}$.

\label{def:univ-term-pred}
  $\typing[\Gamma]{t}{S} \;\circledR\; b \in \textsf{Univ}_{i,j}^{\textbf{El}}$ holds when:
  \begin{enumerate}
  \@idxitem $\typing[\Gamma]{t}{S}$,
  \@idxitem $\tyequiv[\Gamma]{S}{\ensuremath{\texttt{Ty}_{j}}}{\ensuremath{\texttt{Ty}_{i}}}$, and
  \@idxitem there exist $P_b, \textbf{El}_b$ with $b \in \mathcal{U}_j^\ast \searrow P_b \searrow \textbf{El}_b$
    and $\typing[\Gamma]{t}{\ensuremath{\texttt{Ty}_{j}}} \;\circledR\; P_b$ (the term $t$, viewed as a
    type at $\ensuremath{\texttt{Ty}_{j}}$ via Russell, glues to $P_b$).
  \end{enumerate}

\label{def:nf-pred}
  $\typing[\Gamma]{t}{S} \;\circledR\; b \in \textsf{Nf}_i^a$ holds when:
  \begin{enumerate}
  \@idxitem $\typing[\Gamma]{t}{S}$,
  \@idxitem ${\downarrow}^a(b) \approx {\downarrow}^a(b) \in \textsf{Nf}$, and
  \@idxitem for all $\Delta, \phi$ with $\kweak[\Delta]{\phi}{\Gamma}$, there exists
    $w$ with $\textsf{R}^{\textsf{Nf}}_{|\Delta|}({\downarrow}^a(b)) \searrow w$ and
    $\tyequiv[\Delta]{t[\phi]}{w}{S[\phi]}$.
  \end{enumerate}

\label{def:ne-pred}
  $\typing[\Gamma]{t}{S} \;\circledR\; w \in \textsf{Ne}_i^a$ holds when:
  \begin{enumerate}
  \@idxitem $\typing[\Gamma]{t}{S}$,
  \@idxitem $w \approx w \in \textsf{Ne}$, and
  \@idxitem for all $\Delta, \phi$ with $\kweak[\Delta]{\phi}{\Gamma}$, there exists
    $u$ with $\textsf{R}^{\textsf{Ne}}_{|\Delta|}(w) \searrow u$ and
    $\tyequiv[\Delta]{t[\phi]}{u}{S[\phi]}$.
  \end{enumerate}

\label{def:ctx-gluing}
  Given a well-formed context $\Gamma$, the judgment $\Gamma \searrow \textsf{Sb}$
  defines a predicate $\textsf{Sb}$ on substitution--environment pairs
  $\judge[\Delta]{\sigma : \Gamma} \;\circledR\; \rho \in \textsf{Sb}$,
  inductively on $\Gamma$:
  \begin{mathpar}
    \inferrule[\textsc{G-Ctx-$\cdot$}]
    {\textsf{Sb} \Leftrightarrow (\judge[\Delta]{\sigma : \cdot})}
    {\cdot \searrow \textsf{Sb}}

    \inferrule[\textsc{G-Ctx-Ext}]
    {\Gamma \searrow \textsf{Sb}_T \\
     \typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}} \\\\
     \forall \Delta', \sigma_T, \rho_T.\;
       \judge[\Delta']{\sigma_T : \Gamma} \;\circledR\; \rho_T \in \textsf{Sb}_T
       \implies \\
     \quad \exists a, P, \textbf{El}.\;
       \ensuremath{\llbracket S \rrbracket(\rho_T)} \searrow a \;\wedge\;
       a \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El} \;\wedge\;
       \typing[\Delta']{S[\sigma_T]}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; P \\\\
     \textsf{Sb} \Leftrightarrow \textsf{Cons}_i(\Gamma, S, \textsf{Sb}_T)}
    {(\Gamma, x : S) \searrow \textsf{Sb}}
  \end{mathpar}
  Here $\textsf{Cons}_i(\Gamma, S, \textsf{Sb}_T)$ holds at any
  $\judge[\Delta]{\sigma : \Gamma, x:S} \;\circledR\; \rho$ when there exist
  $i, a, P, \textbf{El}$ with:
  \begin{enumerate}
  \@idxitem \emph{Substitution typing:} $\judge[\Delta]{\sigma : \Gamma, x:S}$,
  \@idxitem \emph{Tail:} $\judge[\Delta]{\Uparrow \circ \sigma : \Gamma}
    \;\circledR\; \rho[\Uparrow] \in \textsf{Sb}_T$,
  \@idxitem \emph{Type:} $\ensuremath{\llbracket S \rrbracket(\rho[\Uparrow])} \searrow a$,
    $a \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El}$, and
    $\typing[\Delta]{S[\Uparrow \circ \sigma]}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; P$, and
  \@idxitem \emph{Head:} $\typing[\Delta]{x_0[\sigma]}{S[\Uparrow \circ \sigma]}
    \;\circledR\; \rho(x_0) \in \textbf{El}$.
  \end{enumerate}
  Here $\Uparrow \circ \sigma$ drops the head, mapping index~$n$ to
  $\sigma(n+1)$; the corresponding drop operation $\rho[\Uparrow]$ on
  environments is from \Cref{sec:sem}.

By induction on the derivation of $\Gamma \searrow \textsf{Sb}$.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{G-Ctx-$\cdot$}]
    {\textsf{Sb} \Leftrightarrow (\judge[\Delta]{\sigma : \cdot})}
    {\cdot \searrow \textsf{Sb}}
  \end{mathpar}
  $\vdash \cdot$ holds by \textsc{Ctx-Emp}.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{G-Ctx-Ext}]
    {\Gamma_0 \searrow \textsf{Sb}_T \\
     \typing[\Gamma_0]{S}{\ensuremath{\texttt{Ty}_{i}}} \\\\
     \forall \Delta', \sigma_T, \rho_T.\;
       \judge[\Delta']{\sigma_T : \Gamma_0} \;\circledR\; \rho_T \in \textsf{Sb}_T
       \implies \\
     \quad \exists a, P, \textbf{El}.\;
       \ensuremath{\llbracket S \rrbracket(\rho_T)} \searrow a \;\wedge\;
       a \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El} \;\wedge\;
       \typing[\Delta']{S[\sigma_T]}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; P \\\\
     \textsf{Sb} \Leftrightarrow \textsf{Cons}_i(\Gamma_0, S, \textsf{Sb}_T)}
    {(\Gamma_0, x : S) \searrow \textsf{Sb}}
  \end{mathpar}
  \begin{align*}
    &\vdash \Gamma_0
      && \text{(by IH on $\Gamma_0 \searrow \textsf{Sb}_T$)} \\
    &\typing[\Gamma_0]{S}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by \textsc{G-Ctx-Ext} premise)} \\
    &\vdash \Gamma_0, x:S
      && \text{(by \textsc{Ctx-Ext})}
  \end{align*}

\label{thm:monotonicity}
  Suppose $a \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El}$ and
  $\kweak[\Delta']{\psi}{\Delta}$.
  \begin{enumerate}
  \@idxitem If $\typing[\Delta]{S}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; P$, then
    $\typing[\Delta']{S[\psi]}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; P$.
  \@idxitem If $\typing[\Delta]{t}{S} \;\circledR\; b \in \textbf{El}$, then
    $\typing[\Delta']{t[\psi]}{S[\psi]} \;\circledR\; b \in \textbf{El}$.
  \end{enumerate}

By induction on the derivation $a \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El}$.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{G-Ne}]
    {{\uparrow}^A(e) \in \ensuremath{\mathrm{D}} \\
     P \Leftrightarrow \textsf{Neu}_i^e \\
     \textbf{El} \Leftrightarrow \textsf{Neu}_i^e}
    {{\uparrow}^A(e) \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El}}
  \end{mathpar}

  \emph{Type predicate (1).}
  Assume $\typing[\Delta]{S}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; \textsf{Neu}_i^e$.
  By \Cref{def:neu-type-pred}:
  \begin{align*}
    &\typing[\Delta]{S}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by \Cref{def:neu-type-pred} clause 1)} \\
    &\forall \Delta'', \kweak[\Delta'']{\phi'}{\Delta}.\;
      \exists u.\; \textsf{R}^{\textsf{Ne}}_{|\Delta''|}(e) \searrow u \wedge
      \tyequiv[\Delta'']{S[\phi']}{u}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by \Cref{def:neu-type-pred} clause 2)}
  \end{align*}
  We must show $\typing[\Delta']{S[\psi]}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; \textsf{Neu}_i^e$.
  \begin{align*}
    &\typing[\Delta']{S[\psi]}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by \Cref{lem:kweak-is-wk} on $\psi$ and \Cref{lem:wk-typing})}
  \end{align*}
  For the Kripke condition: take any $\Delta''$ with $\kweak[\Delta'']{\phi'}{\Delta'}$.
  \begin{align*}
    &\kweak[\Delta'']{\psi \circ \phi'}{\Delta}
      && \text{(by \Cref{lem:kweak-comp} on $\psi$ and $\phi'$)} \\
    &\exists u.\; \textsf{R}^{\textsf{Ne}}_{|\Delta''|}(e) \searrow u \wedge
      \tyequiv[\Delta'']{S[\psi \circ \phi']}{u}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by hypothesis on $S$ at the composed weakening)} \\
    &S[\psi \circ \phi'] = S[\psi][\phi']
      && \text{(by \Cref{sec:syn}'s substitution-composition law)} \\
    &\tyequiv[\Delta'']{S[\psi][\phi']}{u}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(rewriting)}
  \end{align*}
  This establishes the Kripke condition for $S[\psi]$ at $\textsf{Neu}_i^e$.

  \emph{Term predicate (2).}
  Assume $\typing[\Delta]{t}{S} \;\circledR\; {\uparrow}^A(w) \in \textsf{Neu}_i^e$.
  By \Cref{def:neu-term-pred}:
  \begin{align*}
    &\typing[\Delta]{S}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; \textsf{Neu}_i^e,\;
      \typing[\Delta]{t}{S},\;
      w \approx w \in \textsf{Ne}
      && \text{(\Cref{def:neu-term-pred} clauses 1--3)} \\
    &\forall \Delta'', \kweak[\Delta'']{\phi'}{\Delta}.\;
      \exists u.\; \textsf{R}^{\textsf{Ne}}_{|\Delta''|}(w) \searrow u \wedge
      \tyequiv[\Delta'']{t[\phi']}{u}{S[\phi']}
      && \text{(\Cref{def:neu-term-pred} clause 4)}
  \end{align*}
  By type-predicate monotonicity (just proved):
  $\typing[\Delta']{S[\psi]}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; \textsf{Neu}_i^e$.
  $\typing[\Delta']{t[\psi]}{S[\psi]}$ by \Cref{sec:props}.
  $w \approx w \in \textsf{Ne}$ unchanged.
  Kripke condition: for $\kweak[\Delta'']{\phi'}{\Delta'}$, by
  \Cref{lem:kweak-comp} $\kweak[\Delta'']{\psi \circ \phi'}{\Delta}$,
  hypothesis gives $\textsf{R}^{\textsf{Ne}}_{|\Delta''|}(w) \searrow u$ and
  $\tyequiv[\Delta'']{t[\psi \circ \phi']}{u}{S[\psi \circ \phi']}$.
  By substitution composition: $t[\psi \circ \phi'] = t[\psi][\phi']$ and
  $S[\psi \circ \phi'] = S[\psi][\phi']$.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{G-Nat}]
    {P \Leftrightarrow \textsf{Nat}_i \\
     \textbf{El} \Leftrightarrow \textsf{Nat}_i}
    {N \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El}}
  \end{mathpar}

  \emph{Type predicate (1).}
  Assume $\typing[\Delta]{S}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; \textsf{Nat}_i$, i.e.\
  $\tyequiv[\Delta]{S}{\ensuremath{\texttt{Nat}}}{\ensuremath{\texttt{Ty}_{i}}}$.
  \begin{align*}
    &\tyequiv[\Delta']{S[\psi]}{\ensuremath{\texttt{Nat}}[\psi]}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by \Cref{lem:wk-typing})} \\
    &\ensuremath{\texttt{Nat}}[\psi] = \ensuremath{\texttt{Nat}}
      && \text{(syntactic, $\ensuremath{\texttt{Nat}}$ closed)} \\
    &\tyequiv[\Delta']{S[\psi]}{\ensuremath{\texttt{Nat}}}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(rewriting)} \\
    &\typing[\Delta']{S[\psi]}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; \textsf{Nat}_i
      && \text{(by \Cref{def:nat-type-pred})}
  \end{align*}

  \emph{Term predicate (2).}
  Assume $\typing[\Delta]{t}{S} \;\circledR\; b \in \textsf{Nat}_i$.
  By inner induction on the derivation $b \in \textsf{Nat}$.

  \medskip\noindent
  \textbf{Sub-case}
  \begin{mathpar}
    \inferrule[\textsc{GN-Ze}]
    {\tyequiv[\Delta]{t}{\textsf{zero}}{S}}
    {\typing[\Delta]{t}{S} \;\circledR\; \texttt{ze} \in \textsf{Nat}}
  \end{mathpar}
  \begin{align*}
    &\tyequiv[\Delta']{t[\psi]}{\textsf{zero}[\psi]}{S[\psi]}
      && \text{(by \Cref{lem:wk-typing})} \\
    &\textsf{zero}[\psi] = \textsf{zero}
      && \text{(syntactic, $\textsf{zero}$ closed)} \\
    &\tyequiv[\Delta']{t[\psi]}{\textsf{zero}}{S[\psi]}
      && \text{(rewriting)} \\
    &\typing[\Delta']{t[\psi]}{S[\psi]} \;\circledR\; \texttt{ze} \in \textsf{Nat}
      && \text{(by \textsc{GN-Ze})}
  \end{align*}

  \medskip\noindent
  \textbf{Sub-case}
  \begin{mathpar}
    \inferrule[\textsc{GN-Su}]
    {\typing[\Delta]{t'}{S} \;\circledR\; b' \in \textsf{Nat} \\
     \tyequiv[\Delta]{t}{\textsf{succ}~t'}{S}}
    {\typing[\Delta]{t}{S} \;\circledR\; \texttt{su}(b') \in \textsf{Nat}}
  \end{mathpar}
  \begin{align*}
    &\typing[\Delta']{t'[\psi]}{S[\psi]} \;\circledR\; b' \in \textsf{Nat}
      && \text{(by inner IH on $b'$)} \\
    &\tyequiv[\Delta']{t[\psi]}{(\textsf{succ}~t')[\psi]}{S[\psi]}
      && \text{(by \Cref{lem:wk-typing})} \\
    &(\textsf{succ}~t')[\psi] = \textsf{succ}~(t'[\psi])
      && \text{(syntactic substitution on $\textsf{succ}~$)} \\
    &\tyequiv[\Delta']{t[\psi]}{\textsf{succ}~(t'[\psi])}{S[\psi]}
      && \text{(rewriting)} \\
    &\typing[\Delta']{t[\psi]}{S[\psi]} \;\circledR\; \texttt{su}(b') \in \textsf{Nat}
      && \text{(by \textsc{GN-Su} on the IH)}
  \end{align*}

  \medskip\noindent
  \textbf{Sub-case}
  \begin{mathpar}
    \inferrule[\textsc{GN-Ne}]
    {\typing[\Delta]{t}{S} \;\circledR\; {\uparrow}^N(w) \in \textsf{Neu}_i^e}
    {\typing[\Delta]{t}{S} \;\circledR\; {\uparrow}^N(w) \in \textsf{Nat}}
  \end{mathpar}
  \begin{align*}
    &\typing[\Delta']{t[\psi]}{S[\psi]} \;\circledR\; {\uparrow}^N(w) \in \textsf{Neu}_i^e
      && \text{(by the \textsc{G-Ne} case above, applied to $\textsf{Neu}_i^e$)} \\
    &\typing[\Delta']{t[\psi]}{S[\psi]} \;\circledR\; {\uparrow}^N(w) \in \textsf{Nat}
      && \text{(by \textsc{GN-Ne})}
  \end{align*}

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{G-Univ}]
    {j < i \\
     P \Leftrightarrow \textsf{Univ}_{i,j} \\
     \textbf{El} \Leftrightarrow \textsf{Univ}_{i,j}^{\textbf{El}}}
    {U_j \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El}}
  \end{mathpar}

  \emph{Type predicate (1).}
  Assume $\typing[\Delta]{S}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; \textsf{Univ}_{i,j}$, i.e.\
  $\tyequiv[\Delta]{S}{\ensuremath{\texttt{Ty}_{j}}}{\ensuremath{\texttt{Ty}_{i}}}$.
  \begin{align*}
    &\tyequiv[\Delta']{S[\psi]}{\ensuremath{\texttt{Ty}_{j}}[\psi]}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by \Cref{lem:wk-typing})} \\
    &\ensuremath{\texttt{Ty}_{j}}[\psi] = \ensuremath{\texttt{Ty}_{j}}
      && \text{(syntactic; $\ensuremath{\texttt{Ty}_{j}}$ closed)} \\
    &\tyequiv[\Delta']{S[\psi]}{\ensuremath{\texttt{Ty}_{j}}}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(rewriting)} \\
    &\typing[\Delta']{S[\psi]}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; \textsf{Univ}_{i,j}
      && \text{(by \Cref{def:univ-type-pred})}
  \end{align*}

  \emph{Term predicate (2).}
  Assume $\typing[\Delta]{t}{S} \;\circledR\; b \in \textsf{Univ}_{i,j}^{\textbf{El}}$.
  By \Cref{def:univ-term-pred}, $b \in \mathcal{U}_j^\ast \searrow P_b \searrow \textbf{El}_b$
  for some $P_b, \textbf{El}_b$, with
  $\typing[\Delta]{t}{\ensuremath{\texttt{Ty}_{j}}} \;\circledR\; P_b$ at level $j$ and
  $\tyequiv[\Delta]{S}{\ensuremath{\texttt{Ty}_{j}}}{\ensuremath{\texttt{Ty}_{i}}}$.
  \begin{align*}
    &\typing[\Delta']{t[\psi]}{\ensuremath{\texttt{Ty}_{j}}[\psi]} \;\circledR\; P_b
      && \text{(by IH at level $j$ on $b \in \mathcal{U}_j^\ast$, type predicate)} \\
    &\ensuremath{\texttt{Ty}_{j}}[\psi] = \ensuremath{\texttt{Ty}_{j}}
      && \text{(syntactic; $\ensuremath{\texttt{Ty}_{j}}$ closed)} \\
    &\typing[\Delta']{t[\psi]}{\ensuremath{\texttt{Ty}_{j}}} \;\circledR\; P_b
      && \text{(rewriting)} \\
    &\tyequiv[\Delta']{S[\psi]}{\ensuremath{\texttt{Ty}_{j}}}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by type-predicate monotonicity (1) above)} \\
    &\typing[\Delta']{t[\psi]}{S[\psi]} \;\circledR\; b \in \textsf{Univ}_{i,j}^{\textbf{El}}
      && \text{(by \Cref{def:univ-term-pred} with the previous lines)}
  \end{align*}

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{G-Pi}]
    {a \in \mathcal{U}_i^\ast \searrow P_I \searrow \textbf{El}_I \\
     a \approx a \in \mathcal{U}_i \searrow R_I \\\\
     \forall\, \ensuremath{\mathcal{D}} :: b \approx b \in R_I,\; c.\;
       \ensuremath{\llbracket T \rrbracket(\rho, b/x)} \searrow c \implies
       c \in \mathcal{U}_i^\ast \searrow P_O(\ensuremath{\mathcal{D}}) \searrow \textbf{El}_O(\ensuremath{\mathcal{D}}) \\\\
     \Pi(a, T, \rho) \approx \Pi(a, T, \rho) \in \mathcal{U}_i \searrow R \\\\
     P \Leftrightarrow \Pi_i(R_I, P_I, \textbf{El}_I, P_O) \\
     \textbf{El} \Leftrightarrow \Pi_i^{\textbf{El}}(R, R_I, P_I, \textbf{El}_I, \textbf{El}_O)}
    {\Pi(a, T, \rho) \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El}}
  \end{mathpar}

  \emph{Type predicate (1).}
  Assume $\typing[\Delta]{S}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; \Pi_i(R_I, P_I, \textbf{El}_I, P_O)$.
  By \Cref{def:pi-type-pred}, this gives $S_1, S_2$ with
  $\tyequiv[\Delta]{S}{\Pi(x:S_1).\,S_2}{\ensuremath{\texttt{Ty}_{i}}}$ and the three clauses
  (well-formedness of $S$, domain-predicate, codomain-predicate). We must show
  $\typing[\Delta']{S[\psi]}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; \Pi_i(R_I, P_I, \textbf{El}_I, P_O)$.

  \emph{Clause 1: $\Pi$-shape equality.}
  \begin{align*}
    &\tyequiv[\Delta]{S}{\Pi(x:S_1).\,S_2}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by \Cref{def:pi-type-pred} clause 1)} \\
    &\tyequiv[\Delta']{S[\psi]}{(\Pi(x:S_1).\,S_2)[\psi]}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by \Cref{lem:wk-typing})} \\
    &(\Pi(x:S_1).\,S_2)[\psi] = \Pi(x:S_1[\psi]).\,(S_2[q(\psi)])
      && \text{(by syntactic substitution on $\Pi$)} \\
    &\tyequiv[\Delta']{S[\psi]}{\Pi(x:S_1[\psi]).\,(S_2[q(\psi)])}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(rewriting)}
  \end{align*}

  \emph{Clause 2: domain-predicate at every Kripke extension of $\Delta'$.}
  Let $\kweak[\Delta'']{\phi'}{\Delta'}$ be arbitrary.
  \begin{align*}
    &\kweak[\Delta'']{\psi \circ \phi'}{\Delta}
      && \text{(by \Cref{lem:kweak-comp})} \\
    &\typing[\Delta'']{S_1[\psi \circ \phi']}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; P_I
      && \text{(by hypothesis clause 2 at $\psi \circ \phi'$)} \\
    &S_1[\psi \circ \phi'] = (S_1[\psi])[\phi']
      && \text{(by \Cref{lem:subst-assoc})} \\
    &\typing[\Delta'']{(S_1[\psi])[\phi']}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; P_I
      && \text{(rewriting)}
  \end{align*}

  \emph{Clause 3: codomain-predicate at every Kripke extension of $\Delta'$
  and every El-related $b$.}
  Let $\kweak[\Delta'']{\phi'}{\Delta'}$, $s, b, \ensuremath{\mathcal{D}} :: b \approx b \in R_I$ with
  $\typing[\Delta'']{s}{(S_1[\psi])[\phi']} \;\circledR\; b \in \textbf{El}_I$.
  \begin{align*}
    &\kweak[\Delta'']{\psi \circ \phi'}{\Delta}
      && \text{(by \Cref{lem:kweak-comp})} \\
    &\typing[\Delta'']{s}{S_1[\psi \circ \phi']} \;\circledR\; b \in \textbf{El}_I
      && \text{(by \Cref{lem:subst-assoc} on the type)} \\
    &\typing[\Delta'']{S_2[\iota(\psi \circ \phi'), s/x]}{\ensuremath{\texttt{Ty}_{i}}}
      \;\circledR\; P_O(\ensuremath{\mathcal{D}})
      && \text{(by hypothesis clause 3 at $\psi \circ \phi', s, b, \ensuremath{\mathcal{D}}$)}
  \end{align*}
  This is the required predicate at the Kripke weakening $\psi \circ \phi'$
  for $\Pi_i$ at $S[\psi]$ over $\Delta'$.

  \emph{Term predicate (2).}
  Assume $\typing[\Delta]{t}{S} \;\circledR\; f \in
  \Pi_i^{\textbf{El}}(R, R_I, P_I, \textbf{El}_I, \textbf{El}_O)$. We verify the four clauses of
  \Cref{def:pi-term-pred} at $\typing[\Delta']{t[\psi]}{S[\psi]}$ and value $f$.

  \emph{Clause 1: self-relatedness $f \approx f \in R$.} Unchanged by Kripke
  weakening (PER fact, independent of $\Delta$).

  \emph{Clause 2: $R_I$-coherence of $f$.} Unchanged for the same reason.

  \emph{Clause 3: type-readback of $f$ at $\Pi$-shape.} By type-predicate
  monotonicity (1) above, the $\Pi_i$-type predicate transfers to $S[\psi]$ over
  $\Delta'$, supplying the type-readback witnesses required by clause 3.

  \emph{Clause 4: application.}
  Let $\kweak[\Delta'']{\phi'}{\Delta'}$, $s, b, \ensuremath{\mathcal{D}} :: b \approx b \in R_I$ with
  $\typing[\Delta'']{s}{(S_1[\psi])[\phi']} \;\circledR\; b \in \textbf{El}_I$.
  \begin{align*}
    &\kweak[\Delta'']{\psi \circ \phi'}{\Delta}
      && \text{(by \Cref{lem:kweak-comp})} \\
    &\typing[\Delta'']{s}{S_1[\psi \circ \phi']} \;\circledR\; b \in \textbf{El}_I
      && \text{(by \Cref{lem:subst-assoc})} \\
    &f \cdot b \searrow c
      && \text{(by hypothesis clause 4 at $\psi \circ \phi', s, b, \ensuremath{\mathcal{D}}$)} \\
    &\typing[\Delta'']{(t[\psi \circ \phi'])\;s}{S_2[\iota(\psi \circ \phi'), s/x]}
      \;\circledR\; c \in \textbf{El}_O(\ensuremath{\mathcal{D}})
      && \text{(by hypothesis clause 4)} \\
    &t[\psi \circ \phi'] = t[\psi][\phi']
      && \text{(by \Cref{lem:subst-assoc})} \\
    &\typing[\Delta'']{t[\psi][\phi']\;s}{S_2[\iota(\psi \circ \phi'), s/x]}
      \;\circledR\; c \in \textbf{El}_O(\ensuremath{\mathcal{D}})
      && \text{(rewriting)}
  \end{align*}
  This is the required form for $\Pi_i^{\textbf{El}}$ clause 4 at $t[\psi]$ over
  $\Delta'$ at the Kripke weakening $\psi \circ \phi'$.

  \emph{Clause 5: $R_I$-coherence under application.} Inherited from the
  original predicate's clause 5 by composition with $\psi$ as in clause 4.

By induction on the context-gluing derivation $\Gamma \searrow \textsf{Sb}$.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{G-Ctx-$\cdot$}]
    {\textsf{Sb} \Leftrightarrow (\judge[\Delta]{\sigma : \cdot})}
    {\cdot \searrow \textsf{Sb}}
  \end{mathpar}
  \begin{align*}
    &\judge[\Delta]{\sigma : \cdot}
      && \text{(by hypothesis on $\sigma$)} \\
    &\judge[\Delta']{\sigma[\psi] : \cdot}
      && \text{(by substitution composition, \Cref{sec:syn})} \\
    &\judge[\Delta']{\sigma[\psi] : \cdot} \;\circledR\; \rho \in \textsf{Sb}
      && \text{(by $\textsf{Sb}$'s definition for $\cdot$)}
  \end{align*}

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{G-Ctx-Ext}]
    {\Gamma_0 \searrow \textsf{Sb}_T \\
     \typing[\Gamma_0]{S}{\ensuremath{\texttt{Ty}_{i}}} \\\\
     \forall \Delta'', \sigma_T, \rho_T.\;
       \judge[\Delta'']{\sigma_T : \Gamma_0} \;\circledR\; \rho_T \in \textsf{Sb}_T
       \implies \\
     \quad \exists a, P, \textbf{El}.\;
       \ensuremath{\llbracket S \rrbracket(\rho_T)} \searrow a \;\wedge\;
       a \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El} \;\wedge\;
       \typing[\Delta'']{S[\sigma_T]}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; P \\\\
     \textsf{Sb} \Leftrightarrow \textsf{Cons}_i(\Gamma_0, S, \textsf{Sb}_T)}
    {(\Gamma_0, x : S) \searrow \textsf{Sb}}
  \end{mathpar}
  Unfolding $\textsf{Cons}_i$ at $\sigma, \rho$ provides existential
  $a, P, \textbf{El}$ specific to this pair:
  \begin{align*}
    &\judge[\Delta]{\Uparrow \circ \sigma : \Gamma_0} \;\circledR\;
      \rho[\Uparrow] \in \textsf{Sb}_T
      && \text{(tail of $\textsf{Cons}_i$)} \\
    &\ensuremath{\llbracket S \rrbracket(\rho[\Uparrow])} \searrow a,\;
      a \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El}
      && \text{(type clause of $\textsf{Cons}_i$)} \\
    &\typing[\Delta]{S[\Uparrow \circ \sigma]}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; P
      && \text{(type clause of $\textsf{Cons}_i$)} \\
    &\typing[\Delta]{x_0[\sigma]}{S[\Uparrow \circ \sigma]} \;\circledR\;
      \rho(x_0) \in \textbf{El}
      && \text{(head of $\textsf{Cons}_i$)} \\
    &\judge[\Delta']{(\Uparrow \circ \sigma)[\psi] : \Gamma_0}
      \;\circledR\; \rho[\Uparrow] \in \textsf{Sb}_T
      && \text{(by IH on the smaller derivation
        $\Gamma_0 \searrow \textsf{Sb}_T$)} \\
    &(\Uparrow \circ \sigma)[\psi] = \Uparrow \circ (\sigma[\psi])
      && \text{(by associativity of $\circ$, \Cref{lem:subst-cat})} \\
    &\typing[\Delta']{S[\Uparrow \circ \sigma][\psi]}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; P
      && \text{(by \Cref{thm:monotonicity} on the type predicate)} \\
    &S[\Uparrow \circ \sigma][\psi] = S[\Uparrow \circ \sigma[\psi]]
      && \text{(by \Cref{lem:subst-assoc} and the previous identity)} \\
    &\typing[\Delta']{x_0[\sigma][\psi]}{S[\Uparrow \circ \sigma][\psi]}
      \;\circledR\; \rho(x_0) \in \textbf{El}
      && \text{(by \Cref{thm:monotonicity} on the head)} \\
    &x_0[\sigma][\psi] = x_0[\sigma[\psi]]
      && \text{(by \Cref{lem:subst-assoc})} \\
    &\typing[\Delta']{x_0[\sigma[\psi]]}{S[\Uparrow \circ \sigma[\psi]]}
      \;\circledR\; \rho(x_0) \in \textbf{El}
      && \text{(rewriting via the previous identities)} \\
    &\judge[\Delta']{\sigma[\psi] : \Gamma_0, x:S}
      \;\circledR\; \rho \in \textsf{Sb}
      && \text{(by $\textsf{Cons}_i$ assembly with the same $a, P, \textbf{El}$)}
  \end{align*}

\label{lem:gluing-implies-per}
  If $a \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El}$, then there exists $R$ such that
  $a \approx a \in \mathcal{U}_i \searrow R$.

By induction on the derivation $a \in \mathcal{U}_i^\ast$.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{G-Ne}]
    {{\uparrow}^A(e) \in \ensuremath{\mathrm{D}}}
    {{\uparrow}^A(e) \in \mathcal{U}_i^\ast}
  \end{mathpar}
  By \textsc{U-Ne} of \Cref{def:per-univ}: ${\uparrow}^A(e) \approx
  {\uparrow}^A(e) \in \mathcal{U}_i \searrow R$ with $R \Leftrightarrow \textsf{Neu}$,
  using $e \approx e \in \textsf{Ne}$ from $\mathcal{U}_i^\ast$'s implicit assumption.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{G-Nat}]
    { }
    {N \in \mathcal{U}_i^\ast}
  \end{mathpar}
  By \textsc{U-Nat}: $N \approx N \in \mathcal{U}_i \searrow R$ with $R \Leftrightarrow
  \textsf{Nat}$.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{G-Univ}]
    {j < i}
    {U_j \in \mathcal{U}_i^\ast}
  \end{mathpar}
  By \textsc{U-Univ}: $U_j \approx U_j \in \mathcal{U}_i \searrow R$ with $R \Leftrightarrow
  \mathcal{U}_j$.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{G-Pi}]
    {a \in \mathcal{U}_i^\ast \searrow P_I \searrow \textbf{El}_I \\
     a \approx a \in \mathcal{U}_i \searrow R_I \\\\
     \forall\, \ensuremath{\mathcal{D}} :: b \approx b \in R_I,\; c.\;
       \ensuremath{\llbracket T \rrbracket(\rho, b/x)} \searrow c \implies
       c \in \mathcal{U}_i^\ast \searrow P_O(\ensuremath{\mathcal{D}}) \searrow \textbf{El}_O(\ensuremath{\mathcal{D}}) \\\\
     \Pi(a, T, \rho) \approx \Pi(a, T, \rho) \in \mathcal{U}_i \searrow R \\\\
     P \Leftrightarrow \Pi_i(R_I, P_I, \textbf{El}_I, P_O) \\
     \textbf{El} \Leftrightarrow \Pi_i^{\textbf{El}}(R, R_I, P_I, \textbf{El}_I, \textbf{El}_O)}
    {\Pi(a, T, \rho) \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El}}
  \end{mathpar}
  The PER witness $R$ for $\Pi(a, T, \rho) \approx \Pi(a, T, \rho) \in \mathcal{U}_i$
  is packaged directly as a premise of \textsc{G-Pi}, hence is available
  immediately.

\label{lem:gluing-typ-escape}
  If $a \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El}$ and
  $\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; P$, then $\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}}$.

By case analysis on $a \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El}$.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{G-Ne}]
    {{\uparrow}^A(e) \in \ensuremath{\mathrm{D}} \\
     P \Leftrightarrow \textsf{Neu}_i^e \\
     \textbf{El} \Leftrightarrow \textsf{Neu}_i^e}
    {{\uparrow}^A(e) \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El}}
  \end{mathpar}
  \begin{align*}
    &\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; \textsf{Neu}_i^e
      && \text{(by hypothesis with $P \Leftrightarrow \textsf{Neu}_i^e$)} \\
    &\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by \Cref{def:neu-type-pred} clause 1)}
  \end{align*}

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{G-Nat}]
    {P \Leftrightarrow \textsf{Nat}_i \\
     \textbf{El} \Leftrightarrow \textsf{Nat}_i}
    {N \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El}}
  \end{mathpar}
  \begin{align*}
    &\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; \textsf{Nat}_i
      && \text{(by hypothesis)} \\
    &\tyequiv[\Gamma]{S}{\ensuremath{\texttt{Nat}}}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by \Cref{def:nat-type-pred})} \\
    &\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by presupposition of judgmental equality)}
  \end{align*}

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{G-Univ}]
    {j < i \\
     P \Leftrightarrow \textsf{Univ}_{i,j} \\
     \textbf{El} \Leftrightarrow \textsf{Univ}_{i,j}^{\textbf{El}}}
    {U_j \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El}}
  \end{mathpar}
  \begin{align*}
    &\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; \textsf{Univ}_{i,j}
      && \text{(by hypothesis)} \\
    &\tyequiv[\Gamma]{S}{\ensuremath{\texttt{Ty}_{j}}}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by \Cref{def:univ-type-pred})} \\
    &\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by presupposition of judgmental equality)}
  \end{align*}

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{G-Pi}]
    {P \Leftrightarrow \Pi_i(R_I, P_I, \textbf{El}_I, P_O) \\
     \textbf{El} \Leftrightarrow \Pi_i^{\textbf{El}}(R, R_I, P_I, \textbf{El}_I, \textbf{El}_O)}
    {\Pi(a_I, T, \rho) \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El}}
  \end{mathpar}
  \begin{align*}
    &\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; \Pi_i(R_I, P_I, \textbf{El}_I, P_O)
      && \text{(by hypothesis)} \\
    &\exists S_1, S_2.\;
      \tyequiv[\Gamma]{S}{\Pi(x:S_1).\,S_2}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by \Cref{def:pi-type-pred} clause 1)} \\
    &\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by presupposition of judgmental equality)}
  \end{align*}

By case analysis on $a \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El}$.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{G-Ne}]
    {{\uparrow}^A(e) \in \ensuremath{\mathrm{D}} \\
     P \Leftrightarrow \textsf{Neu}_i^e \\
     \textbf{El} \Leftrightarrow \textsf{Neu}_i^e}
    {{\uparrow}^A(e) \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El}}
  \end{mathpar}
  \begin{align*}
    &\typing[\Gamma]{t}{S} \;\circledR\; b \in \textsf{Neu}_i^e
      && \text{(by hypothesis)} \\
    &\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; \textsf{Neu}_i^e
      && \text{(by \Cref{def:neu-term-pred} clause 1)} \\
    &\typing[\Gamma]{t}{S}
      && \text{(by \Cref{def:neu-term-pred} clause 2)}
  \end{align*}

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{G-Nat}]
    {P \Leftrightarrow \textsf{Nat}_i \\
     \textbf{El} \Leftrightarrow \textsf{Nat}_i}
    {N \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El}}
  \end{mathpar}
  \begin{align*}
    &\typing[\Gamma]{t}{S} \;\circledR\; b \in \textsf{Nat}_i
      && \text{(by hypothesis)} \\
    &\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; \textsf{Nat}_i
      && \text{(by \Cref{def:nat-term-pred})}
  \end{align*}
  By inner induction on the $\textsf{Nat}$-derivation at $b$:
  \begin{itemize}
  \@idxitem[Sub-case]
    \begin{mathpar}
      \inferrule[\textsc{GN-Ze}]
      {\tyequiv[\Gamma]{t}{\textsf{zero}}{S}}
      {\typing[\Gamma]{t}{S} \;\circledR\; \texttt{ze} \in \textsf{Nat}}
    \end{mathpar}
    $\typing[\Gamma]{t}{S}$ by presupposition of $\tyequiv[\Gamma]{t}{\textsf{zero}}{S}$.
  \@idxitem[Sub-case]
    \begin{mathpar}
      \inferrule[\textsc{GN-Su}]
      {\typing[\Gamma]{t'}{S} \;\circledR\; b' \in \textsf{Nat} \\
       \tyequiv[\Gamma]{t}{\textsf{succ}~t'}{S}}
      {\typing[\Gamma]{t}{S} \;\circledR\; \texttt{su}(b') \in \textsf{Nat}}
    \end{mathpar}
    $\typing[\Gamma]{t}{S}$ by presupposition of $\tyequiv[\Gamma]{t}{\textsf{succ}~t'}{S}$.
  \@idxitem[Sub-case]
    \begin{mathpar}
      \inferrule[\textsc{GN-Ne}]
      {\typing[\Gamma]{t}{S} \;\circledR\; {\uparrow}^N(w) \in \textsf{Neu}_i^e}
      {\typing[\Gamma]{t}{S} \;\circledR\; {\uparrow}^N(w) \in \textsf{Nat}}
    \end{mathpar}
    $\typing[\Gamma]{t}{S}$ by \textsc{G-Ne} case (just proved) on the neutral
    premise.
  \end{itemize}

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{G-Univ}]
    {j < i \\
     P \Leftrightarrow \textsf{Univ}_{i,j} \\
     \textbf{El} \Leftrightarrow \textsf{Univ}_{i,j}^{\textbf{El}}}
    {U_j \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El}}
  \end{mathpar}
  \begin{align*}
    &\typing[\Gamma]{t}{S} \;\circledR\; b \in \textsf{Univ}_{i,j}^{\textbf{El}}
      && \text{(by hypothesis)} \\
    &\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; \textsf{Univ}_{i,j}
      && \text{(by \Cref{def:univ-term-pred} clause 1)} \\
    &\typing[\Gamma]{t}{\ensuremath{\texttt{Ty}_{j}}} \;\circledR\; P_b
      && \text{(by \Cref{def:univ-term-pred} clause 2)} \\
    &\typing[\Gamma]{t}{\ensuremath{\texttt{Ty}_{j}}}
      && \text{(by \Cref{lem:gluing-typ-escape} on the previous line at level $j$)} \\
    &\tyequiv[\Gamma]{S}{\ensuremath{\texttt{Ty}_{j}}}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by \Cref{def:univ-type-pred})} \\
    &\subty[\Gamma]{\ensuremath{\texttt{Ty}_{j}}}{S}
      && \text{(by \textsc{Sub-Eq} from the symmetric equality)} \\
    &\typing[\Gamma]{t}{S}
      && \text{(by \textsc{Subsump})}
  \end{align*}

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{G-Pi}]
    {P \Leftrightarrow \Pi_i(R_I, P_I, \textbf{El}_I, P_O) \\
     \textbf{El} \Leftrightarrow \Pi_i^{\textbf{El}}(R, R_I, P_I, \textbf{El}_I, \textbf{El}_O)}
    {\Pi(a_I, T, \rho) \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El}}
  \end{mathpar}
  \begin{align*}
    &\typing[\Gamma]{t}{S} \;\circledR\; b \in \Pi_i^{\textbf{El}}
      && \text{(by hypothesis)} \\
    &\typing[\Gamma]{t}{S}
      && \text{(by \Cref{def:pi-term-pred} clause 2)} \\
    &\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; \Pi_i
      && \text{(by \Cref{def:pi-term-pred} clause 3)}
  \end{align*}

By induction on the first derivation $a \in \mathcal{U}_i^\ast$, with case analysis
  on the second (which must end with the same rule, since each rule's
  conclusion form determines $a$ syntactically).

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{G-Ne}]
    {{\uparrow}^A(e) \in \ensuremath{\mathrm{D}} \\
     P \Leftrightarrow \textsf{Neu}_i^e \\
     \textbf{El} \Leftrightarrow \textsf{Neu}_i^e}
    {{\uparrow}^A(e) \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El}}
  \end{mathpar}
  \begin{align*}
    &P_1 \Leftrightarrow \textsf{Neu}_i^e
      && \text{(by \textsc{G-Ne} on the first derivation)} \\
    &P_2 \Leftrightarrow \textsf{Neu}_i^e
      && \text{(by \textsc{G-Ne} on the second derivation)} \\
    &P_1 \Leftrightarrow P_2
      && \text{(transitivity)} \\
    &\textbf{El}_1 \Leftrightarrow \textsf{Neu}_i^e \Leftrightarrow \textbf{El}_2
      && \text{(symmetrically)}
  \end{align*}

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{G-Nat}]
    {P \Leftrightarrow \textsf{Nat}_i \\
     \textbf{El} \Leftrightarrow \textsf{Nat}_i}
    {N \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El}}
  \end{mathpar}
  \begin{align*}
    &P_1 \Leftrightarrow \textsf{Nat}_i \Leftrightarrow P_2,\;
      \textbf{El}_1 \Leftrightarrow \textsf{Nat}_i \Leftrightarrow \textbf{El}_2
      && \text{(by \textsc{G-Nat} on both derivations)}
  \end{align*}

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{G-Univ}]
    {j < i \\
     P \Leftrightarrow \textsf{Univ}_{i,j} \\
     \textbf{El} \Leftrightarrow \textsf{Univ}_{i,j}^{\textbf{El}}}
    {U_j \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El}}
  \end{mathpar}
  Both derivations fix the same $j < i$, so $P_1 \Leftrightarrow
  \textsf{Univ}_{i,j} \Leftrightarrow P_2$ and $\textbf{El}_1 \Leftrightarrow
  \textsf{Univ}_{i,j}^{\textbf{El}} \Leftrightarrow \textbf{El}_2$.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{G-Pi}]
    {a \in \mathcal{U}_i^\ast \searrow P_I \searrow \textbf{El}_I \\
     a \approx a \in \mathcal{U}_i \searrow R_I \\\\
     \forall\, \ensuremath{\mathcal{D}} :: b \approx b \in R_I,\; c.\;
       \ensuremath{\llbracket T \rrbracket(\rho, b/x)} \searrow c \implies
       c \in \mathcal{U}_i^\ast \searrow P_O(\ensuremath{\mathcal{D}}) \searrow \textbf{El}_O(\ensuremath{\mathcal{D}}) \\\\
     \Pi(a, T, \rho) \approx \Pi(a, T, \rho) \in \mathcal{U}_i \searrow R \\\\
     P \Leftrightarrow \Pi_i(R_I, P_I, \textbf{El}_I, P_O) \\
     \textbf{El} \Leftrightarrow \Pi_i^{\textbf{El}}(R, R_I, P_I, \textbf{El}_I, \textbf{El}_O)}
    {\Pi(a, T, \rho) \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El}}
  \end{mathpar}
  Let the two derivations have inner data $(P_I^{(1)}, \textbf{El}_I^{(1)}, R_I^{(1)},
  P_O^{(1)}, \textbf{El}_O^{(1)}, R^{(1)})$ and $(P_I^{(2)}, \ldots)$ respectively.
  \begin{align*}
    &P_I^{(1)} \Leftrightarrow P_I^{(2)},\;
      \textbf{El}_I^{(1)} \Leftrightarrow \textbf{El}_I^{(2)}
      && \text{(by IH on the inner $a \in \mathcal{U}_i^\ast$)} \\
    &R_I^{(1)} \Leftrightarrow R_I^{(2)},\;
      R^{(1)} \Leftrightarrow R^{(2)}
      && \text{(by \Cref{lem:univ-functional} on the inner $\mathcal{U}_i$ judgments)} \\
    &\forall \ensuremath{\mathcal{D}}.\; P_O^{(1)}(\ensuremath{\mathcal{D}}) \Leftrightarrow P_O^{(2)}(\ensuremath{\mathcal{D}}),\;
      \textbf{El}_O^{(1)}(\ensuremath{\mathcal{D}}) \Leftrightarrow \textbf{El}_O^{(2)}(\ensuremath{\mathcal{D}})
      && \text{(by IH on the codomain fibers, pointwise in $\ensuremath{\mathcal{D}}$)} \\
    &P_1 \Leftrightarrow \Pi_i(R_I^{(1)}, P_I^{(1)}, \textbf{El}_I^{(1)}, P_O^{(1)})
      \Leftrightarrow \Pi_i(R_I^{(2)}, P_I^{(2)}, \textbf{El}_I^{(2)}, P_O^{(2)}) \\
    & \quad \Leftrightarrow P_2
      && \text{(by congruence of $\Pi_i$)} \\
    &\textbf{El}_1 \Leftrightarrow \Pi_i^{\textbf{El}}(\ldots) \Leftrightarrow \textbf{El}_2
      && \text{(symmetrically)}
  \end{align*}

\label{lem:gluing-cumul}
  Suppose $i \le j$, $a \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El}$, and
  $a \in \mathcal{U}_j^\ast \searrow P' \searrow \textbf{El}'$. Then:
  \begin{enumerate}
  \@idxitem \emph{Type-predicate raising:} If $\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}}
    \;\circledR\; P$, then $\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{j}}} \;\circledR\; P'$.
  \@idxitem \emph{Term-predicate raising:} If $\typing[\Gamma]{t}{S} \;\circledR\;
    b \in \textbf{El}$, then $\typing[\Gamma]{t}{S} \;\circledR\; b \in \textbf{El}'$.
  \@idxitem \emph{Term-predicate lowering (under type-predicate at level $i$):}
    If $\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; P$ and
    $\typing[\Gamma]{t}{S} \;\circledR\; b \in \textbf{El}'$, then
    $\typing[\Gamma]{t}{S} \;\circledR\; b \in \textbf{El}$.
  \end{enumerate}
  Existence of $P', \textbf{El}'$ at level $j$ follows from re-applying the gluing
  rules at level $j$ to the same data.

Since the gluing rules at level $i$ and level $j$ agree on the syntactic
  shape of $a$, the second derivation $a \in \mathcal{U}_j^\ast \searrow P' \searrow \textbf{El}'$
  must end with the same rule (\textsc{G-Ne}, \textsc{G-Nat}, \textsc{G-Univ},
  or \textsc{G-Pi}) as the first. We proceed by induction on
  $a \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El}$, with sub-case-analysis on the
  rule shared by the two derivations.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{G-Ne}]
    {{\uparrow}^A(e) \in \ensuremath{\mathrm{D}} \\
     P \Leftrightarrow \textsf{Neu}_i^e \\
     \textbf{El} \Leftrightarrow \textsf{Neu}_i^e}
    {{\uparrow}^A(e) \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El}}
  \end{mathpar}
  Then $P' \Leftrightarrow \textsf{Neu}_j^e$ and $\textbf{El}' \Leftrightarrow \textsf{Neu}_j^e$.
  But $\textsf{Neu}_*^e$ does not depend on the index
  (\Cref{def:neu-type-pred,def:neu-term-pred}), so $P \Leftrightarrow P'$ and
  $\textbf{El} \Leftrightarrow \textbf{El}'$. All three claims (1)--(3) hold trivially.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{G-Nat}]
    {P \Leftrightarrow \textsf{Nat}_i \\
     \textbf{El} \Leftrightarrow \textsf{Nat}_i}
    {N \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El}}
  \end{mathpar}
  Then $P' \Leftrightarrow \textsf{Nat}_j$ and $\textbf{El}' \Leftrightarrow \textsf{Nat}_j$.

  \emph{Type-predicate raising (1):} given $\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}}
  \;\circledR\; \textsf{Nat}_i$:
  \begin{align*}
    &\tyequiv[\Gamma]{S}{\ensuremath{\texttt{Nat}}}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by \Cref{def:nat-type-pred})} \\
    &\tyequiv[\Gamma]{S}{\ensuremath{\texttt{Nat}}}{\ensuremath{\texttt{Ty}_{j}}}
      && \text{(by cumulativity of universes, $i \le j$, \Cref{sec:rules})} \\
    &\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{j}}} \;\circledR\; \textsf{Nat}_j
      && \text{(by \Cref{def:nat-type-pred} at level $j$)}
  \end{align*}

  \emph{Term-predicate raising (2):} given $\typing[\Gamma]{t}{S} \;\circledR\;
  b \in \textsf{Nat}_i$, by inner induction on the $\textsf{Nat}$-derivation at
  $b$. Each sub-case (\textsc{GN-Ze, GN-Su, GN-Ne}) constructs the same
  derivation at level $j$, since the constructors $\ensuremath{\texttt{Nat}}, \textsf{zero}, \textsf{succ}~$ and the
  neutral predicate $\textsf{Neu}_*^e$ are level-independent. The
  type-predicate part upgrades via (1).

  \emph{Term-predicate lowering (3):} given $\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}}
  \;\circledR\; \textsf{Nat}_i$ and $\typing[\Gamma]{t}{S} \;\circledR\; b
  \in \textsf{Nat}_j$. By inner induction on the $\textsf{Nat}$-derivation at
  $b$ (level-$j$); each sub-case re-uses the level-independent constructors and
  re-derives the $\textsf{Nat}$-predicate at level $i$, with the type-predicate
  part already provided by hypothesis.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{G-Univ}]
    {k < i \\
     P \Leftrightarrow \textsf{Univ}_{i,k} \\
     \textbf{El} \Leftrightarrow \textsf{Univ}_{i,k}^{\textbf{El}}}
    {U_k \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El}}
  \end{mathpar}
  Then $k < j$ (from $k < i \le j$), $P' \Leftrightarrow \textsf{Univ}_{j,k}$,
  $\textbf{El}' \Leftrightarrow \textsf{Univ}_{j,k}^{\textbf{El}}$.

  \emph{Type-predicate raising (1):}
  \begin{align*}
    &\tyequiv[\Gamma]{S}{\ensuremath{\texttt{Ty}_{k}}}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by \Cref{def:univ-type-pred} on $\textsf{Univ}_{i,k}$)} \\
    &\tyequiv[\Gamma]{S}{\ensuremath{\texttt{Ty}_{k}}}{\ensuremath{\texttt{Ty}_{j}}}
      && \text{(by cumulativity of universes, $i \le j$, \Cref{sec:rules})} \\
    &\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{j}}} \;\circledR\; \textsf{Univ}_{j,k}
      && \text{(by \Cref{def:univ-type-pred} at level $j$)}
  \end{align*}

  \emph{Term-predicate raising (2):} the conditions $b \in \mathcal{U}_k^\ast \searrow
  P_b \searrow \textbf{El}_b$ and $\typing[\Gamma]{t}{\ensuremath{\texttt{Ty}_{k}}} \;\circledR\; P_b$ at
  level $k$ are unchanged; the type-predicate part upgrades via (1).

  \emph{Term-predicate lowering (3):} given $\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}}
  \;\circledR\; \textsf{Univ}_{i,k}$ and $\typing[\Gamma]{t}{S} \;\circledR\; b
  \in \textsf{Univ}_{j,k}^{\textbf{El}}$. The conditions at level $k$ ($b \in
  \mathcal{U}_k^\ast \searrow P_b \searrow \textbf{El}_b$ and $\typing[\Gamma]{t}{\ensuremath{\texttt{Ty}_{k}}}
  \;\circledR\; P_b$) are level-$k$ data, unchanged; the type-predicate at
  level $i$ is provided by hypothesis. Hence
  $\typing[\Gamma]{t}{S} \;\circledR\; b \in \textsf{Univ}_{i,k}^{\textbf{El}}$ via
  \Cref{def:univ-term-pred}.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{G-Pi}]
    {a \in \mathcal{U}_i^\ast \searrow P_I \searrow \textbf{El}_I \\
     a \approx a \in \mathcal{U}_i \searrow R_I \\\\
     \forall\, \ensuremath{\mathcal{D}} :: b \approx b \in R_I,\; c.\;
       \ensuremath{\llbracket T \rrbracket(\rho, b/x)} \searrow c \implies
       c \in \mathcal{U}_i^\ast \searrow P_O(\ensuremath{\mathcal{D}}) \searrow \textbf{El}_O(\ensuremath{\mathcal{D}}) \\\\
     \Pi(a, T, \rho) \approx \Pi(a, T, \rho) \in \mathcal{U}_i \searrow R \\\\
     P \Leftrightarrow \Pi_i(R_I, P_I, \textbf{El}_I, P_O) \\
     \textbf{El} \Leftrightarrow \Pi_i^{\textbf{El}}(R, R_I, P_I, \textbf{El}_I, \textbf{El}_O)}
    {\Pi(a, T, \rho) \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El}}
  \end{mathpar}
  By inversion on the level-$j$ derivation (which must end with \textsc{G-Pi}
  by the syntactic shape of $\Pi(a, T, \rho)$):
  \begin{align*}
    &a \in \mathcal{U}_j^\ast \searrow P_I' \searrow \textbf{El}_I'
      && \text{(level-$j$ inner data)} \\
    &a \approx a \in \mathcal{U}_j \searrow R_I
      && \text{(by \Cref{lem:cumul}; same $R_I$ as level $i$)} \\
    &\forall\, \ensuremath{\mathcal{D}}, c.\;
      \ensuremath{\llbracket T \rrbracket(\rho, b/x)} \searrow c \implies
      c \in \mathcal{U}_j^\ast \searrow P_O'(\ensuremath{\mathcal{D}}) \searrow \textbf{El}_O'(\ensuremath{\mathcal{D}})
      && \text{(level-$j$ codomain fibers)} \\
    &\Pi(a, T, \rho) \approx \Pi(a, T, \rho) \in \mathcal{U}_j \searrow R
      && \text{(by \Cref{lem:cumul}; same $R$)} \\
    &P' \Leftrightarrow \Pi_j(R_I, P_I', \textbf{El}_I', P_O') \\
    &\textbf{El}' \Leftrightarrow \Pi_j^{\textbf{El}}(R, R_I, P_I', \textbf{El}_I', \textbf{El}_O')
  \end{align*}
  The PER witnesses $R_I, R$ are unchanged (level-independent in $\mathcal{U}$ via
  \Cref{lem:cumul}). The IH applies to the inner $a$ and to each codomain fiber
  $c$ (smaller derivations).

  \emph{Type-predicate raising (1).}
  Suppose $\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; \Pi_i(R_I, P_I, \textbf{El}_I, P_O)$
  with witnesses $S_1, S_2$. We verify the three clauses of
  $\Pi_j(R_I, P_I', \textbf{El}_I', P_O')$ at $S$.

  \emph{Clause 1.}
  \begin{align*}
    &\tyequiv[\Gamma]{S}{\Pi(x:S_1).\,S_2}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by \Cref{def:pi-type-pred} clause 1 on the hypothesis)} \\
    &\tyequiv[\Gamma]{S}{\Pi(x:S_1).\,S_2}{\ensuremath{\texttt{Ty}_{j}}}
      && \text{(by cumulativity of universes, $i \le j$, \Cref{sec:rules})}
  \end{align*}

  \emph{Clause 2.} Let $\kweak[\Delta]{\phi}{\Gamma}$.
  \begin{align*}
    &\typing[\Delta]{S_1[\phi]}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; P_I
      && \text{(by \Cref{def:pi-type-pred} clause 2 on the hypothesis)} \\
    &\typing[\Delta]{S_1[\phi]}{\ensuremath{\texttt{Ty}_{j}}} \;\circledR\; P_I'
      && \text{(by IH (1) on $a$, raising)}
  \end{align*}

  \emph{Clause 3.} Let $\kweak[\Delta]{\phi}{\Gamma}$, $s, b, \ensuremath{\mathcal{D}} :: b \approx
  b \in R_I$ with $\typing[\Delta]{s}{S_1[\phi]} \;\circledR\; b \in \textbf{El}_I'$.
  \begin{align*}
    &\typing[\Delta]{S_1[\phi]}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; P_I
      && \text{(by clause 2 above, the level-$i$ part)} \\
    &\typing[\Delta]{s}{S_1[\phi]} \;\circledR\; b \in \textbf{El}_I
      && \text{(by IH (3) on $a$, lowering, using the previous line as the
        level-$i$ type-predicate)} \\
    &\typing[\Delta]{S_2[\iota(\phi), s/x]}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; P_O(\ensuremath{\mathcal{D}})
      && \text{(by \Cref{def:pi-type-pred} clause 3 on the hypothesis)} \\
    &\typing[\Delta]{S_2[\iota(\phi), s/x]}{\ensuremath{\texttt{Ty}_{j}}} \;\circledR\; P_O'(\ensuremath{\mathcal{D}})
      && \text{(by IH (1) on the codomain fiber} \\
    & && \text{$c$ at $\ensuremath{\mathcal{D}}$, raising)}
  \end{align*}

  \emph{Term-predicate raising (2).}
  Suppose $\typing[\Gamma]{t}{S} \;\circledR\; f \in \Pi_i^{\textbf{El}}(R, R_I, P_I,
  \textbf{El}_I, \textbf{El}_O)$. We verify the four clauses of
  $\Pi_j^{\textbf{El}}(R, R_I, P_I', \textbf{El}_I', \textbf{El}_O')$ at $t, f$.

  \emph{Clauses 1--2.}
  \begin{align*}
    &f \approx f \in R
      && \text{(unchanged from hypothesis)} \\
    &\typing[\Gamma]{t}{S}
      && \text{(unchanged from hypothesis)}
  \end{align*}

  \emph{Clause 3.}
  \begin{align*}
    &\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; \Pi_i(R_I, P_I, \textbf{El}_I, P_O)
      && \text{(by \Cref{def:pi-term-pred} clause 3 on the hypothesis)} \\
    &\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{j}}} \;\circledR\; \Pi_j(R_I, P_I', \textbf{El}_I', P_O')
      && \text{(by part (1) of this case, applied just above)}
  \end{align*}

  \emph{Clause 4 (application).}
  Let $\kweak[\Delta]{\phi}{\Gamma}$, $s, b, \ensuremath{\mathcal{D}} :: b \approx b \in R_I$ with
  $\typing[\Delta]{s}{S_1[\phi]} \;\circledR\; b \in \textbf{El}_I'$.
  \begin{align*}
    &\typing[\Delta]{S_1[\phi]}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; P_I
      && \text{(by hypothesis clause 3 at level $i$, clause 2 of $\Pi_i$)} \\
    &\typing[\Delta]{s}{S_1[\phi]} \;\circledR\; b \in \textbf{El}_I
      && \text{(by IH (3) on $a$, lowering)} \\
    &f \cdot b \searrow c,\;
      \typing[\Delta]{(t[\phi])\;s}{S_2[\iota(\phi), s/x]}
      \;\circledR\; c \in \textbf{El}_O(\ensuremath{\mathcal{D}})
      && \text{(by hypothesis clause 4 at level $i$)} \\
    &\typing[\Delta]{(t[\phi])\;s}{S_2[\iota(\phi), s/x]}
      \;\circledR\; c \in \textbf{El}_O'(\ensuremath{\mathcal{D}})
      && \text{(by IH (2) on the codomain fiber $c$, raising)}
  \end{align*}

  \emph{Clause 5 ($R_I$-coherence).} Unchanged, since the $R_I$-classes and
  the function value $f$ are level-independent.

  \emph{Term-predicate lowering (3).}
  Suppose $\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; \Pi_i(R_I, P_I, \textbf{El}_I, P_O)$
  and $\typing[\Gamma]{t}{S} \;\circledR\; f \in \Pi_j^{\textbf{El}}(R, R_I, P_I',
  \textbf{El}_I', \textbf{El}_O')$. We verify the four clauses of $\Pi_i^{\textbf{El}}$ at $t, f$.

  \emph{Clauses 1--3.}
  \begin{align*}
    &f \approx f \in R
      && \text{(by \Cref{def:pi-term-pred} clause 1 on hypothesis at level $j$)} \\
    &\typing[\Gamma]{t}{S}
      && \text{(by \Cref{def:pi-term-pred} clause 2 on hypothesis at level $j$)} \\
    &\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; \Pi_i(R_I, P_I, \textbf{El}_I, P_O)
      && \text{(by lemma's lowering hypothesis on $S$)}
  \end{align*}

  \emph{Clause 4 (application).}
  Let $\kweak[\Delta]{\phi}{\Gamma}$, $s, b, \ensuremath{\mathcal{D}} :: b \approx b \in R_I$ with
  $\typing[\Delta]{s}{S_1[\phi]} \;\circledR\; b \in \textbf{El}_I$.
  \begin{align*}
    &\typing[\Delta]{s}{S_1[\phi]} \;\circledR\; b \in \textbf{El}_I'
      && \text{(by IH (2) on $a$, raising)} \\
    &f \cdot b \searrow c
      && \text{(by hypothesis clause 4 at level $j$)} \\
    &\typing[\Delta]{(t[\phi])\;s}{S_2[\iota(\phi), s/x]}
      \;\circledR\; c \in \textbf{El}_O'(\ensuremath{\mathcal{D}})
      && \text{(by hypothesis clause 4 at level $j$)} \\
    &\typing[\Delta]{S_2[\iota(\phi), s/x]}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; P_O(\ensuremath{\mathcal{D}})
      && \text{(by \Cref{def:pi-type-pred} clause 3 on the} \\
    & && \text{level-$i$ type-predicate hypothesis)} \\
    &\typing[\Delta]{(t[\phi])\;s}{S_2[\iota(\phi), s/x]}
      \;\circledR\; c \in \textbf{El}_O(\ensuremath{\mathcal{D}})
      && \text{(by IH (3) on the codomain fiber $c$, lowering)}
  \end{align*}

By induction on $a \in \mathcal{U}_i^\ast$.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{G-Ne}]
    {{\uparrow}^A(e) \in \ensuremath{\mathrm{D}} \\
     P \Leftrightarrow \textsf{Neu}_i^e \\
     \textbf{El} \Leftrightarrow \textsf{Neu}_i^e}
    {{\uparrow}^A(e) \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El}}
  \end{mathpar}
  \emph{Type predicate (1).}
  Given $\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; \textsf{Neu}_i^e$
  and $\tyequiv[\Gamma]{S}{S'}{\ensuremath{\texttt{Ty}_{i}}}$ with $\typing[\Gamma]{S'}{\ensuremath{\texttt{Ty}_{i}}}$.
  For arbitrary $\kweak[\Delta]{\phi}{\Gamma}$:
  \begin{align*}
    &\exists u.\; \textsf{R}^{\textsf{Ne}}_{|\Delta|}(e) \searrow u \wedge
      \tyequiv[\Delta]{S[\phi]}{u}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by hypothesis on $S$)} \\
    &\tyequiv[\Delta]{S[\phi]}{S'[\phi]}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by \Cref{lem:wk-typing})} \\
    &\tyequiv[\Delta]{S'[\phi]}{u}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by symmetry and transitivity of judgmental equality)} \\
    &\typing[\Gamma]{S'}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; \textsf{Neu}_i^e
      && \text{(by \Cref{def:neu-type-pred})}
  \end{align*}

  \emph{Term predicate (2).}
  Given $\typing[\Gamma]{t}{S} \;\circledR\; {\uparrow}^A(w) \in \textsf{Neu}_i^e$
  and $\tyequiv[\Gamma]{t}{t'}{S}$ with $\typing[\Gamma]{t'}{S}$.
  For $\kweak[\Delta]{\phi}{\Gamma}$:
  \begin{align*}
    &\exists u.\; \textsf{R}^{\textsf{Ne}}_{|\Delta|}(w) \searrow u \wedge
      \tyequiv[\Delta]{t[\phi]}{u}{S[\phi]}
      && \text{(by hypothesis on $t$)} \\
    &\tyequiv[\Delta]{t[\phi]}{t'[\phi]}{S[\phi]}
      && \text{(by \Cref{lem:wk-typing})} \\
    &\tyequiv[\Delta]{t'[\phi]}{u}{S[\phi]}
      && \text{(by symmetry and transitivity)} \\
    &\typing[\Gamma]{t'}{S} \;\circledR\; {\uparrow}^A(w) \in \textsf{Neu}_i^e
      && \text{(by \Cref{def:neu-term-pred})}
  \end{align*}

  \emph{Type-side rewriting (3).}
  Given $\typing[\Gamma]{t}{S} \;\circledR\; {\uparrow}^A(w) \in \textsf{Neu}_i^e$
  and $\tyequiv[\Gamma]{S}{S'}{\ensuremath{\texttt{Ty}_{i}}}$ with $\typing[\Gamma]{t}{S'}$.
  For $\kweak[\Delta]{\phi}{\Gamma}$:
  \begin{align*}
    &\exists u.\; \textsf{R}^{\textsf{Ne}}_{|\Delta|}(w) \searrow u \wedge
      \tyequiv[\Delta]{t[\phi]}{u}{S[\phi]}
      && \text{(by hypothesis on $t$)} \\
    &\tyequiv[\Delta]{S[\phi]}{S'[\phi]}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by \Cref{lem:wk-typing})} \\
    &\tyequiv[\Delta]{t[\phi]}{u}{S'[\phi]}
      && \text{(by \textsc{Tm-Subsump} with the previous line)} \\
    &\typing[\Gamma]{t}{S'} \;\circledR\; {\uparrow}^A(w) \in \textsf{Neu}_i^e
      && \text{(by \Cref{def:neu-term-pred}, using the type predicate at $S'$
        from (1))}
  \end{align*}

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{G-Nat}]
    {P \Leftrightarrow \textsf{Nat}_i \\
     \textbf{El} \Leftrightarrow \textsf{Nat}_i}
    {N \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El}}
  \end{mathpar}
  \emph{Type predicate (1).}
  \begin{align*}
    &\tyequiv[\Gamma]{S}{\ensuremath{\texttt{Nat}}}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by \Cref{def:nat-type-pred} on hypothesis)} \\
    &\tyequiv[\Gamma]{S'}{S}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by symmetry of $\tyequiv[\Gamma]{S}{S'}{\ensuremath{\texttt{Ty}_{i}}}$)} \\
    &\tyequiv[\Gamma]{S'}{\ensuremath{\texttt{Nat}}}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by transitivity of judgmental equality)} \\
    &\typing[\Gamma]{S'}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; \textsf{Nat}_i
      && \text{(by \Cref{def:nat-type-pred})}
  \end{align*}

  \emph{Term predicate (2).}
  Given $\typing[\Gamma]{t}{S} \;\circledR\; b \in \textsf{Nat}_i$ and
  $\tyequiv[\Gamma]{t}{t'}{S}$. By inner induction on the derivation
  $b \in \textsf{Nat}_i$ at $t$:
  \begin{itemize}
  \@idxitem[Sub-case]
    \begin{mathpar}
      \inferrule[\textsc{GN-Ze}]
      {\tyequiv[\Gamma]{t}{\textsf{zero}}{S}}
      {\typing[\Gamma]{t}{S} \;\circledR\; \texttt{ze} \in \textsf{Nat}}
    \end{mathpar}
    \begin{align*}
      &\tyequiv[\Gamma]{t'}{t}{S}
        && \text{(by symmetry of $\tyequiv[\Gamma]{t}{t'}{S}$)} \\
      &\tyequiv[\Gamma]{t'}{\textsf{zero}}{S}
        && \text{(by transitivity)} \\
      &\typing[\Gamma]{t'}{S} \;\circledR\; \texttt{ze} \in \textsf{Nat}
        && \text{(by \textsc{GN-Ze})}
    \end{align*}
  \@idxitem[Sub-case]
    \begin{mathpar}
      \inferrule[\textsc{GN-Su}]
      {\typing[\Gamma]{t_0}{S} \;\circledR\; b' \in \textsf{Nat} \\
       \tyequiv[\Gamma]{t}{\textsf{succ}~t_0}{S}}
      {\typing[\Gamma]{t}{S} \;\circledR\; \texttt{su}(b') \in \textsf{Nat}}
    \end{mathpar}
    \begin{align*}
      &\tyequiv[\Gamma]{t'}{\textsf{succ}~t_0}{S}
        && \text{(by symmetry/transitivity, as above)} \\
      &\typing[\Gamma]{t_0}{S} \;\circledR\; b' \in \textsf{Nat}
        && \text{(unchanged, hypothesis on $t_0$)} \\
      &\typing[\Gamma]{t'}{S} \;\circledR\; \texttt{su}(b') \in \textsf{Nat}
        && \text{(by \textsc{GN-Su})}
    \end{align*}
  \@idxitem[Sub-case]
    \begin{mathpar}
      \inferrule[\textsc{GN-Ne}]
      {\typing[\Gamma]{t}{S} \;\circledR\; w \in \textsf{Ne}_i^N}
      {\typing[\Gamma]{t}{S} \;\circledR\; {\uparrow}^N(w) \in \textsf{Nat}}
    \end{mathpar}
    \begin{align*}
      &\typing[\Gamma]{t'}{S} \;\circledR\; w \in \textsf{Ne}_i^N
        && \text{(by the \textsc{G-Ne} case (2) above on the neutral predicate)} \\
      &\typing[\Gamma]{t'}{S} \;\circledR\; {\uparrow}^N(w) \in \textsf{Nat}
        && \text{(by \textsc{GN-Ne})}
    \end{align*}
  \end{itemize}

  \emph{Type-side rewriting (3).}
  Given $\tyequiv[\Gamma]{S}{S'}{\ensuremath{\texttt{Ty}_{i}}}$. Then $\tyequiv[\Gamma]{S'}{\ensuremath{\texttt{Nat}}}{\ensuremath{\texttt{Ty}_{i}}}$
  by symmetry/transitivity with $\tyequiv[\Gamma]{S}{\ensuremath{\texttt{Nat}}}{\ensuremath{\texttt{Ty}_{i}}}$. The
  $\textsf{Nat}$-derivation transfers to $\typing[\Gamma]{t}{S'}$ since each
  sub-case's hypotheses involve $S$ only through $\tyequiv[\Gamma]{t}{w}{S}$
  for some $w$, which becomes $\tyequiv[\Gamma]{t}{w}{S'}$ via \textsc{Tm-Subsump}.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{G-Univ}]
    {j < i \\
     P \Leftrightarrow \textsf{Univ}_{i,j} \\
     \textbf{El} \Leftrightarrow \textsf{Univ}_{i,j}^{\textbf{El}}}
    {U_j \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El}}
  \end{mathpar}
  \emph{Type predicate (1).}
  \begin{align*}
    &\tyequiv[\Gamma]{S}{\ensuremath{\texttt{Ty}_{j}}}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by \Cref{def:univ-type-pred})} \\
    &\tyequiv[\Gamma]{S'}{\ensuremath{\texttt{Ty}_{j}}}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by symmetry/transitivity with the assumed equality)} \\
    &\typing[\Gamma]{S'}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; \textsf{Univ}_{i,j}
      && \text{(by \Cref{def:univ-type-pred})}
  \end{align*}

  \emph{Term predicate (2).}
  Given $\typing[\Gamma]{t}{S} \;\circledR\; b \in \textsf{Univ}_{i,j}^{\textbf{El}}$
  and $\tyequiv[\Gamma]{t}{t'}{S}$. By \Cref{def:univ-term-pred},
  $b \in \mathcal{U}_j^\ast \searrow P_b \searrow \textbf{El}_b$ with
  $\typing[\Gamma]{t}{\ensuremath{\texttt{Ty}_{j}}} \;\circledR\; P_b$ and
  $\tyequiv[\Gamma]{S}{\ensuremath{\texttt{Ty}_{j}}}{\ensuremath{\texttt{Ty}_{i}}}$.
  \begin{align*}
    &\tyequiv[\Gamma]{t}{t'}{\ensuremath{\texttt{Ty}_{j}}}
      && \text{(by judgmental-equality conversion under
        $\tyequiv[\Gamma]{S}{\ensuremath{\texttt{Ty}_{j}}}{\ensuremath{\texttt{Ty}_{i}}}$)} \\
    &\typing[\Gamma]{t'}{\ensuremath{\texttt{Ty}_{j}}} \;\circledR\; P_b
      && \text{(by IH on $P_b$ at level $j$, type-predicate part)} \\
    &\typing[\Gamma]{t'}{S} \;\circledR\; b \in \textsf{Univ}_{i,j}^{\textbf{El}}
      && \text{(by \Cref{def:univ-term-pred} with $\tyequiv[\Gamma]{S}{\ensuremath{\texttt{Ty}_{j}}}{\ensuremath{\texttt{Ty}_{i}}}$)}
  \end{align*}

  \emph{Type-side rewriting (3).}
  Given $\tyequiv[\Gamma]{S}{S'}{\ensuremath{\texttt{Ty}_{i}}}$. Then
  $\tyequiv[\Gamma]{S'}{\ensuremath{\texttt{Ty}_{j}}}{\ensuremath{\texttt{Ty}_{i}}}$ by transitivity, and the universe
  term predicate at $S'$ holds with the same data $b, P_b, \textbf{El}_b$.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{G-Pi}]
    {a \in \mathcal{U}_i^\ast \searrow P_I \searrow \textbf{El}_I \\
     a \approx a \in \mathcal{U}_i \searrow R_I \\\\
     \forall\, \ensuremath{\mathcal{D}} :: b \approx b \in R_I,\; c.\;
       \ensuremath{\llbracket T \rrbracket(\rho, b/x)} \searrow c \implies
       c \in \mathcal{U}_i^\ast \searrow P_O(\ensuremath{\mathcal{D}}) \searrow \textbf{El}_O(\ensuremath{\mathcal{D}}) \\\\
     \Pi(a, T, \rho) \approx \Pi(a, T, \rho) \in \mathcal{U}_i \searrow R \\\\
     P \Leftrightarrow \Pi_i(\ldots) \\
     \textbf{El} \Leftrightarrow \Pi_i^{\textbf{El}}(\ldots)}
    {\Pi(a, T, \rho) \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El}}
  \end{mathpar}
  \emph{Type predicate (1).}
  Given $\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; \Pi_i(R_I, P_I, \textbf{El}_I, P_O)$
  and $\tyequiv[\Gamma]{S}{S'}{\ensuremath{\texttt{Ty}_{i}}}$. By \Cref{def:pi-type-pred} clause~1,
  $\tyequiv[\Gamma]{S}{\Pi(x:S_1).\,S_2}{\ensuremath{\texttt{Ty}_{i}}}$ for some $S_1, S_2$.
  \begin{align*}
    &\tyequiv[\Gamma]{S'}{S}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by symmetry of $\tyequiv[\Gamma]{S}{S'}{\ensuremath{\texttt{Ty}_{i}}}$)} \\
    &\tyequiv[\Gamma]{S'}{\Pi(x:S_1).\,S_2}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by transitivity with the previous line)}
  \end{align*}
  Clauses 2--3 of $\Pi_i$ for $S'$ at any $\kweak[\Delta]{\phi}{\Gamma}$ require
  the same data on $S_1[\phi]$ and $S_2[\iota(\phi), s/x]$ as the original
  predicate; these are exactly the data already satisfied by hypothesis on
  $S$, since the data depend on $S_1, S_2$ rather than on the outer type $S$.

  \emph{Term predicate (2).}
  Given $\typing[\Gamma]{t}{S} \;\circledR\; f \in
  \Pi_i^{\textbf{El}}(R, R_I, P_I, \textbf{El}_I, \textbf{El}_O)$ and $\tyequiv[\Gamma]{t}{t'}{S}$ with
  $\typing[\Gamma]{t'}{S}$. We verify the four clauses of \Cref{def:pi-term-pred}
  at $t'$ and value $f$.
  \begin{enumerate}
  \@idxitem Self-relatedness $f \approx f \in R$ does not depend on $t$.
  \@idxitem $R_I$-coherence: a property of $f$, not of $t$.
  \@idxitem Type-readback: clause~3 of $\Pi_i^{\textbf{El}}$ matches clause~3 of $\Pi_i$ on
    $S$ at $t$, and is preserved by part (1) above on $S'$ unchanged.
  \@idxitem Application: let $\kweak[\Delta]{\phi}{\Gamma}$, $s, b, \ensuremath{\mathcal{D}} :: b \approx b \in R_I$
    with $\typing[\Delta]{s}{S_1[\phi]} \;\circledR\; b \in \textbf{El}_I$.
    \begin{align*}
      &f \cdot b \searrow c
        && \text{(by hypothesis clause 4 on $f$)} \\
      &\typing[\Delta]{(t[\phi])\;s}{S_2[\iota(\phi), s/x]}
        \;\circledR\; c \in \textbf{El}_O(\ensuremath{\mathcal{D}})
        && \text{(by hypothesis clause 4)} \\
      &\tyequiv[\Delta]{t[\phi]}{t'[\phi]}{S[\phi]}
        && \text{(by \Cref{lem:wk-typing})} \\
      &\tyequiv[\Delta]{(t[\phi])\;s}{(t'[\phi])\;s}{S_2[\iota(\phi), s/x]}
        && \text{(by \textsc{App-Cong} on the previous line,} \\
    & && \text{after observing that $S[\phi]$ on the function side} \\
    & && \text{reduces to $\Pi(x:S_1[\phi]).\,(S_2[q(\phi)])$)} \\
      &\typing[\Delta]{(t'[\phi])\;s}{S_2[\iota(\phi), s/x]}
        \;\circledR\; c \in \textbf{El}_O(\ensuremath{\mathcal{D}})
        && \text{(by IH (2) on $\textbf{El}_O(\ensuremath{\mathcal{D}})$ applied} \\
    & && \text{to the equality above)}
    \end{align*}
  \@idxitem $R_I$-coherence under application: a property of $f$ via clauses 4
    parametrically; transfers from $t$ to $t'$ alongside clause 4.
  \end{enumerate}

  \emph{Type-side rewriting (3).}
  Given $\tyequiv[\Gamma]{S}{S'}{\ensuremath{\texttt{Ty}_{i}}}$ with $\typing[\Gamma]{t}{S'}$.
  Clauses 1, 4 of $\Pi_i^{\textbf{El}}$ depend on $S$ only through $S_2[\iota(\phi), s/x]$
  (the codomain instantiation), which is invariant under the equation
  $S \approx S'$. Clause 3's $\Pi$-shape readback transfers via part (1)
  applied to the universe-equation. Hence
  $\typing[\Gamma]{t}{S'} \;\circledR\; f \in \Pi_i^{\textbf{El}}$.

\label{lem:gluing-univ-equiv}
  If $a \approx a' \in \mathcal{U}_i \searrow R$ and $a \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El}$,
  then $a' \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El}$.

By induction on $a \approx a' \in \mathcal{U}_i$.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{U-Ne}]
    {b \approx b' \in \textsf{Ne} \\ R \Leftrightarrow \textsf{Neu}}
    {{\uparrow}^A(b) \approx {\uparrow}^{A'}(b') \in \mathcal{U}_i \searrow R}
  \end{mathpar}
  $a = {\uparrow}^A(b)$, $a' = {\uparrow}^{A'}(b')$.
  $a \in \mathcal{U}_i^\ast$ via \textsc{G-Ne} with $P \Leftrightarrow \textbf{El} \Leftrightarrow
  \textsf{Neu}_i^b$.
  By definition of $\textsf{Ne}$ ($b \approx b' \in \textsf{Ne}$), readbacks of $b$ and $b'$
  coincide, so $\textsf{Neu}_i^b \Leftrightarrow \textsf{Neu}_i^{b'}$.
  Hence $a' \in \mathcal{U}_i^\ast$ via \textsc{G-Ne} with the same predicates.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{U-Univ}]
    {j < i \\ R \Leftrightarrow \mathcal{U}_j}
    {U_j \approx U_j \in \mathcal{U}_i \searrow R}
  \end{mathpar}
  $a = a' = U_j$; the conclusion is immediate.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{U-Nat}]
    {R \Leftrightarrow \textsf{Nat}}
    {N \approx N \in \mathcal{U}_i \searrow R}
  \end{mathpar}
  $a = a' = N$; immediate.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{U-Pi}]
    {a_I \approx a_I' \in \mathcal{U}_i \searrow R_I \\
     R_I \text{ is a PER} \\\\
     \forall\, \ensuremath{\mathcal{D}} :: b \approx b' \in R_I.\;
       \ensuremath{\llbracket T \rrbracket(\rho, b/x)} \approx \ensuremath{\llbracket T' \rrbracket(\rho', b'/x)} \in \mathcal{U}_i \searrow R_O(\ensuremath{\mathcal{D}}) \\\\
     \forall\, f, f'.\; f \approx f' \in R \;\leftrightarrow\;
       (\forall\, \ensuremath{\mathcal{D}} :: b \approx b' \in R_I.\;
        f \cdot b \approx f' \cdot b' \in R_O(\ensuremath{\mathcal{D}}))}
    {\Pi(a_I, T, \rho) \approx \Pi(a_I', T', \rho') \in \mathcal{U}_i \searrow R}
  \end{mathpar}
  $a = \Pi(a_I, T, \rho)$, $a' = \Pi(a_I', T', \rho')$.
  $a \in \mathcal{U}_i^\ast$ via \textsc{G-Pi} provides inner data
  $a_I \in \mathcal{U}_i^\ast \searrow P_I \searrow \textbf{El}_I$ and a codomain clause:
  for any $\ensuremath{\mathcal{D}} :: b \approx b \in R_I$ and $c$ with $\ensuremath{\llbracket T \rrbracket(\rho, b/x)}
  \searrow c$, $c \in \mathcal{U}_i^\ast \searrow P_O(\ensuremath{\mathcal{D}}) \searrow \textbf{El}_O(\ensuremath{\mathcal{D}})$.
  \begin{align*}
    &a_I \approx a_I' \in \mathcal{U}_i \searrow R_I
      && \text{(from the \textsc{U-Pi} premise)} \\
    &a_I' \in \mathcal{U}_i^\ast \searrow P_I \searrow \textbf{El}_I
      && \text{(by IH on $a_I \approx a_I' \in \mathcal{U}_i$ and $a_I \in \mathcal{U}_i^\ast$)} \\
    &\forall \ensuremath{\mathcal{D}}' :: b' \approx b' \in R_I, c'.\;
      \ensuremath{\llbracket T' \rrbracket(\rho', b'/x)} \searrow c' \\
    & \quad \implies c' \approx c' \in \mathcal{U}_i
      && \text{(by symmetry/transitivity from the \textsc{U-Pi} premise)} \\
    &\forall \ensuremath{\mathcal{D}}' :: b' \approx b' \in R_I, c'.\;
      \ensuremath{\llbracket T' \rrbracket(\rho', b'/x)} \searrow c' \\
    & \quad \implies
      c' \in \mathcal{U}_i^\ast \searrow P_O(\ensuremath{\mathcal{D}}') \searrow \textbf{El}_O(\ensuremath{\mathcal{D}}')
      && \text{(by IH on the codomain fibers,} \\
    & && \text{transporting from $c \approx c'$)} \\
    &\Pi(a_I', T', \rho') \approx \Pi(a_I', T', \rho') \in \mathcal{U}_i \searrow R
      && \text{(by \Cref{lem:univ-sym,lem:univ-trans})} \\
    &\Pi(a_I', T', \rho') \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El}
      && \text{(by \textsc{G-Pi} at the previous data, with the same $P, \textbf{El}$)}
  \end{align*}

\label{lem:per-implies-gluing}
  If $a \approx a \in \mathcal{U}_i \searrow R$, then there exist $P, \textbf{El}$ with
  $a \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El}$.

By induction on $a \approx a \in \mathcal{U}_i$.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{U-Ne}]
    {b \approx b \in \textsf{Ne} \\ R \Leftrightarrow \textsf{Neu}}
    {{\uparrow}^A(b) \approx {\uparrow}^A(b) \in \mathcal{U}_i \searrow R}
  \end{mathpar}
  \begin{align*}
    &{\uparrow}^A(b) \in \mathcal{U}_i^\ast
      \searrow \textsf{Neu}_i^b
      \searrow \textsf{Neu}_i^b
      && \text{(by \textsc{G-Ne} on $b$)}
  \end{align*}

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{U-Univ}]
    {j < i \\ R \Leftrightarrow \mathcal{U}_j}
    {U_j \approx U_j \in \mathcal{U}_i \searrow R}
  \end{mathpar}
  \begin{align*}
    &U_j \in \mathcal{U}_i^\ast
      \searrow \textsf{Univ}_{i,j}
      \searrow \textsf{Univ}_{i,j}^{\textbf{El}}
      && \text{(by \textsc{G-Univ} at $j < i$)}
  \end{align*}

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{U-Nat}]
    {R \Leftrightarrow \textsf{Nat}}
    {N \approx N \in \mathcal{U}_i \searrow R}
  \end{mathpar}
  \begin{align*}
    &N \in \mathcal{U}_i^\ast \searrow \textsf{Nat}_i \searrow \textsf{Nat}_i
      && \text{(by \textsc{G-Nat})}
  \end{align*}

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{U-Pi}]
    {a_I \approx a_I \in \mathcal{U}_i \searrow R_I \\
     R_I \text{ is a PER} \\\\
     \forall\, \ensuremath{\mathcal{D}} :: b \approx b \in R_I.\;
       \ensuremath{\llbracket T \rrbracket(\rho, b/x)} \approx \ensuremath{\llbracket T \rrbracket(\rho, b/x)} \in \mathcal{U}_i
         \searrow R_O(\ensuremath{\mathcal{D}}) \\\\
     \forall\, f, f'.\; f \approx f' \in R \;\leftrightarrow\;
       (\forall\, \ensuremath{\mathcal{D}} :: b \approx b' \in R_I.\;
        f \cdot b \approx f' \cdot b' \in R_O(\ensuremath{\mathcal{D}}))}
    {\Pi(a_I, T, \rho) \approx \Pi(a_I, T, \rho) \in \mathcal{U}_i \searrow R}
  \end{mathpar}
  \begin{align*}
    &a_I \in \mathcal{U}_i^\ast \searrow P_I \searrow \textbf{El}_I
      && \tag{by IH} \\
    &\forall\, \ensuremath{\mathcal{D}} :: b \approx b \in R_I,\; c.\;
      \ensuremath{\llbracket T \rrbracket(\rho, b/x)} \searrow c \\
    & \quad \implies c \in \mathcal{U}_i^\ast
        \searrow P_O(\ensuremath{\mathcal{D}}) \searrow \textbf{El}_O(\ensuremath{\mathcal{D}})
      && \tag{by IH} \\
    &\Pi(a_I, T, \rho) \in \mathcal{U}_i^\ast
      \searrow \Pi_i(R_I, P_I, \textbf{El}_I, P_O)
      \searrow \Pi_i^{\textbf{El}}(R, R_I, P_I, \textbf{El}_I, \textbf{El}_O)
      && \text{(by \textsc{G-Pi})}
  \end{align*}

By induction on $a \in \mathcal{U}_i^\ast$.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{G-Ne}]
    {{\uparrow}^A(e) \in \ensuremath{\mathrm{D}} \\
     P \Leftrightarrow \textsf{Neu}_i^e \\
     \textbf{El} \Leftrightarrow \textsf{Neu}_i^e}
    {{\uparrow}^A(e) \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El}}
  \end{mathpar}
  $R \Leftrightarrow \textsf{Neu}$. From $\textbf{El} \Leftrightarrow \textsf{Neu}_i^e$,
  $b = {\uparrow}^{A_0}(w)$ with $w \approx w \in \textsf{Ne}$.
  $b \approx b' \in R \Leftrightarrow \textsf{Neu}$ gives
  $b' = {\uparrow}^{A_0'}(w')$ with $w \approx w' \in \textsf{Ne}$.
  \begin{align*}
    &\forall \kweak[\Delta]{\phi}{\Gamma}.\;
      \exists u.\; \textsf{R}^{\textsf{Ne}}_{|\Delta|}(w) \searrow u \wedge
      \tyequiv[\Delta]{t[\phi]}{u}{S[\phi]}
      && \text{(hypothesis on $b = {\uparrow}^{A_0}(w)$)} \\
    &\textsf{R}^{\textsf{Ne}}_{|\Delta|}(w') \searrow u
      && \text{(by definition of $\textsf{Ne}$, $w \approx w'$ read back to the same $u$)} \\
    &\typing[\Gamma]{t}{S} \;\circledR\; {\uparrow}^{A_0'}(w') \in \textsf{Neu}_i^e
      && \text{(by \Cref{def:neu-term-pred})}
  \end{align*}

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{G-Nat}]
    {P \Leftrightarrow \textsf{Nat}_i \\
     \textbf{El} \Leftrightarrow \textsf{Nat}_i}
    {N \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El}}
  \end{mathpar}
  $R \Leftrightarrow \textsf{Nat}$, and $b \approx b' \in \textsf{Nat}$.
  By inner induction on the $\textsf{Nat}$ derivation (\Cref{def:per-nat}).

  \medskip\noindent
  \textbf{Sub-case}
  \begin{mathpar}
    \inferrule[\textsc{Nat-Ze}]
    { }
    {\texttt{ze} \approx \texttt{ze} \in \textsf{Nat}}
  \end{mathpar}
  $b = b' = \texttt{ze}$; the predicate is unchanged.

  \medskip\noindent
  \textbf{Sub-case}
  \begin{mathpar}
    \inferrule[\textsc{Nat-Su}]
    {b_0 \approx b_0' \in \textsf{Nat}}
    {\texttt{su}(b_0) \approx \texttt{su}(b_0') \in \textsf{Nat}}
  \end{mathpar}
  $b = \texttt{su}(b_0)$, $b' = \texttt{su}(b_0')$. The $\textsf{Nat}$-predicate derivation
  for $b$ uses \textsc{GN-Su} from a derivation for some $t_0$ at $b_0$:
  \begin{align*}
    &\typing[\Gamma]{t_0}{S} \;\circledR\; b_0 \in \textsf{Nat}
      && \text{(from the \textsc{GN-Su} premise)} \\
    &\tyequiv[\Gamma]{t}{\textsf{succ}~t_0}{S}
      && \text{(from the \textsc{GN-Su} premise)} \\
    &\typing[\Gamma]{t_0}{S} \;\circledR\; b_0' \in \textsf{Nat}
      && \text{(by inner IH)} \\
    &\typing[\Gamma]{t}{S} \;\circledR\; \texttt{su}(b_0') \in \textsf{Nat}
      && \text{(by \textsc{GN-Su} repackaging)}
  \end{align*}

  \medskip\noindent
  \textbf{Sub-case}
  \begin{mathpar}
    \inferrule[\textsc{Nat-Ne}]
    {e \approx e' \in \textsf{Ne}}
    {{\uparrow}^N(e) \approx {\uparrow}^N(e') \in \textsf{Nat}}
  \end{mathpar}
  $b = {\uparrow}^N(e)$, $b' = {\uparrow}^N(e')$. The $\textsf{Nat}$-predicate
  derivation for $b$ uses \textsc{GN-Ne} from a neutral predicate at $e$:
  \begin{align*}
    &\typing[\Gamma]{t}{S} \;\circledR\; e \in \textsf{Ne}_i^N
      && \text{(from the \textsc{GN-Ne} premise)} \\
    &\typing[\Gamma]{t}{S} \;\circledR\; e' \in \textsf{Ne}_i^N
      && \text{(by readback equality: $e \approx e' \in \textsf{Ne}$ implies
        $\textsf{R}^{\textsf{Ne}}(e) = \textsf{R}^{\textsf{Ne}}(e')$ at every depth)} \\
    &\typing[\Gamma]{t}{S} \;\circledR\; {\uparrow}^N(e') \in \textsf{Nat}
      && \text{(by \textsc{GN-Ne})}
  \end{align*}

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{G-Univ}]
    {j < i \\
     P \Leftrightarrow \textsf{Univ}_{i,j} \\
     \textbf{El} \Leftrightarrow \textsf{Univ}_{i,j}^{\textbf{El}}}
    {U_j \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El}}
  \end{mathpar}
  $R \Leftrightarrow \mathcal{U}_j$. By \Cref{def:univ-term-pred}, $b \in \mathcal{U}_j^\ast
  \searrow P_b \searrow \textbf{El}_b$ with $\typing[\Gamma]{t}{\ensuremath{\texttt{Ty}_{j}}} \;\circledR\; P_b$,
  and $b \approx b' \in \mathcal{U}_j$.
  \begin{align*}
    &b' \in \mathcal{U}_j^\ast \searrow P_b \searrow \textbf{El}_b
      && \text{(by \Cref{lem:gluing-univ-equiv} at level $j$ on $b \approx b'$)} \\
    &\typing[\Gamma]{t}{\ensuremath{\texttt{Ty}_{j}}} \;\circledR\; P_b
      && \text{(unchanged from hypothesis)} \\
    &\typing[\Gamma]{t}{S} \;\circledR\; b' \in \textsf{Univ}_{i,j}^{\textbf{El}}
      && \text{(by \Cref{def:univ-term-pred} with the
        previous lines} \\
    & && \text{and $\tyequiv[\Gamma]{S}{\ensuremath{\texttt{Ty}_{j}}}{\ensuremath{\texttt{Ty}_{i}}}$)}
  \end{align*}

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{G-Pi}]
    {a \in \mathcal{U}_i^\ast \searrow P_I \searrow \textbf{El}_I \\
     a \approx a \in \mathcal{U}_i \searrow R_I \\\\
     \forall\, \ensuremath{\mathcal{D}} :: b_0 \approx b_0 \in R_I,\; c.\;
       \ensuremath{\llbracket T \rrbracket(\rho, b_0/x)} \searrow c \implies
       c \in \mathcal{U}_i^\ast \searrow P_O(\ensuremath{\mathcal{D}}) \searrow \textbf{El}_O(\ensuremath{\mathcal{D}}) \\\\
     \Pi(a, T, \rho) \approx \Pi(a, T, \rho) \in \mathcal{U}_i \searrow R \\\\
     P \Leftrightarrow \Pi_i(\ldots) \\
     \textbf{El} \Leftrightarrow \Pi_i^{\textbf{El}}(\ldots)}
    {\Pi(a, T, \rho) \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El}}
  \end{mathpar}
  Hypothesis: $\typing[\Gamma]{t}{S} \;\circledR\; f \in
  \Pi_i^{\textbf{El}}(R, R_I, P_I, \textbf{El}_I, \textbf{El}_O)$ and $f \approx f' \in R$. We verify
  the four clauses of \Cref{def:pi-term-pred} at $f'$.
  \begin{enumerate}
  \@idxitem Self-relatedness $f' \approx f' \in R$: by PER symmetry and transitivity
    on $f \approx f' \in R$ (\Cref{lem:univ-sym,lem:univ-trans}).
  \@idxitem $R_I$-coherence of $f'$: clause (2) is a property of $R$-classes; since
    $f, f'$ are in the same $R$-class, the coherence transfers.
  \@idxitem Type-readback of $f'$: clause (3) depends only on $S$ and the
    $\Pi$-shape, not on the function value, so it transfers verbatim.
  \@idxitem Application: let $\kweak[\Delta]{\phi}{\Gamma}$, $s, b_0, \ensuremath{\mathcal{D}} :: b_0 \approx b_0 \in R_I$
    with $\typing[\Delta]{s}{S_1[\phi]} \;\circledR\; b_0 \in \textbf{El}_I$.
    \begin{align*}
      &f \cdot b_0 \searrow c
        && \text{(by hypothesis on $f$, clause (4))} \\
      &\typing[\Delta]{(t[\phi])\;s}{S_2[\iota(\phi), s/x]}
        \;\circledR\; c \in \textbf{El}_O(\ensuremath{\mathcal{D}})
        && \text{(by hypothesis on $f$, clause (4))} \\
      &f \cdot b_0 \approx f' \cdot b_0 \in R_O(\ensuremath{\mathcal{D}})
        && \text{(by the application clause of $R$ for $f \approx f' \in R$
          at $b_0 \approx b_0 \in R_I$)} \\
      &\exists c'.\; f' \cdot b_0 \searrow c',\; c \approx c' \in R_O(\ensuremath{\mathcal{D}})
        && \text{(by determinism of evaluation and the previous line)} \\
      &\typing[\Delta]{(t[\phi])\;s}{S_2[\iota(\phi), s/x]}
        \;\circledR\; c' \in \textbf{El}_O(\ensuremath{\mathcal{D}})
        && \text{(by IH on the codomain fiber $\textbf{El}_O(\ensuremath{\mathcal{D}})$, applied to $c \approx c'$)}
    \end{align*}
  \@idxitem $R_I$-coherence under application: a property of the $R$-class on the
    codomain; transfers as in clauses (1)--(2).
  \end{enumerate}

By induction on $a_1 \mathrel{<:_i} a_2$.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{$<$:-Ne}]
    {b \approx b' \in \textsf{Ne}}
    {{\uparrow}^A(b) \mathrel{<:_i} {\uparrow}^{A'}(b')}
  \end{mathpar}
  $P_1 \Leftrightarrow \textsf{Neu}_i^b$, $P_2 \Leftrightarrow \textsf{Neu}_i^{b'}$.
  The hypothesis $b \approx b' \in \textsf{Ne}$ implies $\textsf{R}^{\textsf{Ne}}_n(b)$ and $\textsf{R}^{\textsf{Ne}}_n(b')$
  produce the same syntactic neutral at every depth.
  \begin{align*}
    &\textsf{R}^{\textsf{Ne}}_{|\Gamma|}(b) \searrow u,\;
      \tyequiv[\Gamma]{S_1}{u}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by \Cref{def:neu-type-pred} on $S_1$ at $\phi = \ensuremath{\textsf{id}}$)} \\
    &\textsf{R}^{\textsf{Ne}}_{|\Gamma|}(b') \searrow u
      && \text{(by $b \approx b' \in \textsf{Ne}$, same readback)} \\
    &\tyequiv[\Gamma]{S_2}{u}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by \Cref{def:neu-type-pred} on $S_2$ at $\phi = \ensuremath{\textsf{id}}$)} \\
    &\tyequiv[\Gamma]{S_1}{S_2}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by symmetry/transitivity of judgmental equality)} \\
    &\subty[\Gamma]{S_1}{S_2}
      && \text{(by \textsc{Sub-Eq} on the previous line)}
  \end{align*}

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{$<$:-Univ}]
    {j \le k \\ k < i}
    {U_j \mathrel{<:_i} U_k}
  \end{mathpar}
  $P_1 \Leftrightarrow \textsf{Univ}_{i,j}$, $P_2 \Leftrightarrow
  \textsf{Univ}_{i,k}$.
  \begin{align*}
    &\tyequiv[\Gamma]{S_1}{\ensuremath{\texttt{Ty}_{j}}}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by \Cref{def:univ-type-pred} on $\textsf{Univ}_{i,j}$)} \\
    &\tyequiv[\Gamma]{S_2}{\ensuremath{\texttt{Ty}_{k}}}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by \Cref{def:univ-type-pred} on $\textsf{Univ}_{i,k}$)} \\
    &\subty[\Gamma]{\ensuremath{\texttt{Ty}_{j}}}{\ensuremath{\texttt{Ty}_{k}}}
      && \text{(by \textsc{Sub-Univ} from $j \le k$)} \\
    &\subty[\Gamma]{S_1}{S_2}
      && \text{(by \textsc{Sub-Trans} via the equalities and the previous line)}
  \end{align*}

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{$<$:-Nat}]
    { }
    {N \mathrel{<:_i} N}
  \end{mathpar}
  $P_1 \Leftrightarrow P_2 \Leftrightarrow \textsf{Nat}_i$.
  \begin{align*}
    &\tyequiv[\Gamma]{S_1}{\ensuremath{\texttt{Nat}}}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by \Cref{def:nat-type-pred} on $S_1$)} \\
    &\tyequiv[\Gamma]{S_2}{\ensuremath{\texttt{Nat}}}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by \Cref{def:nat-type-pred} on $S_2$)} \\
    &\tyequiv[\Gamma]{S_1}{S_2}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by symmetry/transitivity through $\ensuremath{\texttt{Nat}}$)} \\
    &\subty[\Gamma]{S_1}{S_2}
      && \text{(by \textsc{Sub-Eq})}
  \end{align*}

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{$<$:-Pi}]
    {A \approx A' \in \mathcal{U}_i \searrow R_I \\
     \forall\, \ensuremath{\mathcal{D}} :: a \approx a' \in R_I.\;
       \ensuremath{\llbracket T \rrbracket(\rho, a/x)} \mathrel{<:_i} \ensuremath{\llbracket T' \rrbracket(\rho', a'/x)} \\\\
     \Pi(A, T, \rho) \approx \Pi(A, T, \rho) \in \mathcal{U}_i \\
     \Pi(A', T', \rho') \approx \Pi(A', T', \rho') \in \mathcal{U}_i}
    {\Pi(A, T, \rho) \mathrel{<:_i} \Pi(A', T', \rho')}
  \end{mathpar}
  $P_1 \Leftrightarrow \Pi_i(R_I, P_I, \textbf{El}_I, P_O)$,
  $P_2 \Leftrightarrow \Pi_i(R_I', P_I', \textbf{El}_I', P_O')$.
  The domain PERs are related by \emph{equality}
  ($A \approx A' \in \mathcal{U}_i \searrow R_I$, so $R_I = R_I'$ via
  \Cref{lem:univ-functional}; correspondingly $P_I \Leftrightarrow P_I'$,
  $\textbf{El}_I \Leftrightarrow \textbf{El}_I'$ via \Cref{lem:gluing-univ-equiv}).

  Given $\typing[\Gamma]{S_1}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; \Pi_i(\ldots)$ at shape
  $\Pi(x:S_{1,1}).\,S_{1,2}$ and similarly $S_2$ at $\Pi(x:S_{2,1}).\,S_{2,2}$
  (both by \Cref{def:pi-type-pred} clause 1).
  \begin{align*}
    &\typing[\Gamma]{S_{1,1}}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; P_I
      && \text{(by \Cref{def:pi-type-pred} clause 2 on $S_1$ at $\phi = \ensuremath{\textsf{id}}$)} \\
    &\typing[\Gamma]{S_{2,1}}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; P_I
      && \text{(symmetrically on $S_2$, using $P_I' \Leftrightarrow P_I$)} \\
    &\tyequiv[\Gamma]{S_{1,1}}{S_{2,1}}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by \Cref{lem:gluing-functional} on the two predicates at $a = A$)} \\
    &\subty[\Gamma, x:S_{1,1}]{S_{1,2}}{S_{2,2}}
      && \text{(by IH on the codomain subtyping at fresh variable $x$ at $A$)} \\
    &\subty[\Gamma]{\Pi(x:S_{1,1}).\,S_{1,2}}{\Pi(x:S_{2,1}).\,S_{2,2}}
      && \text{(by \textsc{Sub-Pi})} \\
    &\subty[\Gamma]{S_1}{S_2}
      && \text{(by \textsc{Sub-Eq} with the $\Pi$-shape equalities)}
  \end{align*}

By induction on $a_1 \mathrel{<:_i} a_2$. Each case extracts the type
  predicate at $S_1$ from the term predicate (via the relevant
  $\textbf{El}$-definition) and then applies \Cref{lem:gluing-subty-typ} to obtain
  $\subty[\Gamma]{S_1}{S_2}$.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{$<$:-Ne}]
    {b \approx b' \in \textsf{Ne}}
    {{\uparrow}^A(b) \mathrel{<:_i} {\uparrow}^{A'}(b')}
  \end{mathpar}
  $P_1 \Leftrightarrow \textbf{El}_1 \Leftrightarrow \textsf{Neu}_i^b$,
  $P_2 \Leftrightarrow \textbf{El}_2 \Leftrightarrow \textsf{Neu}_i^{b'}$. Given
  $\typing[\Gamma]{t}{S_1} \;\circledR\; w \in \textsf{Neu}_i^b$.
  \begin{align*}
    &\typing[\Gamma]{S_1}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; \textsf{Neu}_i^b
      && \text{(by \Cref{def:neu-term-pred} on the hypothesis)} \\
    &\subty[\Gamma]{S_1}{S_2}
      && \text{(by \Cref{lem:gluing-subty-typ} on $S_1, S_2, P_1, P_2$)}
  \end{align*}
  For each $\kweak[\Delta]{\phi}{\Gamma}$, by \Cref{def:neu-term-pred}:
  \begin{align*}
    &\exists v.\; \textsf{R}^{\textsf{Ne}}_{|\Delta|}(w) \searrow v \wedge
      \tyequiv[\Delta]{t[\phi]}{v}{S_1[\phi]}
      && \text{(Kripke condition at $w$)} \\
    &\subty[\Delta]{S_1[\phi]}{S_2[\phi]}
      && \text{(by \Cref{lem:wk-typing} on the previous-block subtyping)} \\
    &\tyequiv[\Delta]{t[\phi]}{v}{S_2[\phi]}
      && \text{(by \textsc{Tm-Subsump} on the previous two lines)}
  \end{align*}
  Combining with $b \approx b' \in \textsf{Ne}$ (same readback at every depth) and
  the type predicate at $S_2$ (hypothesis), \Cref{def:neu-term-pred} gives
  $\typing[\Gamma]{t}{S_2} \;\circledR\; w \in \textsf{Neu}_i^{b'}$.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{$<$:-Univ}]
    {j \le k \\ k < i}
    {U_j \mathrel{<:_i} U_k}
  \end{mathpar}
  $\textbf{El}_1 \Leftrightarrow \textsf{Univ}_{i,j}^{\textbf{El}}$,
  $\textbf{El}_2 \Leftrightarrow \textsf{Univ}_{i,k}^{\textbf{El}}$. Given $\typing[\Gamma]{t}{S_1}
  \;\circledR\; b \in \textsf{Univ}_{i,j}^{\textbf{El}}$, so by
  \Cref{def:univ-term-pred}: $b \in \mathcal{U}_j^\ast \searrow P_b \searrow \textbf{El}_b$
  and $\typing[\Gamma]{t}{\ensuremath{\texttt{Ty}_{j}}} \;\circledR\; P_b$.
  \begin{align*}
    &\exists P_b', \textbf{El}_b'.\; b \in \mathcal{U}_k^\ast \searrow P_b' \searrow \textbf{El}_b'
      && \text{(by \Cref{lem:gluing-cumul} existence at $k$, since $j \le k$)} \\
    &\typing[\Gamma]{t}{\ensuremath{\texttt{Ty}_{k}}} \;\circledR\; P_b'
      && \text{(by \Cref{lem:gluing-cumul} (1) raising on $b$ from $j$ to $k$)} \\
    &\typing[\Gamma]{S_2}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; \textsf{Univ}_{i,k}
      && \text{(by hypothesis $P_2 = \textsf{Univ}_{i,k}$)} \\
    &\typing[\Gamma]{t}{S_2} \;\circledR\; b \in \textsf{Univ}_{i,k}^{\textbf{El}}
      && \text{(by \Cref{def:univ-term-pred} with the previous lines)}
  \end{align*}

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{$<$:-Nat}]
    { }
    {N \mathrel{<:_i} N}
  \end{mathpar}
  $P_1 \Leftrightarrow \textbf{El}_1 \Leftrightarrow P_2 \Leftrightarrow \textbf{El}_2
  \Leftrightarrow \textsf{Nat}_i$. Given $\typing[\Gamma]{t}{S_1}
  \;\circledR\; b \in \textsf{Nat}_i$.
  \begin{align*}
    &\typing[\Gamma]{S_1}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; \textsf{Nat}_i
      && \text{(by \Cref{def:nat-term-pred} on the hypothesis)} \\
    &\subty[\Gamma]{S_1}{S_2}
      && \text{(by \Cref{lem:gluing-subty-typ})} \\
    &\tyequiv[\Gamma]{S_1}{S_2}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by \Cref{def:nat-type-pred} on $S_1$ and $S_2$, both equal $\ensuremath{\texttt{Nat}}$)} \\
    &\typing[\Gamma]{t}{S_2} \;\circledR\; b \in \textsf{Nat}_i
      && \text{(by \Cref{lem:gluing-respects-eq} (3) on $a = N$)}
  \end{align*}

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{$<$:-Pi}]
    {A \approx A' \in \mathcal{U}_i \searrow R_I \\
     \forall\, \ensuremath{\mathcal{D}} :: a \approx a' \in R_I.\;
       \ensuremath{\llbracket T \rrbracket(\rho, a/x)} \mathrel{<:_i} \ensuremath{\llbracket T' \rrbracket(\rho', a'/x)} \\\\
     \Pi(A, T, \rho) \approx \Pi(A, T, \rho) \in \mathcal{U}_i \\
     \Pi(A', T', \rho') \approx \Pi(A', T', \rho') \in \mathcal{U}_i}
    {\Pi(A, T, \rho) \mathrel{<:_i} \Pi(A', T', \rho')}
  \end{mathpar}
  $P_1 \Leftrightarrow \Pi_i(R_I, P_I, \textbf{El}_I, P_O)$,
  $\textbf{El}_1 \Leftrightarrow \Pi_i^{\textbf{El}}(R, R_I, P_I, \textbf{El}_I, \textbf{El}_O)$,
  $P_2 \Leftrightarrow \Pi_i(R_I, P_I, \textbf{El}_I, P_O')$,
  $\textbf{El}_2 \Leftrightarrow \Pi_i^{\textbf{El}}(R', R_I, P_I, \textbf{El}_I, \textbf{El}_O')$
  ($R_I, P_I, \textbf{El}_I$ shared via \Cref{lem:gluing-univ-equiv}, as the domains
  are PER-equal). The hypothesis $P_2$ has shape $\Pi(x:S_{2,1}).\,S_{2,2}$;
  similarly $S_1$ has shape $\Pi(x:S_{1,1}).\,S_{1,2}$ from the term-predicate
  hypothesis on $\textbf{El}_1$ via \Cref{def:pi-term-pred} clause 3.

  \emph{Setup: subtyping at the syntactic Pi-shapes.}
  \begin{align*}
    &\typing[\Gamma]{S_1}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; \Pi_i(R_I, P_I, \textbf{El}_I, P_O)
      && \text{(by \Cref{def:pi-term-pred} clause 3 on $f \in \textbf{El}_1$)} \\
    &\subty[\Gamma]{S_1}{S_2}
      && \text{(by \Cref{lem:gluing-subty-typ})}
  \end{align*}

  Given $\typing[\Gamma]{t}{S_1} \;\circledR\; f \in \Pi_i^{\textbf{El}}$ at $\textbf{El}_1$.
  We verify the four clauses of $\textbf{El}_2 \Leftrightarrow \Pi_i^{\textbf{El}}(R', R_I,
  P_I, \textbf{El}_I, \textbf{El}_O')$ at $S_2, t, f$.

  \emph{Clause 1.}
  \begin{align*}
    &f \approx f \in R
      && \text{(by hypothesis clause 1 on $f \in \textbf{El}_1$)} \\
    &f \approx f \in R'
      && \text{(by \textsc{U-Pi}'s biconditional: domains equal,} \\
    & && \text{codomains $R_O \mathrel{<:_i} R_O'$ from the inner subtyping)}
  \end{align*}

  \emph{Clause 2.}
  \begin{align*}
    &\typing[\Gamma]{t}{S_1}
      && \text{(by hypothesis clause 2 on $f \in \textbf{El}_1$)} \\
    &\typing[\Gamma]{t}{S_2}
      && \text{(by \textsc{Subsump} with $\subty[\Gamma]{S_1}{S_2}$)}
  \end{align*}

  \emph{Clause 3.} $\typing[\Gamma]{S_2}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\;
  \Pi_i(R_I, P_I, \textbf{El}_I, P_O')$ holds directly by the lemma's hypothesis on
  $S_2, P_2$.

  \emph{Clause 4 (application).} Let $\kweak[\Delta]{\phi}{\Gamma}$, $s, b_0,
  \ensuremath{\mathcal{D}} :: b_0 \approx b_0 \in R_I$ with
  $\typing[\Delta]{s}{S_{2,1}[\phi]} \;\circledR\; b_0 \in \textbf{El}_I$.
  \begin{align*}
    &\typing[\Gamma]{S_{1,1}}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; P_I,\;
      \typing[\Gamma]{S_{2,1}}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; P_I
      && \text{(by clause 2 of $\Pi_i$ on $S_1, S_2$ at $\phi = \ensuremath{\textsf{id}}$)} \\
    &\tyequiv[\Gamma]{S_{1,1}}{S_{2,1}}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by \Cref{lem:gluing-functional} on the two predicates)} \\
    &\tyequiv[\Delta]{S_{1,1}[\phi]}{S_{2,1}[\phi]}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by \Cref{lem:wk-typing})} \\
    &\typing[\Delta]{s}{S_{1,1}[\phi]} \;\circledR\; b_0 \in \textbf{El}_I
      && \text{(by \Cref{lem:gluing-respects-eq} (3) on the equality above)} \\
    &f \cdot b_0 \searrow c,\;
      \typing[\Delta]{(t[\phi])\;s}{S_{1,2}[\iota(\phi), s/x]}
      \;\circledR\; c \in \textbf{El}_O(\ensuremath{\mathcal{D}})
      && \text{(by hypothesis clause 4 on $f \in \textbf{El}_1$)} \\
    &\ensuremath{\llbracket T \rrbracket(\rho, b_0/x)} \mathrel{<:_i} \ensuremath{\llbracket T' \rrbracket(\rho', b_0/x)}
      && \text{(by codomain subtyping at $\ensuremath{\mathcal{D}} :: b_0 \approx b_0 \in R_I$)} \\
    &\typing[\Delta]{S_{2,2}[\iota(\phi), s/x]}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; P_O'(\ensuremath{\mathcal{D}})
      && \text{(by clause 3 of $\Pi_i$ on $S_2$ at $\phi, s, b_0, \ensuremath{\mathcal{D}}$)} \\
    &\typing[\Delta]{(t[\phi])\;s}{S_{2,2}[\iota(\phi), s/x]}
      \;\circledR\; c \in \textbf{El}_O'(\ensuremath{\mathcal{D}})
      && \text{(by IH (term-transfer) on the codomain subtyping at $\ensuremath{\mathcal{D}}$,} \\
    & && \text{using the previous-line type-predicate at level $i$)}
  \end{align*}

  \emph{Clause 5 ($R_I$-coherence under application).} Inherited from
  clause 5 on $f \in \textbf{El}_1$, alongside the codomain subtyping: an
  $R_I$-class of arguments produces an $R_O'$-class of results in the
  codomain via clause 4.

\label{thm:gluing-realizability}
  Suppose $a \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El}$.
  \begin{enumerate}
  \@idxitem\label{thm:bot-implies-el}
    \emph{($\textsf{Bot}$ enters $\textbf{El}$.)} If
    $\typing[\Gamma]{t}{S} \;\circledR\; w \in \textsf{Bot}_i^a$, then
    $\typing[\Gamma]{t}{S} \;\circledR\; {\uparrow}^a(w) \in \textbf{El}$.
  \@idxitem\label{thm:el-implies-nf}
    \emph{($\textbf{El}$ enters $\textsf{Top}$.)} If
    $\typing[\Gamma]{t}{S} \;\circledR\; b \in \textbf{El}$ and
    $b \approx b \in R$ (where $a \approx a \in \mathcal{U}_i \searrow R$), then
    $\typing[\Gamma]{t}{S} \;\circledR\; b \in \textsf{Top}_i^a$.
  \@idxitem\label{thm:gluing-types-readback}
    \emph{($P$ enters $\textsf{Top}$.)} If $\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; P$,
    then $\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; \textsf{Top}_i^a$.
  \end{enumerate}

By simultaneous induction on the lexicographic pair
  $(i,\; a \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El})$: the outer induction on the
  level~$i$ provides the IH at strictly smaller levels, used in the
  \textsc{G-Univ} case; the inner induction on the gluing derivation provides
  the IH at structurally smaller derivations at the same level~$i$.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{G-Ne}]
    {a = {\uparrow}^A(e) \\
     P \Leftrightarrow \textsf{Neu}_i^e \\
     \textbf{El} \Leftrightarrow \textsf{Neu}_i^e}
    {{\uparrow}^A(e) \in \mathcal{U}_i^\ast}
  \end{mathpar}
  \begin{enumerate}
  \@idxitem \emph{$\textsf{Bot}$ enters $\textbf{El}$.} Suppose
    $\typing[\Gamma]{t}{S} \;\circledR\; w \in \textsf{Bot}_i^a$. Unpacking
    \Cref{def:glu-wrapped} clauses (a)--(c) yields
    $\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; \textsf{Neu}_i^e$ (the $P$-side
    component) and $\typing[\Gamma]{t}{S} \;\circledR\; w \in \textsf{Ne}_i^a$.
    These are exactly the four clauses of \Cref{def:neu-term-pred} for the
    term ${\uparrow}^A(w)$, hence
    $\typing[\Gamma]{t}{S} \;\circledR\; {\uparrow}^A(w) \in \textbf{El} \Leftrightarrow
    \textsf{Neu}_i^e$.
  \@idxitem \emph{$\textbf{El}$ enters $\textsf{Top}$.} Suppose
    $\typing[\Gamma]{t}{S} \;\circledR\; {\uparrow}^A(w) \in \textsf{Neu}_i^e$
    and ${\uparrow}^A(w) \approx {\uparrow}^A(w) \in R$. We assemble the three
    clauses of \Cref{def:glu-wrapped}(c). The type-side gluing
    $\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; P \Leftrightarrow \textsf{Neu}_i^e$
    is the inner component of $\textsf{Neu}_i^e$ at term level. For
    $\textsf{Nf}_i^a$: for each $\kweak[\Delta]{\phi}{\Gamma}$, by \textsc{Rf-ne}:
    \begin{align*}
      &\textsf{R}^{\textsf{Nf}}_{|\Delta|}({\downarrow}^{{\uparrow}^A(e)}({\uparrow}^A(w))) \searrow v
        && \text{(via $\textsf{R}^{\textsf{Ne}}_{|\Delta|}(w) \searrow v$, by \textsc{Rf-ne})} \\
      &\tyequiv[\Delta]{t[\phi]}{v}{S[\phi]}
        && \text{(by \Cref{def:neu-term-pred})}
    \end{align*}
    This satisfies $\textsf{Nf}_i^a$, and packaged with $\typing[\Gamma]{t}{S}$ and
    the type gluing yields $\typing[\Gamma]{t}{S} \;\circledR\; {\uparrow}^A(w)
    \in \textsf{Top}_i^a$.
  \@idxitem \emph{$P$ enters $\textsf{Top}$.} Hypothesis:
    $\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; \textsf{Neu}_i^e$. We assemble
    the three clauses of \Cref{def:glu-wrapped}(b). The first clause
    $\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}}$ is part of $\textsf{Neu}_i^e$. For
    $a \approx a \in \mathcal{U}_i \searrow R$: by \Cref{lem:gluing-implies-per},
    the binary relation $R$ exists. For each
    $\kweak[\Delta]{\phi}{\Gamma}$:
    \begin{align*}
      &\textsf{R}^{\textsf{Ne}}_{|\Delta|}(e) \searrow u
        && \text{(by \Cref{def:neu-type-pred} applied to $\textsf{Neu}_i^e$)} \\
      &\textsf{R}^{\textsf{Ty}}_{|\Delta|}({\uparrow}^A(e)) \searrow u
        && \text{(by \textsc{Rty-ne})} \\
      &\tyequiv[\Delta]{S[\phi]}{u}{\ensuremath{\texttt{Ty}_{i}}}
        && \text{(by \Cref{def:neu-type-pred})}
    \end{align*}
  \end{enumerate}

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{G-Nat}]
    {P \Leftrightarrow \textsf{Nat}_i \\
     \textbf{El} \Leftrightarrow \textsf{Nat}_i}
    {N \in \mathcal{U}_i^\ast}
  \end{mathpar}
  \begin{enumerate}
  \@idxitem \emph{$\textsf{Bot}$ enters $\textbf{El}$.} Suppose
    $\typing[\Gamma]{t}{S} \;\circledR\; w \in \textsf{Bot}_i^N$. Unpacking
    \Cref{def:glu-wrapped}(a) yields
    $\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; \textsf{Nat}_i$ (which by
    \Cref{def:nat-type-pred} gives $\tyequiv[\Gamma]{S}{\ensuremath{\texttt{Nat}}}{\ensuremath{\texttt{Ty}_{i}}}$) and
    $\typing[\Gamma]{t}{S} \;\circledR\; w \in \textsf{Ne}_i^N$. The premises of
    \textsc{GN-Ne} are exactly these, hence ${\uparrow}^N(w) \in \textsf{Nat}_i$
    at $t$.
  \@idxitem \emph{$\textbf{El}$ enters $\textsf{Top}$.} Given
    $\typing[\Gamma]{t}{S} \;\circledR\; b \in \textsf{Nat}_i$ and
    $b \approx b \in R$ (where $R$ is the Nat-PER closure), we establish the
    three clauses of \Cref{def:glu-wrapped}(c). The type-side
    $\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; \textsf{Nat}_i$ is part of
    \Cref{def:nat-term-pred}; for $\textsf{Nf}_i^N$, by inner induction on
    the derivation of $b \in \textsf{Nat}_i$.
    \begin{itemize}
    \@idxitem[Sub-case]
      \begin{mathpar}
        \inferrule[\textsc{GN-Ze}]
        {\tyequiv[\Gamma]{t}{\textsf{zero}}{S}}
        {\typing[\Gamma]{t}{S} \;\circledR\; \texttt{ze} \in \textsf{Nat}}
      \end{mathpar}
      For each $\kweak[\Delta]{\phi}{\Gamma}$:
      \begin{align*}
        &\textsf{R}^{\textsf{Nf}}_{|\Delta|}({\downarrow}^N(\texttt{ze})) \searrow \textsf{zero}
          && \text{(by \textsc{Rf-ze})} \\
        &\tyequiv[\Delta]{t[\phi]}{\textsf{zero}}{S[\phi]}
          && \text{(by \Cref{lem:wk-typing} on the hypothesis)}
      \end{align*}
    \@idxitem[Sub-case]
      \begin{mathpar}
        \inferrule[\textsc{GN-Su}]
        {\typing[\Gamma]{t'}{S} \;\circledR\; b' \in \textsf{Nat} \\
         \tyequiv[\Gamma]{t}{\textsf{succ}~t'}{S}}
        {\typing[\Gamma]{t}{S} \;\circledR\; \texttt{su}(b') \in \textsf{Nat}}
      \end{mathpar}
      For each $\kweak[\Delta]{\phi}{\Gamma}$:
      \begin{align*}
        &\textsf{R}^{\textsf{Nf}}_{|\Delta|}({\downarrow}^N(b')) \searrow w'
          && \text{(by inner IH on $b'$)} \\
        &\tyequiv[\Delta]{t'[\phi]}{w'}{S[\phi]}
          && \text{(by inner IH on $b'$)} \\
        &\textsf{R}^{\textsf{Nf}}_{|\Delta|}({\downarrow}^N(\texttt{su}(b'))) \searrow \textsf{succ}~w'
          && \text{(by \textsc{Rf-su})} \\
        &\tyequiv[\Delta]{\textsf{succ}~t'[\phi]}{\textsf{succ}~w'}{S[\phi]}
          && \text{(by \textsc{Su-Cong} on the previous line)} \\
        &\tyequiv[\Delta]{t[\phi]}{\textsf{succ}~w'}{S[\phi]}
          && \text{(by transitivity with the \textsc{GN-Su} hypothesis)}
      \end{align*}
    \@idxitem[Sub-case]
      \begin{mathpar}
        \inferrule[\textsc{GN-Ne}]
        {\typing[\Gamma]{t}{S} \;\circledR\; {\uparrow}^N(w) \in \textsf{Neu}_i^e}
        {\typing[\Gamma]{t}{S} \;\circledR\; {\uparrow}^N(w) \in \textsf{Nat}}
      \end{mathpar}
      For each $\kweak[\Delta]{\phi}{\Gamma}$:
      \begin{align*}
        &\textsf{R}^{\textsf{Ne}}_{|\Delta|}(w) \searrow v
          && \text{(by hypothesis on $w \in \textsf{Ne}_i^a$)} \\
        &\textsf{R}^{\textsf{Nf}}_{|\Delta|}({\downarrow}^N({\uparrow}^N(w))) \searrow v
          && \text{(by \textsc{Rf-ne})} \\
        &\tyequiv[\Delta]{t[\phi]}{v}{S[\phi]}
          && \text{(by hypothesis on $w$)}
      \end{align*}
    \end{itemize}
  \@idxitem \emph{$P$ enters $\textsf{Top}$.} Hypothesis:
    $\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; \textsf{Nat}_i$. We assemble the
    three clauses of \Cref{def:glu-wrapped}(b). The first clause
    $\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}}$ is part of \Cref{def:nat-type-pred} via
    presupposition. For $N \approx N \in \mathcal{U}_i \searrow R_N$: immediate by the
    PER definition. For each $\kweak[\Delta]{\phi}{\Gamma}$:
    \begin{align*}
      &\textsf{R}^{\textsf{Ty}}_{|\Delta|}(N) \searrow \ensuremath{\texttt{Nat}}
        && \text{(by \textsc{Rty-N})} \\
      &\tyequiv[\Delta]{S[\phi]}{\ensuremath{\texttt{Nat}}}{\ensuremath{\texttt{Ty}_{i}}}
        && \text{(by \Cref{def:nat-type-pred})}
    \end{align*}
  \end{enumerate}

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{G-Pi}]
    {a = \Pi(a_I, T, \rho) \\
     a_I \in \mathcal{U}_i^\ast \searrow P_I \searrow \textbf{El}_I \\\\
     \forall\,\ensuremath{\mathcal{D}} :: b \approx b \in R_I,\; c.\;
       \ensuremath{\llbracket T \rrbracket(\rho, b/x)} \searrow c \implies
       c \in \mathcal{U}_i^\ast \searrow P_O(\ensuremath{\mathcal{D}}) \searrow \textbf{El}_O(\ensuremath{\mathcal{D}}) \\\\
     P \Leftrightarrow \Pi_i(R_I, P_I, P_O) \\
     \textbf{El} \Leftrightarrow \Pi_i^{\textbf{El}}(R, R_I, P_I, \textbf{El}_I, \textbf{El}_O)}
    {\Pi(a_I, T, \rho) \in \mathcal{U}_i^\ast}
  \end{mathpar}
  By inner IH-(1) on $a_I$, neutral inhabitants enter $\textbf{El}_I$; by inner IH-(2) on
  $a_I$, $\textbf{El}_I$-elements read back; analogously for $\textbf{El}_O(\ensuremath{\mathcal{D}})$ at each
  $\ensuremath{\mathcal{D}}$.
  \begin{enumerate}
  \@idxitem \emph{$\textsf{Bot}$ enters $\textbf{El}$.} Suppose
    \[
      \typing[\Gamma]{t}{S} \;\circledR\; w \in \textsf{Bot}_i^a.
    \]
    Unpacking \Cref{def:glu-wrapped}(a) yields
    \[
      \typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\;
      \Pi_i(R_I, P_I, \textbf{El}_I, P_O)
    \]
    together with
    $\typing[\Gamma]{t}{S} \;\circledR\; w \in \textsf{Ne}_i^a$.
    We verify the four clauses of \Cref{def:pi-term-pred}
    for ${\uparrow}^a(w)$.
    \begin{enumerate}
    \@idxitem[(1)] Self-relatedness ${\uparrow}^a(w) \approx {\uparrow}^a(w) \in R$
      holds by \textsc{U-Ne} of the PER closure.
    \@idxitem[(2)] Coherence under $R_I$: trivial because the function value does not
      depend on a representative of $R_I$ on the left of the predicate.
    \@idxitem[(3)] For each $\kweak[\Delta]{\phi}{\Gamma}$, $\textsf{R}^{\textsf{Ne}}_{|\Delta|}(w) \searrow v$
      by hypothesis on $w \in \textsf{Ne}$, so the type readback obligation holds via
      \Cref{def:pi-type-pred}.
    \@idxitem[(4)] Application: given $\kweak[\Delta]{\phi}{\Gamma}$ and
      $\typing[\Delta]{s}{S_1[\phi]} \;\circledR\; b \in \textbf{El}_I$ with
      $\ensuremath{\mathcal{D}} :: b \approx b \in R_I$ (by inner IH-(1) bridging through
      \Cref{lem:gluing-implies-per}, applied to $b$):
      \begin{align*}
        &\ensuremath{\llbracket T \rrbracket(\rho, b/x)} \searrow c_b
          && \text{(evaluation of $T$ at $\rho, b/x$; well-defined since
            $\Pi(a_I, T, \rho) \approx \Pi(a_I, T, \rho) \in \mathcal{U}_i$)} \\
        &c_b \in \mathcal{U}_i^\ast \searrow P_O(\ensuremath{\mathcal{D}}) \searrow \textbf{El}_O(\ensuremath{\mathcal{D}})
          && \text{(by the \textsc{G-Pi} codomain clause applied to $\ensuremath{\mathcal{D}}$ and $c_b$)} \\
        &b \in \textsf{Nf}_i^{a_I}
          && \text{(by inner IH-(2) on $a_I$ applied to $b \in \textbf{El}_I$)} \\
        &\textsf{R}^{\textsf{Nf}}_{|\Delta|}({\downarrow}^{a_I}(b)) \searrow u_b
          && \text{(by the previous line)} \\
        &{\uparrow}^a(w) \cdot b \searrow
          {\uparrow}^{c_b}(w \;\$\; {\downarrow}^{a_I}(b))
          && \text{(by neutral application)} \\
        &w \;\$\; {\downarrow}^{a_I}(b) \in \textsf{Ne}_i^{c_b}
          && \text{(by \textsc{Rne-app}, using
            $\textsf{R}^{\textsf{Ne}}_{|\Delta|}(w)$ and $u_b$)} \\
        &\typing[\Delta]{(t[\phi])\;s}{S_2[\iota(\phi), s/x]} \\
        & \quad \;\circledR\;
          {\uparrow}^{c_b}(w \;\$\; {\downarrow}^{a_I}(b)) \in \textbf{El}_O(\ensuremath{\mathcal{D}})
          && \text{(by inner IH-(1) on $c_b$)}
      \end{align*}
    \end{enumerate}
  \@idxitem \emph{$\textbf{El}$ enters $\textsf{Top}$.} Suppose
    $\typing[\Gamma]{t}{S} \;\circledR\; f \in \Pi_i^{\textbf{El}}(R, R_I, P_I, \textbf{El}_I, \textbf{El}_O)$
    and $f \approx f \in R$. We assemble the three clauses of
    \Cref{def:glu-wrapped}(c). The type-side $\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}}
    \;\circledR\; \Pi_i(R_I, P_I, \textbf{El}_I, P_O)$ is part of
    \Cref{def:pi-term-pred}; the term-typing $\typing[\Gamma]{t}{S}$ likewise.
    For $\textsf{Nf}_i^a$, for
    each $\kweak[\Delta]{\phi}{\Gamma}$, set $n := |\Delta|$ and form
    $\Delta' := \Delta, x' : S_1[\phi]$ together with the lifted Kripke weakening
    $\phi \circ \Uparrow$ (by \textsc{KW-Shift}; \Cref{lem:kweak-comp}).
    \begin{align*}
      &\typing[\Delta']{x'}{S_1[\phi \circ \Uparrow]}
        \;\circledR\; {\uparrow}^{a_I}(\ell_n) \in \textbf{El}_I
        && \text{(by inner IH-(1) on $a_I$ applied to $\ell_n$)} \\
      &f \cdot {\uparrow}^{a_I}(\ell_n) \searrow c
        && \text{(by clause (4) of $\Pi_i^{\textbf{El}}$ on $f$)} \\
      &\typing[\Delta']{(t[\phi \circ \Uparrow])\;x'}
                       {S_2[\iota(\phi \circ \Uparrow), x'/x]}
        \;\circledR\; c \in \textbf{El}_O(\ensuremath{\mathcal{D}}')
        && \text{(by clause (4) on $f$, with $\ensuremath{\mathcal{D}}'$ the witness from line 1)} \\
      &c \in \textsf{Nf}_i^{c_{\ell_n}}
        && \text{(by inner IH-(2) on $c_{\ell_n} \in \mathcal{U}_i^\ast$)} \\
      &\textsf{R}^{\textsf{Nf}}_{n+1}({\downarrow}^{c_{\ell_n}}(c)) \searrow v
        && \text{(by the previous line)} \\
      &\tyequiv[\Delta']{(t[\phi \circ \Uparrow])\;x'}{v}
                       {S_2[\iota(\phi \circ \Uparrow), x'/x]}
        && \text{(by inner IH-(2) on $c_{\ell_n}$)} \\
      &\textsf{R}^{\textsf{Nf}}_n({\downarrow}^a(f)) \searrow \lambda x.\,v
        && \text{(by \textsc{Rf-Pi}, using the previous line)} \\
      &\tyequiv[\Delta]{t[\phi]}{\lambda x.\,(t[\phi \circ \Uparrow])\;x'}
                       {S[\phi]}
        && \text{(by \textsc{$\Pi$-$\eta$})} \\
      &\tyequiv[\Delta]{t[\phi]}{\lambda x.\,v}{S[\phi]}
        && \text{(by congruence with the $\textsf{R}^{\textsf{Nf}}$ equality)}
    \end{align*}
  \@idxitem \emph{$P$ enters $\textsf{Top}$.} Hypothesis: $\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}}
    \;\circledR\; \Pi_i(R_I, P_I, \textbf{El}_I, P_O)$. We assemble the three clauses
    of \Cref{def:glu-wrapped}(b). The first clause $\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}}$
    is part of \Cref{def:pi-type-pred}. For $a \approx a \in \mathcal{U}_i \searrow R$:
    by \Cref{lem:gluing-implies-per} on the components $a_I$ and $c$ at each
    $\ensuremath{\mathcal{D}}$, the binary closure exists. For each
    $\kweak[\Delta]{\phi}{\Gamma}$, set $n := |\Delta|$:
    \begin{align*}
      &\textsf{R}^{\textsf{Ty}}_n(a_I) \searrow W_S,\;
        \tyequiv[\Delta]{S_1[\phi]}{W_S}{\ensuremath{\texttt{Ty}_{i}}}
        && \text{(by inner IH-(3) on $a_I$)} \\
      &\ensuremath{\llbracket T \rrbracket(\rho, {\uparrow}^{a_I}(\ell_n)/x)} \searrow c_{\ell_n}
        && \text{(by \Cref{def:pi-type-pred})} \\
      &\textsf{R}^{\textsf{Ty}}_{n+1}(c_{\ell_n}) \searrow W_T
        && \text{(by inner IH-(3) on $c_{\ell_n}$)} \\
      &\tyequiv[\Delta, x' : S_1[\phi]]{S_2[\iota(\phi \circ \Uparrow), x'/x]}
                                       {W_T}{\ensuremath{\texttt{Ty}_{i}}}
        && \text{(by inner IH-(3) on $c_{\ell_n}$)} \\
      &\textsf{R}^{\textsf{Ty}}_n(\Pi(a_I, T, \rho)) \searrow \Pi(x:W_S).\,W_T
        && \text{(by \textsc{Rty-Pi})} \\
      &\tyequiv[\Delta]{S[\phi]}{\Pi(x:W_S).\,W_T}{\ensuremath{\texttt{Ty}_{i}}}
        && \text{(by \Cref{def:pi-type-pred} clauses 1--3 and \textsc{$\Pi$-Cong})}
    \end{align*}
  \end{enumerate}

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{G-Univ}]
    {j < i \\
     P \Leftrightarrow \textsf{Univ}_{i,j} \\
     \textbf{El} \Leftrightarrow \textsf{Univ}_{i,j}^{\textbf{El}}}
    {U_j \in \mathcal{U}_i^\ast}
  \end{mathpar}
  Since $j < i$, the outer-IH applies at level $j$ to every value $b \in \mathcal{U}_j^\ast$.
  \begin{enumerate}
  \@idxitem \emph{$\textsf{Bot}$ enters $\textbf{El}$.} Suppose
    $\typing[\Gamma]{t}{S} \;\circledR\; w \in \textsf{Bot}_i^{U_j}$. Unpacking
    \Cref{def:glu-wrapped}(a) yields $\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\;
    \textsf{Univ}_{i,j}$ and $\typing[\Gamma]{t}{S} \;\circledR\; w \in
    \textsf{Ne}_i^{U_j}$. Apply \textsc{G-Ne} at level $j$:
    \begin{align*}
      &{\uparrow}^A(w) \in \mathcal{U}_j^\ast \searrow \textsf{Neu}_j^e \searrow \textsf{Neu}_j^e
        && \text{(by \textsc{G-Ne} at level $j$)} \\
      &\typing[\Gamma]{t}{S} \;\circledR\; {\uparrow}^A(w) \in \mathcal{U}_j^\ast
        && \text{(by \Cref{def:univ-term-pred} clause (1) with the previous line)} \\
      &\typing[\Gamma]{t}{\ensuremath{\texttt{Ty}_{j}}} \;\circledR\; \textsf{Neu}_j^e
        && \text{(by \Cref{def:univ-term-pred} clause (2);} \\
    & && \text{the type predicate attached to ${\uparrow}^A(w)$ is} \\
    & && \text{$\textsf{Neu}_j^e$, which by hypothesis on $w$ inhabits} \\
    & && \text{the type-predicate condition; the equality} \\
    & && \text{$\tyequiv[\Gamma]{S}{\ensuremath{\texttt{Ty}_{j}}}{\ensuremath{\texttt{Ty}_{i}}}$ comes from \Cref{def:univ-type-pred})}
    \end{align*}
  \@idxitem \emph{$\textbf{El}$ enters $\textsf{Top}$.} Suppose
    $\typing[\Gamma]{t}{S} \;\circledR\; b \in \textsf{Univ}_{i,j}^{\textbf{El}}$ and
    $b \approx b \in R$. By \Cref{def:univ-term-pred}, $b \in \mathcal{U}_j^\ast
    \searrow P_b \searrow \textbf{El}_b$ for some $P_b, \textbf{El}_b$, with
    $\typing[\Gamma]{t}{\ensuremath{\texttt{Ty}_{j}}} \;\circledR\; P_b$ at the type level. We
    assemble \Cref{def:glu-wrapped}(c). The $P$-side
    $\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; \textsf{Univ}_{i,j}$ comes from
    \Cref{def:univ-term-pred}; for $\textsf{Nf}_i^{U_j}$, for each
    $\kweak[\Delta]{\phi}{\Gamma}$, $n := |\Delta|$:
    \begin{align*}
      &\textsf{R}^{\textsf{Ty}}_n(b) \searrow W
        && \text{(by outer-IH-(3) on $b \in \mathcal{U}_j^\ast$)} \\
      &\tyequiv[\Delta]{t[\phi]}{W}{\ensuremath{\texttt{Ty}_{j}}}
        && \text{(by outer-IH-(3) on $b$)} \\
      &\textsf{R}^{\textsf{Nf}}_n({\downarrow}^{U_j}(b)) \searrow W
        && \text{(by \textsc{Rf-Univ})} \\
      &\tyequiv[\Delta]{t[\phi]}{W}{S[\phi]}
        && \text{(by \Cref{def:univ-type-pred}:
          $\tyequiv[\Delta]{S[\phi]}{\ensuremath{\texttt{Ty}_{j}}}{\ensuremath{\texttt{Ty}_{i}}}$,} \\
      & && \text{and \textsc{Subsump} from the $\ensuremath{\texttt{Ty}_{j}}$-equality)}
    \end{align*}
  \@idxitem \emph{$P$ enters $\textsf{Top}$.} Hypothesis: $\typing[\Gamma]{S}{\ensuremath{\texttt{Ty}_{i}}}
    \;\circledR\; \textsf{Univ}_{i,j}$. We assemble
    \Cref{def:glu-wrapped}(b). The first clause is from
    \Cref{def:univ-type-pred}; for $U_j \approx U_j \in \mathcal{U}_i \searrow R$,
    immediate from \textsc{U-Univ} of the PER. For each
    $\kweak[\Delta]{\phi}{\Gamma}$:
    \begin{align*}
      &\textsf{R}^{\textsf{Ty}}_{|\Delta|}(U_j) \searrow \ensuremath{\texttt{Ty}_{j}}
        && \text{(by \textsc{Rty-Univ})} \\
      &\tyequiv[\Delta]{S[\phi]}{\ensuremath{\texttt{Ty}_{j}}}{\ensuremath{\texttt{Ty}_{i}}}
        && \text{(by \Cref{def:univ-type-pred})}
    \end{align*}
  \end{enumerate}

\label{lem:init-env-valid}
  If $\Gamma \searrow \textsf{Sb}$, then
  $\judge[\Gamma]{\ensuremath{\textsf{id}} : \Gamma} \;\circledR\; {\uparrow}^\Gamma \in \textsf{Sb}$.

By induction on $\Gamma \searrow \textsf{Sb}$.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{G-Ctx-$\cdot$}]
    {\textsf{Sb} \Leftrightarrow (\judge[\Delta]{\sigma : \cdot})}
    {\cdot \searrow \textsf{Sb}}
  \end{mathpar}
  $\judge[\cdot]{\ensuremath{\textsf{id}} : \cdot}$ holds trivially, hence
  $\judge[\cdot]{\ensuremath{\textsf{id}} : \cdot} \;\circledR\; {\uparrow}^\cdot \in \textsf{Sb}$.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{G-Ctx-Ext}]
    {\Gamma' \searrow \textsf{Sb}' \\
     \typing[\Gamma']{S_k}{\ensuremath{\texttt{Ty}_{i}}} \\\\
     \forall \Delta_0, \sigma_T, \rho_T.\;
       \judge[\Delta_0]{\sigma_T : \Gamma'} \;\circledR\; \rho_T \in \textsf{Sb}'
       \implies \\
     \quad \exists a, P, \textbf{El}.\;
       \ensuremath{\llbracket S_k \rrbracket(\rho_T)} \searrow a \;\wedge\;
       a \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El} \;\wedge\;
       \typing[\Delta_0]{S_k[\sigma_T]}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; P \\\\
     \textsf{Sb} \Leftrightarrow \textsf{Cons}_i(\Gamma', S_k, \textsf{Sb}')}
    {(\Gamma', x_k : S_k) \searrow \textsf{Sb}}
  \end{mathpar}
  Set $\Gamma := \Gamma', x_k : S_k$ with $|\Gamma| = k+1$.
  \begin{align*}
    &\judge[\Gamma']{\ensuremath{\textsf{id}} : \Gamma'} \;\circledR\; {\uparrow}^{\Gamma'} \in \textsf{Sb}'
      && \text{(by IH on $\Gamma' \searrow \textsf{Sb}'$)} \\
    &\ensuremath{\llbracket S_k \rrbracket({\uparrow}^{\Gamma'})} \searrow A_k,\;
      A_k \in \mathcal{U}_i^\ast \searrow P_k \searrow \textbf{El}_k
      && \text{(by the universal type-clause of \textsc{G-Ctx-Ext}} \\
    & && \text{instantiated at $\ensuremath{\textsf{id}}, {\uparrow}^{\Gamma'}$)} \\
    &\typing[\Gamma']{S_k[\ensuremath{\textsf{id}}]}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; P_k
      && \text{(type clause at the same instantiation)} \\
    &\typing[\Gamma']{S_k}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; P_k
      && \text{(using $S_k[\ensuremath{\textsf{id}}] = S_k$)}
  \end{align*}
  We supply the head witness for $\textsf{Cons}_i$:
  \begin{align*}
    &{\uparrow}^\Gamma = ({\uparrow}^{\Gamma'},\, {\uparrow}^{A_k}(\ell_k)/x_k)
      && \text{(by \Cref{def:init-env})} \\
    &\typing[\Gamma]{x_k}{S_k[\Uparrow]}
      && \text{(by \textsc{Var-Hd})} \\
    &\textsf{R}^{\textsf{Ne}}_{|\Delta'|}(\ell_k) \searrow x_{|\Delta'| - k - 1}
      \text{ for each $\kweak[\Delta']{\phi}{\Gamma}$}
      && \text{(by \textsc{Rne-var}, the level-reading rule for $\ell_k$)} \\
    &\tyequiv[\Delta']{x_k[\phi]}{x_{|\Delta'| - k - 1}}{S_k[\Uparrow][\phi]}
      && \text{(by the syntactic action of $\phi$ on the variable $x_k$)} \\
    &\typing[\Gamma]{x_k}{S_k[\Uparrow]} \;\circledR\;
      \ell_k \in \textsf{Ne}_i^{A_k}
      && \text{(by \Cref{def:neu-term-pred}, using the previous two lines)} \\
    &\typing[\Gamma]{x_k}{S_k[\Uparrow]} \;\circledR\;
      {\uparrow}^{A_k}(\ell_k) \in \textbf{El}_k
      && \text{(by \Cref{thm:gluing-realizability} part (1) on $A_k$)} \\
    &\judge[\Gamma]{\ensuremath{\textsf{id}} : \Gamma} \;\circledR\;
      {\uparrow}^\Gamma \in \textsf{Sb}
      && \text{(by $\textsf{Cons}_i$ assembly: tail (IH) and head witness above)}
  \end{align*}

By $\Vdash \Gamma$, fix $\Gamma \searrow \textsf{Sb}$ and let
  $\judge[\Delta]{\sigma : \Gamma} \;\circledR\; \rho \in \textsf{Sb}$ be given.
  We proceed by induction on the lookup derivation $x : S \in \Gamma$.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{Var-Hd}]
    { }
    {x_0 : T[\Uparrow] \in \Gamma_0, x_0 : T}
  \end{mathpar}
  Here $\Gamma = \Gamma_0, x_0:T$ and $S = T[\Uparrow]$. We must show
  $\Semtyp[\Gamma]{x_0}{T[\Uparrow]}$: for the given
  $\judge[\Delta]{\sigma : \Gamma} \;\circledR\; \rho \in \textsf{Sb}$,
  evaluating $T[\Uparrow]$ at $\rho$ yields a value $a^\ast$ with
  $a^\ast \in \mathcal{U}_i^\ast \searrow P^\ast \searrow \textbf{El}^\ast$, and:
  \begin{enumerate}
  \@idxitem $\typing[\Delta]{T[\Uparrow \circ \sigma]}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; P^\ast$, and
  \@idxitem $\typing[\Delta]{x_0[\sigma]}{T[\Uparrow \circ \sigma]} \;\circledR\;
    \ensuremath{\llbracket x_0 \rrbracket(\rho)} \in \textbf{El}^\ast$.
  \end{enumerate}

  Since $\Gamma = \Gamma_0, x_0:T$, the gluing $\Gamma \searrow \textsf{Sb}$
  is by \textsc{G-Ctx-Ext} on $\Gamma_0 \searrow \textsf{Sb}_{T_0}$ with
  $\typing[\Gamma_0]{T}{\ensuremath{\texttt{Ty}_{i}}}$, and
  $\textsf{Sb} \Leftrightarrow \textsf{Cons}_i(\Gamma_0, T, \textsf{Sb}_{T_0})$.
  Unfolding $\textsf{Cons}_i$ at our $\sigma, \rho$ (which provides existential
  $a, P, \textbf{El}$ specific to this $\sigma, \rho$):
  \begin{align*}
    &\judge[\Delta]{\Uparrow \circ \sigma : \Gamma_0} \;\circledR\;
      \rho[\Uparrow] \in \textsf{Sb}_{T_0}
      && \text{(tail of $\textsf{Cons}_i$)} \\
    &\ensuremath{\llbracket T \rrbracket(\rho[\Uparrow])} \searrow a,\;
      a \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El}
      && \text{(type clause of $\textsf{Cons}_i$)} \\
    &\typing[\Delta]{T[\Uparrow \circ \sigma]}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; P
      && \text{(type clause of $\textsf{Cons}_i$)} \\
    &\typing[\Delta]{x_0[\sigma]}{T[\Uparrow \circ \sigma]} \;\circledR\;
      \rho(x_0) \in \textbf{El}
      && \text{(head of $\textsf{Cons}_i$)} \\
    &\ensuremath{\llbracket x_0 \rrbracket(\rho)} = \rho(x_0)
      && \text{(by \textsc{ev-var})}
  \end{align*}

  \emph{Establishing the goal $\ensuremath{\llbracket T[\Uparrow] \rrbracket(\rho)} \searrow a^\ast$ at the
  same $(P, \textbf{El})$.}
  The $\textsf{Cons}_i$ type clause gives $\ensuremath{\llbracket T \rrbracket(\rho[\Uparrow])} \searrow a$,
  but the goal needs $\ensuremath{\llbracket T[\Uparrow] \rrbracket(\rho)} \searrow a^\ast$. By
  \Cref{thm:fundamental} of \Cref{sec:comp} on $\typing[\Gamma_0]{T}{\ensuremath{\texttt{Ty}_{i}}}$,
  $\semtyeq[\Gamma_0]{T}{T}{\ensuremath{\texttt{Ty}_{i}}}$. Instantiate this at $\Uparrow$ and $\rho$
  (self-related in $R_\Gamma$):
  \begin{align*}
    &\semweak[\Gamma]{\Uparrow}{\Gamma_0}
      && \text{(by \textsc{KW-Shift})} \\
    &\semtyeq[\Gamma]{\Uparrow}{\Uparrow}{\Gamma_0}
      && \text{(by \Cref{lem:sem-wk})} \\
    &\ensuremath{\llbracket T[\Uparrow] \rrbracket(\rho)} \approx \ensuremath{\llbracket T \rrbracket(\ensuremath{\llbracket \Uparrow \rrbracket(\rho)})} \in \mathcal{U}_i \searrow R
      && \text{(four-value pattern of $\semtyeq[\Gamma_0]{T}{T}{\ensuremath{\texttt{Ty}_{i}}}$ at
        $\Uparrow, \rho$)} \\
    &\ensuremath{\llbracket \Uparrow \rrbracket(\rho)} = \rho[\Uparrow]
      && \text{(by definition of weakening evaluation, \Cref{sec:sem})} \\
    &a^\ast \approx a \in \mathcal{U}_i \searrow R
      && \text{(rewriting $\ensuremath{\llbracket T[\Uparrow] \rrbracket(\rho)} = a^\ast$ and
        $\ensuremath{\llbracket T \rrbracket(\rho[\Uparrow])} = a$)} \\
    &a^\ast \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El}
      && \text{(by \Cref{lem:gluing-univ-equiv} from
        $a \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El}$)}
  \end{align*}
  This supplies the goal evaluation $\ensuremath{\llbracket T[\Uparrow] \rrbracket(\rho)} \searrow a^\ast$
  with $a^\ast \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El}$, where $(P, \textbf{El})$ are
  the same predicates packaged by $\textsf{Cons}_i$. Clauses (1) and (2) of
  $\Semtyp[\Gamma]{x_0}{T[\Uparrow]}$ are exactly the $\textsf{Cons}_i$ type
  clause $\typing[\Delta]{T[\Uparrow \circ \sigma]}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; P$
  and the head's $\textbf{El}$-witness $\rho(x_0) = \ensuremath{\llbracket x_0 \rrbracket(\rho)}$ above.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{Var-Tl}]
    {y : S' \in \Gamma_0}
    {1{+}y : S'[\Uparrow] \in \Gamma_0, z:T}
  \end{mathpar}
  Here $\Gamma = \Gamma_0, z:T$, $x = 1{+}y$ for some $y$ with $y : S' \in \Gamma_0$,
  and $S = S'[\Uparrow]$. We must show $\Semtyp[\Gamma]{1{+}y}{S'[\Uparrow]}$:
  evaluating $S'[\Uparrow]$ at $\rho$ yields a value $a^\ast$ in
  $\mathcal{U}_i^\ast \searrow P^\ast \searrow \textbf{El}^\ast$, with the type and term
  predicates at $\sigma, \rho$.
  $\textsf{Sb}$ unfolds to $\textsf{Cons}_i$ at $\sigma, \rho$, giving the
  tail $\Uparrow \circ \sigma, \rho[\Uparrow] \in \textsf{Sb}_T$.

  \emph{Apply IH on the tail.}
  \begin{align*}
    &\judge[\Delta]{\Uparrow \circ \sigma : \Gamma_0}
      \;\circledR\; \rho[\Uparrow] \in \textsf{Sb}_T
      && \text{(tail of $\textsf{Cons}_i$)} \\
    &y : S' \in \Gamma_0
      && \text{(premise)} \\
    &\Semtyp[\Gamma_0]{y}{S'}
      && \text{(by IH on the shorter lookup derivation,} \\
    & && \text{with $\Vdash \Gamma_0$ from $\Vdash \Gamma$ via the tail)} \\
    &\ensuremath{\llbracket S' \rrbracket(\rho[\Uparrow])} \searrow b,\;
      b \in \mathcal{U}_i^\ast \searrow P' \searrow \textbf{El}'
      && \text{(by IH on $S'$ at $\Uparrow \circ \sigma, \rho[\Uparrow]$)} \\
    &\typing[\Delta]{S'[\Uparrow \circ \sigma]}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; P'
      && \text{(by IH on $S'$, type part)} \\
    &\typing[\Delta]{y[\Uparrow \circ \sigma]}{S'[\Uparrow \circ \sigma]}
      \;\circledR\; \ensuremath{\llbracket y \rrbracket(\rho[\Uparrow])} \in \textbf{El}'
      && \text{(by IH on $y$, term part)}
  \end{align*}

  \emph{Bridging the goal evaluation $\ensuremath{\llbracket S'[\Uparrow] \rrbracket(\rho)}$ to $b$.}
  By \Cref{thm:fundamental} of \Cref{sec:comp} on $\typing[\Gamma_0]{S'}{\ensuremath{\texttt{Ty}_{i}}}$
  (extracted from the IH via \Cref{lem:gluing-typ-escape}):
  $\semtyeq[\Gamma_0]{S'}{S'}{\ensuremath{\texttt{Ty}_{i}}}$. Instantiating at $\Uparrow$ and $\rho$
  (self-related in $R_\Gamma$):
  \begin{align*}
    &\ensuremath{\llbracket \Uparrow \rrbracket(\rho)} = \rho[\Uparrow]
      && \text{(by definition of weakening evaluation, \Cref{sec:sem})} \\
    &\ensuremath{\llbracket S'[\Uparrow] \rrbracket(\rho)} \approx \ensuremath{\llbracket S' \rrbracket(\rho[\Uparrow])} \in \mathcal{U}_i \searrow R'
      && \text{(four-value pattern of $\semtyeq[\Gamma_0]{S'}{S'}{\ensuremath{\texttt{Ty}_{i}}}$ at
        $\Uparrow, \rho$)} \\
    &a^\ast \approx b \in \mathcal{U}_i \searrow R'
      && \text{(rewriting $\ensuremath{\llbracket S'[\Uparrow] \rrbracket(\rho)} = a^\ast$ and
        $\ensuremath{\llbracket S' \rrbracket(\rho[\Uparrow])} = b$)} \\
    &a^\ast \in \mathcal{U}_i^\ast \searrow P' \searrow \textbf{El}'
      && \text{(by \Cref{lem:gluing-univ-equiv} from
        $b \in \mathcal{U}_i^\ast \searrow P' \searrow \textbf{El}'$)}
  \end{align*}
  The term-side equality $\ensuremath{\llbracket 1{+}y \rrbracket(\rho)} = \ensuremath{\llbracket y \rrbracket(\rho[\Uparrow])}$ holds
  directly: $\ensuremath{\llbracket 1{+}y \rrbracket(\rho)} = \rho(1{+}y) = \rho[\Uparrow](y) = \ensuremath{\llbracket y \rrbracket(\rho[\Uparrow])}$
  (variable lookup), so no bridging is needed for the term side.

  \emph{Assembling the goal.}
  \begin{align*}
    &(1{+}y)[\sigma] = y[\Uparrow \circ \sigma]
      && \text{(by syntactic action and \Cref{lem:subst-assoc})} \\
    &S'[\Uparrow][\sigma] = S'[\Uparrow \circ \sigma]
      && \text{(by \Cref{lem:subst-assoc})} \\
    &\typing[\Delta]{(1{+}y)[\sigma]}{S'[\Uparrow][\sigma]}
      \;\circledR\; \ensuremath{\llbracket 1{+}y \rrbracket(\rho)} \in \textbf{El}'
      && \text{(rewriting the IH instance via the previous identities)}
  \end{align*}
  This supplies the goal at $a^\ast \in \mathcal{U}_i^\ast \searrow P' \searrow \textbf{El}'$.

By $\Vdash \Gamma$, fix $\Gamma \searrow \textsf{Sb}$ and let
  $\judge[\Delta]{\sigma : \Gamma} \;\circledR\; \rho \in \textsf{Sb}$ be given.
  Type is $\ensuremath{\texttt{Ty}_{i}}$, sitting at universe-level $1+i$. We establish the four
  clauses of $\Semtyp[\Gamma]{\ensuremath{\texttt{Ty}_{j}}}{\ensuremath{\texttt{Ty}_{i}}}$ at $a = U_i$,
  $P = \textsf{Univ}_{1+i, i}$, $\textbf{El} = \textsf{Univ}_{1+i, i}^{\textbf{El}}$.
  \begin{align*}
    &\ensuremath{\llbracket \ensuremath{\texttt{Ty}_{i}} \rrbracket(\rho)} \searrow U_i
      && \text{(by \textsc{ev-U})} \tag*{[clause 1]} \\
    &U_i \in \mathcal{U}_{1+i}^\ast \searrow \textsf{Univ}_{1+i, i} \searrow
      \textsf{Univ}_{1+i, i}^{\textbf{El}}
      && \text{(by \textsc{G-Univ})} \tag*{[clause 2]} \\
    &\ensuremath{\texttt{Ty}_{i}}[\sigma] = \ensuremath{\texttt{Ty}_{i}}
      && \text{(syntactic; closed)} \\
    &\tyequiv[\Delta]{\ensuremath{\texttt{Ty}_{i}}[\sigma]}{\ensuremath{\texttt{Ty}_{i}}}{\ensuremath{\texttt{Ty}_{1+i}}}
      && \text{(by reflexivity)} \\
    &\typing[\Delta]{\ensuremath{\texttt{Ty}_{i}}[\sigma]}{\ensuremath{\texttt{Ty}_{1+i}}} \;\circledR\;
      \textsf{Univ}_{1+i, i}
      && \text{(by \Cref{def:univ-type-pred})} \tag*{[clause 3]} \\
    &\ensuremath{\llbracket \ensuremath{\texttt{Ty}_{j}} \rrbracket(\rho)} \searrow U_j
      && \text{(by \textsc{ev-U})} \\
    &U_j \in \mathcal{U}_{1+j}^\ast \searrow \textsf{Univ}_{1+j, j} \searrow
      \textsf{Univ}_{1+j, j}^{\textbf{El}}
      && \text{(by \textsc{G-Univ} at level $1+j$)} \\
    &U_j \in \mathcal{U}_i^\ast \searrow \textsf{Univ}_{i, j} \searrow
      \textsf{Univ}_{i, j}^{\textbf{El}}
      && \text{(by \Cref{lem:gluing-cumul} from $1+j \le i$, since $j < i$)} \\
    &\tyequiv[\Delta]{\ensuremath{\texttt{Ty}_{j}}[\sigma]}{\ensuremath{\texttt{Ty}_{j}}}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by reflexivity, $j < i$)} \\
    &\typing[\Delta]{\ensuremath{\texttt{Ty}_{j}}[\sigma]}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\;
      U_j \in \textsf{Univ}_{1+i, i}^{\textbf{El}}
      && \text{(by \Cref{def:univ-term-pred} on $U_j \in \mathcal{U}_i^\ast \searrow
        \textsf{Univ}_{i,j} \searrow \textsf{Univ}_{i,j}^{\textbf{El}}$)}
      \tag*{[clause 4]}
  \end{align*}

By $\Vdash \Gamma$, fix $\Gamma \searrow \textsf{Sb}$ and let
  $\judge[\Delta]{\sigma : \Gamma} \;\circledR\; \rho \in \textsf{Sb}$ be given.
  We establish the four clauses of $\Semtyp[\Gamma]{\ensuremath{\texttt{Nat}}}{\ensuremath{\texttt{Ty}_{i}}}$ at
  $a = U_i$, $P = \textsf{Univ}_{1+i, i}$, $\textbf{El} = \textsf{Univ}_{1+i, i}^{\textbf{El}}$.
  \begin{align*}
    &\ensuremath{\llbracket \ensuremath{\texttt{Ty}_{i}} \rrbracket(\rho)} \searrow U_i
      && \text{(by \textsc{ev-U})} \tag*{[clause 1]} \\
    &U_i \in \mathcal{U}_{1+i}^\ast \searrow \textsf{Univ}_{1+i, i}
        \searrow \textsf{Univ}_{1+i, i}^{\textbf{El}}
      && \text{(by \textsc{G-Univ})} \tag*{[clause 2]} \\
    &\ensuremath{\texttt{Ty}_{i}}[\sigma] = \ensuremath{\texttt{Ty}_{i}}
      && \text{(syntactic; closed)} \\
    &\tyequiv[\Delta]{\ensuremath{\texttt{Ty}_{i}}[\sigma]}{\ensuremath{\texttt{Ty}_{i}}}{\ensuremath{\texttt{Ty}_{1+i}}}
      && \text{(by reflexivity)} \\
    &\typing[\Delta]{\ensuremath{\texttt{Ty}_{i}}[\sigma]}{\ensuremath{\texttt{Ty}_{1+i}}} \;\circledR\;
      \textsf{Univ}_{1+i, i}
      && \text{(by \Cref{def:univ-type-pred})} \tag*{[clause 3]} \\
    &\ensuremath{\llbracket \ensuremath{\texttt{Nat}} \rrbracket(\rho)} \searrow N
      && \text{(by \textsc{ev-N})} \\
    &N \in \mathcal{U}_i^\ast \searrow \textsf{Nat}_i \searrow \textsf{Nat}_i
      && \text{(by \textsc{G-Nat})} \\
    &\ensuremath{\texttt{Nat}}[\sigma] = \ensuremath{\texttt{Nat}}
      && \text{(syntactic; closed)} \\
    &\tyequiv[\Delta]{\ensuremath{\texttt{Nat}}[\sigma]}{\ensuremath{\texttt{Nat}}}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by reflexivity)} \\
    &\typing[\Delta]{\ensuremath{\texttt{Nat}}[\sigma]}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\;
      N \in \textsf{Univ}_{1+i, i}^{\textbf{El}}
      && \text{(by \Cref{def:univ-term-pred} on $N \in \mathcal{U}_i^\ast$)}
      \tag*{[clause 4]}
  \end{align*}

\label{lem:fund-sound-pi-wf}
  If $\Semtyp[\Gamma]{S_1}{\ensuremath{\texttt{Ty}_{i}}}$ and $\Semtyp[\Gamma, x:S_1]{S_2}{\ensuremath{\texttt{Ty}_{i}}}$,
  then $\Semtyp[\Gamma]{\Pi(x:S_1).\,S_2}{\ensuremath{\texttt{Ty}_{i}}}$.

Fix $\Gamma \searrow \textsf{Sb}$ from $\Semtyp[\Gamma]{S_1}{\ensuremath{\texttt{Ty}_{i}}}$ and
  $\Gamma, x:S_1 \searrow \textsf{Sb}'$ from $\Semtyp[\Gamma, x:S_1]{S_2}{\ensuremath{\texttt{Ty}_{i}}}$.
  By inversion on \textsc{G-Ctx-Ext} for the latter,
  $\textsf{Sb}' \Leftrightarrow \textsf{Cons}_i(\Gamma, S_1, \textsf{Sb})$
  (using $\textsf{Sb}$ uniqueness up to biimplication via
  \Cref{lem:gluing-functional}).

  Let $\judge[\Delta]{\sigma : \Gamma} \;\circledR\; \rho \in \textsf{Sb}$ be given.
  By hypothesis on $S_1$ at $\sigma, \rho$:
  \begin{align*}
    &\ensuremath{\llbracket S_1 \rrbracket(\rho)} \searrow a_I,\;
      a_I \in \mathcal{U}_i^\ast \searrow P_I \searrow \textbf{El}_I
      && \text{(by hypothesis on $S_1$)} \\
    &\typing[\Delta]{S_1[\sigma]}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; P_I
      && \text{(by hypothesis on $S_1$, type part at level $1+i$)} \\
    &a_I \approx a_I \in \mathcal{U}_i \searrow R_I
      && \text{(by \Cref{lem:gluing-implies-per})} \\
    &\ensuremath{\llbracket \Pi(x:S_1).\,S_2 \rrbracket(\rho)} \searrow \Pi(a_I,\, S_2,\, \rho)
      && \text{(by \textsc{ev-Pi})}
  \end{align*}
  By syntactic substitution:
  \begin{align*}
    &(\Pi(x:S_1).\,S_2)[\sigma] = \Pi(x:S_1[\sigma]).\,(S_2[q(\sigma)])
      && \text{(definition of substitution on $\Pi$)}
  \end{align*}
  We construct $\Pi(a_I, S_2, \rho) \in \mathcal{U}_i^\ast$ by \textsc{G-Pi}, deriving
  each premise. We first establish the PER-side membership of the $\Pi$, which
  introduces the codomain PER family $R_O$ used below.

  \emph{PER-side: $\Pi(a_I, S_2, \rho) \approx \Pi(a_I, S_2, \rho) \in \mathcal{U}_i \searrow R$.}
  \begin{align*}
    &\typing[\Gamma]{S_1}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by \Cref{lem:gluing-typ-escape} on hypothesis $S_1$)} \\
    &\typing[\Gamma, x:S_1]{S_2}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by \Cref{lem:gluing-typ-escape} on hypothesis $S_2$)} \\
    &\typing[\Gamma]{\Pi(x:S_1).\,S_2}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by \textsc{$\Pi$-Wf})} \\
    &\semtyeq[\Gamma]{\Pi(x:S_1).\,S_2}{\Pi(x:S_1).\,S_2}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by \Cref{thm:fundamental} of \Cref{sec:comp})} \\
    &\Pi(a_I, S_2, \rho) \approx \Pi(a_I, S_2, \rho) \in \mathcal{U}_i \searrow R
      && \text{(by instantiating at $\sigma, \rho$ self-related in $R_\Gamma$)}
  \end{align*}
  Inverting the resulting \textsc{U-Pi} witness yields the codomain PER
  family: for every $\ensuremath{\mathcal{D}} :: b \approx b \in R_I$,
  $\ensuremath{\llbracket S_2 \rrbracket((\rho, b/x))} \approx \ensuremath{\llbracket S_2 \rrbracket((\rho, b/x))} \in \mathcal{U}_i \searrow
  R_O(\ensuremath{\mathcal{D}})$.

  \emph{Codomain gluing.} Let $\ensuremath{\mathcal{D}} :: b \approx b \in R_I$ and $c$ with
  $\ensuremath{\llbracket S_2 \rrbracket((\rho, b/x))} \searrow c$ be given.
  \begin{align*}
    &c \approx c \in \mathcal{U}_i \searrow R_O(\ensuremath{\mathcal{D}})
      && \text{(by the codomain PER family established above)} \\
    &c \in \mathcal{U}_i^\ast \searrow P_O(\ensuremath{\mathcal{D}}) \searrow \textbf{El}_O(\ensuremath{\mathcal{D}})
      && \text{(by \Cref{lem:per-implies-gluing})}
  \end{align*}
  This defines $P_O(\ensuremath{\mathcal{D}}), \textbf{El}_O(\ensuremath{\mathcal{D}})$; functionality in $\ensuremath{\mathcal{D}}$ follows from
  \Cref{lem:gluing-functional}, since glu-univ-elem predicates at a fixed
  domain value are unique up to logical equivalence.

  Combining all premises:
  \begin{align*}
    &\Pi(a_I, S_2, \rho) \in \mathcal{U}_i^\ast \searrow
      \Pi_i(R_I, P_I, \textbf{El}_I, P_O) \searrow \Pi_i^{\textbf{El}}(R, R_I, P_I, \textbf{El}_I, \textbf{El}_O)
      && \text{(by \textsc{G-Pi})}
  \end{align*}

  \emph{Type-predicate $\Pi_i$ at $(\Pi(x:S_1).\,S_2)[\sigma]$.} We verify the
  three clauses of \Cref{def:pi-type-pred}.

  \emph{Clause 1.}
  \begin{align*}
    &(\Pi(x:S_1).\,S_2)[\sigma] = \Pi(x:S_1[\sigma]).\,(S_2[q(\sigma)])
      && \text{(syntactic substitution on $\Pi$)} \\
    &\tyequiv[\Delta]{(\Pi(x:S_1).\,S_2)[\sigma]}
                     {\Pi(x:S_1[\sigma]).\,(S_2[q(\sigma)])}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by reflexivity)}
  \end{align*}

  \emph{Clause 2 (domain Kripke).} For each $\kweak[\Delta'']{\phi'}{\Delta}$:
  \begin{align*}
    &\judge[\Delta'']{\sigma[\phi'] : \Gamma}
      \;\circledR\; \rho \in \textsf{Sb}
      && \text{(by \Cref{cor:ctx-mono})} \\
    &\typing[\Delta'']{S_1[\sigma[\phi']]}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; P_I
      && \text{(by hypothesis on $S_1$, type part at $\sigma[\phi'], \rho$)} \\
    &S_1[\sigma][\phi'] = S_1[\sigma[\phi']]
      && \text{(by \Cref{lem:subst-assoc})} \\
    &\typing[\Delta'']{S_1[\sigma][\phi']}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; P_I
      && \text{(rewriting)}
  \end{align*}

  \emph{Clause 3 (codomain Kripke).} For each $\kweak[\Delta'']{\phi'}{\Delta}$,
  $s', b', \ensuremath{\mathcal{D}} :: b' \approx b' \in R_I$ with
  $\typing[\Delta'']{s'}{S_1[\sigma][\phi']} \;\circledR\; b' \in \textbf{El}_I$,
  set $\sigma_*' := (\sigma[\phi'],\, s'/x)$. We first transport the
  substitution into $\textsf{Sb}'$, then unpack
  $\Semtyp[\Gamma, x:S_1]{S_2}{\ensuremath{\texttt{Ty}_{i}}}$ at the resulting pair.
  \begin{align*}
    &\judge[\Delta'']{\sigma[\phi'] : \Gamma}
      \;\circledR\; \rho \in \textsf{Sb}
      && \text{(by \Cref{cor:ctx-mono} on the substitution-environment pair)} \\
    &\judge[\Delta'']{\sigma_*' : \Gamma, x:S_1}
      \;\circledR\; (\rho, b'/x) \in \textsf{Sb}'
      && \text{(by \textsc{G-Ctx-Ext}'s $\textsf{Cons}_i$, head: $b' \in \textbf{El}_I$)}
  \end{align*}
  Instantiating $\Semtyp[\Gamma, x:S_1]{S_2}{\ensuremath{\texttt{Ty}_{i}}}$ at $\sigma_*',
  (\rho, b'/x)$ yields the four clauses of \Cref{sec:sound:sem-rules}'s
  semantic typing judgment at $a = U_i$, $P = \textsf{Univ}_{1+i,i}$,
  $\textbf{El} = \textsf{Univ}_{1+i,i}^{\textbf{El}}$. The fourth clause states
  $\typing[\Delta'']{S_2[\sigma_*']}{\ensuremath{\texttt{Ty}_{i}}[\sigma_*']} \;\circledR\;
  \ensuremath{\llbracket S_2 \rrbracket((\rho, b'/x))} \in \textsf{Univ}_{1+i,i}^{\textbf{El}}$.
  Unpacking \Cref{def:univ-term-pred}:
  \begin{align*}
    &\ensuremath{\llbracket S_2 \rrbracket((\rho, b'/x))} \searrow c_{b'}
      && \text{(evaluation; deterministic)} \\
    &c_{b'} \in \mathcal{U}_i^\ast \searrow P_{b'} \searrow \textbf{El}_{b'}
      && \text{(by \Cref{def:univ-term-pred} clause (3))} \\
    &\typing[\Delta'']{S_2[\sigma_*']}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; P_{b'}
      && \text{(by \Cref{def:univ-term-pred} clause (3), Russell type-side gluing)}
  \end{align*}
  By \Cref{lem:gluing-functional} (the gluing-model membership $c_{b'} \in
  \mathcal{U}_i^\ast$ uniquely determines its predicates up to extensional
  equivalence), $P_{b'} \Leftrightarrow P_O(\ensuremath{\mathcal{D}})$ and $\textbf{El}_{b'}
  \Leftrightarrow \textbf{El}_O(\ensuremath{\mathcal{D}})$, where $P_O, \textbf{El}_O$ are the codomain
  predicates established in the Codomain-gluing block. Rewriting:
  \begin{align*}
    &c_{b'} \in \mathcal{U}_i^\ast \searrow P_O(\ensuremath{\mathcal{D}}) \searrow \textbf{El}_O(\ensuremath{\mathcal{D}})
      && \text{(by \Cref{lem:gluing-functional})} \\
    &S_2[\sigma_*'] = S_2[(\sigma[\phi'], s'/x)] = S_2[q(\sigma)][\phi', s'/x]
      && \text{(by \Cref{lem:q-ext-gen})} \\
    &\typing[\Delta'']{S_2[q(\sigma)][\phi', s'/x]}{\ensuremath{\texttt{Ty}_{i}}}
      \;\circledR\; P_O(\ensuremath{\mathcal{D}})
      && \text{(rewriting the previous type-gluing line)}
  \end{align*}
  Combining the three clauses of $\Pi_i$:
  \begin{align*}
    &\typing[\Delta]{\Pi(x:S_1[\sigma]).\,(S_2[q(\sigma)])}{\ensuremath{\texttt{Ty}_{i}}}
      \;\circledR\; \Pi_i(R_I, P_I, \textbf{El}_I, P_O)
      && \text{(by \Cref{def:pi-type-pred} clauses 1--3)} \\
    &\typing[\Delta]{(\Pi(x:S_1).\,S_2)[\sigma]}{\ensuremath{\texttt{Ty}_{i}}}
      \;\circledR\; \Pi_i(R_I, P_I, \textbf{El}_I, P_O)
      && \text{(by clause 1's equality on the LHS)}
  \end{align*}
  For the term predicate at $\ensuremath{\texttt{Ty}_{1+i}}$, $\Pi(a_I, S_2, \rho) \in \mathcal{U}_i^\ast$ by
  the previous derivation, the four clauses of $\Semtyp[\Gamma]{\Pi(x:S_1).\,S_2}{\ensuremath{\texttt{Ty}_{i}}}$
  at $a = U_i$, $P = \textsf{Univ}_{1+i, i}$, $\textbf{El} = \textsf{Univ}_{1+i, i}^{\textbf{El}}$:
  \begin{align*}
    &\ensuremath{\llbracket \ensuremath{\texttt{Ty}_{i}} \rrbracket(\rho)} \searrow U_i
      && \text{(by \textsc{ev-U})} \tag*{[clause 1]} \\
    &U_i \in \mathcal{U}_{1+i}^\ast \searrow \textsf{Univ}_{1+i, i} \searrow
      \textsf{Univ}_{1+i, i}^{\textbf{El}}
      && \text{(by \textsc{G-Univ})} \tag*{[clause 2]} \\
    &\typing[\Delta]{\ensuremath{\texttt{Ty}_{i}}[\sigma]}{\ensuremath{\texttt{Ty}_{1+i}}} \;\circledR\;
      \textsf{Univ}_{1+i, i}
      && \text{(by \Cref{def:univ-type-pred} with $\ensuremath{\texttt{Ty}_{i}}[\sigma] = \ensuremath{\texttt{Ty}_{i}}$)}
      \tag*{[clause 3]} \\
    &\typing[\Delta]{(\Pi(x:S_1).\,S_2)[\sigma]}{\ensuremath{\texttt{Ty}_{i}}}
      \;\circledR\; \Pi(a_I, S_2, \rho) \in \textsf{Univ}_{1+i, i}^{\textbf{El}}
      && \text{(by \Cref{def:univ-term-pred} on the $\Pi$-gluing above)}
      \tag*{[clause 4]}
  \end{align*}

By $\Vdash \Gamma$, fix $\Gamma \searrow \textsf{Sb}$ and let
  $\judge[\Delta]{\sigma : \Gamma} \;\circledR\; \rho \in \textsf{Sb}$ be given.
  We establish the four clauses of $\Semtyp[\Gamma]{\textsf{zero}}{\ensuremath{\texttt{Nat}}}$ at $a = N$,
  $P = \textsf{Nat}_i$, $\textbf{El} = \textsf{Nat}_i$.
  \begin{align*}
    &\ensuremath{\llbracket \ensuremath{\texttt{Nat}} \rrbracket(\rho)} \searrow N
      && \text{(by \textsc{ev-N})} \tag*{[clause 1]} \\
    &N \in \mathcal{U}_i^\ast \searrow \textsf{Nat}_i \searrow \textsf{Nat}_i
      && \text{(by \textsc{G-Nat})} \tag*{[clause 2]} \\
    &\ensuremath{\texttt{Nat}}[\sigma] = \ensuremath{\texttt{Nat}}
      && \text{(syntactic; closed)} \\
    &\tyequiv[\Delta]{\ensuremath{\texttt{Nat}}[\sigma]}{\ensuremath{\texttt{Nat}}}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by reflexivity)} \\
    &\typing[\Delta]{\ensuremath{\texttt{Nat}}[\sigma]}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; \textsf{Nat}_i
      && \text{(by \Cref{def:nat-type-pred})} \tag*{[clause 3]} \\
    &\ensuremath{\llbracket \textsf{zero} \rrbracket(\rho)} \searrow \texttt{ze}
      && \text{(by \textsc{ev-ze})} \\
    &\textsf{zero}[\sigma] = \textsf{zero}
      && \text{(syntactic; closed)} \\
    &\tyequiv[\Delta]{\textsf{zero}[\sigma]}{\textsf{zero}}{\ensuremath{\texttt{Nat}}[\sigma]}
      && \text{(by reflexivity)} \\
    &\typing[\Delta]{\textsf{zero}[\sigma]}{\ensuremath{\texttt{Nat}}[\sigma]} \;\circledR\;
      \texttt{ze} \in \textsf{Nat}_i
      && \text{(by \textsc{GN-Ze} combined with the type predicate}\\
    & && \text{above, \Cref{def:nat-term-pred})} \tag*{[clause 4]}
  \end{align*}

$\Vdash \Gamma$ is presupposed; fix $\Gamma \searrow \textsf{Sb}_\Gamma$
  and $\Gamma, x:S_1 \searrow \textsf{Sb}_{\Gamma,x:S_1}$ where, by inversion
  on \textsc{G-Ctx-Ext}, $\textsf{Sb}_{\Gamma,x:S_1} \Leftrightarrow
  \textsf{Cons}_i(\Gamma, S_1, \textsf{Sb}_\Gamma)$. By
  \Cref{lem:gluing-typ-escape} on the hypotheses:
  \begin{align*}
    &\typing[\Gamma]{S_1}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by \Cref{lem:gluing-typ-escape} on the $S_1$ hypothesis)} \\
    &\typing[\Gamma, x:S_1]{S_2}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by \Cref{lem:gluing-typ-escape} on the $S_2$ hypothesis)} \\
    &\typing[\Gamma, x:S_1]{t}{S_2}
      && \text{(by \Cref{lem:gluing-trm-escape} on the $t$ hypothesis)} \\
    &\typing[\Gamma]{\lambda x.\,t}{\Pi(x:S_1).\,S_2}
      && \text{(by \textsc{$\lambda$-I})}
  \end{align*}
  By \Cref{lem:fund-sound-pi-wf} on the $S_1, S_2$ hypotheses,
  $\Semtyp[\Gamma]{\Pi(x:S_1).\,S_2}{\ensuremath{\texttt{Ty}_{i}}}$.

  Let $\judge[\Delta]{\sigma : \Gamma} \;\circledR\; \rho \in
  \textsf{Sb}_\Gamma$ be given.
  \begin{align*}
    &\ensuremath{\llbracket S_1 \rrbracket(\rho)} \searrow a_I,\;
      a_I \in \mathcal{U}_i^\ast \searrow P_I \searrow \textbf{El}_I
      && \text{(by hypothesis on $S_1$, evaluation and gluing clauses)} \\
    &a_I \approx a_I \in \mathcal{U}_i \searrow R_I
      && \text{(by \Cref{lem:gluing-implies-per})} \\
    &\typing[\Delta]{S_1[\sigma]}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; P_I
      && \text{(by hypothesis on $S_1$, type clause)} \\
    &\ensuremath{\llbracket \Pi(x:S_1).\,S_2 \rrbracket(\rho)} \searrow \Pi(a_I,\, S_2,\, \rho)
      && \text{(by \textsc{ev-Pi})} \\
    &\ensuremath{\llbracket \lambda x.\,t \rrbracket(\rho)} \searrow \lambda(t, \rho)
      && \text{(by \textsc{ev-lam})} \\
    &\Pi(a_I, S_2, \rho) \in \mathcal{U}_i^\ast \\
    & \quad \searrow \Pi_i(R_I, P_I, \textbf{El}_I, P_O)
      \searrow \Pi_i^{\textbf{El}}(R, R_I, P_I, \textbf{El}_I, \textbf{El}_O)
      && \text{(by \Cref{lem:fund-sound-pi-wf}, gluing clause)} \\
    &\typing[\Delta]{(\Pi(x:S_1).\,S_2)[\sigma]}{\ensuremath{\texttt{Ty}_{i}}}
      \;\circledR\; \Pi_i(R_I, P_I, \textbf{El}_I, P_O)
      && \text{(by \Cref{lem:fund-sound-pi-wf}, type clause)}
  \end{align*}
  We assemble the four clauses of $\Semtyp[\Gamma]{\lambda x.\,t}
  {\Pi(x:S_1).\,S_2}$ at $a := \Pi(a_I, S_2, \rho)$,
  $P := \Pi_i(R_I, P_I, \textbf{El}_I, P_O)$,
  $\textbf{El} := \Pi_i^{\textbf{El}}(R, R_I, P_I, \textbf{El}_I, \textbf{El}_O)$:
  \begin{align*}
    &\ensuremath{\llbracket \Pi(x:S_1).\,S_2 \rrbracket(\rho)} \searrow \Pi(a_I, S_2, \rho)
      && \tag*{[clause 1]} \\
    &\Pi(a_I, S_2, \rho) \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El}
      && \tag*{[clause 2]} \\
    &\typing[\Delta]{(\Pi(x:S_1).\,S_2)[\sigma]}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; P
      && \tag*{[clause 3]}
  \end{align*}
  All three are restated from the per-substitution data block. For
  clause~(4), we must show
  $\typing[\Delta]{(\lambda x.\,t)[\sigma]}{(\Pi(x:S_1).\,S_2)[\sigma]}
  \;\circledR\; \lambda(t, \rho) \in \textbf{El}$. We verify the four sub-clauses
  of \Cref{def:pi-term-pred}.

  \emph{Sub-clause (1): $\typing[\Delta]{(\lambda x.\,t)[\sigma]}
  {(\Pi(x:S_1).\,S_2)[\sigma]}$.} By syntactic substitution applied to
  $\typing[\Gamma]{\lambda x.\,t}{\Pi(x:S_1).\,S_2}$ along
  $\judge[\Delta]{\sigma : \Gamma}$.

  \emph{Sub-clause (2): $\lambda(t, \rho) \approx \lambda(t, \rho) \in R$.}
  By \Cref{thm:fundamental} of \Cref{sec:comp} on
  $\typing[\Gamma]{\lambda x.\,t}{\Pi(x:S_1).\,S_2}$, instantiated at
  $\rho \approx \rho \in \ensuremath{\llbracket \Gamma \rrbracket}$ (self-related via
  \Cref{lem:gluing-implies-per}):
  $\lambda(t, \rho) \approx \lambda(t, \rho) \in R$.

  \emph{Sub-clause (3): $\typing[\Delta]{(\Pi(x:S_1).\,S_2)[\sigma]}{\ensuremath{\texttt{Ty}_{i}}}
  \;\circledR\; \Pi_i(R_I, P_I, \textbf{El}_I, P_O)$.} Established above from
  \Cref{lem:fund-sound-pi-wf}.

  \emph{Sub-clause (4): application.} Given $\kweak[\Delta']{\phi}{\Delta}$
  and $s, b$ with $\typing[\Delta']{s}{S_1[\sigma][\phi]} \;\circledR\; b
  \in \textbf{El}_I$, and $\ensuremath{\mathcal{D}} :: b \approx b \in R_I$ (by
  \Cref{lem:gluing-implies-per} on $b \in \textbf{El}_I$). Set $\sigma_*' :=
  (\sigma[\phi],\, s/x)$.
  \begin{align*}
    &\judge[\Delta']{\sigma[\phi] : \Gamma}
      \;\circledR\; \rho \in \textsf{Sb}_\Gamma
      && \text{(by \Cref{cor:ctx-mono} on $\sigma, \rho$ along $\phi$)} \\
    &\typing[\Delta']{S_1[\sigma[\phi]]}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; P_I
      && \text{(by hypothesis on $S_1$ at $\sigma[\phi], \rho$, type clause)} \\
    &S_1[\sigma][\phi] = S_1[\sigma[\phi]]
      && \text{(by \Cref{lem:subst-assoc})} \\
    &\typing[\Delta']{s}{S_1[\sigma[\phi]]} \;\circledR\; b \in \textbf{El}_I
      && \text{(rewriting via the previous line)} \\
    &\judge[\Delta']{\sigma_*' : \Gamma, x:S_1}
      \;\circledR\; (\rho, b/x) \in \textsf{Sb}_{\Gamma,x:S_1}
      && \text{(by $\textsf{Cons}_i$ on the type-side $P_I$ and the
        term-side $b \in \textbf{El}_I$,} \\
    & && \text{realized by $s$ at $S_1[\sigma[\phi]]$)}
  \end{align*}
  Instantiate the $t$-hypothesis at $\sigma_*', (\rho, b/x)$:
  \begin{align*}
    &\ensuremath{\llbracket t \rrbracket((\rho, b/x))} \searrow c
      && \text{(by hypothesis on $t$, evaluation clause)} \\
    &\ensuremath{\llbracket S_2 \rrbracket((\rho, b/x))} \searrow a'
      && \text{(by hypothesis on $t$, type-eval clause)} \\
    &a' \in \mathcal{U}_i^\ast \searrow P' \searrow \textbf{El}'
      && \text{(by hypothesis on $t$, gluing clause)} \\
    &\typing[\Delta']{t[\sigma_*']}{S_2[\sigma_*']}
      \;\circledR\; c \in \textbf{El}'
      && \text{(by hypothesis on $t$, term clause)} \\
    &P' \Leftrightarrow P_O(\ensuremath{\mathcal{D}}),\;\;
      \textbf{El}' \Leftrightarrow \textbf{El}_O(\ensuremath{\mathcal{D}})
      && \text{(by \Cref{lem:gluing-functional}: same $a'$
        as in} \\
    & && \text{\Cref{lem:fund-sound-pi-wf}; gluing-model
        predicates at} \\
    & && \text{a fixed value are unique up to logical
        equivalence)} \\
    &\typing[\Delta']{t[\sigma_*']}{S_2[\sigma_*']}
      \;\circledR\; c \in \textbf{El}_O(\ensuremath{\mathcal{D}})
      && \text{(rewriting via the previous line)} \\
    &\lambda(t, \rho) \cdot b \searrow c
      && \text{(by \textsc{ev-app-clos})}
  \end{align*}
  Compute syntactic identities for the resulting term and type:
  \begin{align*}
    &(\lambda x.\,t)[\sigma] = \lambda x.\,(t[q(\sigma)])
      && \text{(by syntactic substitution on $\lambda$)} \\
    &(\lambda x.\,(t[q(\sigma)]))[\phi] = \lambda x.\,(t[q(\sigma)][q(\phi)])
      && \text{(by syntactic substitution on $\lambda$ along $\phi$)} \\
    &t[q(\sigma)][q(\phi)] = t[q(\sigma) \circ q(\phi)] = t[q(\sigma[\phi])]
      && \text{(by \Cref{lem:subst-assoc} and \Cref{lem:subst-q-comp})} \\
    &(\lambda x.\,t)[\sigma][\phi] = \lambda x.\,(t[q(\sigma[\phi])])
      && \text{(combining)} \\
    &t[q(\sigma[\phi])][s/x] = t[\sigma_*']
      && \text{(by \Cref{lem:q-ext})} \\
    &S_2[q(\sigma[\phi])][s/x] = S_2[\sigma_*']
      && \text{(by \Cref{lem:q-ext})}
  \end{align*}
  Apply the $\beta$-rule with premises
  $\typing[\Delta']{S_1[\sigma[\phi]]}{\ensuremath{\texttt{Ty}_{i}}}$ (escaped above);
  $\typing[\Delta', x:S_1[\sigma[\phi]]]{S_2[q(\sigma[\phi])]}{\ensuremath{\texttt{Ty}_{i}}}$ (by
  substitution typing on the $S_2$ escape along $q(\sigma[\phi])$);
  $\typing[\Delta', x:S_1[\sigma[\phi]]]{t[q(\sigma[\phi])]}
  {S_2[q(\sigma[\phi])]}$ (by substitution typing on the $t$ escape); and
  $\typing[\Delta']{s}{S_1[\sigma[\phi]]}$ (escape on $s$):
  \begin{align*}
    &\tyequiv[\Delta']{(\lambda x.\,(t[q(\sigma[\phi])]))\;s}
                     {t[q(\sigma[\phi])][s/x]}
                     {S_2[q(\sigma[\phi])][s/x]}
      && \text{(by $\beta$)} \\
    &\tyequiv[\Delta']{(\lambda x.\,t)[\sigma][\phi]\;s}
                     {t[\sigma_*']}
                     {S_2[\sigma_*']}
      && \text{(rewriting)} \\
    &\typing[\Delta']{(\lambda x.\,t)[\sigma][\phi]\;s}{S_2[\sigma_*']}
      \;\circledR\; c \in \textbf{El}_O(\ensuremath{\mathcal{D}})
      && \text{(by \Cref{lem:gluing-respects-eq})} \\
    &S_2[\sigma_*'] = S_2[q(\sigma)][\iota(\phi), s/x]
      && \text{(by \Cref{lem:q-ext-gen})} \\
    &\typing[\Delta']{(\lambda x.\,t)[\sigma][\phi]\;s}
                    {S_2[q(\sigma)][\iota(\phi), s/x]}
      \;\circledR\; c \in \textbf{El}_O(\ensuremath{\mathcal{D}})
      && \text{(rewriting; matches} \\
    & && \text{\Cref{def:pi-term-pred} clause~(4))}
  \end{align*}

Write $E := \ensuremath{\textsf{elim}_{\ensuremath{\texttt{Nat}}}~(x.\,T[q(\sigma)])~z[\sigma]~(x, y.\,s[q(q(\sigma))])~t_*}$
  for the syntactic recursor under $\sigma$. By inner induction on
  $b \in \textsf{Nat}$ (\Cref{def:nat-term-pred}).

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{GN-Ze}]
    {\tyequiv[\Delta]{t_*}{\textsf{zero}}{\ensuremath{\texttt{Nat}}}}
    {\typing[\Delta]{t_*}{\ensuremath{\texttt{Nat}}} \;\circledR\; \texttt{ze} \in \textsf{Nat}}
  \end{mathpar}
  Here $b = \texttt{ze}$, so the helper's hypothesis specializes to
  $\ensuremath{\llbracket T \rrbracket((\rho, \texttt{ze}/x))} \searrow a$.
  \begin{align*}
    &\ensuremath{\llbracket T[\textsf{zero}/x] \rrbracket(\rho)} \searrow a^{ze}
      && \text{(by hypothesis on $z$, type-evaluation clause)} \\
    &a^{ze} \in \mathcal{U}_i^\ast \searrow P^{ze} \searrow \textbf{El}^{ze}
      && \text{(by hypothesis on $z$, gluing clause)} \\
    &\ensuremath{\llbracket z \rrbracket(\rho)} \searrow r_z
      && \text{(by hypothesis on $z$, evaluation clause)} \\
    &\typing[\Delta]{z[\sigma]}{T[\textsf{zero}/x][\sigma]}
      \;\circledR\; r_z \in \textbf{El}^{ze}
      && \text{(by hypothesis on $z$, term clause)} \\
    &\mathsf{rec}(\texttt{ze}, T, z, s, \rho) \searrow r_z
      && \text{(by \textsc{rec-ze})} \\
    &a^{ze} \approx a \in \mathcal{U}_i
      && \text{(by completeness on
        $\typing[\Gamma, x:\ensuremath{\texttt{Nat}}]{T}{\ensuremath{\texttt{Ty}_{i}}}$ instantiated at} \\
    & && \text{$(\ensuremath{\textsf{id}}, \textsf{zero}/x)$; both evaluations
        produce the same value modulo $\mathcal{U}_i$)} \\
    &\textbf{El}^{ze} \Leftrightarrow \textbf{El}
      && \text{(by \Cref{lem:gluing-functional}: gluing-model
        predicates at} \\
    & && \text{the same value are unique up to logical equivalence)} \\
    &T[\textsf{zero}/x][\sigma] = T[\sigma, \textsf{zero}/x]
      && \text{(by \Cref{lem:subst-ext-comm})} \\
    &\tyequiv[\Delta]{T[\sigma, \textsf{zero}/x]}{T[\sigma, t_*/x]}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by \Cref{cor:subst-head-eq} on
        $\typing[\Gamma, x:\ensuremath{\texttt{Nat}}]{T}{\ensuremath{\texttt{Ty}_{i}}}$ from
        \Cref{lem:gluing-typ-escape},} \\
    & && \text{the substitution $\sigma$, and the head equality
        $\tyequiv[\Delta]{\textsf{zero}}{t_*}{\ensuremath{\texttt{Nat}}}$} \\
    & && \text{from $\tyequiv[\Delta]{t_*}{\textsf{zero}}{\ensuremath{\texttt{Nat}}}$ by symmetry)} \\
    &\tyequiv[\Delta]{E}{z[\sigma]}{T[\sigma, t_*/x]}
      && \text{(by the $\beta$-zero rule combined with
        $\tyequiv[\Delta]{t_*}{\textsf{zero}}{\ensuremath{\texttt{Nat}}}$)} \\
    &\typing[\Delta]{E}{T[\sigma, t_*/x]}
      \;\circledR\; r_z \in \textbf{El}
      && \text{(by \Cref{lem:gluing-respects-eq} on the previous
        lines)}
  \end{align*}
  Take $r := r_z$.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{GN-Su}]
    {\typing[\Delta]{t_*'}{\ensuremath{\texttt{Nat}}} \;\circledR\; b' \in \textsf{Nat} \\
     \tyequiv[\Delta]{t_*}{\textsf{succ}~t_*'}{\ensuremath{\texttt{Nat}}}}
    {\typing[\Delta]{t_*}{\ensuremath{\texttt{Nat}}} \;\circledR\; \texttt{su}(b') \in \textsf{Nat}}
  \end{mathpar}
  Here $b = \texttt{su}(b')$.

  \emph{Predecessor via inner IH.}
  We need to apply the helper inductively at $t_*', b'$. By
  \Cref{thm:fundamental} of \Cref{sec:comp} on
  $\typing[\Gamma, x:\ensuremath{\texttt{Nat}}]{T}{\ensuremath{\texttt{Ty}_{i}}}$ instantiated at the related
  environments $(\rho, b'/x) \approx (\rho, b'/x) \in \ensuremath{\llbracket \Gamma, x:\ensuremath{\texttt{Nat}} \rrbracket}$
  (using $b' \in R_\ensuremath{\texttt{Nat}}$ via \Cref{lem:gluing-implies-per} on the inner
  predecessor):
  \begin{align*}
    &\ensuremath{\llbracket T \rrbracket((\rho, b'/x))} \searrow a'
      && \text{(by completeness on $T$)} \\
    &a' \in \mathcal{U}_i^\ast \searrow P' \searrow \textbf{El}'
      && \text{(by \Cref{lem:per-implies-gluing} on $a' \approx a' \in \mathcal{U}_i$)} \\
    &\mathsf{rec}(b', T, z, s, \rho) \searrow r',\;
      \typing[\Delta]{E'}{T[\sigma, t_*'/x]} \;\circledR\; r' \in \textbf{El}'
      && \text{(by inner IH on $b', t_*', a', P', \textbf{El}'$;} \\
    & && \text{$E' := \ensuremath{\textsf{elim}_{\ensuremath{\texttt{Nat}}}~(x.\,T[q(\sigma)])~z[\sigma]~(x, y.\,s[q(q(\sigma))])~t_*'}$)}
  \end{align*}

  \emph{Step instantiation.} Set
  $\sigma_{\text{step}} := (\sigma, t_*'/x, E'/y)$ and
  $\rho_{\text{step}} := (\rho, b'/x, r'/y)$.
  \begin{align*}
    &\judge[\Delta]{(\sigma, t_*'/x) : \Gamma, x:\ensuremath{\texttt{Nat}}}
      \;\circledR\; (\rho, b'/x) \in \textsf{Sb}_{x:\ensuremath{\texttt{Nat}}}
      && \text{(by $\textsf{Cons}_0$ on
        $\typing[\Delta]{t_*'}{\ensuremath{\texttt{Nat}}[\sigma]} \;\circledR\; b' \in \textsf{Nat}_i$,} \\
    & && \text{after rewriting $\ensuremath{\texttt{Nat}}[\sigma] = \ensuremath{\texttt{Nat}}$)} \\
    &\judge[\Delta]{\sigma_{\text{step}} : \Gamma, x:\ensuremath{\texttt{Nat}}, y:T}
      \;\circledR\; \rho_{\text{step}} \in \textsf{Sb}_{x:\ensuremath{\texttt{Nat}},y:T}
      && \text{(by $\textsf{Cons}_i$ on the previous line, head
        $r' \in \textbf{El}'$,} \\
    & && \text{type bridged via \Cref{lem:gluing-respects-eq})} \\
    &\ensuremath{\llbracket T[\Uparrow \circ \Uparrow, \textsf{succ}~x_1/x] \rrbracket(\rho_{\text{step}})}
      \searrow a^{su}
      && \text{(by hypothesis on $s$, type-evaluation clause)} \\
    &a^{su} \in \mathcal{U}_i^\ast \searrow P^{su} \searrow \textbf{El}^{su}
      && \text{(by hypothesis on $s$, gluing clause)} \\
    &\ensuremath{\llbracket s \rrbracket(\rho_{\text{step}})} \searrow r_s
      && \text{(by hypothesis on $s$, evaluation clause)} \\
    &\typing[\Delta]
      {s[\sigma_{\text{step}}]}
      {T[\Uparrow \circ \Uparrow, \textsf{succ}~x_1/x][\sigma_{\text{step}}]}
      \;\circledR\; r_s \in \textbf{El}^{su}
      && \text{(by hypothesis on $s$, term clause)} \\
    &\mathsf{rec}(\texttt{su}(b'), T, z, s, \rho) \searrow r_s
      && \text{(by \textsc{rec-su} on $\mathsf{rec}(b', \ldots) \searrow r'$
        and $\ensuremath{\llbracket s \rrbracket(\rho_{\text{step}})} \searrow r_s$)}
  \end{align*}

  \emph{Type rewriting for the step branch.} We compute the substituted
  motive type:
  \begin{align*}
    &T[\Uparrow \circ \Uparrow, \textsf{succ}~x_1/x][\sigma_{\text{step}}]
      = T[(\Uparrow \circ \Uparrow, \textsf{succ}~x_1/x) \circ \sigma_{\text{step}}]
      && \text{(by \Cref{lem:subst-assoc})} \\
    &(\Uparrow \circ \Uparrow, \textsf{succ}~x_1/x) \circ \sigma_{\text{step}}
      = (\Uparrow \circ \Uparrow \circ \sigma_{\text{step}},\,
         \textsf{succ}~x_1[\sigma_{\text{step}}]/x)
      && \text{(by \Cref{lem:ext-comp})} \\
    &\Uparrow \circ \sigma_{\text{step}} = (\sigma, t_*'/x),\;
      \Uparrow \circ (\sigma, t_*'/x) = \sigma
      && \text{(by \Cref{lem:shift-ext})} \\
    &\Uparrow \circ \Uparrow \circ \sigma_{\text{step}} = \sigma
      && \text{(combining)} \\
    &x_1[\sigma_{\text{step}}] = t_*'
      && \text{(de Bruijn lookup at index 1 in $\sigma_{\text{step}}$)} \\
    &\textsf{succ}~x_1[\sigma_{\text{step}}] = \textsf{succ}~x_1[\sigma_{\text{step}}]
      = \textsf{succ}~t_*'
      && \text{(by syntactic substitution on $\textsf{succ}~$)} \\
    &T[\Uparrow \circ \Uparrow, \textsf{succ}~x_1/x][\sigma_{\text{step}}]
      = T[\sigma, \textsf{succ}~t_*'/x]
      && \text{(combining the previous lines)} \\
    &\tyequiv[\Delta]{T[\sigma, \textsf{succ}~t_*'/x]}{T[\sigma, t_*/x]}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by \Cref{cor:subst-head-eq} on
        $\typing[\Gamma, x:\ensuremath{\texttt{Nat}}]{T}{\ensuremath{\texttt{Ty}_{i}}}$, the} \\
    & && \text{substitution $\sigma$, and the head equality
        $\tyequiv[\Delta]{\textsf{succ}~t_*'}{t_*}{\ensuremath{\texttt{Nat}}}$} \\
    & && \text{from $\tyequiv[\Delta]{t_*}{\textsf{succ}~t_*'}{\ensuremath{\texttt{Nat}}}$ by symmetry)}
  \end{align*}

  \emph{Functionality.} By the type rewriting,
  $T[\Uparrow \circ \Uparrow, \textsf{succ}~x_1/x][\sigma_{\text{step}}]
  = T[\sigma, \textsf{succ}~t_*'/x]$, whose evaluation is
  $\ensuremath{\llbracket T \rrbracket((\rho, \texttt{su}(b')/x))} \searrow a$ (the helper's hypothesis on
  $a$ at $b = \texttt{su}(b')$). Hence $a^{su} \approx a \in \mathcal{U}_i$ by
  completeness on $\typing[\Gamma, x:\ensuremath{\texttt{Nat}}]{T}{\ensuremath{\texttt{Ty}_{i}}}$, and
  $\textbf{El}^{su} \Leftrightarrow \textbf{El}$ by \Cref{lem:gluing-functional}.

  \emph{Conclusion.}
  \begin{align*}
    &\tyequiv[\Delta]{E}{s[\sigma_{\text{step}}]}{T[\sigma, t_*/x]}
      && \text{(by the $\beta$-su rule combined with
        $\tyequiv[\Delta]{t_*}{\textsf{succ}~t_*'}{\ensuremath{\texttt{Nat}}}$ and the type rewriting)} \\
    &\typing[\Delta]{E}{T[\sigma, t_*/x]}
      \;\circledR\; r_s \in \textbf{El}
      && \text{(by \Cref{lem:gluing-respects-eq})}
  \end{align*}
  Take $r := r_s$.

  \medskip\noindent
  \textbf{Case}
  \begin{mathpar}
    \inferrule[\textsc{GN-Ne}]
    {\typing[\Delta]{t_*}{\ensuremath{\texttt{Nat}}} \;\circledR\;
      {\uparrow}^N(e) \in \textsf{Neu}_i^e}
    {\typing[\Delta]{t_*}{\ensuremath{\texttt{Nat}}} \;\circledR\;
      {\uparrow}^N(e) \in \textsf{Nat}}
  \end{mathpar}
  Here $b = {\uparrow}^N(e)$, with the type-side neutral predicate giving
  $\textsf{R}^{\textsf{Ne}}_n(e) \searrow u_e$ and $\tyequiv[\Delta'']{t_*[\phi]}{u_e}{\ensuremath{\texttt{Nat}}}$ for
  every $\kweak[\Delta'']{\phi}{\Delta}$, $n := |\Delta''|$.

  \emph{Reduction step.} The helper's hypothesis specializes to
  $\ensuremath{\llbracket T \rrbracket((\rho, {\uparrow}^N(e)/x))} \searrow a$.
  \begin{align*}
    &\mathsf{rec}({\uparrow}^N(e), T, z, s, \rho)
      \searrow {\uparrow}^a(\mathsf{rec}(T, a_z, s, \rho, e))
      && \text{(by \textsc{rec-ne}, where
        $\ensuremath{\llbracket z \rrbracket(\rho)} \searrow a_z$)} \\
    &{\uparrow}^N(e) \approx {\uparrow}^N(e) \in R_\ensuremath{\texttt{Nat}}
      && \text{(by \textsc{U-Ne})}
  \end{align*}

  \emph{Recursor as a neutral.} We verify $\mathsf{rec}(T, a_z, s, \rho, e) \in
  \textsf{Ne}_i^a$ at the term $E$. For each $\kweak[\Delta'']{\phi}{\Delta}$, set
  $n := |\Delta''|$ and assemble the four readback components:
  \begin{align*}
    &\textsf{R}^{\textsf{Ne}}_n(e) \searrow u_e,\;
      \tyequiv[\Delta'']{t_*[\phi]}{u_e}{\ensuremath{\texttt{Nat}}}
      && \text{(by hypothesis on $e$, neutral readback)} \\
    &\textsf{R}^{\textsf{Ty}}_{n+1}(a) \searrow W_T,\;
      \tyequiv[\Delta'', x':\ensuremath{\texttt{Nat}}]
        {T[q(\sigma)][\iota(\phi), x'/x]}{W_T}{\ensuremath{\texttt{Ty}_{i}}}
      && \text{(by \Cref{thm:gluing-realizability} part (3)
        on} \\
    & && \text{$a \in \mathcal{U}_i^\ast$, at the Kripke weakening
        to $\Delta'', x':\ensuremath{\texttt{Nat}}$)} \\
    &\ensuremath{\llbracket T[\textsf{zero}/x] \rrbracket(\rho)} \searrow A_z',\;
      A_z' \in \mathcal{U}_i^\ast \searrow P_z' \searrow \textbf{El}_z'
      && \text{(by hypothesis on $z$ via
        $\Semtyp[\Gamma]{z}{T[\textsf{zero}/x]}$,} \\
    & && \text{type-evaluation and gluing clauses)} \\
    &\typing[\Delta]{z[\sigma]}{T[\textsf{zero}/x][\sigma]}
      \;\circledR\; a_z \in \textbf{El}_z'
      && \text{(by hypothesis on $z$, term clause; with
        $a_z := \ensuremath{\llbracket z \rrbracket(\rho)}$)} \\
    &\ensuremath{\llbracket T \rrbracket((\rho, \texttt{ze}/x))} \searrow A_z
      && \text{(type evaluation; the form required by
        \textsc{Re-rec})} \\
    &A_z' \approx A_z \in \mathcal{U}_i
      && \text{(by completeness on
        $\typing[\Gamma, x:\ensuremath{\texttt{Nat}}]{T}{\ensuremath{\texttt{Ty}_{i}}}$ instantiated} \\
    & && \text{at the substitution $(\ensuremath{\textsf{id}}, \textsf{zero}/x)$)} \\
    &A_z \in \mathcal{U}_i^\ast \searrow P_z \searrow \textbf{El}_z,\;
      \textbf{El}_z' \Leftrightarrow \textbf{El}_z
      && \text{(by \Cref{lem:gluing-univ-equiv} and
        \Cref{lem:gluing-functional})} \\
    &\textsf{R}^{\textsf{Nf}}_n({\downarrow}^{A_z}(a_z)) \searrow w_z
      && \text{(by \Cref{thm:gluing-realizability} part (2) on
        $a_z \in \textbf{El}_z$)} \\
    &\tyequiv[\Delta''] {z[\sigma][\phi]}{w_z}{T[\textsf{zero}/x][\sigma][\phi]}
      && \text{(after term-side type-bridging via
        \Cref{lem:gluing-respects-eq})} \\
    &\ensuremath{\llbracket T \rrbracket((\rho, \texttt{su}({\uparrow}^N(\ell_n))/x))} \searrow A_s
      && \text{(type evaluation at the fresh-step head $\texttt{su}(\ell_n)$)} \\
    &\ensuremath{\llbracket s \rrbracket(\rho, {\uparrow}^N(\ell_n)/x,
            {\uparrow}^{A_p}(\ell_{n+1})/y)} \searrow b_s
      && \text{(step branch evaluated at the fresh-neutral pair,} \\
    & && \text{where $A_p := \ensuremath{\llbracket T \rrbracket((\rho, {\uparrow}^N(\ell_n)/x))}$)} \\
    &\textsf{R}^{\textsf{Nf}}_{n+2}({\downarrow}^{A_s}(b_s)) \searrow w_s
      && \text{(by \Cref{thm:gluing-realizability} part (2) on
        the step value)} \\
    &\Delta_s \vdash s[q(q(\sigma))][\iota(\iota(\phi))]
      \approx w_s \\
    & \qquad : T[q(\sigma)][\iota(\phi), \textsf{succ}~x'/x]
      && \text{(at the corresponding type, where} \\
    & && \text{$\Delta_s := \Delta'', x':\ensuremath{\texttt{Nat}},
        y':T[q(\sigma)][\iota(\phi), x'/x]$)} \\
    &\textsf{R}^{\textsf{Ne}}_n(\mathsf{rec}(T, a_z, s, \rho, e)) \\
    & \quad \searrow \ensuremath{\textsf{elim}_{\ensuremath{\texttt{Nat}}}~(x.\,W_T)~w_z~(x, y.\,w_s)~u_e}
      && \text{(by \textsc{Rne-rec})} \\
    &\Delta'' \vdash E[\phi] \approx
      \ensuremath{\textsf{elim}_{\ensuremath{\texttt{Nat}}}~(x.\,W_T)~w_z~(x, y.\,w_s)~u_e} \\
    & \qquad : T[\sigma,\, t_*/x][\phi]
      && \text{(by \textsc{N-E-Cong} on the four
        readback equalities)}
  \end{align*}

  \emph{Type-side gluing.} The helper's hypothesis already gives the
  type-side gluing of $T[\sigma, t_*/x]$ at $P$ (via the outer
  $\Semtyp[\Gamma, x:\ensuremath{\texttt{Nat}}]{T}{\ensuremath{\texttt{Ty}_{i}}}$ instantiation that produced
  $a, P, \textbf{El}$).

  \emph{Conclusion.}
  \begin{align*}
    &\typing[\Delta]{E}{T[\sigma, t_*/x]} \;\circledR\;
      \mathsf{rec}(T, a_z, s, \rho, e) \in \textsf{Ne}_i^a
      && \text{(by \Cref{def:neu-term-pred} from the previous block)} \\
    &\typing[\Delta]{E}{T[\sigma, t_*/x]} \;\circledR\;
      {\uparrow}^a(\mathsf{rec}(T, a_z, s, \rho, e)) \in \textbf{El}
      && \text{(by \Cref{thm:gluing-realizability} part (1) on
        $a \in \mathcal{U}_i^\ast$)}
  \end{align*}
  Take $r := {\uparrow}^a(\mathsf{rec}(T, a_z, s, \rho, e))$.

$\Vdash \Gamma$ is presupposed by the hypotheses.
  Fix $\Gamma \searrow \textsf{Sb}$ and let
  $\judge[\Delta]{\sigma : \Gamma} \;\circledR\; \rho \in \textsf{Sb}$ be given.
  \begin{align*}
    &\ensuremath{\llbracket t \rrbracket(\rho)} \searrow a
      && \text{(by hypothesis on $t$, evaluation clause)} \\
    &\typing[\Delta]{t[\sigma]}{\ensuremath{\texttt{Nat}}[\sigma]} \;\circledR\; a \in \textsf{Nat}_i
      && \text{(by hypothesis on $t$, term clause)} \\
    &\tyequiv[\Delta]{\ensuremath{\texttt{Nat}}[\sigma]}{\ensuremath{\texttt{Nat}}}{\ensuremath{\texttt{Ty}_{0}}}
      && \text{(syntactic; closed)} \\
    &\typing[\Delta]{t[\sigma]}{\ensuremath{\texttt{Nat}}} \;\circledR\; a \in \textsf{Nat}_i
      && \text{(by \Cref{lem:gluing-respects-eq})}
  \end{align*}
  Build the substitution pair for $T$:
  \begin{align*}
    &\sigma_T := (\sigma, t[\sigma]/x)
      && \text{(definition)} \\
    &\judge[\Delta]{\sigma_T : \Gamma, x:\ensuremath{\texttt{Nat}}}
      \;\circledR\; (\rho, a/x) \in \textsf{Sb}_{x:\ensuremath{\texttt{Nat}}}
      && \text{(by $\textsf{Cons}_0$ on $\textsf{Sb}$, head $a \in \textsf{Nat}_i$
        realized by $t[\sigma]$)} \\
    &\ensuremath{\llbracket T \rrbracket((\rho, a/x))} \searrow a_T
      && \text{(by hypothesis on $T$ at $\sigma_T, (\rho, a/x)$)} \\
    &a_T \in \mathcal{U}_i^\ast \searrow P_T \searrow \textbf{El}_T
      && \text{(by hypothesis on $T$, gluing clause)} \\
    &\typing[\Delta]{T[\sigma_T]}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; P_T
      && \text{(by hypothesis on $T$, type clause)}
  \end{align*}
  By \Cref{lem:fund-sound-rec-helper} on $t_* := t[\sigma]$, $b := a$, with
  the data above:
  \begin{align*}
    &\mathsf{rec}(a, T, z, s, \rho) \searrow r
      && \text{(by helper)} \\
    &\typing[\Delta]
      {\ensuremath{\textsf{elim}_{\ensuremath{\texttt{Nat}}}~(x.\,T[q(\sigma)])~z[\sigma]~(x, y.\,s[q(q(\sigma))])~t[\sigma]}}
      {T[\sigma, t[\sigma]/x]}
      \;\circledR\; r \in \textbf{El}_T
      && \text{(by helper)} \\
    &\ensuremath{\llbracket \ensuremath{\textsf{elim}_{\ensuremath{\texttt{Nat}}}~(x.\,T)~z~(x, y.\,s)~t} \rrbracket(\rho)} \searrow r
      && \text{(by \textsc{ev-rec})} \\
    &(\ensuremath{\textsf{elim}_{\ensuremath{\texttt{Nat}}}~(x.\,T)~z~(x, y.\,s)~t})[\sigma]
      && \text{(by syntactic} \\
    & \quad = \ensuremath{\textsf{elim}_{\ensuremath{\texttt{Nat}}}~(x.\,T[q(\sigma)])~z[\sigma]~(x, y.\,s[q(q(\sigma))])~t[\sigma]}
      && \text{substitution on $\textsf{elim}_{\ensuremath{\texttt{Nat}}}$)} \\
    &T[\sigma_T] = T[\sigma, t[\sigma]/x] = T[t/x][\sigma]
      && \text{(by \Cref{lem:subst-ext-comm})}
  \end{align*}
  We assemble the four clauses of $
  \Semjudge[$]{f : o}
r the conclusion at $a :=
  a_T$, $P := P_T$, $\textbf{El} := \textbf{El}_T$:
  \begin{align*}
    &\ensuremath{\llbracket T[t/x] \rrbracket(\rho)} \searrow a_T
      && \text{(via the equality $\ensuremath{\llbracket T[t/x] \rrbracket(\rho)} = \ensuremath{\llbracket T \rrbracket((\rho, a/x))}$
        established by} \\
    & && \text{\Cref{thm:fundamental} of \Cref{sec:comp} on
        $\typing[\Gamma, x:\ensuremath{\texttt{Nat}}]{T}{\ensuremath{\texttt{Ty}_{i}}}$)}
      \tag*{[clause 1]} \\
    &a_T \in \mathcal{U}_i^\ast \searrow P_T \searrow \textbf{El}_T
      && \text{(established above)} \tag*{[clause 2]} \\
    &\typing[\Delta]{T[t/x][\sigma]}{\ensuremath{\texttt{Ty}_{i}}} \;\circledR\; P_T
      && \text{(by rewriting the $T[\sigma_T]$ identity)} \tag*{[clause 3]} \\
    &\typing[\Delta]{(\ensuremath{\textsf{elim}_{\ensuremath{\texttt{Nat}}}~(x.\,T)~z~(x, y.\,s)~t})[\sigma]}{T[t/x][\sigma]} \\
    & \quad \;\circledR\; r \in \textbf{El}_T
      && \text{(by rewriting via the syntactic identity above)}
      \tag*{[clause 4]}
  \end{align*}

\label{lem:fund-sound-subsump}
  If $\Semtyp[\Gamma]{t}{S}$, $\Semtyp[\Gamma]{T}{\ensuremath{\texttt{Ty}_{i}}}$, and
  $\subty[\Gamma]{S}{T}$, then $\Semtyp[\Gamma]{t}{T}$.

\label{thm:fundamental-sound}\hfill
  \begin{enumerate}
  \@idxitem If $\vdash \Gamma$, then $\Vdash \Gamma$.
  \@idxitem If $\typing[\Gamma]{t}{T}$, then $\Vdash \Gamma$ and
    $\Semtyp[\Gamma]{t}{T}$.
  \end{enumerate}

\label{thm:soundness}
  If $\typing[\Gamma]{t}{T}$, then $\textsf{nbe}^T_\Gamma(t) = v$ for some $v$ with
  $\tyequiv[\Gamma]{t}{v}{T}$.

\begin{align*}
    &\Vdash \Gamma,\;
      \Semtyp[\Gamma]{t}{T}
      && \text{(by \Cref{thm:fundamental-sound} part (2))} \\
    &\Gamma \searrow \textsf{Sb}
      && \text{(by \Cref{def:sound-semctx} on $\Vdash \Gamma$)} \\
    &\judge[\Gamma]{\ensuremath{\textsf{id}} : \Gamma} \;\circledR\; {\uparrow}^\Gamma \in \textsf{Sb}
      && \text{(by \Cref{lem:init-env-valid} on $\Gamma \searrow \textsf{Sb}$)} \\
    &\ensuremath{\llbracket T \rrbracket({\uparrow}^\Gamma)} \searrow a,\;
      a \in \mathcal{U}_i^\ast \searrow P \searrow \textbf{El}
      && \text{(unfolding $\Vdash$ at $\ensuremath{\textsf{id}}, {\uparrow}^\Gamma$)} \\
    &\typing[\Gamma]{t[\ensuremath{\textsf{id}}]}{T[\ensuremath{\textsf{id}}]} \;\circledR\; \ensuremath{\llbracket t \rrbracket({\uparrow}^\Gamma)} \in \textbf{El}
      && \text{(unfolding $\Vdash$ at $\ensuremath{\textsf{id}}, {\uparrow}^\Gamma$)} \\
    &T[\ensuremath{\textsf{id}}] = T,\; t[\ensuremath{\textsf{id}}] = t
      && \text{(by left-id of substitution)} \\
    &\typing[\Gamma]{t}{T} \;\circledR\; b \in \textsf{Nf}_i^a
      \text{ where } b = \ensuremath{\llbracket t \rrbracket({\uparrow}^\Gamma)}
      && \text{(by \Cref{thm:gluing-realizability} part (2))} \\
    &\textsf{R}^{\textsf{Nf}}_{|\Gamma|}({\downarrow}^a(b)) \searrow v,\;
      \tyequiv[\Gamma]{t[\ensuremath{\textsf{id}}]}{v}{T[\ensuremath{\textsf{id}}]}
      && \text{(Kripke condition at $\phi = \ensuremath{\textsf{id}}$)} \\
    &\tyequiv[\Gamma]{t}{v}{T}
      && \text{(using $t[\ensuremath{\textsf{id}}] = t, T[\ensuremath{\textsf{id}}] = T$)} \\
    &\textsf{nbe}^T_\Gamma(t) = v
      && \text{(by \Cref{def:nbe}: evaluation followed by readback)}
  \end{align*}

\label{cor:decidability}
  Given $\typing[\Gamma]{s}{T}$ and $\typing[\Gamma]{t}{T}$, the judgment
  $\tyequiv[\Gamma]{s}{t}{T}$ is decidable.
